extraordinario, imprevisible e irresistible, que impide la ejecución de la obligación
o determina su cumplimiento parcial, tardío o defectuoso” (Art. 1313 CC). Conforme
se evidencia la citada norma no hace diferencia entre caso fortuito o fuerza mayor.
Y para todo efecto práctico, nuestro ordenamiento civil considera el caso fortuito y
la fuerza mayor como conceptos análogos, que tienen consecuencias similares: la
exoneración de la responsabilidad.
Para Fernando de Trazegnies la noción de caso fortuito o fuerza mayor sólo es relevan
te en el campo de la responsabilidad objetiva, porque, tratándose de responsabilidad
subjetiva, todas las situaciones comprendidas en el caso fortuito se hallan excluidas
de tal responsabilidad por el simple hecho que carecen de culpa. En consecuencia, la
responsabilidad subjetiva solo responsabiliza a quien tiene culpa, estos casos quedan
exentos; yya no será necesario hablar de caso fortuito o de fuerza mayor, porque basta
demostrar la simple ausencia de culpa para quedar libre de responsabilidad.
b. - El hecho determinante de un tercero.- La regla contenida en él artículo 1972 C.C. ha
querido exonerar de responsabilidad a quien no fue autor de un daño, es decir, libe
rar al presunto agente cuando el verdadero productor del daño fue un tercero, lo cual
no significa que cualquier hecho de un tercero exime de responsabilidad; porque si
así fuera no habría responsabilidad objetiva.
En realidad, tanto en el caso fortuito como en el hecho determinante de tercero son
casos de fuerza mayor. La diferencia se da en que el caso fortuito es una fuerza anóni
ma, mientras que el hecho de un terceroy el hecho de la víctima tienen un carácter de
fuerza mayorcon el autor. Este carácter de “hecho de autor” da lugaraque no se cancele
la responsabilidad extracontractual, simplemente se desplaza del presunto causante
al verdadero causante. Es un hecho determinante que exonera de responsabilidad a
una persona en particular a quien se le creía causante, pero no establece que no hay
responsabilidad, sino que otra persona es identificada como el “autor del daño”; y es
contra ella que se vuelve la institución de la responsabilidad extracontractual.
Ejemplo: Juan se encuentra manejando una moto, cuando intempestivamente cruza
por la misma vía en dirección contraria Paulina, chocando contra Juan, siendo arro-
