Es necesario además señalar que existen hechos de terceros que no son eximentes
en virtud de la Ley, no todo hecho determinante de tercero exonera de responsabili-
dadya que nuestro Código Civil establece ciertos casos en los que estamos obligados
a pagar indemnización, por ejemplo:
• Caso de representante legal de la persona incapacitada.
• Caso del que incita a otro para que cometa un delito.
9 Caso del que tiene a otro bajo sus órdenes.
c - El hecho determinante de la víctima.- Previstos en eh 972oy 1973odel Código Civi I. El
Artículo 1972o precisa que se libera al presunto autor no cuando ha mediado un he
cho determinante de la víctimasino una imprudencia de ella, por lo que es necesario
precisar que esta viene a ser el defecto de la advertencia o previsión que debía haber
puesto en alguna cosa.
Se trata de un daño del cual el demandado no es el autor. Pero a diferencia del caso
fortuito en el que el daño es atribuido a un suceso anónim oy del hecho determinan
te en el daño es imputable a una tercera persona, aquí la causa se encuentra en el
hecho de la propia víctima.
Ejemplo: Si en plena vía expresa, Juana decidiera quitarse laviday se arroja debajo de
un vehículo en plena marcha, aun cuando el daño fue causado por el conductor, no
existe duda que podrá liberarse de la responsabilidad pues fue la propia conducta de
la víctima quien causo el daño.
En todos los casos de fractura causal debe dejarse de lado el análisis del aspecto
subjetivo del autor de la conducta de la causa inicial, pues lo único relevante es que
el daño ha sido consecuencia de una conducta o evento ajeno o distinto, ya sea un
caso fortuito o fuerza mayor, de hecho de tercero o de hecho de la propia víctima.
Es decir, las fracturas causales deben ser invocadas cuando se le impute a un sujeto
una responsabilidad civil por un daño que no ha causado, habiendo sido el mismo
consecuencia de un evento o culpa ajena, siendo que ésta no guarda vinculación al
guna con la noción de culpabilidad, tratándose de un asunto objetivo, referido a qué
conducta o evento es la causa del daño.
2. Concausa.- Regulado porel artículo 1973° del Código Civil, en este caso el daño es siempre
consecuencia de la conducta del autor, pero con contribución o participación de la propia
víctima, tratándose de un supuesto totalmente distinto al de la fractura causal.
Se da un supuesto de concausa cuando la víctima contribuye con su propio comporta
miento a la conducta del autor o a la realización de un daño, en este caso el daño no es
consecuencia única y exclusiva de la conducta del autor, sino que la propia víctima ha
contribuido y colaborado objetivamente a la realización del mismo, el cual no se hubiera
producido de no mediar el comportamiento de la propia víctima.
