UBILEX
Ejemplo:] avier practica ciclismo en la pista de la Av. Javier Prado y no en las ciclovías exis
tentes, existirá concausa en el supuesto deque un conductor de esta vía rápida atropelle a
Javier. No se trata de una fractura causal puesto que el solo hecho de la conducta de hacer
ciclismo en la pista no es suficiente en sí misma para sufrir un accidente de tránsito, pero
si se tratara de una concausa por cuanto con este comportamiento Javier está contribu
yendo objetivamente a la producción del daño.
El efecto jurídico de la concausa no es la liberación de la responsabilidad civil del autor,
sino únicamente la reducción de la indemnización a cargo del autor, la reducción deberá
ser determinada por el juez, según las circunstancias.
Usualmente es difícil distinguir cuando se da una fractura causal y cuando la concausa.
El único criterio para diferenciarlos será responder la siguiente preguntadla conducta de la
víctima por si sola es suficiente para la producción del daño?
Si la respuesta es negativa se tratará de una concausa, si es afirmativa será una fractura causal.
3.- Concurrencia de causas.- En el caso de que se dé la concurrencia de causas, denominado
también pluralidad de causas o coautores (en los cuales dos o más sujetos, mediante una
conducta común o a través de conductas singulares, causa un mismo daño). En este caso
se trata del supuesto en que el daño no es consecuencia de la conducta de un solo sujeto,
sino de la conducta de varios sujetos, se encuentra previsto en el artículo 1983° del C.C.y
el efecto es que son solidariamente responsables. Cuando no sea posible discriminar o
distinguir el diferente grado de participación, la indemnización se distribuirá entre ellos
en partes iguales.
Factores de atribución.- Viene a ser el fundamento del deber de indemnizar, existe dos
sistemas de responsabilidad: el sistema subjetivo y el sistema objetivo, cada uno de ellos
fundamentados en distintos factores de atribución denominados factores de atribución
subjetivos y objetivos.
A. Sistema subjetivo
a) Dolo: En el derecho tiene diversas acepciones. En sentido lato significa una idea de
mala fe, malicia, fraude, daño.
Por ello entendemos como dolo como lavoluntadoel ánimo deliberado de la perso
na de causar el daño, coincide con el artículo 1318o del Código Civil en lo referente al
incumplimiento de la obligación.
Se presenta desempeñando una triple función:
Dolo como vicio de la voluntad, es el engaño que se emplea para inducir a al
guien a consentir con la formación de un acto jurídico, que sin ese dolo no se
habría realizado o lo hubiera sido en condiciones diferentes. En este caso puede
ser el dolo que falsea la intención del agente y que este puede aducir para obte
ner la anulación de un acto celebrado con ese vicio.
En materia de actos ilícitos, el dolo designa la intención del agente de provocar
el daño que deriva de un hecho.
El incumplimiento de la obligación, el dolo alude a la intención con que el deu
dor ha obrado para inejecutar la prestación debida.
