Tema 2: Temas de derecho civi
Es un concepto que ha tomado la responsabilidad civil,y que normalmente se había
confinado al campo penal y puede ser:
Dolo Directo.- En este tipo de dolo el sujeto actúa para provocar el daño. Cuando el
propósito va dirigido a un fin.
Dolo Eventual.- En el cual no se actúa para dañar, pues la persona obra aunque se
represente la posibilidad de un resultado dañoso, que no descarta. Asume el riesgo
de que su conducta pueda causar un daño. Ejemplo: Juan conduce un vehículo a ex
cesiva velocidad, asumiendo que con esa conducta puede ocasionar un accidente,
sin embargo, no hace nada para asumir la responsabilidad.
b) Culpa: Es la creación de un riesgo injustificado y para evaluar si ese riesgo sea ju sti
ficado o no, se necesitará confrontarlo con la utilidad social de la actividad a la cual
este se refiere, teniendo en cuenta el costo de la remoción de este; cuando más gran
de es la utilidad social y el costo de remoción, tanto más grande es el riesgo creado.
La culpa es el fundamento del sistema subjetivo de responsabilidad civil (fluye, ema
na claramente del art. 1969o C.C); y ante la dificultad de probar la culpa del autor, es
decir, dado lo difícil que es conocer el aspecto subjetivo del autor, nuestro ordena
miento ha considerado que es conveniente establecer presunciones de culpabilidad,
invirtiendo la carga de la prueba, de tal modo que la víctimaya no estará obligado a
demostrar la ausencia de culpa. Esta inversión de la carga de la prueba y correlativa
presunción de culpabilidad del autoren el sistema subjetivo de responsabilidad civil
extracontractual presume la culpa del autor del daño causado.
Culpa Objetiva o Culpa in abstracto.- Viene a ser la culpa por violación de las leyes,
cuando el ordenamiento determina el parámetro de comportamiento y si la per
sona no cumple es responsable. Un ejemplo clásico es el art. 961o del Código Ci
vil. El criterio de la normal tolerancia sirva para determinar si hayo no culpa.
Culpa Subjetiva o culpa in concreto.- Se basa en las características personales
del agente,y un ejemplo de ello lo encontramos en él artículo 13 14 o. Este tipo de
culpa engloba a la imprudencia (el sujeto hace más de lo debido)y a la negligen
cia (el sujeto hace menos de los debido).
En la responsabilidad por incumplimiento de obligaciones, se suele diferenciar di
versos grados de cul pa:
Culpa grave (Art. 1319 CC): definido como culpa inexcusable y viene a ser el no
uso de la diligencia que es propia de la mayoría de las personas. Ejemplo, se deja
a una persona a cargo de un almacén, deja abierta las puertas de noche y roban
los productos.
Culpa leve: Es la omisión de la diligencia ordinaria exigida por la naturaleza de
la obligación y que corresponda a las circunstancias de las personas, el tiem poy
el lugar. (Art. 1320 C.C.)
B. Sistema objetivo
Riesgo creado: De acuerdo al Diccionario de la Lengua de la Real Academia Espa
ñola “riesgo" es una contingencia o proximidad de un daño, y de otro lado, define la
