Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 486 of 1506 --

palabra peligroso com o“que tiene riesgoo puede ocasionar daño. Para ladoctrinael
riesgo creado viene a ser el riesgo adicional al ordinario tales como: automotores, ar
tefactos eléctricos, cocinas de gas, ascensores, diversas armas de fuego, insecticidas,
medicamentos, actividades industriales.
Todo este tipo de bienes y actividades no será necesario examinar la culpabilidad del
autor, pues deberá bastar con acreditar el daño producido, la relación de causalidad
y que se trate de un bien o actividad que suponga un riesgo adicional al normal y
común, por lo que merece la calificación de “riesgosos”. Haya sido el autor culpable o
no, igualmente será responsable por haber causado el daño mediante una actividad
riesgosa o peligrosa.
Se observa entonces que la ausencia de culpa no sirve como mecanismo liberador
de responsabilidad civil, adquiriendo por el contrario importancia fundamental la
noción de causa ajena o fractura causal.
El sistema objetivo de responsabilidad civil no pretende que los daños que se hayan
causado a través de bienes o actividades riesgosas, no exista la culpa del autor, lo
que se pretende es la total abstracción de la culpa o ausencia de la culpa del autor,
de tal modo que la existencia de culpa o no sea totalm ente intrascendente para la
configuración de un supuesto de responsabilidad civil extracontractual, debiendo
acreditarse la relación causal, la calidad del bien o la actividad como una riesgosa.
Cabe agregar que la calificación de un bien o actividad riesgosa o peligrosa no de
pende de las circunstancias de un caso concreto en particular, pues de ser así cual
quier actividad podría ser considerada riesgosa. Esta calificación depende del riesgo
que supone el uso socialmente aceptado del bien o actividad de que se trate, siem-
prey cuando su uso suponga un riesgo adicional al común y ordinario, como sucede
con las armas de fuego o con los vehículos.
CLASES DE DAÑO
A. Daño patrimonial
Viene a ser la lesión de derechos de naturaleza económica o material que debe ser
reparado, por ejemplo: la destrucción de una computadora. Se clasifica a su vez en:
- Daño emergente.- Viene a ser la pérdida patrimonial como consecuencia de un
hecho ilícito, implica siempre un empobrecimiento, comprende tanto los daños
inmediatos como los daños futuros, pues no siempre las consecuencias van a ser
inmediatas. Es en consecuencia ladisminución de la esfera patrimonial. Ejemplo-.
la factura de los medicamentos a consecuencia de una intervención quirúrgica,
el costo de las terapias de rehabilitación que son gastos inmediatos y futuros.
- Lucro Cesante.- Se entiende como ganancia dejada de percibir o el no incremen
to en el patrimonio dañado, mientras que en el daño emergente hay empobre
cimiento en el lucro cesante hay un impedimento de enriquecimiento legitimo.
Ejemplo, a consecuencia de una defectuosa intervención quirúrgica el agraviado
