B. Daño extrapatrimonial
Viene a ser el daño ocasionado a la persona en sí misma, dentro de la cual se encuen
tra el daño moral y a la persona.
Daño moral.- Es el daño no patrimonial que se entiende como una lesión a los
sentimientos de la víctim ay que produce un gran dolor, afección o sufrimiento,
ejemplo la pérdida de un ser querido como consecuencia de un accidente de
tránsito con consecuencia fatal. Es la lesión o cualquier sentimiento considera
do socialmente legítimo.
Si bien no existe un concepto unívoco de daño moral, es menester considerar
que éste es el daño no patrimonial inferido en derechos de la personalidad o
en valores que pertenecen más al campo de la efectividad que al de la realidad
económica; en cuanto a sus efectos, es susceptible de producir una pérdida pe-
cuniariay una afectación espiritual25.
Existen dos grandes problemas con referencia al daño moral como acreditarlo y
como cuantifi cario.
Respecto a cuantificarlo si bien no existe una suma de dinero que pueda reparar la
pérdida de un ser querido, el artículo 1984o del Código Civil expresa que el monto
indemnizatorio debe ir acorde con el grado de sufrimiento de la víctim ay la ma
nera como ese sufrimiento se ha manifestado en la situación de la víctima y su
familia en general.
Daño a la persona.- Lizardo Taboada argumenta que “el daño a la persona se
produce cuando se lesiona la integridad física del sujeto, su aspecto psicológico
y/o su proyecto de vida, todo lo cual deberá ser obviamente acreditado”. Para
otro sector de la doctrina el daño a la persona constituye la frustración de! proyecto
de vida. Así, por ejemplo, los casos típicos que utilizan estos autores, hacer refe
rencia a la pérdida de uno o varios dedos para una pianista, de una pierna para
una bailarina, etc.
Lizardo Taboada con respecto al proyecto de vida menciona: “que no se trata de cualquier po
sibilidad de desarrollo de una persona, que puede ser incierta, sino que deberá tratarse de la
frustración de un proyecto evidenciadoy en proceso de ejecución y desarrollo que se frustra de
un momento a otro. No se debe confundir proyecto de vida con cualquier posibilidad respecto
de la cual no exista ningún tipo de evidencia comprobada. Como tampoco se debe confundir
proyecto de vida con las simples motivaciones de los sujetos”. Para este autor la fórm ula plan
teada es la más lógica y razonable para entender la noción de daño a la persona, por cuanto
la persona no es únicamente cuerpo sino también una mente, y en muchos casos supone un
proyecto de vida evidenciado por hechos y conductas concretas.
