UBILEX
La indemnización: Condiciones generales del daño reparable.
En el campo contractual se Indemnizan los daños patrimoniales como el daño moral (daño
extrapatrimonial) en cuanto sean consecuencia inmediata y directa del incumplimiento de
obligaciones por parte del deudor. Ello es lógico por cuanto siempre se requiere que los daños
sean consecuencia del incumplimiento absoluto o relativo de la prestación debida por parte
del deudor, esto es, es necesario que exista una relación de causalidad inmediata y directa
entre los daños causados al acreedory el incumplimiento total, cumplim iento parcial, cum pli
miento defectuoso, o por retraso en el cumplim iento de la prestación. Sin embargo, además
de la relación causal, debe señalarse que en el campo contractual el monto ¡ndemnizatorlo
será mayor o menor dependiendo del grado de culpabilidad del deudor. Así, si el cumplim ien
to es consecuencia de dolo o culpa grave del deudor, los daños y perjuicios a reparar son to
dos aquellos consecuencia inmediata y directa del incumplimiento que pudieran preverse o
no al momento de contraerse la obligación. Por el contrario, si el Incumplimiento obedeciere
únicamente a culpa leve, sólo se indemnizarán los daños y perjuicios que sean consecuencia
inmediata de contraerse la obligación. Esto que en el campo contractual el monto indemni-
zatorio será mayor o que significa que le monto ¡ndemnizatorio no depende exclusivamente
de la relación de causalidad, sino también del factor de atribución subjetivo, es decir, de la
culpabilidad. Consiguientemente en los casos de dolo o culpa grave o inexcusable el resarci
miento comprende los daños Inmediatos y directos previsibles e imprevisibles al momento de
contraer la obligación, mientras que en los casos de culpa leve los daños Inmediatos y directos
solamente previsibles al momento de asumir la obligación.
En el campo extracontractual, por el contrario, el monto ¡ndemnizatorlo no depende del gra
do de culpabilidad del autor del daño, sino únicamente de la existencia de una relación de
causalidad adecuada, en tanto y en cuanto se indemnizan todos los daños siempre que sean
consecuencia de una relación de causalidad adecuada. Esto significa que el ámbito extracon
tractual se Indemnizan todos los daños y no interesa la calificación de previsibles e Imprevisi
bles, como tampoco el quesean consecuencia inm ediatay directa o no de la conducta antiju
rídica. Este principio recibe ladenominación de reparación Integral y se encuentra claramente
establecido en el artículo 1985odel Código Civil.
De esta forma se llega a diferenciar los criterios para cuantlficar o calcular los montos Indem
nízatenos en los sistemas de responsabilidad civil, debiendo aclarar que en el campo con
tractual el monto ¡ndemnizatorlo depende fundamentalmente del grado de culpabilidad,
mientras que en el extracontractual depende exclusivamente de la relación de causalidad
adecuada, siendo indiferente la calificación jurídica del daño y el grado de culpabilidad del
autor de la conducta antijurídica.
21. El seguro y la responsabilidad civil
El Código Civil de 1984 plasma el reconocimiento del vínculo entre el seguro y la responsabili
dad civil en los siguientes artículos:
