Tema 2: Temas de derecho civil
Alt. 1 98 7 : La acción indemnizatoña puede ser dirigida contra el .asegurador por et dañOj guien respon
derá solidariamente con el responsable directo de éste.
Alt. 1 988. La ley determina el tipo de daño sujeto al régimen de seguro obligatorio, las personas que
deben contratar las pólizas y la naturaleza, límites y demás características de tal seguro.
Por otro lado, dentro del universo de seguros patrimoniales regulados en la Ley del Contrato
de Seguro-Ley N° 29946, tenemos al de responsabilidad civil. El seguro de responsabilidad ci
vil tiene por objeto poner a salvo el patrimonio del asegurado en caso de que un tercero recla
me un pago indemnizatorio derivado de la señalada responsabilidad civil, por lo que no está
orientado al damnificado, sino al responsable del daño. Señala el Art. 105 que: “El asegurador se
obliga a mantener indemne al asegurado de cuanto este debe pagar a un tercero, en razón de la respon
sabilidad prevista en el contrato, a consecuencia de un hecho dañoso acaecido en el plazo convenido." En
cuanto a la acción directa del tercero damnificado dispone en el Art. 110: “El tercera víctima del
daño tiene acción directa contra el asegurador, hasta el límite de las obligaciones previstas en el contrato
de seguroy siempre que se incluya al asegurado en su demanda.”
Retomando el análisis del Art. 1987 del Código Civil, de este dispositivo se desprenden dos as
pectos fundamentales. La posibilidad de que la víctima o damnificado pueda dirigirse di recta
mente contra la empresa aseguradora^ el hecho de que, en ese caso, la aseguradora responde
solidariamente con el “responsable directo”.
En cuanto a la acción directa De Trazegnies señala: “es por ese motivo que, mediante el otor
gamiento de una acción directa a la víctima, coloca a esa indemnización al abrigo de terceros
acreedores del responsable directo del dañoy simplifica los procedimientos para que la vícti
ma sea reparada a la mayor brevedad”.
Respecto de la respuesta solidaria por parte de la aseguradora, el profesor Marco Ortega26 re
salta que “finalmente se haya adoptado el régimen de la acción directa del damnificado con
tra la aseguradora del responsable, dejándose de lado la acción subrogatoria que es la que
correspondería ejercer. El problema, no obstante, radica en la solidaridad que se representó
el legislador civil, solidaridad que está fuera de todo contexto, es forzada, es postiza, ya que
la aseguradora no es responsable del daño extracontractual, sino que la ley de manera ex
cepcional ha establecido que es pasible de una acción directa del damnificado, de manera
que lo cobrada sea imputado a la indemnización debida por el responsable, el asegurado. La
solidaridad presupone pluralidad de deudores, o acreedores, en el marco de una misma rela
ción obligacional. En este caso, no hay tal pluralidad, ya que la aseguradora no es causante, no
es responsable, no es un tercero civilmente responsable, sino que mantiene un adeudo con el
asegurado como consecuencia que le resulta exigible Responsabilidad Civil extracontractual,
activándose con ello la cobertura en favor del asegurado, tal como se define en los correspon
dientes términos y condiciones de la póliza. No interesa si se trata de una solidaridad legal,
porque la aseguradora no es una codeudora.
