UBILEX
Se ha destacado en más de una oportunidad que la solidaridad en cuestión ha generado más
de un problema, si bien el legisladorcivil dei984 se fue más allá de lo aceptable, asimilando a
la aseguradora a la condición de una cocausante o de un tercero civilmente responsable, quie
nes sí están vinculados frente a la víctima. El tema está actualmente superado por la Ley del
Contrato de Seguro, la misma que ha derogado tácitamente al artículo 1987 del Código Civil de
1984, en cuanto reconoce la acción directa hasta por el monto de la póliza contratada.” Igual
mente, la Corte Suprema ha emitido jurisprudencia, mas o menos consistente, en el sentido
de lim itar la responsabilidad de la aseguradora al monto del contrato de seguro. Así, podemos
mencionar las siguientes resoluciones: Casación N°9492-99''Lima, Casación N °3 3 4 7 -2 0 0 1 -Lima,
Casación N°2926-2003-üma, Casación N°2779-2004-P¡ura, Casación N°4H4-2008-Lima.
En conclusión, la normativa vigente establece un límite de responsabilidad de la aseguradora
al monto de contrato de seguro, del mismo modo nuestra jurisprudencia se ha pronunciado
en ese sentido.
¿Ti BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 491 of 1506 --

Tema 2: Temas de derecho civil
Derecho Internacional Privado es la rama autónoma del derecho que comprende las relacio
nes jurídicas que tienen un elemento ostensible u oculto, extraño al derecho local, sin analizar
previamente su naturaleza esencial, no Importa que ella sea de carácter civil, comercial o pe
nal; es suficiente que el interés comprometido sea de una persona privaday que a su respecto
se plantee el problema de la ley que la reglamentay de la jurisdicción competente.
Es un Derecho que se originó como indicador del dominio legal a que deben someterse las
relaciones que vinculan a los individuos o a éstos con los Estados cuando en razón de las per
sonas, los bienes o los actos afectan el dominio legal de dos o más naciones. Los elementos
extraños de la relación jurídica son precisamente los que determinan un conflicto entre dos
o más soberanías legislativas, pero en la actualidad el acento estará dado por los elementos
extraños visualizados en la relación, más que por el carácter indicador o adjetivo de ciertas
normas que componen el Derecho Internacional Privado.
1. Comprensión del derecho internacional privado
Resulta indispensable precisar el ámbito de aplicación de las normas que sobre Derecho In
ternacional Privado contiene el Código Civil. En ese sentido el artículo 2047 establece una pre-
lación jurídica de normas que es necesario tener en cuenta para ubicar el Libro X en su lugar
exacto dentro del ordenamiento jurídico peruano.
Las relaciones jurídicas privadas de carácter internacional se regulan en primer térm ino por
los tratados internacionales ratificados por el Perú sean éstos de Derecho Internacional Pri
vado propiamente dicho es decir de sistemas basados en normas de conflicto por ejemplo el
Código de Bustamante de 1928 o de derecho sustantivo supranacional como pueden ser los
tratados sobre propiedad intelectual ratificados por el Congreso del Perú.
Solamente en caso de no existir un tratado aplicable a la relación jurídica concreta, serán utili-
zables las normas contenidas en el Libro X del Código Civil peruano.
Fuentes: Se conoce como fuentes del derecho aquellas que dan origen o inicio a determinada
disciplina jurídica, a partir de ello podemos decir que el Derecho Internacional Privado tiene
dos fuentes la nacional y la internacional.
Fuentes internacionales
1. Derecho positivo: Es aquella que se registra bajo constancia documentaria gráfica vemos
entonces las siguientes:
Tratados. Es el acuerdo entre estados que pueden ser tanto bilaterales como multilaterales.
Convencionales. Es similar en su redacción al tratado pero con una diferencia que es que
sus normas repercuten como normas de conducta para los habitantes de los países que
lo suscriben.
Legislación Uniforme. Son las leyes internacionales uniformes emitidas por organismos
internacionales.
2. Costumbre jurídica: Es un derecho no escrito, es un conjunto de usos y prácticas reiterantes
que generan el mismo derecho no escrito. Es vigente por ejemplo en el transporte marítimo
Internacional y en derecho internacional: CIF, FOB etc.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 492 of 1506 --

UBILEX
3. Jurisprudencia: Es el conjunto de precedentes emitidos por tribunales internacionales que
'' van a solucionar casos que pueden ser judiciales o arbitrales.
4. Doctrina: Es la ciencia de Derecho Internacional Privado creada en el ámbito del derecho por
los juristas (Joseph Story, Wenceslao Mancini, Karl Von Savigni y otros) o instituciones extranje
ros Cámara de comercio de Paris etc - Es la única no obligable las otras precedentes fuentes si
pueden ser coercibles al ser recogidas por el juez y el legislador internacional en la ley.
Fuentes nacionales:
1. Derecho positivo: Tenemos en ella dos clases de normas:
Norma de Conflicto. Que son las que establecen el Libro X del Código Civil.
Norma Material. Los demás artículos del Código Civil.
2. Jurisprudencia: Sigue el mismo esquema que el de las fuentes internacionales estos prece
dentes se aplican con más frecuencia en el derecho comercial, la llamada cámara de Comercio
tiene una comisión especial de asesoramiento.
3. Costumbre: La costumbre está referida a algunas convenciones que se van realizando como
parte de la obligación de aplicar al derecho común.
4. Doctrina: Es la contribución de los tratadistas como fundamento indispensable a la obra le
gislativa, destacan en el Perú don Carlos Castañeta, Manuel García Calderón Koeclin, Roberto
Mac Lean Ugarteche.
2. Método del derecho internacional privado
Se emplea el método deductivo, es decir, de lo general a lo particular a diferencia de otras
ramas del derecho donde se emplea el método deductivo.
Pasos a seguir
- Primer Paso: Establecer si el caso de Derecho Internacional Privado, ubicando los elemen
tos relevantes que se hallen vinculados a un ordenamiento jurídico al efecto no será rele
vante por ejemplo en la compraventa de una computadora el hecho que la misma haya sido
fabricada en los Estados Unidos de América pues esto no sería un factor jurídico vinculante.
- Segundo Paso: Conocido que el caso es de Derecho Internacional Privado se debe pro
ceder a establecer si existe un tratado sobre la materia aplicable al caso concreto en este
extremo se terminaría el método por cuanto seria a través de ese tratado que tendría que
resolverse el caso.
Caso contrario se avanza al siguiente paso del método.
- Tercer Paso: Si no existe tratado o el mismo no resuelve el caso concreto se procede a deter
minar si el Juez peruano es competente para conocer si no lo fuera entonces las normas de
conflicto peruano no serían aplicables no correspondiéndole a los jueces peruanos conocer
del asunto sin embargo de resultar competente el Juez peruano se continuad método.
- Cuarto Paso: Se pasa establecer donde se ubicará la categoría jurídica aplicable al caso
concreto al efecto se determinara si es una relación jurídica de derecho reales, sucesiones,
etc. y consiguientemente quedara determinado el factor de conexión aplicable; ¡ex loci
celebrationis, lexforí, etc.
f e 92 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 493 of 1506 --

Tema 2: Temas de derecho civil
- Quinto Paso: De acuerdo al factor de conexión aplicable lo ¡nterpretaremosy encontrare
mos la ley nacional competente.
- Sexto Paso: Identificada la ley competente de ser extranjerase procede a analizar su contenido
a fin de establecer si es de aplicación las excepciones a la aplicación de la ley extranjera que
aparece circunscrita en nuestro sistema jurídico y la excepción de orden público inc. 7 del artí
culo 2104oteniendo en cuenta que la referida excepción se halla a nuestro criterio consagrada
en la excepción del fraude a la ley que no aparece como tal en el Código Civil de 1984.
Si resultara aplicable la excepción de orden público deberá resolverse el caso conforme a las
normas jurídicas del derecho interno peruano, de lo contrario, es decir, la ley extranjera no es
incompatible con nuestro orden público internacional la solución del caso se basará en ese
ordenamiento jurídico.
3. Estructura de las normas
Nuestro sistema de Derecho Internacional Privado se basa en normas de conflicto. El Título III
(Ley aplicable) del Libro X del Código Civil refiere al método confl ictual o de “conflicto de leyes”.
La estructura de la norma de conflicto consta de:
Relación o situación jurídica: Como se ha sostenido por la doctrina mayoritaria, la estructura
de la norma de conflicto difiere de la norma usual de los ordenamientos jurídicos inter
nos. La norma de conflicto no contempla un supuesto de hecho, es decir, un suceso de la
realidad en cuanto tal, sino un concepto jurídico (por ejemplo, un contrato de donación,
el matrimonio, la adopción, la existencia de la persona jurídica, la responsabilidad extra
contractual, etc.). La operación de encontrar la justa inserción entre la relación jurídica
privada internacional con el concepto contemplado en el supuesto de la norma confl ic
tual se conoce como "calificación".
Factor de conexión: Es el "punto intermedio” de la norma confl ictual, y consiste en el criterio
que se aplicará a la relación jurídica y que dará como resultado la legislación interna o
la legislación extranjera aplicable. El factor de conexión varía de acuerdo al criterio que
posea el legisladory que le atribuya a cada institución en particular (puede ser, la nacio
nalidad, el domicilio, etc.).
Resultado: El método conflictual solo puede conducir a dos escenarios posibles, que son
la aplicación de la legislación nacional o de la legislación extranjera. Es en este punto del
análisis donde ingresa la aplicación del método autolimitativo.
4. La jurisdicción en ios contratos en los que interviene el Estado
La solución prevista en el inciso 3 del artículo 2058o señala que "cuando las partes se sometan ex
presa o tácitamente a su jurisdicción. Salvo convención en contrario, contemporáneo o anteriora la sum i
sión, la elección del tribunal es exclusiva”, esta nos refiere al artículo 63o de la Constitución Política
de 1993 que en su segundo párrafo señala: “En todo contrato del Estado y de las personas de derecho
público con extranjeros domiciliados consta el sometimiento de éstos a las leyesy órganos jurisdiccionales
de la república y su renuncia a toda reclamación diplomática. Pueden ser exceptuadas de la jurisdicción
nacional los contratos de carácter financiero”.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 494 of 1506 --

UBILEX
En el caso de jurisdicción voluntaria “El estado y las demás personas de derecho público pueden someter
las controversias derivadas de relación contractual a tribunales constituidos en virtud de tratados en vigor
Pueden también someterlas al arbitraje nacional e Internacional en la forma en que disponga la Ley”.
5. Lim itaciones a Sa aplicación de la ley extranjera
Quien interpone acción ante Juez extranjero puede conseguir posteriormente el reconoci
miento de la sentencia que se dicta en el Perú e incluso ejecutar la decisión así obtenida en
nuestro territorio con el solo requisito de que la resolución judicial en cuestión cumpla con
una serie de condiciones que señala el orden jurídico en el que se pretende ejecutar la senten
cia. En el caso de nuestro código estos requisitos están señalados en el Título IV del Libro de
Derecho Internacional Privado.
Para que una sentencia extranjera sea reconocida en el país será necesario que ella no resuelva
sobre materia de jurisdicción exclusiva. Existen así una serie de supuestos en los que el legis
lador peruano ha dispuesto que sólo pueden considerarse como válidamente resueltos cuan
do el juicio se sigue en su fuero. En consecuencia aun cuando otros estados consideren a sus
tribunales como competentes para avocarse al litigio la resolución que derive del mismo no
será posible de ejecutaren territorio peruano los casos de exclusividad en la competencia son
excepción a la regla general que es la competencia facultativa y se limitan a los que expresa
mente señala el código Civil (acciones reales sobre predios, acciones civiles relativas a delitos
y faltas, pacto de sometimiento expreso a la jurisdicción peruana, competencia jurisdiccional
exclusiva del estado contratante).
6. Métodos y sistem as de reconocim iento de sentencias y fallos arbitrales extranjeros
Tenemos entre los más usados e importantes los siguientes:
Sistema conflictual tradicional: Mediante este método se intenta resolver un problema de Dere
cho Internacional Privado de manera indirecta, con la aplicación de una norma jurídica que le
dé respuesta directa.
Normas de aplicación inmediata: Se trata de normas que constituyen determinadas políticas le
gislativas estatales con diferentes objetivos pero que en todos los casos resultan normas que
deben ser aplicadas obligatoriamente desplazando por lo tanto el recurrir a cualquier otro
método de aplicación de derecho extranjero.
Normas materiales: Son normas con vocación internacional que de manera directa resuelven el
fondo de un asunto derivado del tráfico jurídico internacional y que a diferencia de las normas
de aplicación inmediata su solución no está condicionada por una obligatoriedad determina
da sino por razones de certeza o seguridad jurídica o bien porque la solución así ha sido plan
teada por el legislador nacional, pero que en todo caso,ya sea de parte del juez que las aplica o
del legislador que las emite, hay una voluntad de coordinarsu sistema jurídico con los demás.
Lex Mercatoria: Su característica principal es que se trata de reglas que no tiene origen estatal
o bien una obligatoriedad en su aplicación por parte de los Estados. Son reglas que las partes
hacen suyas en sus relaciones jurídicas y las convierten en obligatorias entre ellas o bien son
reglas aceptadas por organizaciones de comerciantes o de prestadores de servicios y su uso
generalizado las hace obligatorias entre sus afiliados.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 495 of 1506 --

Tema 2: Temas de derecho civil
Derecho uniforme: Mediante este método a través de normas de derecho material establecidas
por un tratado o acuerdo internacional, se regulan las relaciones jurídicas que los particulares
desarrollan a nivel internacional.
Conflictos de competencia judicial: Consiste en decidir la competencia conforme a las leyes proce
sales propias (/ex fori) y después si el asunto lo requiere aplicar las leyes sustantivas correspon
dientes, incluso extranjeras si es necesario. Hacerlo así es actuar jurídicamente bien e im partir
justicia en cada caso concreto.
7. Reconocimiento de sentencias extranjeras
Si bien el Perú reconoce a las sentencias extranjeras el mismo valor y fuerza que a las nacio
nales, cuando se traten de sentencias que resuelvan asuntos contenciosos que se pretendan
ejecutar en el país, se exige que las mismas sean vistas previamente por las cortes peruanas
a fin de que éstas otorguen una resolución judicial de reconocimiento. Esto es lo que en la
doctrinase llama exequátur.
Reconocimiento del Tribunal Extranjero. Condición de reciprocidad.
Las normas de Derecho Internacional Privado obligan a evaluarsi el tribunal que lo dictó
da valor a las sentencias de los jueces del Perú.
El artículo 2i03°y el inciso 8 del artículo 2104o indican que no tendrá valoren el país la sen
tencia que proceda de un Estado que no da cumplimiento a los fallos de los tribunales pe-
ruanosy las de aquéllos en que para darle cumplimiento se revisa el fondo de la resolución.
El Perú se ubica entre los estados que sí admiten la ejecución de sentencias extranjeras,
pero que condicionan la ejecución de reciprocidad.
Reconocimiento del fallo extranjero. Una vez determ i nado que el fallo procede de un tribu
nal cuyas resoluciones pueden ser ejecutadas en el país, deberá evaluarse si cumple las otras
condiciones que la señala la ley peruana para que pueda ser reconocido en el Perú.
El Tribunal extranjero cuya resolución se pretende ejecutar debe haber sido competente para
conocer el asunto, de acuerdo con sus normas de derecho internacional y con los principios
generales de competencia procesal internacional.
Es necesario que se haya citado al demandado conforme a la ley del lugar del proceso, que
se la haya concedido plazo razonable para comparecer y que se la haya otorgado garantías
procesales para defenderse.
Que la sentencia tenga la autoridad de cosa juzgada según las leyes del lugar en que fue dic
tada. No se puede ejecutar una sentencia que pueda ser materia de recursos impúgnatenos y
que, por lo tanto, sea susceptible de ser revocada.
Que la sentencia extranjera no debe ser contraria al orden públicoy buenas costumbres.
8. Condiciones de las sentencias extranjeras para su reconocim iento y ejecución en el
Perú
En nuestro sistema sólo se verifica aspectos de forma a fin de establecer garantías procesales
a las partes implicadas en el proceso, a excepción de una de las condiciones referidas al orden pú-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 496 of 1506 --

blicoy a las buenas costumbres que está referida al análisis del fondo. Pasaremos a analizar los
requisitos que debe reunir un fallo extranjero.
Que la sentencia extranjera no resuelva sobre asuntos de competencia peruana exclusiva (inciso i
del artículo 2 1 0 4 °).
Referida a la competencia jurisdiccional de nuestros tribunales, específicamente a la
competencia jurisdiccional exclusiva que son aquellas que no toleran la competencia ju
risdiccional de un tribunal extranjero. El artículo 2058 del Código Civil establece en qué
casos los tribunales peruanos tienen competencia exclusiva llamada también obligatoria
estando referidas a acciones relativas a derechos reales sobre predios situados en el Perú,
un caso referido a la existencia de acciones civiles derivadas de delitos o fallos perpetua
dos en el Perú o cuando sus resultados se hayan producido en el Perú y en los casos refe
ridos a la sumisión de ambas partes a la jurisdicción de los tribunales peruanos.
También se considera que los tribunales peruanos tienen competencia exclusiva en liti
gios referentes a buques de bandera peruana a menos que ambas partes o, la parte que
pudiera invocar la jurisdicción de los tribunales peruanos hayan renunciado a ella No se
puede abandonar al conocimiento de los tribunales extranjeros aquellos litigios donde
el demandado tenga su domicilio en el Perú a menos que la parte que pudiera invocar la
jurisdicción peruana haya renunciado a su derecho.
En otros aspectos tratándose de sentencias arbítrales extranjeras se debe tomar en cuenta
que existen ciertos asuntos que no, pueden ser objeto de arbitraje, es decir que para que
una sentencia arbitrable extranjera pueda ser reconocida y ejecutada en el Perú debe ha
ber resuelto un caso considerado arbitrable.
Que la sentencia extranjera haya sido dictada por un tribunal extranjero competente según sus
normas de derecho internacional privado y los principios generales de competencia internacional
(inciso 2 del artículo 210 4 o) .
Se refiere a las reglas de competencia jurisdiccional se debe tener en cuenta que cada
tribunal aplica sus propias reglas de competencia jurisdiccional para declararse compe
tente o incompetente respecto a u asunto. Es por ello que nuestros tribunales se obligan
a examinar las reglas de competencia jurisdiccional extranjera a fin de saber si el tribunal
extranjero que emitió sentencia tenía competencia según sus propias normas.
Para mayor seguridad nuestros tribunales tendrán que examinarsi el asunto se encuentra
vinculado de una manera suficiente al tribunal extranjero que dictó sentencia.
Que se haya citado al demandado conforme a la ley de! lugar del proceso, que se le haya concedido
un plazo razonable para comparecer, y que se le hayan otorgado garantías procesales para defen
derse (inciso 3 del artículo 2104°).
Con esto se trata de evitar el fraude procesal. Existe fraude procesal en aquellos procesos
que sin haberse establecido la relación procesal entre el demandante y el demandado
existe una sentencia que favorece al demandante.
Es necesario verificar si el proceso en el extranjero ha respetado las garantías procesales
de defensa es decir que se haya respetado todos los términos del proceso conforme a las
leyes del lugar donde se lleva a cabo también que se hayan actuado todos los medios
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 497 of 1506 --

Tema 2: Temas de derecho civil
probatorios que se ha creído conveniente. Y que se haya tenido bien informado sobre el
estado del procedimiento en cada una de las etapas.
Que la sentencia tenga autoridad de cosa juzgada en el concepto de las leyes del lugar del proceso
(inciso 4, artículo 2104°).
La autoridad de cosa juzgada de las sentencias extranjeras en nuestro país la revisara con
los cánones de la ley peruana. Se considera que el punto de partida de la autoridad de la
cosa juzgada es conforme al país donde se emitió la sentencia debiéndose encuadrar esa
noción dentro del concepto de cosa juzgada del país que acoge la sentencia.
Se ha podido comprobarquea nivel internacional lacosajuzgada no se encuentra dotada
de un valor universal sino que tiene una validez relativa.
Que no exista en el perjuicio pendiente entre las mismas partes y sobre el mismo objeto iniciado con
anterioridad a la interposición de la demanda que origino la sentencia (inciso 5, artículo 2104o).
La litispendencia se basa en el principio en que no debe existir un juicio paralelo a otro
que ya se encuentra instaurado. La litispendencia internacional existe más de un orden
jurisdiccional que se encuentran implicados. Pues los tribunales que siguen cada uno el
proceso pertenecen a diferentes países lo que incidirá que la eficacia de la litispendencia
internacional sea relativa.
Existen en la doctrina internacional y de los estados para superar estos impases, por lo
que se han celebrado tratados internacionales y en defecto de estos tratados los estados
han elaborado reglas que normen sobre la litispendencia internacional como es el caso
del artículo 2066o del código civil peruano.
Tratándose de ejecutar una sentencia extranjeray existiendo juicio pendiente en nuestro
país el proceso, en el extranjero debe haber comenzado con anterioridad al proceso ins
taurado en el Perú En cambio si se comprueba la existencia de un proceso en el Perú ini
ciado con anterioridad al proceso extranjero que genero la sentencia extranjera entonces
no se otorgara el reconocimiento ni la ejecución a dicha sentencia extranjera.
Que la sentencia extranjera no sea incompatible con otra sentencia que reúne los requisitos de recono
cimiento y ejecución exigidos por la ley haya sido dictada anteriormente (inciso 6 del artículo 2104o) .
Se tiene preferencia por aquellas sentencias extranjeras que se aplican en virtud de los
tratados internacionales. Si bien se trata de uniformidad en los criterios para ejecutar las
sentencias extranjeras ello no debe perm itir a los tribunales peruanos revisar el fondo
de la sentencia extranjera bajo pretexto de que se encuentra incompatible con el fondo
de otra sentencia aplicada anteriormente Esta incompatibilidad con otras sentencias ex
tranjeras no está precisada por nuestro legisladory es difícil para los tribunales peruanos
el tratar de determinarlas.
Que la sentencia extranjera no sea contraria al orden público ni a las buenas costumbres (inciso 7
del artículo 210 4 o) ■
Está referido a que las sentencias extranjeras no deben ser contrarias al orden público
internacional, entendida esta como la idiosincrasia jurídica de un país. Esto quiere decir
que la sentencia extranjera no debe de atentar contra la idiosincrasia jurídica del Perú.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 498 of 1506 --

UBILEX
El artículo 2055° del Código Civil está referido a la intervención del orden público inter
nacional a nivel de los derechos adquiridos que debemos concordarlo con el inciso 7 del
artículo 2104o del Código Civil.
Debemos tener en cuenta que la intervención del orden público internacional en uno u
otro nivel es diferente en el ámbito de la creación de los derechos el orden público in
ternacional interviene excluyendo la ley extranjera y reemplazándola por la ley local en
cambio en el ámbito de los derechos adquiridos la intervención del orden público inter
nacional tendrá como efecto el rechazo a la ley extranjera contenida en una sentencia
extranjera, es decir, el rechazo de la sentencia extranjera La ley que contenga no debe
contrariara los valores y principios jurídicos sobre los que descansa nuestro ordenamien
to jurídico.
Que se pruebe la reciprocidad (inciso 8 artículo 2104).
Referida a la reciprocidad en cuanto al trato que deben tener las sentencias peruanas en
el país de donde proviene la sentencia extranjera.
El exequátur o procedimiento judicial para la homologación de sentencias extranjeras,
tiene por finalidad darle fuerza ejecutiva en el Perú al fallo pronunciado en el extranje
ro con el objeto de evitar la duplicidad judicial, en aras del principio internacional de la
reciprocidad o también denominado de cortesía nacional; en consecuencia, el inciso 8
del artículo 2104 del Código Civil debe ser interpretado en el sentido de que es la no reci
procidad la que determina la improcedencia del exequátury por lo tanto la que debe ser
acreditada por él que lo contradice, por lo que la falta de contradicción debe presumirse
iu rista n tu m (Ej. Supr. 20.04.1993 en Normas Legales T. 231, Trujillo. 19 95- RJ-10).
El segundo párrafo del artículo 2102o del Código Civil establece si no hay tratado con el
país en que se pronunció la sentencia, tiene ésta la misma fuerza que en aquel país se da
a las sentencias pronunciadas por los tribunales peruanos.
