UBILEX
DERECHO PROCESAL CIVI
El Derecho Procesal Civil es la rama de la ciencia jurídica que estudia la naturaleza, desenvolvi
miento y eficacia del conjunto de relaciones jurídicas, denominado proceso civil.
1. Principios del derecho procesal civil. Aplicación de los principios del derecho
procesal civil
Derecho a la Tutela Jurisdiccional. La noción del derecho a la tutela jurisdiccional efectiva im
plica, que cuando una persona pretenda la defensa de sus derechos o intereses legítimos, ella
deba ser atendida por un órgano jurisdiccional mediante un proceso dotado de un conjunto
de garantías mínimas (STC Exp. N° 0004-2006-AI/TC, 29/03/06, Fj. 6). Su contenido protegido
no se agota en garantizar el "derecho al proceso”, entendido como facultad de excitar la activi
dad jurisdiccional del Estado y de gozar de determinadas garantías procesales en el transcurso
de él, sino también garantiza que el proceso iniciado se desarrolle como un procedimiento
de tutela idóneo para asegurar la plena satisfacción de los intereses accionados (STC Exp. N°
0010-2001-AI, 26/08/03, Fj.10).
Principio de Dirección e Impulso Procesal. El principio de dirección representa la parte con
traria del Principio Dispositivo, por el cual el Juez era esencialmente pasivo, limitándose tan
sólo a observar la actividad de los sujetos procesales y resolver en consecuencia. Así, el Prin
cipio de Dirección se constituye en la manifestación pura del sistema Inquisitivo, por el que
el papel del Juez investiga los hechos valiéndose de todos los medios a su alcance con dicho
propósito; ello a fin deformarse una opinión y resolver el conflicto o la incertidumbre jurídica.
En ese sentido, el principio de impulso procesal se viene a constituir como un elemento de
dinamicidad dentro del proceso. Esto quiere decir que el Juez tiende agilizar el proceso, y con
ducirlo en forma independiente a los actos realizados por las partes.
Fines del Proceso e Integración de la Norma Procesal. En sentido concreto, el fin del proceso
es el hacer efectivo los derechos sustantivos al momento de la resolución de un determinado
conflicto de intereses o incertidumbre jurídica, mientras que la finalidad del proceso, en sen
tido abstracto, será el logro de la paz social en justicia.
En ese contexto, si en el desarrollo del proceso se advirtiera vacíos o deficiencias de la ley pro
cesal, dichas falencias serán integradas de tal forma que no se altere la persecución de los fines
antes indicados. De esta forma el Estado mantendrá la eficacia del ordenamiento jurídico en
general.
Principios de Iniciativa de Parte y de Conducta Procesal. El principio de iniciativa de parte
representa lo que en doctrina se conoce como condiciones de la acción, que a su se constituye
como aquellos presupuestos procesales indispensables para que el juzgador pueda pronun
ciarse válidamente sobre el fondo de la cuestión controvertida. Con ello nos referimos a la
exigencia que todo justiciable debe cum plir antes de acudir al órgano jurisdiccional y pre
tender la resolución de un conflicto de intereses o incertidumbre jurídica, en términos de un
pronunciamiento válido sobre el fondo del asunto. Nos referimos a ¡nterésy legitimidad para
obrar. El primero se materializa como la necesidad de solicitar tutela jurídica efectiva al Poder
