Tema 2: Temas de derecho civil
judicial como único y últim o medio válido para solucionar el conflicto de intereses o la situa
ción incierta en concreto. La segunda implica que el proceso se lleve a cabo entre los mismos
sujetos que integran la relación jurídica sustantiva o comúnmente denominada material. La
excepción de la exigencia de interésy legitimidad, que es la regla general, no es aplicable a las
entidades autorizadas para la defensa de intereses difusos o colectivos (el Ministerio Público,
por ejemplo).
De otro lado, el principio de conducta procesal implica aquella imposición a todos los sujetos
que intervienen en el proceso (las partes, sus abogados, etc.), de actuar con lealtad, probidad,
veracidad y buena fe. El juez está facultado para sancionar a los actores procesales que no
obren con sujeción a los valores procesales mencionados.
Principio de Inmediación, Concentración, Economía y Celeridad Procesal. En virtud al Prin
cipio de Inmediación el juzgador se encuentra en la obligación de mantener un trato directo e
inmediato con la actuación de las partes dentro del proceso (en las audiencias, por ejemplo),
respecto de los hechos alegados por éstos, de los medios probatorios que pudieran ofrecer, y
en general, respecto de toda las formas posibles de establecer un medio que permita al juez
arribar a una decisión fundada en la convicción real y natural como producto de la valora
ción de las actuaciones de las partes. Sin que ello signifique el incremento de las actuaciones
procesales, en razón a que el Principio de Concentración postula el desarrollo del proceso en un
menor uso posible de actos procesales, concentrándolos o agrupándolos en un solo acto, por
reiterativos o inútiles. No restringiéndolos o eliminándolos como proponed Principio de Econo
mía Procesal en razón a la inutilidad o a lo innecesario que pudiera resultar su desarrollo (esto
últim o no debe afectar el derecho de defensa ni a la realización de ciertos actos de obligatorio
cumplimiento). El Principio de Celeridad Procesal pregona la realización de los actos procesales
dentro de los plazos establecidos en la ley; de ese modo se constituye como un mecanismo
de control frente a las maniobras dilatorias, proponiendo la adopción de una determinada
medida o sancionándolas.
Principio de Socialización del Proceso. En virtud del cual el juez está en la obligación de cau
telar la igualdad entre las partes involucradas en el proceso, evitando así cualquier form a de
discriminación, por religión, idioma, sexo, etc.
juez y Derecho (fura N o v it C uria). Constituye aquella presunción de derecho según el cual el
juez conoce mejor el derecho que las partes, razón por la cual el juzgador se encuentra en la
obligación de aplicar la norma jurídica que corresponda a la situación concreta. Sin que ello
signifique un pronunciamiento ultra petita (más allá del petitorio). Su contrapeso resulta ser el
principio de congruencia.
Principio de gratuidad en el acceso a la justicia. Por este principio el Estado concede gratui
tamente la prestación jurisdiccional, sin perjuicio de que el litigante vencido totalm ente en
un proceso, en su caso, el litigante de mala fe, deba abonar las costas, costos y multas, de ser
el caso.
Principio de vinculación y de Formalidad. El primero de ellos enseña que las normas procesa
les, por ser de naturaleza de derecho público, tienen carácter imperativo, salvo las excepciones
señaladas en la propia ley. No es lo mismo decir de naturaleza de derecho público y de orden
público, pues la segunda de ellas es de carácter absoluto (vinculante), a diferencia de la prime-
