UBILEX
ra. El Principio de Formalidad porsu parte, establece que las— formalidades— previstas en la
ley procesal son imperativas; sin embargo, el Juez tiene la facultada para adecuar su exigencia
al logro de los fines del proceso. A falta de formalidad establecida, será válido cualquiera sea
la formalidad empleada.
Principio de Doble Instancia. Este principio presta seguridad y garantía a los litigantes, para
evitar errores judiciales y las conductas dolosas o culposas de los jueces de primera instancia,
en la emisión de las resoluciones judicialesy así mismo, se arguye que la revisión por el supe-
rior concede la posibilidad concreta de subsanar los errores procesales. Esto se hace viable,
según nuestra normatividad procesal, a través del recurso de apelación, y en algunos casos a
través del recurso de revisión.
Principio de Contradicción. Encuentra su sustento en el principio de bilateralidad, que signi
fica que cada una de las partes debe tener razonable oportunidad de audiencia y de prueba.
Esto se manifiesta en la información previa y oportuna de un acto procesal, a la parte contra
ria, a fin de que éste pueda hacer valersu derecho de defensa y rebatir la pretensión.
Principio de Adquisición. Significa que todos los instrumentos ofrecidos por las partes, des
de el momento en que son admitidos e incorporados al proceso, éstos dejan de pertenecer a
quienes los ofrecieron; convirtiéndose de ese modo, dichos instrumentos, en pertenencia del
proceso como instrumento público del órgano jurisdiccional.
Principio de Eventualidad. Al estar dividida la actividad procesal en etapas, los actos proce
sales de las partes deben corresponder a determinada etapa, fuera del cual (según los plazos
establecidos) carecen de validez dentro del proceso. A este principio también se le conoce con
el nombre de Preclusión.
Principio de Congruencia. Representa un principio que lim ita las facultades resolutivas del
Juez, al alcance de las peticiones formuladas por las partes; ello a fin de establecerse la exis
tencia de una identidad jurídica entre lo resuelto y las pretensiones, excepciones o defensas
deducidas oportunamente.
Principio de Publicidad. Además de representar una garantía de laAdm inistradón de justicia,
constituye un medio por el cual la imparcialidad que debe caracterizar al órgano jurisdiccio
nal, será expuesta de manera pública. Esto respecto de ciertos actos procesales (las audiencias,
por ejemplo) en las que cualquier interesado tendrá libre acceso.
Oralidad en el proceso civil. El CPC vigente no reconoce de manera expresa la aplicación del
modelo de oralidad. El grupo de trabajo constituido por Resolución Ministerial N° 0299-2016-
JUSsí ha incorporado la oralidad para un nuevo CPC, pero aun es un proyecto. En ese contexto,
la oralidad en el proceso civil peruano no se aplica por efecto de la ley, sino por iniciativa de
la judicatura de la especialidad, precedida del proyecto piloto para la modernización del des
pacho judicial en los juzgados civiles elaborado por el Centro de Estudios de Justicia de las
Américas (CEJA), aprobado por Resolución Administrativa N ° i24-2018-CE-PJ, en cuyo marco
se conformó la comisión nacional de implementación, supervisióny monitoreo de la oralidad
civil en el Poder Judicial a través de Resolución Administrativa N° 229-2019-CE-PJ.
La oralidad es una metodología vinculada al denominado case m am gem ent, entendido como
una gestión del caso donde además de resolver el conflicto, importa el tiempo y los costos
