invertidos, de modo que sin afectar el debido proceso, cada litigio merezca el tratam iento di
ferenciado que requiere.
Por Resolución Administrativa N° 015-2020-P-CE-PJ se aprueban diversos instrumentos nor
mativos de gestión, entre los que aparece el Reglamento de actuación para los módulos civiles
corporativos de litigación oral. Allí, el art. 11 señala que “si el juez decide expedir sentencia en
audiencia, “informará el fallo y las razones que justifican la decisión adoptada", con cargo a
que se incorpore luego la decisión por escrito".
Por Resolución Administrativa N°342-202i-CE-PJ, se aprueba la implantación del Expediente
Judicial Electrónico-Oralidad Civil, en su segunda fase, la que se aplicará en las Cortes Superio
res de Justicia de Arequipa, Junín, Puno y Callao; de igual manera, el 11.06.2022 se publicó la
Resolución Administrativa N° 213-2022-CE-PJ, por medio de la cual se aprueba la implantación
del denominado Expediente Judicial Electrónico así como la Mesa de Partes Electrónica en la
Corte Superior de Justicia de Cajamarca, que atienden procesos civiles bajo el alcance de la
Oralidad Civil.
Finalmente,el 4.05.2022se publicó la Ley N °31464, normaque modifica la regulación del pro
ceso de alimentos, a través de la cual se procura asegurar la adecuada y correcta aplicación del
principio del interés superior del niño y con ello lograr la asignación de una pensión de ali
mentos acorde a las necesidades del beneficiario. Esta ley modificó el art. 555 del CPC estable
ciendo, en la parte final, que después de actuados— en audiencia— los medios probatorios
referidos al asunto de fondo, el juez dará uso de la palabra a los abogados que lo soliciten y, de
manera inm ediatay oral, comunicará al actory al demandado el sentido del fallo; luego, den
tro de los cinco días posteriores, el juez notificará por escrito el íntegro de la sentencia. Siendo
esta reforma, una evidencia del avance en la iniciativa de la judicatura por im plem entar la
oralidad en el proceso civil a nivel nacional.
2. Reglas de com petencia del Proceso Civil (Ver en Derecho Procesal)
3. Acumulación
Es una figura procesal que consiste en la reunión en un solo proceso de dos o más sujetos ac
tuando en calidad de parte (demandante, demandada, o de ambos), o de reunir en un único
proceso dos o más pretensiones, o por últim o reunir en un solo proceso a más de un sujeto
actuando en calidad de parte con más de una pretensión.
De acuerdo con el artículo 83 del Código Procesal Civil tenemos que: “En un proceso pueden haber
más de una pretensión, o más de dos personas. La primera es una acumulación objetiva y la segunda una
acumulación subjetiva.
La acumulación objetiva y la subjetiva pueden ser originarias o sucesivas, según se propongan en la de
manda o después de iniciado el proceso, respectivamente.”
Conexidad: Según Ariana Deho “la conexión es el nexo q ue se puede establecer entre los diver
sos elementos identificadores de las pretensiones (personae, p e titu m y causa petendi).
El que la conexión entre pretensiones sea la base del fenómeno acumulativo lo testimonia la
presencia en el CPC del artículo 84, que a la letra establece: “Hay conexidad cuando se presentan
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 504 of 1506 --

elementos comunes entre distintas pretensiones o, por lo menos, elementos afines en ella". Pues bien,
los tipos de conexión que se pueden dar entre diversas pretensiones pueden ser dos: la cone
xión subjetivay la conexión objetiva.
La conexión subjetiva se da cuando el nexo entre las pretensiones se da en el elemento sub
jetivo (personae) en el sentido de que todas las pretensiones se plantean y se dirigen por y
contra los mismos sujetos (en buena cuenta: identidad de partes).
La conexión objetiva, por su parte, se da cuando el nexo se establece entre los elementos
objetivos de la pretensión (petitum y/o causa petendi). Ahora, respecto de la conexión ob
jetiva hay que distinguir dos modalidades, a saber.-
a) La conexión objetiva llamada “propia”: cuando el vínculo entre las pretensiones se da
entre los concretos elementos objetivos de la pretensión (petitum y /o causa petendi);
b) La conexión objetiva llamada "impropia”: cuando el vínculo no está propiamente entre
los elementos objetivos concretos de las pretensiones, sino cuando todas las preten
siones plantean la misma cuestión jurídica. Es llamada también conexión por a fin i
dad".
Adviértase que el concepto de conexidad que el Código asume está referido a la conexión im
propia, es decir, la existencia de elementos afines entre pretensiones distintas,y no a la cone
xión propia presente entre pretensiones que se derivan de un mismo título o causa (Monroy
Gálvez,l99 3, p. 47)
Clases de acumulación: Objetiva (pluralidad de pretensiones) y subjetiva (pluralidad de per
sonas). Ambas admiten, en cuanto a su fuente, que sea originaria (nace en la demanda) o
sucesiva (después del emplazamiento de la demanda). Esta clasificación se encuentra esta
blecida en el artículo 83 del C.RC.
1. Acumulación objetiva:
Acumulación objetiva originaria: (Art. 87 C.PC). Existen tres tipos de acumulación de
pretensiones: subordinada, alternativa y accesoria.
"En el caso que nos ocupa queda claro que se trata de una acumulación objetiva originaria, ai
haberse planteado una pretensión principal, como es la de disolución del vínculo matrimonial, y
c o m o pretensiones accesorias el ejercicio de la patria potestad, alimentos y separación de bienes
gananciales." Cas. N° 2887-2016 La Libertad. FJ. 4to.
a) Subordinada: El actor acumula una pretensión titu la ry una pretensión subordinada,
pues en el supuesto que la primera sea desestimada, el juez se pronunciará a conti
nuación por la segunda. La pretensión subordinada es expectaticia, porque si el juez
ampara la pretensión titu lar no se pronunciará por la condicionada.
