Tema 2: Temas de derecho civil
"En consecuencia, en este cipo de acumulación de pretensiones el sujeto Mular de las mismas Ídem:
tífica a una ds ellas como pretensión principal y a la otra como subordinada, esta identificación se
realiza precisamente porque las pretensiones resultan contradictorias en cuanto a susrfmdamen^
(os. En ese sentido, el órgano jurisdiccional que conozca de las pretensiones deberá pronunciamemm
el orden fijado por el demandante, primero por la pretensión principal y únicamente en ehsupuesto
en que ésta no prosperará, deberá pronunciarse respecto a la pretensión subordinada." Tas, N° S007-
2013-Lima. F-JMo,
b) Alternativa: El accionante acumula pretensiones de manera disyuntiva, a fin que el
demandado opte, en ejecución de sentencia, cum plir con la “pretensión a)” o la "pre
tensión b)”; en caso que no lo verifique será el actor quien lo realice. El juez no puede
elegir la pretensión, en aplicación del principio dispositivo.
c) Accesoria: La pretensión accesoria depende de la pretensión principal. Ejemplo, se
demanda la reivindicación (pretensión principal),asícomoel pago de frutos y el des
alojo accesorio (pretensiones accesorias).
Acumulación objetiva sucesiva (Art. 8 8 CPC): Son tres supuestos: La ampliación de la de
manda (segundo párrafo del Art. 428 CPC); reconvención (Art. 445 CPC); y, acumulación
de procesos (Art. 90 CPC) y cuando el demandado form ula el aseguramiento de la preten
sión futura.
Requisitos de la acumulación objetiva (Art. 85 CPC):
1. Las pretensiones sean de competencia del mismo Juez;
z. Las pretensiones no sean contrarias entre sí, salvo que sean propuestas en forma subordi
nada o alternativa;
3. Las pretensiones sean tramitables en una misma vía procedimental.
Se exceptúan de estos requisitos los casos expresamente establecidos en este Código y leyes
especiales.
También son supuestos de acumulación los siguientes:
a. Cuando las pretensiones sean tramitadas en distinta vía procedimental, en cuyo caso, las
pretensiones acumuladas se tramitan en la vía procedimental más larga prevista para al
guna de las pretensiones acumuladas.
b. Cuando las pretensiones sean de competencia de Jueces distintos, en cuyo caso la compe
tencia para conocer las pretensiones acumuladas corresponderá al órgano jurisdiccional
de mayor grado.
2. Acumulación subjetiva:
Acumulación subjetiva originaria y sucesiva (Art. 89 CPC). Es originaria, cuando la de
manda es interpuesta por varias personas o es dirigida contra varias personas. Es sucesiva,
cuando se trate de la incorporación, con posterioridad a la notificación de la demanda, de
alguna persona al proceso.
Requisitos de la acumulación subjetiva (Art. 86 CPC):
1. Las pretensiones deben provenir de un mismo título,
2. Las pretensiones se refieran a un mismo objeto o exista conexidad entre ellas.
