UBILEX
Además de los requisitos señalados en el art. 85 CPC, en cuanto le sean aplicables.
Desacumulación;
Cuando el Juez considere que la acumulación afecte el Principio de Economía procesal, por
razón de tiempo, gasto o esfuerzo humano, puede separar los procesos, los que deberán se
guirse independientemente, ante sus Jueces originales. (Art. 91 CPC).
4. Intervención de terceros
Tercero es una persona ajena a la relación jurídica procesal, en cuanto no es parte, pero tiene un
interésen el proceso. Una vez que el tercero es admitido, es considerado como un sujeto procesal.
La intervención de terceros atañe a la acumulación subjetiva sucesiva.
Clases: Voluntaria y forzosa. Es voluntaria cuando el tercero solicita su intervención en el pro
ceso; es forzosa cuando el tercero es llamado por las partes o el juez.
Intervención voluntaria
a) Coadyuvante. Conocida también como intervención adhesiva. El interés del tercero es
mediato. El artículo 97 del C.PC. lo define: Quien tenga con una de las partes una relación
jurídica sustantiva, a la que no deba extenderse los efectos de la sentencia que resuelva
las pretensiones controvertidas en el proceso, pero que pueda ser afectada desfavorable
mente si dicha parte es vencida, puede intervenir en el proceso como coadyuvante de
ella.
Ejemplo: La acción subrogatoria u oblicua (inciso 4 del Art. 1219 del C. C.y Art. 60 del CPC),
ejercitada por el acreedor quien toma conocimiento que su deudores demandado en un
juicio de reivindicación seguido por Cayo, juicio que se sigue en rebeldía; en este caso el
acreedor (tercero) puede auxiliar, coadyuvar en la defensa de su deudor a efectos que no
pierda su inmueble, protegiéndose al acreedor ante la eventualidad que su deudor pierda
parte de su patrimonio.
Esta intervención puede admitirse incluso durante el trám ite en segunda instancia. El co
adyuvante puede realizar los actos procesales que no estén en oposición a la parte que
ayuda y no impliquen disposición del derecho discutido. V. gr., este tercero no puede
allanarse a la pretensión, conciliar o transigir, pero sí podrá ofrecer medios probatorios,
interponer medios impugnatorios.
"(...) el tercero coadyuvante no puede ser considerado como litisconsorte. Ambas figuras se dife
rencian en que el artículo 98 del Código Procesal Civil exige que el tercero se considere titular de
una relación jurídica sustancial a la que presumiblemente deban extenderse los efectos de una
sentencia, y por tal razón, estuviera legitimado para demandar o haber sido demandado en el
proceso." Exp. N° 929-2002.
b) Intervención litisconsorcial. El tercero invoca ser titu la r de una relación jurídica sustan
tiva a la que presumiblemente deban extenderse los efectos de una sentencia, y que por
tal razón estuviera legitimado para demandar o haber sido demandado en el proceso,
pudiendo intervenir como litisconsorte de una parte, con las mismas facultades de ésta
(A rt 98).
506 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 507 of 1506 --

Tema 2: Temas de derecho civil
Estrictamente, no se debe confundir la intervención litisconsorcial con el litisconsorte.
Aquél siempre es un tercero, pues en la relación jurídica procesal no es el actor o deman
dado; en cambio, un litisconsorte siempre es parte.
Ejemplo: XIMEX S.A.C. celebra un contrato de asociación en participación con un famoso
nadador (asociado), a efectos que se use comercialmente su nombre e imagen. Ocurre
que un menor muere en la piscina. Los padres (herederos) demandan una indemnización
por dañosy perjuicios a la mencionada empresa. El asociado tiene un interés en el juicio,
pues si bien no fue demandado, si se declarara fundada la demanda, sus ganancias van a
verse mermadas.
Esta intervención puede ocurrir incluso durante el trámite en segunda instancia.
c) Intervención excluyeme principal. El interés del tercero se encuentra en oposición a las
partes, en cuanto aquél pretende, en todo o en parte, ser declarado titu lar del derecho
discutido. Su intervención sólo se admite hasta antes de la expedición de la sentencia de
primera instancia (Art. 99 CPC).
Ejemplo: Cuando un tercero tiene interés en una concurrencia de acreedores inmobiliarios,
aquél sol icita q ue sea declarado mejor propietario frente a las partes (Art. 1135 del Código Civi I).
El excluyente actuará como una parte más en el proceso. Si ofreciera prueba, ésta se su
jetará al trám ite propio del proceso en que comparece, otorgándose similares facultades
probatorias a las partes. La intervención del excluyente no suspende el proceso, pero sí la
expedición de la sentencia.
Ejemplo: Alberto y Aramis discuten la propiedad de un automóvil en un proceso. Trami
tándose éste aparece Rodolfo solicitando al juez lo incorpore al proceso, dado que él es el
verdadero dueño del automóvil. Como se advierte, Rodolfo-excluyente principal- tiene
una pretensión propia que, además, es contraria a la posición de las partes.
d) Intervención excluyente de propiedad o de derecho preferente. Conocido también
como tercería, tramitándose como proceso abreviado; los demás tipos de intervención
de terceros siguen el trám ite y la competencia del juez originario.
La intervención excluyente principal de propiedad, el tercero pretende se le reconozca su
derecho en oposición a los litigantes, como consecuencia de alguna medida cautelar eje
cutada sobre un bien de su propiedad.
La intervención de derecho preferente, el tercero pretende que se le reconozca derecho
preferente respecto a lo obtenido en la ejecución forzada.
Ejemplo i: Rocío demanda ejecutivamente a Roco y obtiene una medida cautelar de se
cuestro sobre el vehículo que hace unas semanas vio manejando a éste. Sin embargo, el
vehículo ya no es de propiedad de Roco a la fecha de la realización del secuestro, sino de
Damian quien lo adquirió de aquél y a quien lo desposeyeron del mismo en ejecución del
secuestro. Damian, premunido de su título de propiedad, se apersona al proceso y pide
se deje sin efecto la orden de secuestro sobre su vehículo. Ésta es una intervención exclu
yente de propiedad.
E jem plo2; Financiera Rental demanda a la empresa Servicios S.A. y pide un embargo en
forma de intervención en administración sobre su local industrial. Sin embargo, antes de
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 508 of 1506 --

la ejecución del embargo, Servicios SA había suscrito un contrato de gestión y adminis
tración por el que le había cedido la gestión y la administración de su local industrial a la
empresa Rasta EIRL. Ésta, afectada por el embargo en intervención, solicita al juez se le
otorgue preferencia sobre la administración del local industrial dado que su contrato se
encuentra inscrito y es oponible a terceros. Ésta es una intervención excluyente de dere
cho preferente.
Intervención forzosa
a) Denuncia civil. Es aquel acto procesal que permite al demandado incorporar al proce
so a un tercero, porque éste tiene alguna obligación o responsabilidad (artículos 102 y
103). V. gr., el Art. 1498 del Código Civil prescribe: Promovido juicio de evicción, queda el
adquirente obligado a solicitar, dentro del plazo para contestar la demanda, que ésta se
notifique al transfe rente que él designe. Ese pedido que hace el demandado a fin que se
notifique de la demanda al transferente (tercero), constituye una denuncia civil. De per
der el juicio el demandado, surtirán efecto las obligaciones de saneamiento por evicción.
El demandado en su denuncia debe indicar el nombre y dom icilio del tercero. Si el juez
considera procedente la denuncia, emplazará al denunciado con las formalidades esta
blecidas para el emplazamiento de la demanda, concediéndolo un plazo no mayor de 30
días para que intervenga en el proceso, lapso durante el cual se produce la suspensión
legal del juicio.
Una vez emplazado, el denunciado será considerado como litisconsorte del denunciante
y tendrá las mismas facultades que éste.
La sentencia resolverá, cuando fuera pertinente, sobre la relación sustancial entre el de-
nunciantey el denunciado.
b) Aseguramiento de una pretensión futura. Es una modalidad de la denuncia civil, y tiene
la particularidad de aplicarse cuando la parte que considere tener derecho para exigir de
un tercero una indemnización por el dañoy perjuicio que pudiera causarle el resultado de
un proceso, o derecho a repetir contra dicho tercero loque debiera pagaren ejecución de
sentencia, puede solicitar el emplazamiento del tercero con el objeto de que en el mismo
proceso se resuelva, además, la pretensión que tuviera contra él (Art. 104 del C.RC.).
c) Llamamiento posesorio. También es otra modalidad de denuncia civil ubicada dentro el
ámbito posesorio. Ejemplo-, Se interpone una demanda de desalojo por ocupante preca
rio contra el guardián del inmueble, siendo que el verdadero poseedor es otro.
El artículo 105 del C.RC. desarrolla esta institución en los siguientes términos: “Quien te
niendo un bien en nombre de otro, es demandado como poseedor de él, debe expresarlo
en la contestación a la demanda, precisando el domicilio del poseedor, bajo apercibi
miento de ser condenado en el mismo proceso a pagar una indemnización por los daños
y perjuicios que su silencio cause al demandante, además de una multa.
Si el citado comparece y reconoce que es poseedor, reemplazará al demandado, quien
quedará fuera del proceso. En este caso, el juez emplazará con la demanda al poseedor.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 509 of 1506 --

Tema 2: Temas de derecho civil
d)
Si el citado no comparece, o haciéndolo niega su calidad de poseedor, el proceso conti
nuará con el demandado, pero la sentencia surtirá efecto respecto de éste y del poseedor
por él designado.”
Por otro lado, hay otra forma de llamamiento posesorio, y que es la prevista en materia de
desalojo (Art 587 C.RC). La particularidad es que la denuncia aquí lo debe realizar el actor.
Llamamiento en caso de fraude o colusión. La incorporación lo efectúa el juez, cuando pre
suma fraude o colusión entre las partes y que afecté los intereses de un tercero. Realmente
constituye una facultad del juez, enmarcada dentro del principio de autoridad. Para tal efecto,
el juez puede suspender el proceso por un plazo no mayor a 30 días (Art. 106 del C.PC.).
5. Litisconsorcio
Hay litisconsorcio cuando dos o más personas litigan en forma conjunta como demandantes
o demandados, porque tienen una misma pretensión, sus pretensiones son conexas o porque
la sentencia a expedirse respecto de una pudiera afectar a la otra.
Clasificación: Activa (varios demandantes), pasiva (varios demandados) y mixta (varios de
mandantes y demandados); necesaria y facultativa.
Litisconsorcio necesario: En general, el litisconsorcio se presenta cuando en un proceso
existen varios demandantes y/o demandados; en esta acumulación subjetiva hay real
mente una pluralidad de sujetos considerados como parte. De acuerdo a la obligatorie
dad o no de su conformación, el litisconsorcio puede ser necesario o facultativo.
En el litisconsorcio necesario es obligatoria la pluralidad de sujetos para la conformación
de la relación jurídica procesal válida, porque los efectos de la sentencia van a afectar de
manera uniforme a todos los litisconsortes, sea por expresa disposición legal (litisconsor
cio propio) o por la naturaleza de la pretensión (litisconsorcio impropio).
El Juez puede integrar a la relación procesal en los casos de litisconsorcio necesario (Art.
95 del C.RC.).
"El litisconsorcio necesario permite la integración, de varias personas en la posición de una
w ^ sola parte, requiriéndose: que todos los sujetos de la relación jurídico material subyacente, al
proceso estén presentes en el proceso, bajo pena de que no pueda proferirse una sentencia de
] 9 H H h fondo realmente útil. Su participación implica que los sujetos integren una sola parte, que ac-
H H p j túen unidos, por lo que las peticiones procesales que realice un litisconsorte con independen
cia de los otros, incluyendo los recursos interpuestos, favorecerán a toda la parte y no de forma
exclusiva a la persona que realice la actuación correspondiente. De otra parte, la disposición
del Derecho no es posible si no, proviene de todos los litisconsortes necesarios. Se trata del litisconsorcio por
antonomasia, ya que la idea es, no de una posible reunión de sujetos, sino de la exigencia de convocar a todos
los interesados en el mismo fallo, por la eficacia que para ellos tiene lo resuelto en un solo proceso. La ausen
cia de un litisconsorte necesario origina la invalidez de la relación procesal." Cas. N ° 719-2006-Pimo.
Supuestos del litisconsorcio por origen normativo:
a) Patrimonio autónomo cuando es considerado como parte demandada (sociedad de ga
nanciales, copropiedad, sucesión indivisa, fideicomiso), debe emplazarse a todos sus
conformantes (Art. 65 del C.RC.).
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 509

-- 510 of 1506 --

UBILEX
b) Separación de cuerpos y divorcio por causal (Art. 481 del C.RC. La demanda debe seguirse
contra el cónyuge culpabley el Ministerio Público).
c) Acción contestatoria de la paternidad (Art. 369 del C. C. La demanda debe entenderse
contra ei hijo y la madre).
d) Acción contestatoria de la maternidad (Art. 372 del C. C.). La demanda debe entenderse
contra el hijo y el padre).
e) Filiación planteada por el hijo (Art. 373 del C. C.). La demanda debe seguirse contra el
padre y la madre o los herederos.
f) Interdicción (Art. 581 del C.RC.), se dirige contra la persona cuya interdicción se pide, así
como con aquellas que teniendo derecho a solicitarla no lo hubieran hecho.
g) Tercería excluyente de propiedad o de derecho preferente (Art. 533 del C.RC.), la demanda
debe entenderse contra el demandantey demandado.
h) Acción petitoria de herencia (Art. 664 del C. C.). La demanda debe entenderse contra los
herederos.
i) Partición judicial (Art. 865 del C.C.). La demanda debe seguirse contra todos los sucesores.
j) Retracto (Art. 496 del C.RC.). La demanda se interpone contra el enajenante y el adqui
riente del bien que se intenta retraer.
Supuestos por la naturaleza de la pretensión: Las normas expresamente no señalan el na
cimiento del litisconsorcio necesario, pero la naturaleza de la pretensión hace obligatorio su
constitución, pues los efectos de la sentencia van a afectara los sujetos que participaron en la
relación jurídica sustantiva.
a) Acción revocatoria (se infiere del Art. 195 del C.C.). La demanda debe entenderse contra el
deudoryel adquiriente que cometieron el fraude del acto jurídico.
b) Acción de simulación (se infiere del Art. 193 del C.C.). La demanda debe entenderse con
quienes celebraron el acto jurídico objeto de la simulación.
c) Rescisión de contrato (se infiere del Art. 1370 del C.C.). Si la contraparte está constituida
por varias personas, la demanda debe entenderse con todos el los.
d) Resolución de contrato (se infiere del Art. 1371 del C. C.). Si la contraparte está constituida
por varias personas, la demanda debe entenderse con todos el los.
Efectos: Para conciliar, transigir se requiere la conformidad de todos los litisconsortes; la sen
tencia afecta uniformemente para todos ellos; basta la interposición del recurso porcualquier
litisconsorte, para que beneficie a los demás.
- Litisconsorcio facultativo: No es obligatoria la conformación del litisconsorcio. Los litiscon
sortes facultativos son considerados como litigantes independientes. Los actos de cada uno
de ellos no favorecen ni perjudican a los demás, sin que por ello se afecte la unidad de proceso
(artículo 9 4 )-
Ejemplo: Se produce un lamentable accidente de tránsito, habiendo varios agraviados. Un gru
po de ellos voluntariamente decide interponerconjuntamente la demanda; pudieron haberlo
hecho de manera independiente.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 511 of 1506 --

Tema 2: Temas de derecho civil
“El litisconsorcio facultativo llamado también voluntario se presenta cuando una persona que
tiene interés propio y particular interviene en el proceso ya sea como demandante o como de- :
mandado, proponiendo sus pretensiones procesales, sin embargo, dichas pretensiones no obli
gan ai litisconsorte voluntario a intervenir en el proceso, aunque pueden ser afectados con la
decisión del Juez". Cas. N° 2478-2006-Callao.
Efectos-. Para conciliar, transigir no se requiere la conformidad de todos los litisconsortes, bas
tando que uno de ellos lo realice para que el proceso concluya para él; la sentencia se pronun
cia por la situación jurídica de cada litisconsorte; la interposición del recurso sólo beneficia
para el litisconsorte que lo interpuso.
6. Intervención del Ministerio Público
El Código Procesal Civil admite la diferenciación funcional, en atención a que éste actúe como
parte o como autor de un dictamen, esto es, entre fiscal parte y fiscal dictaminador. También
admite su actuación como tercero legitimado, pero sólo en los casos que por ley se le cite.
Como parte: El Ministerio Público asume lacondición de parte, de manera especial, porque su
interés no es privado sino que actúa en defensa de la legalidad. La legitimación del Ministerio
Público es extraordinaria, pues parte de la imposibilidad práctica de la defensa individual del
Derecho subjetivo, pues, se orienta a la protección de intereses públicos.
Como tercero con interés: Puede intervenir en casos en que la ley expresamente lo cite.
Como dictaminador: Cuando es dictaminadorsu intervención es apreciada por algunos secto
res de la doctrina, como asesoría al órgano jurisdiccional; sin embargo, esa explicación supone
alterar todo el sistema de actuación jurisdiccional basado en el conocimientoy aplicación del
Derecho objetivo. Opera una situación intermedia, el interés público no llega al extremo de
legitimar al Ministerio pero la existencia de aquel hace conveniente que el juez tenga conoci
miento de cuál es la opinión del Ministerio Público en el extremo concreto.
7. La curadoría procesal
Hinostroza Mínguez señala que el curador procesal es aquella persona designada por el Juez
para comparecer en un proceso en lugar de la parte o de su representante legal por no tener
éstos capacidad procesal o no poder hacerla efectiva. El nombramiento necesariamente re
caerá en un abogado.
El antecedente legislativo del curador procesal lo tenemos en el derogado Código de Procedi
mientos Civiles bajo la figura del Defensor de Ausentes.
El artículo 6i°d e l Código Procesal Civil prescribe que el curador procesal es un abogado nom
brado por el Juez a pedido de interesado, que interviene en el proceso en los siguientes casos:
i. Cuando no sea posible emplazar válidamente al demandado por ser indeterminado, in
cierto o con dom icilio o residencia ignorado, según lo dispuesto por el artículo 435°;
z. Cuando no se pueda establecer o se suspenda la relación procesal por restricción de la
capacidad de ejercicio de la parte o de su representante legal;
3. Cuando exista falta, ausencia o impedimento del representante de la persona con capaci
dad de ejercicio restri ngida, según lo dispuesto por el artículo 6 6 ; o
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 512 of 1506 --

4 . Cuando no comparece el sucesor procesal, en los casos que así corresponda, según lo dis
puesto por el artículo 108°
Concluye la actuación del curador procesal si la parte o su representante legal comparecen al
haber adquirido o recuperado su capacidad procesal.
El artículo 6 6 ° del Código acotado señala que en caso de falta, ausencia o impedimento del
representante del incapaz, se aplican las siguientes reglas:
1. Cuando persona con capacidad de ejercicio restringida no tenga representante legal o
éste estuviera ausente y surja la necesidad de comparecer en un proceso, lo expondrá así
al Juez para que le designe curador procesal o confirme al designado por él, si lo considera
idóneo;
2 . Cuando la demanda se dirija contra una persona con capacidad de ejercicio restringida
que carece de representante o éste se halle ausente, el Juez le nombrará un curador pro
cesal o confirmará el propuesto por la persona con capacidad de ejercicio restringida, si lo
considera idóneo.
3. El Juez nombrará curador procesal para la persona con capacidad de ejercicio restringi
da que pretenda demandar a su representante legal, o que sea demandado por éste, o;
confirmará el propuesto por la persona con capacidad de ejercicio restringida, si fuera
idóneo.
4. También se procederá al nombramiento de curador procesal cuando el Juez advierta la
aparición de un conflicto de intereses entre la persona con capacidad de ejercicio restrin
gida y su representante legal, o confirmará el propuesto por la persona con capacidad de
ejercicio restringida.
El artículo 79 in fine del Código acotado señala que en caso de muerte o declaración de ausen
cia, determinación de restricción de la capacidad de ejercicio del representante o del apode
rado, remoción o cese de nombramiento o del representante legal de un incapaz y circunstan
cias análogas, se suspenderá el proceso por un plazo máximo de 30 días, mientras se designa
representante o curador procesal.
8. Procuración oficiosa (Art. 81 C.P.C.)
Es un supuesto de legitimación extraordinaria, pues una persona no teniendo poder, compa
rece en nombre de otra, alegando que ésta se encuentra impedida de hacerlo por sí misma;
estuviera ausente del país, tenga razones de fundado temor o amenaza, se trate de una situa
ción de emergencia o de inminente peligro o cualquier otra causa análoga y desconociera la
existencia de representante con poder suficiente.
Los actos procesales que realice el procurador oficioso deben ser ratificados por quien se com
parece, dentro de los dos meses siguientes de su participación. La ratificación no puede ser
parcial o condicionada.
Si no se produce la ratificación, se declarará por concluido el proceso, y se podrá condenar a
al procurador oficioso al pago de daños y perjuicios, así como a las costas y costos, quedando
ello a criterio del juez.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 513 of 1506 --

sema 2: Temas de derecho civil
9. Representación de los intereses difusos
También, es otro supuesto de legitimación extraordinaria. Para entender esta institución es
imprescindible dilucidar las clases de intereses procesales, que son el intersubjetivo, el colec
tivo y el difuso.
El interés intersubjetivo: Se encuentra ligado inmediatamente a la relación jurídica que la
sustenta, como es el interés del comprador frente a su vendedor, pues éste no le otorga la es
critura pública que se obligó, no teniendo otro camino que acudir al órgano jurisdiccional.
El interés colectivo: Es determinado, se encuentra circunscrito a un grupo, como es el caso de
los gremios sindicales o empresariales.
El interés difuso: Es aquel cuya titularidad corresponde a un conjunto indeterminado de per
sonas, respecto de bienes de inestimable valor patrimonial, tales como el medio ambiente o
el patrimonio cultural o histórico o del consumidor.
El interés difuso es de carácter indeterminado, y, es de la últim a generación de los intereses
procesales (Art. 82 C.RC.). Protege a bienes de inestimable valor patrimonial, tales como la
defensa del medio ambiente, de bienes o valores culturales o históricos o del consumidor. Tie
nen legitim idad en este proceso, el Ministerio Público, los Gobiernos Regionales, los Gobier
nos Locales, las Comunidades Campesinasy/o las Comunidades Nativas en cuya jurisdicción
se produjo el daño ambiental o al patrimonio cultural y las asociaciones o instituciones sin
fines de lucro que según la Leyy criterio del Juez, este últim o por resolución debidamente mo
tivada, estén legitimadas para ello. Las Rondas Campesinas que acrediten personería jurídica,
tienen el mismo derecho que las Comunidades Campesinas o las Comunidades Nativas en los
lugares donde éstas no existan o no se hayan apersonado a juicio.
Si se promueven procesos relacionados con la defensa del medio ambiente o de bienes o va
lores culturales, sin la intervención de los Gobiernos Locales indicados en el párrafo anterior, el
Juez deberá incorporarlos en calidad de litisconsortes necesarios, aplicándose lo dispuesto en
los Artículos 93 a 95 del C.RC.
Supletoriamente se aplican las normas sobre acumulación subjetiva de pretensiones (Art. 89
C.RC.). En caso que la sentencia no ampare la demanda será eleva en consulta a la Corte Su
perior. La sentencia definitiva que declare fundada la demanda será obligatoria además para
quienes no hayan participado del proceso, lo cual constituye una excepción a los efectos sub
jetivos de la cosa juzgada.
La indemnización que se establezca en la sentencia, deberá ser entregada a las M unicipalida
des Distrital o Provincial que hubieran intervenido en el proceso, a fin de que la emplee en la
reparación del daño ocasionado o la conservación del medio ambiente de su circunscripción.
10. Prueba anticipada (Arts. 284 a 299 C.P.C.)
La prueba anticipada tiene dos finalidades:
a) Actuar por motivos justificados, una prueba antes del proceso.
b) Otorgar mérito ejecutivo a la absolución de posiciones y al reconocimiento de documen
tos.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 513

-- 514 of 1506 --

UBILEX
Admisibilidad y procedencia:
Se tram ita como proceso no contencioso. La competencia por razón de grado, cuantía y terri
torio, corresponde al juez que va a conocer la demanda próxima a interponerse (artículos 33 y
297C.RC.).
Es fundamental que el solicitante exprese la pretensión genérica que va a reclamary la razón
que justifica su actuación anticipada (artículo 284 in fine, C.RC).
Las disposiciones relativas a la actuación de los medios probatorios se aplican, en cuanto sean
pertinentes, a la prueba anticipada.
El emplazamiento puede ser con citación (que es lo normal) o sin citación (inaudita parte), sus
tentado en razones de garantía y seguridad, especificando el petitorio de la futura demanda
(artículo 287 C.RC.).
Entre los artículos 290 a 295 del C.RC. se precisan los supuestos de los medios probatorios que
se pueden actuar anticipadamente.
El emplazado sólo puede oponerse fundándose en que la solicitud no reúne los requisitos ge
nerales indicados en el artículo 284 C.RC. (ausencia de la pretensión genérica de lo que se va a
reclamary la razón que justifica su actuación anticipada), además de los especiales del medio
probatorio solicitado o si la actuación fuese imposible.
Apercibimientos:
Si el emplazado no cumpliera con lo solicitado, se aplicarán los siguientes apercibimientos
(Art. 296 C.RC.):
a) En el reconocimiento se tendrá por verdadero el documento.
b) En la exhibición se tendrá por verdadera la copia presentada o por ciertas las afirmaciones
concretas sobre el contenido del documento; y,
c) En la absolución de posiciones se tendrán por absueltas en sentido afirmativo las pregun
tas del Interrogatorio presentado.
Sobre estos apercibimientos, realmente deben entenderse que su objetivo es para dar mérito
ejecutivo en los supuestos a) y c); el literal b), no tiene cabida, según las clases de títulos eje
cutivos tipificadas en los Incisos 6 y 7 del artículo 688 C.RC.
Finalmente, actuada la prueba anticipada, se entregará el expediente al interesado, conser
vándose copia certificada de éste en el archivo del juzgado, a costo del peticionante y bajo
responsabilidad del secretarlo de juzgado.
11. Cuestiones probatorias
La cuestión probatoria es un medio de defensa que se opone contra el ofrecimiento de medios
probatorios típicos o atípicos de la contraparte. Fundamentada en el principio de contradic
ción.
Clases
Tacha y oposición: Se tachan los testigos y los documentos. Se opone a la actuación de una
declaración de parte, a una exhibición, a una pericia o a una inspección judicial.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 515 of 1506 --

Tema 2: Temas de derecho civil
Admisibilidad de la tacha y de la oposición:
La cuestión probatoria se interpone en el plazo que establece cada vía procedimental, con
tado desde notificada la resolución que los tiene por ofrecidos, precisándose con claridad los
fundamentos en que se sustentan y acompañándose la prueba respectiva. La absolución debe
hacerse de la misma maneray el mismo plazo, anexándose los medios probatorios correspon
dientes. En ambos casos, cuando no se cumplan con los requisitos indicados, serán declaradas
inadmisibles, concediéndose un plazo no mayor de tres días para subsanar los defectos.
Estos requisitos no se exigen a las absoluciones realizadas en el proceso sumarísimo. La actua
ción de los medios probatorios se realiza en la audiencia de pruebas, iniciándose ésta por la
actuación de las cuestiones probatorias.
Se advierte que el medio probatorio cuestionado será actuado, sin perjuicio de que su eficacia
sea resuelta en la sentencia, salvo decisión debidamente fundamentada e inimpugnable (Art.
301 del CPC).
Conocimiento sobreviniente y sanciones:
El conocimiento sobreviniente es una oportunidad excepcional de plantear la cuestión pro
batoria, cuando se tiene conocimiento de la causal de tacha u oposición con posterioridad al
plazo para interponerla. Es necesario acompañar el documento que lo sustente. El juez, sin
otro trámite que el conocimiento de la otra parte, apreciará el hecho al momento de senten
ciar (Art. 30Z CPC).
Al litigante que maliciosamente formule tacha u oposición, se le impondrá una m ulta no me-
nordetres ni mayorde diez URR sin perjuicio de las costasy costos desutram itación (Art. 304
CPC).
12. Interrupción del proceso (Art. 317 CPC)
La declaración de interrupción tiene por efecto cortar el plazo o diferir el térm ino para reali
zar un acto procesal, produciendo la ineficacia de la fracción del plazo o difiriendo el térm ino
transcurrido.
La interrupción será declarada porel Juezen resolución inimpugnable, de oficio o a pedido de par
te, sustentándola en la ocurrencia de un hecho imprevisto o que siendo previsible es inevitable.
El plazo para solicitar la declaración de interrupción vence al tercer día de cesado el hecho
interruptivo.
13. Suspensión del proceso (Art. 318 CPC)
La suspensión es la inutilización de un período de tiempo del proceso o de una parte del plazo
concedido para la realización de un acto procesal.
Se puede declarar la suspensión del proceso, de oficio o a pedido de parte, en los casos previs
tos legalmente, y cuando a criterio del juez sea necesario.
Suspensión convencional: La suspensión acordada por las partes requiere aprobación ju d i
cial. Se concede sólo una vez por instancia y no puede ser mayor de dos meses en cada caso
(Art. 319 CPC).
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 516 of 1506 --

UBILEX
Suspensión legal y judicial: Se puede declarar la suspensión del proceso, de oficio o a pedido
de parte, en los casos previstos legalmente o cuando a criterio del juez sea necesario.
El juez a pedido de parte, suspende la expedición de la sentencia en un proceso siempre que
la pretensión planteada en él dependa directamente de lo que debe resolver en otro proceso
en el que se haya planteado otra pretensión cuya dilucidación sea esencial y determinante
para resolver la pretensión planteada por él. Para ello es necesario que las pretensiones sean
conexas, a pesar de lo cual no puedan ser acumuladas, caso contrario, deberá disponerse su
acumulación. (Art. 320 C.RC.)
14. Conclusión del proceso sin y con declaración sobre el fondo
Conclusión del proceso sin declaración sobre el fondo.-
Según el artículo 321 del C.RC. concluye el proceso sin declaración sobre el fondo cuando:
1. Se sustrae la pretensión del ámbito jurisdiccional;
2. Por disposición legal el conflicto de intereses deja de ser un caso justiciable;
3. Se declara el abandono del proceso;
4. Queda consentida la resolución que ampara alguna excepción o defensa previa sin que el
demandante haya cumplido con sanear la relación procesal dentro del plazo concedido
conforme al artículo 451, en los casos que así corresponda;
5. El juez declara la caducidad del derecho;
6 . El demandante se desiste del proceso o de la pretensión;
7. Sobreviene consolidación en los derechos de los litigantes,- o,
8 . En los demás casos previstos en las disposiciones legales.
Las costas y costos del proceso se fijan atendiendo a la institución acogiday a la parte que dio
motivo a la declaración de conclusión.
Conclusión del proceso con declaración sobre el fondo.- Según el artículo 322 del C.RC. con
cluye el proceso con declaración sobre el fondo cuando:
1. El juez declara en definitiva fundada o infundada la demanda;
2. Las partes concllian;
3. El demandado reconoce la demanda o se allana al petitorio;
4. Las partes transigen; o
5. El demandante renuncia al derecho que sustenta su pretensión.
15. Aclaración y corrección de resoluciones
El juez no puede alterar las resoluciones después de notificadas. Sin embargo, antes que la re
solución cause ejecutoria, de oficio o a pedido de parte, puede aclarar algún concepto oscuro
o dudoso expresado en la parte decisoria de la resolución o que influya en ella. La aclaración
no puede alterar el contenido sustancial de la decisión. El pedido de aclaración será resuelto
sin dar trámite. La resolución que lo rechaza es inimpugnable.
6 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 517 of 1506 --

Tema 2: Temas de derecho civil
Antes que la resolución cause ejecutoria, el Juez puede, de oficio o a pedido de parte y sin trá
mite alguno, corregir cualquier error material evidente que contenga. Los errores numéricos
y ortográficos pueden corregirse incluso durante la ejecución de la resolución. Mediante la
corrección las partes también piden al Juez que complete la resolución respecto de puntos
controvertidos pero no resueltos. La resolución que desestima la corrección solicitada es inim -
pugnable.
16. Costas y costos
El principio de la condena de costas y costos, significa que el reembolso de dichos conceptos
no requiere ser demandado y es de cargo de la parte vencida, salvo declaración judicial expre
sa y motivada que los exima.
Las costas están constituidas por las tasas judiciales, los honorarios de los órganos de auxilio
judicial (como los peritos) y los demás gastos judiciales realizados en el proceso; su liquida
ción lo hace la parte acreedora de ellas, después de ejecutoriada la resolución que las Imponga
o la que ordene se cumpla lo ejecutoriado.
Se atenderán sólo los gastos acreditados. Las partes tienen tres días para observar la liquida
ción. Transcurrido el plazo sin que haya observación será aprobada por resolución inim pug
nable.
Situación distinta es cuando se formula observaciones. En este caso, se confiere traslado a la
otra parte por tres días. Con su absolución o sin ella el juez resolverá. La resolución es apelable
sin efecto suspensivo. El único medio probatorio admisible en la observación es el dictamen
pericial, que podrá acompañarse hasta seis días después de haberse admitido. Del dictamen
se conferirá traslado por tres días, y con su contestación o sin ella el juez resolverá con decisión
inimpugnable.
Son costos del proceso el honorario del abogado de la parte vencedora, más un 5% destinado
al Colegio de Abogados del Distrito Judicial respectivo para su Fondo Mutual y para cubrir los
honorarios de los abogados en los casos de auxilio judicial.
Para hacerse efectivo el cobro de los costos, el vencedor deberá acompañar documento in
dubitable y de fecha cierta que acredite su pago, así como de los tributos que correspondan.
Atendiendo a los documentos presentados, el juez aprobará el monto.
La condena en costas y costos se establece por cada Instancia, pero si la resolución de segun
da revoca la de primera, la parte vencida pagará las costas y costos de ambas Instancias. Este
criterio se aplica también para lo que resuelva la Corte de Casación. Si en un proceso se han
discutido varias pretensiones, las costas y costos se referirán únicamente a las que hayan sido
acogidas para el vencedor.
En los casos en que se hubiera concedido auxilio judicial a la parte ganadora, corresponderá a
la vencida el reembolso de tasas judiciales al Poder Judicial.
La parte vencida en un incidente debe reembolsara lavencedora las tasasjudiciales, los hono
rarios de los órganos de auxilio judicial y demás gastos judiciales incurridos durante su tram i
tación. No se considera los honorarios del abogado. La liquidación correspondiente se realiza
al finalizar el proceso.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 517

-- 518 of 1506 --

UBILEX
En caso de desistimiento y abandono» si el proceso concluye por desistimiento, ya sea del
proceso o de la pretensión, quien se desista es condenado en costas y costos, salvo pacto en
contrario.
El abandono del proceso determina la condena en costasy costos del demandante.
Exención y exoneración:
Están exentos de la condena en costas y costos los Poderes Ejecutivo, Legislativo y Judicial, el
Ministerio Público, los órganos constitucionales autónomos, los gobiernos regionales y loca
les. Se encuentran exonerados de los gastos del proceso las Universidades públicas, quienes
obtengan auxilio judicial y la parte demandante en los procesos de alimentos dentro de los
límites establecidos en la Ley pudiendo ser condenados al pago de costas y costos.
También está exonerado quien reconoce o se allana a la demanda dentro del plazo para con
testarla.
Las costasy costos deben pagarse inmediatamente después de ejecutoriada la resolución que
los apruebe. En caso de mora, devengan intereses legales. El pago se exige ante el juez de la
demanda.
Liquidación de las costas:
Las costas serán liquidadas por la parte acreedora de ellas, después de ejecutoriada la resolu
ción que las imponga o la que ordena se cumpla lo ejecutoriado, debiéndose incorporar sólo
los gastos judiciales comprobados y correspondientes a actuaciones legalmente autorizadas.
La parte condenada tiene tres días para observar la liquidación, con medio probatorio idó
neo. Transcurrido el plazo sin que haya observación, la liquidación es aprobada por resolución
inimpugnable.
17. Etapa postulatoria
En esta etapa procesal las partes plantean sus pretensionesy sus medios de defensa. Se estudian
instituciones tales como la demanda, las excepciones, la contestación de la demanda, etc.
17.1. La demanda. Requisitos. Inadmisibilidad e improcedencia. Modificación y amplia
ción de la demanda. Medios probatorios extemporáneos. Traslado de la demanda.
Emplazamiento
La demanda es el acto jurídico procesal que da inicio el proceso, que viabiliza el derecho de ac
ción y contiene la pretensión. La demanda es propia del principio de iniciativa de parte: Nemo
¡udexslm adore.
Requisitos generales de la demanda.
Toda demanda debe ceñirse a los requisitos establecidos en el a r t í c u l o s del CPC:
1. La designación del Juez ante quien se interpone.
2. El nombre, datos de identidad, dirección domiciliaria, dom icilio procesal del demandan
te y el dom icilio procesal electrónico, constituido por la casilla electrónica asignada por el
Poder Judicial de acuerdo a la Ley 30229.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 519 of 1506 --

Tema2: lem as de derecho civi
3. El nom brey dirección domiciliaria del representante o apoderado del demandante, si no
puede comparecer o no comparece por sí mismo.
4. El nom brey dirección domiciliaria del demandado. Si se ignora esta última, se expresará
esta circunstancia bajo juramento que se entenderá prestado con la presentación de la
demanda.
5. El petitorio, que comprende la determinación clara y concreta de lo que se pide.
6. Los hechos en que se funde el petitorio, expuestos enumeradamente en forma precisa,
con orden y claridad.
7. La fundamentación jurídica del petitorio.
8 . El monto del petitorio, salvo que no pudiera establecerse.
9. El ofrecimiento de todos los medios probatorios.
10. La firm a del demandante o de su representante o de su apoderado y la del abogado, la
cual no será exigióle en los procesos de alimentos y de declaración de paternidad. El se
cretario respectivo certificará la huella digital del demandante analfabeto.
A estos requisitos generales o básicos, son indispensables además adjuntar los anexos que
se precisan en el artículo 425 CPC. V. gr., acompañar la copia legible del documento de iden
tidad del actory, en su caso del representante; el documento que contiene el poder de iniciar
el proceso, si fuera el caso; acreditar la representación legal del demandante, si se trata de
personas jurídicas o naturales que no pueden comparecer por sí mismas; acreditar la calidad
de heredero, cónyuge, curador de bienes, administrador de bienes comunes, albacea o del tí
tulo con que actúe el demandante, salvo que tal calidad sea materia del conflicto de intereses
y en el caso del procurador oficioso; documentos probatorios y copia certificada del acta de
conciliación extrajudicial, en los procesos judiciales cuya materia se encuentre sujeta a dicho
procedimiento previo.
Requisitos especiales de la demanda: Cada demanda requiere satisfacer ciertos requisitos
especiales que exige el ordenamiento jurídico. Ejemplo, si se demanda un retracto es necesa
rio, además de cum plir con los requisitos generales antes abordados, anexarse el certificado
de depósito en dinero del equivalente de la prestación recibida por el enajenante, los tributos
y los gastos pagados por el adquirente y, en su caso, los intereses debidos por éste y que se
hubieren devengado, y otro detalle previsto en el artículo 495 del C.RC.
Tanto los requisitos generales y especiales de la demanda, constituyen uno de los presupues
tos procesales, es decir, aquellos requisitos esenciales para que se pueda establecer una rela
ción jurídica procesal válida.
Inadmisibilidad e improcedencia de la demanda: Una de las novedades que tiene el Código
adjetivo es el rechazo m lim ine de la demanda. Este rechazo puede ser provisional o subsana
ble (inadmisibilidad), o, definitivo o insubsanable (improcedente).
En general, el juez declara la inadmisibilidad de un acto procesal cuando carece de un requi
sito de forma o éste se cumple defectuosamente. Declara su improcedencia si la omisión o
defecto de un requisito de fondo (Art. 128 CPC).
Cabe precisar que lo subsanable sólo es factible en la etapa postulatoria.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 520 of 1506 --

UBILEX
Los supuestos de inadmisibilidad de la demanda lo encontramos en el artículo 426 del C.RC:
a) No tenga los requisitos legales; esto es, que no se cumplan con los requisitos generales y
especiales de la demanda.
b) No se acompañen los anexos exigidos por ley. Ejemplo, en la separación convencional es
necesario anexarse especialmente la propuesta de convenio, firmada por ambos cónyu
ges, que regule los regímenes de ejercicio de la patria potestad, de alimentos y de liqui
dación de sociedad de gananciales conforme a inventario valorizado de los bienes cuya
propiedad sea acreditada (Art. 575 del C.RC.).
c) El petitorio sea incompleto o impreciso. El petitorio comprende la determinación clara y
concreta de lo que se pide.
d) Contenga una indebida acumulación de pretensiones. Para acumular pretensiones es im
prescindible que las pretensiones sean conexas. Hay conexidad cuando se presentan ele
mentos comunes entre distintas pretensiones o, por lo menos, elementos afines en ellas
(Art. 84 CPC). Ejemplo, no hay conexidad si el actor pretende acumular el cumplim iento
de un contrato de obra de una vivienda con la resolución de un contrato de compraventa
de un vehículo, pues se tratan de distintas relaciones jurídicas.
En estos casos el juez ordenará al actor subsane la omisión o defecto en un plazo no mayor de
diez días. Si aquél no cumpliera con lo ordenado, el juez rechazará la demanda y ordenará el
archivo del expediente.
Los casos de improcedencia de la demanda están desarrollados en el artículo 427 C.RC.:
a) El demandante carezca evidentemente legitimidad para obrar. No requieren acreditar
legitimidad, ni interés para obrar el Ministerio Público, el procurador oficioso, ni quien
representa intereses difusos (Art. IV del T.R del C.RC.), ni el acreedor en la acción subroga
toria o sustitución procesal (inc. 4 del art. 1219 del C. C. y art. 60 del C.RC.).
La legitimidad para obrar ordinaria o legitim atio ad causam es la afirmación que hace el
accionante dese rtitu larde un derecho sustantivo. Ejemplo: El actor sostiene ser propieta
rio no poseedor, y por ello demanda la reivindicación del inmueble subjudice. En caso de
duda, el juez debe dartrám ite a la demanda.
b) El demandante carezca manifiestamente de interés para obrar. El interés para obrares la
situación de necesidad que tiene el accionante de acudir al órgano jurisdiccional. Ejem
plo.. Antes de iniciar un proceso contencioso administrativo, es necesario agotar la vía ad
ministrativa (vía previa); otro caso es aquella deuda que todavía no es exigióle.
c) Advierta la caducidad del derecho. En el rechazo ¡n lim ine de la demanda, la caducidad
puede ser declarada de oficio.
d) No exista conexión lógica entre los hechosy el petitorio. La demanda debe ser congruen
te. Ejemplo: Que en el petitorio de la demanda se afirme que el emplazado le adeuda S/.
100,000, pero en los fundamentos de hecho señale que realmente le debe S/. 30,000.
e) El petitorio fuese jurídica o físicamente imposible. Ejemplo: Que se demande el cumpli
miento de un juego prohibido.
Si el juez estimara que la demanda es manifiestamente improcedente, la declara así de plano
expresando los fundamentos de su decisión y devolviendo los anexos. Si la resolución que
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 521 of 1506 --

Tema2: lem as de derecho civil
declara la improcedencia fuese apelada, el juez pondrá en conocimiento del demandado el
recurso interpuesto. La resolución superior que resuelva en definitiva la improcedencia, pro
duce efectos para ambas partes.
Modificación y ampliación de la demanda: El accionante puede modificar su demanda antes
de que sea notificada. Es posible modificar las pretensiones planteadas en la demanda, siempre
que las nuevas pretensiones se refieran a la misma controversia que fue objeto del procedimien
to conciliatorio (primer párrafo del artículo 428 CPC). Es factible modificarla total o parcialmen
te. Ejemplo, incorporar una pretensión accesoria; ofrecer otros medios probatorios.
La ampliación de la demanda es aquella facultad que tiene el actor de reservarse el derecho
de cobrar las cuotas que se devenguen durante el decurso del proceso, originadas de la misma
relación obligacional. Este derecho se puede hacer efectivo hasta antes que se expida sen
tencia. A este efecto, se consideran comunes a la ampliación los trámites precedentes y se
tramitará únicamente con un traslado a la otra parte (2do parr. del Art. 428 C.RC.). Se sustenta
en el principio de economía procesal, pues si el demandante no se ha reservado tal derecho,
inexorablemente tendrá que iniciar otro juicio.
Iguales derechos de modificación y ampliación tiene el demandado que form ula la reconven
ción.
Medios probatorios extemporáneos: Después de interpuesta la demanda, sólo pueden ser
ofrecidos los medios probatorios referidos a hechos nuevos y a los mencionados por la otra
parte al contestar la demanda o reconvenir.
De presentarse documentos, el juez concederá traslado a la otra parte para que dentro de 05
días reconozca o niegue la autenticidad de los documentos que se le atribuyen.
Traslado de la demanda: Si el juez califica la demanda positivamente, da por ofrecidos los
medios probatorios, confiriendo traslado al demandado para que comparezca al proceso (Art.
4 3 0 CPC).
Reglas sobre el emplazamiento del demandado:
Existen las siguientes situaciones:
a) Emplazamiento en la competencia territorial del juzgado. Se hará por medio de cédula que se
le entregará en su domicilio real, si allí se encontrara.
b) Emplazamiento fuera de la competencia territorial del juzgado. El emplazamiento se hará me
diante exhorto a la autoridad judicial de la localidad que se halle. Se agrega el Cuadro de
Distancias.
c) Emplazamiento fuera del país. El demandado será emplazado mediante exhorto librado a
las autoridades nacionales del lugar más cercano donde domicilie.
d) Emplazamiento de demandados con domicilios distintos. Habiendo varios demandados y se
hallaren en juzgados de competencia territorial diferente, el plazo del emplazamiento
será para todos el que resulte mayor, sin atender al orden en que las notificaciones fueron
practicadas.
e) Emplazamiento a demandado indeterminado o incierto o con domicilio o residencia ignorados. La
notificación se realiza mediante edictos, bajo apercibimiento de nombrarle un curador
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 521

-- 522 of 1506 --

