de conocimiento es de 6 o y 90 días; en el proceso abreviado es de 30 y 45 días; en el pro
ceso sumarísimo es d e is y 25 días.
f) Emplazamiento del apoderado. El emplazamiento podrá hacerse al apoderado, siempre que
tuviera facultad para ello y el demandado no se hallara en el ámbito de competencia te
rritorial del juzgado.
g) Emplazamiento defectuoso. Será nulo el emplazamiento si se hace contraviniendo lo dis
puesto en los artículos 431,432,433, 4 3 4 ,435 y 4 3 6 . Sin embargo, por el principio de tras
cendencia y convalidación de las nulidades, no habrá nulidad si la forma empleada le
ofreció al demandado las mismas o más garantías de las que el Código regula. Tampoco
habrá nulidad si el emplazado comparece y no la form ula dentro del plazo previsto, o si
se prueba que tuvo conocimiento del proceso y om itió reclamarla oportunamente.
Efectos del emplazamiento: El emplazamiento válido con la demanda produce los siguientes
efectos (Art. 438 CPC):
1. La competencia inicial no podrá ser modificada, aunque posteriormente varíen las cir
cunstancias que la determinaron. Concordancia: Artículo 8 del C.RC. Ejemplo, aquel bien
sub litis que se encuentre sujeto a cotización en la Bolsa de Valores, cuando se interpone
la demanda equivalía a io o , pero dos meses después bajaa70, esta fluctuación no afecta
la competencia.
2. El petitorio no podrá ser modificado fuera de los casos permitidos en este Código. Ejem
plo, en cualquier estado del proceso antes de la sentencia, el demandante o el reconvi-
niente, pueden modificar su pretensión de divorcio a una de separación de cuerpos (Art.
482 CPC).
3. No es jurídicamente posible iniciar otro proceso con el mismo petitorio. En este caso, el
demandado puede deducir la excepción de litispendencia (inc 7 de! Art. 446 CPC).
4. Interrumpe la prescripción extintiva. Concordancia: Inc. 3 del art. 1996 del C. C.
Hechos no invocados en la demanda: Cuando al contestarse la demanda o la reconvención
se invocan hechos no expuestos en ellas, la otra parte puede, dentro del plazo establecido en
cada proceso, que en ningún caso será mayor de diez días desde que fue notificado, ofrecer los
medios probatorios referentes a tal hecho.
Sanción por juramento falso: Si se acredita que el demandante o su apoderado o ambos,
faltaron a la verdad respecto de la dirección domiciliaria del demandado, se remitirá copia
de lo actuado al Ministerio Público para la investigación del delito y al Colegio de Abogados
respectivo para la investigación por falta contra la ética profesional, si uno de los dos fuese
Abogado. Adicionalmente, se impondrá una multa individual no menor de 10 ni mayor de 30
URR sin perjuicio de lo regulado en el Art. 4 del CPC.
Contestación: Inspirada en los principios de defensa, contradicción y bilateralidad, que para su
admisión (y consiguiente apersonamiento, del emplazado) debe reunir los mismos requisitos
exigidos para la demanda. Así como, pronunciarse respecto de cada uno de los hechos expuestos
en la demanda, en forma ordenada, clara y precisa. Reconociendo o negando categóricamente
