la recepción de documentos que se alega le fueron enviados; importando el silencio el reconoci
miento o aceptación de tales cargos. Además de exponer los hechos en que se funde la defensa.
Reconvención: Constituye el acto a través del cual el emplazado, con las mismas facultades
conferidas al demandante, plantea una nueva pretensión y la dirige al demandante. Esto, al
momento de contestar la demanda.
La reconvención también debe reunir los mismos requisitos de la demanda para los efectos de
su admisión y/o procedencia (requisitos de form ay de fondo), no debe afectar la competencia
asumida por el Juez ni la vía procedimental originariamente, y las pretensiones de la recon
vención deben ser conexas.
Cabe precisar que la demanda y la reconvención se sustancian conjuntamente, y se resuelven
de la misma manera en la sentencia.
Por último, en caso la pretensión de la reconvención sea materia conciliable, será necesario
que el demandando haya acudido a la audiencia de conciliación; no obstante, se exige que
en el acta de conciliación extrajudicia! quede la descripción de las controversias que serán
materia de debate en el futuro proceso, y que le permitirá plantear su reconvención corres
pondiente.
18. Medios de defensa
A. Excepciones: Las excepciones son medios procesales de defensa que tienen por objeto
cuestionar la válida integración de la relación jurídica procesal en base al cumplim iento de
ciertos presupuestos procesales, según un sistema jurídico, que permiten ejercitar válidamen
te el derecho de acción.
Excepciones proponibles: Según lo dispuesto por el artículo 4 4 6 0 del C.RC. el demandado
sólo puede proponer las siguientes excepciones:
1. Incompetencia; Cuestiona la competencia del Juez, en razón a la materia, cuantía o te
rritorio (puede ser declarada de oficio o a instancia de parte, hasta antes de expedirse el
auto de saneamiento procesal). Es de carácter perentorio.
2. Falta de capacidad de ejercicio del demandante o de su representante; Es de carácter
dilatorio, es aquella que denuncia la falta de capacidad de ejercicio del demandante o de
su representante.
3. Representación defectuosa o insuficiente del demandante o del demandado; A diferen
cia de la excepción anterior, ésta tiene por objeto cuestionar el podery no a la persona del
representante de alguna de las partes. Y es de carácter dilatoria.
4 . Oscuridad o ambigüedad en el modo de proponer la demanda; Es de carácter dilatoria,
que está orientada a cuestionar los aspectos puramente formales de la demanda, así, por
ejemplo, cuando en la demanda se hayan propuesto pretensiones incompatibles, o sin
conexión entre los hechos expuestos, etc.
5 . Falta de agotamiento de la vía administrativa; Cuando se trate de aquellos casos en que
se pretenda impugnar alguna resolución administrativa, sin que se hayan agotado pre-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 524 of 1506 --

UBILEX
viamente los recursos previstos en sede administrativa, antes de acudir a lavíajudicial.Se
trata de una excepción de carácter perentorio.
6 . Falta de legitimidad para obrar del demandante o del demandado; Es de carácter pe
rentorio, y se presenta cuando no se configura la correcta identificación entre los sujetos
confortantes de la relación jurídica material y la relación jurídica procesal. Si la incorrecta
identificación está referida al demandante, estaremos ante una falta de legitim idad para
obrar activa, mientras que la pasiva se configurará por la incorrecta identificación del de
mandado.
7. Litispendencia; Es el instrumento dirigido a denunciar la existencia de dos procesos en
trám ite entre las mismas partes, con iguales pretensiones procesales y promovidas en
virtud a un mismo interés, con la finalidad de extinguir el iniciado con posterioridad al
primer proceso. Por ello es de carácter perentorio.
8. Cosa Juzgada; Es de carácter perentorio, y se presenta cuando un proceso ha terminado
con decisión firme, ya sea mediante sentencia o laudo arbitral, y existe otro proceso en
trámite en el que las partes, las pretensiones y el interés para obrar son las mismas.
9. Desistimiento de la pretensión; Al igual que la anterior, es de carácter perentorio; que se
interpondrá cuando se da inicio a un proceso idéntico a otro concluido por el desistimiento
de la pretensión del demandante. En este caso también se requiere la identificación de la
triple identidad (las mismas partes, las mismas pretensionesy el mismo interés para obrar).
10. Conclusión del proceso por conciliación o transacción; Al tener la conciliación y la tran
sacción los mismos efectos de una sentencia con la calidad de cosa juzgada, por ser
formas especiales de conclusión del proceso; estas excepciones también tienen la natu
raleza perentoria. Cabe mencionar que la transacción extrajudicial no homologada ju d i
cialmente puede ser opuesta como excepción procesal conforme lo prevé el inc. 10) del
artículo 446o del Código Procesal Civil e inc. 4) del artículo 453° del mismo cuerpo legal,
por interpretación sistemática de dichas normas con las que contiene el Código Civil so
bre latransacción, elloen atención a lo establecido porel Primer Pleno Casatorio Civil del
22 de enero de 2008, publicado el 21.04.2008.
n . Caducidad; Esta excepción se interpondrá cuando se haya iniciado un proceso en el que
el actor ha perdido el derecho a entablar una demanda, por no haberse propuesto la pre
tensión procesal dentro del plazo establecido por ley. Los plazos de caducidad no admi
ten interrupción ni suspensión; y únicamente están establecidos por ley. Esta excepción
también es de naturaleza perentoria, y puede también ser declarada de oficio.
12. Prescripción extintiva; Sólo puede operar por proposición de alguna de las partes, en ra
zón a que la prescripción no extingue el derecho sino únicamente la acción, a diferencia
de la caducidad. El plazo de prescripción es susceptible de suspensión o interrupción. Es
de carácter perentorio.
13. Convenio arbitral; Se configurará cuando se inicie un proceso en el que las pretensiones
demandadas ya hayan sido objeto de un convenio arbitral.
14. Falta de representación legal o de apoyo por capacidad de ejercicio restringida del de
mandante o de su representante, de acuerdo al artículo 44 del Código Civil. Los apoyos
