Tema 2: Temas de derecho civil
son formas de asistencia libremente elegidos por una persona mayor de edad para fácil i-
tarle el ejercicio de sus derechos, para diversos ámbitos, como apoyo en la comunicación,
en la comprensión de los actos jurídicos y sus consecuencias, la manifestación e interpre
tación de la voluntad de quienes requiere apoyo.
Plazo y formalidad: Se propone conjuntamente y dentro del plazo que cada tipo de procedi
miento señala, el plazo máximo es de i o días, contados desde la notificación con la demanda,
en el proceso abreviado son de 5 días, en el proceso sumarísimo las excepciones se deducen al
contestarse la demanda.
Medios probatorios: Sólo se admitirán los medios probatorios documentales que se ofrezcan
en el escrito en que se proponen las excepciones o en que se absuelven.
Auto de saneamiento procesal: Absuelto el traslado o transcurrido el plazo para hacerlo, el
Juez resuelve la excepción dentro de los diez días siguientes. Si la declara infundada, declara
también el saneamiento del proceso.
Resolución y recurso: Las excepciones se resuelven en un sólo auto. Si entre ellas figura la
de incompetencia, litispendencia o convenio arbitral y el Juez declara fundada una de ellas,
se abstendrá de resolver las demás; pero si concedida apelación, el superior revoca aquella,
devolverá lo actuado para que el inferior se pronuncie sobre las restantes. El auto que declara
fundada una excepción es apelable con efecto suspensivo.
Efectos de las excepciones: Una vez consentido o ejecutoriado el auto que declara fundada
alguna de las excepciones enumeradas en el Artículo 446, el cuaderno de excepciones se agre
ga al principal y produce los efectos siguientes:
1. Suspender el proceso hasta que el demandante comprendido en los supuestos de los ar
tículos 43 y 4 4 del Código Civil comparezca, legalmente asistido o representado, dentro
del plazo que fija el auto resolutorio, si se trata de la excepción falta de capacidad del
demandante o de su representante.
2. Suspender el proceso hasta que se subsane el defecto o la insuficiencia de representación
del demandante dentro del plazo que fijará el auto resolutorio.
3. Suspender el proceso hasta que el demandante subsane los defectos señalados en el
auto resolutorio y dentro del plazo que este fije, si se trata de la excepción de oscuridad o
ambigüedad en el modo de proponer la demanda.
4. Suspender el proceso hasta que el demandante establezca la relación jurídica procesal
entre las personas que el auto resolutorio ordene y dentro del plazo que éste fije, si se
trata de la excepción de falta de legitimidad para obrar del demandado.
Vencido los plazos a los que se refieren los incisos anteriores sin que se cumpla con lo
ordenado, se declarará la nulidad de lo actuado y la conclusión del proceso.
5. Anular lo actuadoy dar por concluido el proceso, si se trata de las excepciones de incompe
tencia, representación insuficiente del demandado, falta de agotamiento de la vía adminis
trativa, falta de legitimidad para obrar del demandante, litispendencia, cosa juzgada, desis
timiento de la pretensión, conclusión del proceso por conciliación o transacción, caducidad,
prescripción extintiva o convenio arbitral.
