6 . Remitir los actuados al Juez que corresponda, si se trata de la excepción de incompetencia. En
el caso de la excepción de incompetencia territorial relativa, el Juez competente continúa con
el trámite del proceso en el estado en que este se encuentre y si lo considera pertinente, aun
cuando la audiencia de pruebas hubiera ocurrido, puede renovar la actuación de alguno o de
todos los medios probatorios, atendiendo a lo dispuesto en el último párrafo del artículo 50.
En los demás casos el Juez debe proceder a emplazar nuevamente con la demanda.
B. Defensas previas: Son medios procesales a través de los cuales, el demandado solicita la
suspensión del proceso hasta que el actor realice la actividad que el derecho sustantivo prevé
como acto previo al planteamiento de la demanda. No tiene por objeto denunciar la carencia
de falta de un requisito de forma; de un presupuesto de fondo (como las excepciones de forma
reguladas en el código procesal civil); ni tampoco tiene por propósito negar la pretensión pro
cesal propuesta por el accionante (como las reguladas en el código civil), sino tiene por objeto
la suspensión del proceso en tanto se cumpla un acto previo al planteamiento de la demanda
señalado por el ordenamiento civil.
Según lo señalado por el CPC son defensas previas: el beneficio de inventario, el beneficio de excusión
de bienesy otras que regula el derecho sustantivo, dada la naturaleza especial de estas.
Efectos: Cuando el juez declara fundada una defensa previa, debe ordenar la suspensión del
proceso hasta que se cumpla el tiempo o el acto previsto, para el efecto el juzgador tiene que
dictar la resolución correspondiente.
Costas, costos y multas tratándose de las defensas previas: Son de cargo de la parte vencida
en ellas, evaluando la conducta del actor el juez puede condenarlo al pago de una m ulta no
menor de By ni mayor de 5 URR
1 9 . Rebeldía
La rebeldía es una institución procesal que adquiere quien fue debidamente emplazado (de
mandante o demandado) para comparecer al proceso o para realizar determinado acto den
tro del litigio,y no lo hace en el plazo correspondiente. La declaración de rebeldía debe hacer
se efectiva a través de una resolución, a pedido de parte o de oficio. Declarada la rebeldía, el
Juez se pronunciará sobre el saneamiento del proceso, que de ser así, continuará con el pro
ceso, sobre la base de la presunción legal relativa de los hechos expuestos en la demanda; a
menos que al servarlos emplazados algunos conteste la demanda, la pretensión demandada
se sustente en un derecho indisponible (filiación, por ejemplo), disposición de la ley, o que la
presunción legal relativa no produzca convicción en el juzgador. El rebelde puede incorporarse
al proceso en cualquier etapa, sujetándose al estado en que se encuentre.
Efectos de la declaración de rebeldía: La declaración de rebeldía causa presunción legal rela
tiva sobre la verdad de los hechos expuestos en la demanda, salvo que:
1. Habiendo varios emplazados, alguno contesta la demanda;
2. La pretensión se sustente en un derecho indisponible;
3. Requiriendo la ley que la pretensión demandada se pruebe con documento, éste no fue
acompañado a la demanda; o
4. El Juez declare, en resolución motivada, que no le producen convicción.
