21. Fijación de puntos controvertidos
Los puntos controvertidos están constituidos por aquellos puntos sobre los cuales existe dis
crepancia entre las partes,y que a su vez serán materia de probanza. Una vez expedido el auto
de saneamiento procesal, las partes dentro del tercero día de notificadas propondrán al Juez
por escrito los puntos controvertidos. Vencido este plazo con o sin la propuesta de las partes el
Juez procederá a fijar los puntos controvertidos y la declaración de admisión o rechazo, según
sea el caso, de los medios probatorios ofrecidos. (Art. 468 CPC).
No se debe confundir con la pretensión o las pretensiones controvertidas.
Corresponde al Juez fijas objetivamente los puntos en controversia.
Están constituidos por aquellos hechos conducente o útiles para el proceso, respecto de los cua
les existe discrepancia o controversia entre las partes (discrepancia en la causa de los hechos].
“Genéricamente estos son objeto de prueba cuando están controvertidos, es decir, afirmados
por una parte y negados o desconocidos por la otra. Son conducentes, esto es, pertinentes y
útiles, porque inciden con suficiente importancia en el curso de la litis; sin adquirir esta cali
dad los que, estando contrapuestos no llevan mérito suficiente para alterar el contenido hipo
tético del pronunciamiento definitivo” [Gozaini].
