22. Saneamiento probatorio
Es el acto procesal en el que el Juez dispone qué medios probatorios se van actuar en la au
diencia de pruebas, declarando la impertinencia o improcedencia, según sea el caso; a fin de
resolver los puntos controvertidos y consiguiente resolución de la litis. A menos que la cues
tión controvertida sea de puro derecho, o siendo de hecho no existe la necesidad de actuar
medios probatorios; casos en los cuales el Juez comunicará a las partes su decisión de expedir
sentencia sin a dm itir otro trámite. Si se presentaran cuestiones probatorias o los medios pro
batorios admitidos por el juez requieran actuación, se convocará a las partes a una audiencia
de pruebas, etapa en la cual se resuelven las cuestiones probatorias y se actúan los medios
probatorios a fin de resolver el conflicto o incertidumbre jurídica, materia de litigio; que se
realizará según la horay lugar que fije el Juez al expedir el auto que fija puntos controvertidos
y realiza el saneamiento probatorio; momento en el cual concluye la etapa postulatoria y se
inicia la etapa probatoria del proceso.
La decisión por la que se ordena la realización de la audiencia de pruebas o se prescinde de
ella es impugnable sin efecto suspensivoy con la calidad de diferida. Al prescindir de esta Au
diencia el Juez procederá al juzgamiento anticipado, sin perjuicio del derecho de las partes a
solicitar la realización de informe oral.
El saneamiento probatorio debe girar en torno a los puntos controvertidos, de lo contrario se
corre el riesgo de admitirse y actuar pruebas no idóneas para resolver la pretensión demandada.
23. Juzgam iento anticipado del proceso
El Juez comunicará a las partes su decisión de expedir sentencia sin adm itir otro trám ite que
el informe oral:
i . Cuando advierte que la cuestión debatida es sólo de derecho o, siendo también de hecho,
no hay necesidad de actuar medio probatorio alguno en la audiencia respectiva; o,
z. Queda consentida o ejecutoriada la resolución que declara saneado el proceso, en los ca
sos en que la declaración de rebeldía produce presunción legal relativa de verdad.
24. Etapa de actuación de pruebas
Las pruebas de oficio (Art. 194 CPC).
Son de carácter facultativo y supletorio. Cuando los medios probatorios ofrecidos por las partes
sean insuficientes para fo rm a r convicción, el juez, en decisión motivada e inimpugnable, puede
ordenar la actuación de los medios probatorios adicionales que considere convenientes.
Audiencia de Pruebas: Regida por los principios de inmediación, unidad de la audienciay pu
blicidad de la prueba. La Audiencia de Pruebas se efectúa de acuerdo a las normas del Códi
go Procesal Civil y las reglas generales aplicables a las audiencias y disposiciones específicas
previstas para la Audiencia Preliminar fijadas en el Reglamento de Actuación de los Módulos
Civiles Corporativos de Litigación Oral (MCCLO) R.A. N°0i5-2020-P-CE-PJ.
La audiencia de pruebas será dirigida personalmente por el juez, bajo sanción de nulidad. A
aquella deben concurrir personalmente las partes, los terceros legitimados y el representante
del Ministerio Público en su caso. Las personas jurídicas y los incapaces comparecen a través de
sus representantes legales. Las partes y terceros legitimados pueden concurrircon sus abogados.
