S a lv o d is p o s ic ió n d is t in t a d e la le y p r o c e s a l, s ó lo si p r u e b a u n h e c h o g ra v e o ju s t if ic a d o q u e
im p id a s u p r e s e n c ia , el ju e z a u t o r iz a r á a u n a p a rte a a c t u a r m e d ia n t e r e p re s e n t a n t e .
Si a la audiencia de pruebas concurre una de las partes, ésta se realizará sólo con ella. Si no
concurren ambas partes, el juez dará por concluido el proceso (Art. 203 CPC).
