El Art. 208 del C.RC. regula la actuación de los medios probatorios: En el díay hora fijados, el
Juez declara iniciada la Audiencia y dispone la actuación de las pruebas en el siguiente orden:
a) Pericia; b) testigos; c) reconocimiento (no es necesario si no ha sido cuestionado) y exhi
bición; d) declaración de las partes, empezando por la del demandado. Cuando los mismos
medios probatorios hayan sido ofrecidos por ambas partes se actuarán primero los del de
mandante.
La ausencia de uno o más testigos no produce la suspensión de la audiencia, debiendo solo
dejar constancia de la inasistencia y consultar a las partes asistentes la prescindencia de la
testimonial ofrecida. En los procesos de prescripción adquisitiva de dominio, la prescinden
cia exige la previa producción del mínimo legal de tres testimoniales, pues, caso contrario, se
convocará a una nueva audiencia para recabar la declaración del testigo ausente. Los peritos
y testigos ingresarán a la Sala de Audiencia cuando el Juez/a lo dispongay permanecerán du
rante toda la diligencia, salvo disposición contraria. (Art. 47 Reglamento de Actuación de los
MCCLO- R.A. N °0 i 5-2 0 2 0 -P-CE-PJ).
