s e r á el ú lt im o m e d io p r o b a to rio .
Inspección judicial. Se puede realizar al inicio, si es dentro de la competencia territorial del Juez
junto con la prueba pericial, pudiendo recibirse éstay otros medios probatorios en el lugar de
la inspección.
