Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 530 of 1506 --

UBILEX
Confrontación: El juez puede disponer el careo entre testigos, entre peritos y entre éstos, aqué
llos y las partes y entre estas mismas, para lograr la finalidad de los medios probatorios (Art.
209 CPC).
Conclusión de la audiencia de pruebas. El juez comunica a las partes que el proceso está ex
pedito para sersentenciado. El juez, antes de declarar la conclusión de la audiencia, concederá
el uso de la palabra a los abogados de las partes para el respectivo informe oral (alegato de
clausura).
Sistemas de valoración probatoria: La valoración o apreciación de la prueba constituye la úl
tim a etapa de la actividad probatoria, y es la operación intelectual que realiza el juez a efectos
de determinar la eficacia o valor probatorio de los medios de prueba practicados en el proceso.
El Código Procesal Civil sigue la doctrina moderna en materia de valoración de la prueba de
la valoración razonada o libre valoración o sana crítica. El sistema de sana crítica es un proceso
racional en el que el juez debe utilizar a fondo su capacidad de análisis lógico para llegar a
un juicio o conclusión producto de las pruebas actuadas en el proceso. Significa la libertad
arreglada del juez a través de cauces de racionalidad que tiene que justificarla utilizando el
método analítico: estudiar la prueba individualmente y después la relaciona en su conjunto.
El artículo 197 del Código Procesal Civil establece que todos los medios probatorios son valo
rados por el juez en forma conjunta utilizando su apreciación razonada; sin embargo, en la
resolución solo serán expresadas las valoraciones esenciales y determinantes que sustentan
su decisión. Cuando las partes han presentado pruebas para desvirtuar otras, la omisión de
un pronunciamiento expreso al respecto podría causar indefensión. De haber pruebas que
buscan dejar sin efectos otras, es necesario un pronunciamiento expreso de todas ellas por
parte del juzgador.27
