Tema 2: Temas de derecho civil
25. Sentencia
La sentencia constituye uno de los actos jurídicos procesales más trascendentes en el proceso
puesto que, mediante él, no solamente se pone fin al proceso sino que también el Juez ejerce
el poder-deber del cual se encuentra investido, declarando el derecho que corresponde me
diante la aplicación de la norma al caso concreto, buscando logar la paz social en justicia.
Nuestro Código Procesal CiviI en su art.121, primer párrafo, dispone que, mediante la sentencia
el Juez pone fin a la instancia o al proceso en definitiva, pronunciándose en decisión expre
sa, precisa y motivada sobre la cuestión controvertida declarando el derecho de las partes, o
excepcionalmente sobre la validez de la relación procesal (art. 121, últim o párrafo, del C.RC.J.
Clases: Según el criterio clasificatorio clásico, las sentencias pueden ser:
Declarativas.- Se trata de una mera constatación, fijación o expresión judicial de una si
tuación jurídica ya existente. Ejemplo: la sentencia que declara la nulidad de un título
valor, la declaración de propiedad por prescripción, etc.
Constitutivas.-Al igual que lo que sucede con las meras declarativas, no requieren de ac
tos materiales posteriores (ejecución forzada) para la satisfacción del interés de la parte
favorecida. Son sentencias de actuación inmediata.
De condena.- Además de declarar la existencia del derecho a una prestación y el cum pli
miento de ésta por parte del obligado, aplican la sanción que la ley imputa a ese cum pli
miento, y crean, por ello, a favor del titu la r del derecho, la acción tendiente a obtener su
ejecución coactiva.
Otra clasificación:
S. O tra Petita.- Llamada también congruencia negativa, cuando el juez omite del debido
pronunciamiento sobre alguno de los términos del problema judicial.
S. Extra Petita.- La resolución que falla sobre una cuestión no planteada. La inadvertencia
o mala fe del juzgador puede tener consecuencias para las partes que acepten este fallo;
pues se convierte en título jurídicoy se ejecuta lo pertinente, de queda firme.
S. U ltra Petita.- Se da cuando el juez extiende su decisión más allá de los límites del pro
blema judicial que le sometido a su consideración; en este caso la sentencia incurre en
incongruencia ultra petita por dar más de los pedido.
Requisitos:
a) F o rm ale s
Las resoluciones contienen (Art. 122 CPC):
1. La indicación del lugary fechaen que se expiden;
2. El número de orden que les corresponde dentro del expediente o del cuaderno en
que se expiden;
3. La mención sucesiva de los puntos sobre los que versa la resolución con las consi
deraciones, en orden numérico correlativo, de los fundamentos de hecho que sus
tentan la decisión, y los respectivos de derecho con la cita de la norma o normas
aplicables en cada punto, según el mérito de lo actuado;
