4. La e x p r e s ió n c la r a y p r e c is a d e lo q u e se d e c id e u o r d e n a , re sp e c to d e t o d o s lo s p u n
to s c o n t r o v e r t id o s . Si el ju e z d e n e g a s e u n a p e t ic ió n p o r f a lt a d e a lg ú n r e q u is it o o p o r
u n a c it a e r r ó n e a d e la n o r m a a p lic a b le a s u c rite r io , d e b e r á e n f o r m a e x p r e s a in d ic a r
el r e q u is it o f a lt a n t e y la n o r m a c o r r e s p o n d ie n t e ;
5. El plazo para su cumplimiento, si fuera el caso;
6 . La condena en costas y costos y, si procediera, de multas, o la exoneración de su pago;
y
7. La s u s c r ip c ió n d e l ju e z y d e l A u x ilia r j u r is d ic c io n a l re sp e c tiv o .
La resolución que no cumpla con los requisitos antes señalados será nula, salvo los
decretos que no requieren cum plir con lo establecido en los incisos 3, 4, 5 y 6 , y los
autos del expresado en el inciso 6 .
b) Materiales
1. Congruencia: La congruencia viene a constituir la conformidad entre la sentencia y
las pretensiones planteadas por las partes en los actos postulatorios. En ese sentido,
las resoluciones propuestas ante el órgano jurisdiccional al demandar, contestary en
su caso al reconvenir, sin que existan circunstancias posteriores que modifiquen los
términos que dieron origen al conflicto de intereses.
2. Motivación: Comporta la justificación lógica, razonada y conforme a las normas
constitucionales y legales, debiendo asimismo encontrarse con arreglo a los hechos
y al petitorio formulado por las partes en los actos postulatorios, por tanto una mo
tivación de hecho o m factum (en el que se establecen los hechos probados y los no
probados mediante la valorización conjuntay razonada de las pruebas incorporadas
al proceso), y la motivación de derecho o in ju re (en el que se selecciona la norma
jurídica correspondiente o pertinentes) y se efectúa una adecuada interpretación de
la misma.
3. Exhaustividad: Por el principio de exhaustividad de la sentencia, se le imponeal ma
gistrado el deber de pronunciarse sobre todas las pretensiones de las partes, sea para
rechazarlas por extemporáneas, infundadas o inadmisibles o improcedentes. Tam
bién se puede vulnerar este principio si hay omisión de pronunciamiento cuando la
sentencia prescinde totalmente de otorgar o negar la tutela jurídica solicitada sobre
alguna de las pretensiones de las partes, salvo que por alguna causa legal el magis
trado se encuentre eximido de ese deber.
Partes (Art. 122 CPQ:
Expositiva. Constituye el preámbulo de la sentencia, tiene por finalidad la individuali
zación de los sujetos del proceso, las pretensiones y el objeto sobre el cual debe recaer el
pronunciamiento.
Considerativa. Parte de lasentenciaque se refiere a los fundamentos o motivaciones que
el juez adopta y que constituyen el sustento de su decisión.
Resolutiva (Fallo). Viene a ser la conclusión al que el juez ha arribado luego del análisis
de lo actuado en el proceso que se expresa en la decisión en la que se declara el derecho
