Tema 2: Temas de derecho civil
alegado por las partes, precisando en su caso el plazo en el cual deben cumplir con el
mandato salvo sea impugnado, por lo que los efectos de esta se suspenden.
P lazo s m á x im o s p a r a e x p e d ir re so lu c io n e s: De acuerdo a lo normado en el artículo 124 del
CPC (numeral que versa sobre los plazos máximos para expedir resoluciones judiciales):
A. En primera instancia, los decretos se expiden a los dos días de presentado el escrito que
los motiva.
B. Los autos se expide dentro de cinco días hábiles computados desde la fecha en que el
proceso se encuentra expedito para ser resuelto, salvo disposición distinta del Código Pro
cesal Civil.
C. Las sentencias se expedirán dentro del plazo máximo previsto en cada vía procedimental
contados desde la notificación de la resolución que declara al proceso expedito para ser
resuelto. Los plazos máximos para em itir sentencia son éstos:
a) 50 días contados desde la conclusión de la audiencia de pruebas, en los procesos de
conocimiento (Art. 478, inc. 12, del C.RC).
b) 25 días contados desde la conclusión de la audiencia de pruebas, en los procesos
abreviados (Art. 4 9 T inc. 11, del C.RC.).
c) Concluida la audiencia única, en forma inm ediatay oral, hace conocerá las partes el
sentido del fallo de la sentencia, en los procesos sumarísimos (Art. 555, parte final,
del C.RC.).
d) 05 días de realizada la audiencia única o de vencido el plazo para contradecir, emitirá
un auto (mandato ejecutivo) disponiendo el cumplim iento de la obligación conte
nida en el título; bajo apercibimiento de iniciarse la ejecución forzada, los procesos
únicos de ejecutición (Art. 690-C del C.RC.).
e) 03 días contados desde la conclusión de la audiencia de actuación y declaración ju
dicial, en los procesos no contenciosos (Art. 754, antepenúltimo párrafo, del C.RC.).
D. En segunda instancia, los plazos se sujetarán a lo dispuesto en el Código Procesal Civil.
Por ejemplo, tratándose de la apelación de autos concedida con efecto suspensivo, la re
solución final se emite dentro de los cinco días siguientes a la vista de la causa (Art. 376,
parte final, del C.RC.).
E. Los plazos en la Corte Suprema se sujetan a lo dispuesto en el Código Procesal Civil sobre
el recurso de casación. Por ejemplo, habiéndose declarado la Sala Superior la adm isibili
dad del recurso de casación, la Sala Suprema respectiva cuenta con 20 días para resolver
su procedencia (Art. 393,4 del C.RC.); además, la Sala Suprema correspondiente emite la
sentencia en casación dentro de los 20 días contados desde producida la vista de la causa
(Art. 3 9 4 del C.RC.).
F. El retardo en la expedición de las resoluciones será sancionado disciplinariamente por el
superior jerárquico, sin perjuicio de las responsabilidades adicionales a las que hubiera
lugar.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 534 of 1506 --

UBILEX
26. Procesos contenciosos:
Son aquellos procesos en los cuales la ley faculta la oposición entre las pretensiones de los
titulares activos y pasivos de la relación jurídica procesal, a diferencia de los procesos no con
tenciosos, en los que estrictamente no existe contradicción alguna.
En ese contexto, y atendiendo a la finalidad que persigue, los procesos contenciosos de clasi
fican a su vez en:
a. Declarativos. En este proceso se pretende una declaración de certeza sobre la existencia o
no del derecho invocado.
b. Ejecución. Son aquellos que se basan en un derecho cierto, generalmente materializado
en un título ejecutivo o de ejecución donde consta la exigibilidad de la obligación.
1. Proceso de conocimiento:
Es el proceso modelo por excelencia debido a que su tramitación es de aplicación extensiva a
todas aquellas controversias que carezcan de un trámite específico, inclusive se aplican suple
toriamente a los demás procesos (ejecutivos, cautelares, etc.).
Características:
Am plitud de los plazos de las respectivas actuaciones procesales en relación con los otros
tipos de procesos declarativos.
La naturaleza de las pretensiones que se ventilan el proceso de conocimiento son de na
turaleza compleja y de gran estimación patrimonial- refleja su importancia dentro del
contexto jurídico.
Tiene por finalidad la dilucidación y declaración de parte del órgano jurisdiccional del
contenidoy alcance del estado o situación jurídica sustantiva existente entre sus titulares
a través del desarrollo sucesivo de determinados actos jurídicos procesales enmarcados
dentro de una normatividad específica. Procedencia:
Procedencia: Los supuestos en los cuales procede la tramitación de los procesos de conoci
miento se encuentran contemplados en el artículo 475o del CPC.
Se tramitan en proceso de conocimiento, ante los Juzgados Civiles, los asuntos contenciosos que:
1. No tengan una vía procedimentaí, no estén atribuidos por ley a otros órganos jurisdiccio
nales y, además, cuando por su naturaleza o complejidad de la pretensión, el Juez consi
dere atendible su tramitación;
2. la estimación patrimonial del petitorio sea mayor de mil Unidades de Referencia Procesal;
3. son inapreciables en dinero o hay duda sobre su monto, y siempre que el Juez considere
atendible su procedencia;
4. el demandante considere que la cuestión debatida sólo fuese de derecho; y,
5. los demás que la ley señale.
La competencia para este tipo de procedimientos corresponde exclusivamente a los Jueces
Civiles y los Juzgados de Familia, según la materia a que se refiera la pretensión.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 535 of 1506 --

Tema 2: Temas de derecho civil
Cabe precisar que en los procesos de conocimiento es posible la interposición de cuestiones
probatorias, medios de defensa (excepciones y cuestiones previas), reconvención, y se ofrez
can otros medios probatorios al invocarse en la demanda o reconvención con hechos nuevos.
Los plazos para las actuaciones que correspondan en este proceso se encuentran contempla
dos en el artículo 478o del CPC.
2 . P roceso a b re v ia d o :
Es aquel proceso en el que los plazos y formas son breves y simples, y que a diferencia con
el proceso de conocimiento, en este proceso se concentran las actuaciones procesales en un
número menor.
Son competentes para conocer los procesos abreviados los jueces Civiles, los de Paz Letrados,
salvo en aquellos casos en que la ley atribuye su conocimiento a otros órganos jurisdiccio
nales. Los juzgados de Paz Letrados son competentes cuando la cuantía de la pretensión es
mayor de 100y hasta 500 URP; cuando supere este monto, los jueces Civiles
Procedencia: Los supuestos en los cuales procede latramitación de los procesos abreviados se
encuentran contemplados en el artículo 486o del CPC.
Se tramitan en proceso abreviado los siguientes asuntos contenciosos:
1. Retracto;
2. Título supletorio, prescripción adquisitivay rectificación de áreas o linderos;
3. Responsabilidad civil de losjueces;
4. Expropiación;
5. Tercería;
6 . Impugnación de acto o resolución administrativa;
7. La pretensión cuyo petitorio tenga una estimación patrimonial mayor de cien y hasta mil
Unidades de Referencia Procesal;
8 . Los que no tienen una vía procedí mental propia, son inapreciables en di ñero o hay duda sobre
su monto o, por la naturaleza de la pretensión, el juez considere atendible su empleo;y,
9. Los demás que la ley señale.
El saneamiento procesal como la fijación de puntos controvertidos se realiza mediante un auto.
Las cuestiones probatorias, medios de defensa (las excepciones y cuestiones previas), recon
vención, y el ofrecimiento de medios probatorios al invocarse hechos no expuestos en la de
manda o reconvención; son procedentes eventualmente.
Los plazos para este tipo de procesos se encuentran contemplados en el artículo 491° del Có
digo Procesal Civil.
3. Proceso sumarisimo:
Es el proceso contencioso de duración muy corta donde se dan una serie de limitaciones, y
cuya finalidad es precisamente abreviar su tramitación; reservado a aquellas controversias en
las que sea urgente la tutela jurisdiccional o su monto no supere los límites establecidos por
ley (monto mínimo).
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 535

-- 536 of 1506 --

UBILEX
C a ra cterís tic as :
Reducción de los plazos y la concentración de las audiencias en una sola, denominada
audiencia única.
Procedencia: Los supuestos en los cuales procede la tramitación de los procesos sumarísimos
se encuentran contemplados en el artículo 5 4 6 ° del CPC.
Se tramitan en proceso sumarísimo los siguientes asuntos contenciosos-,
i. Alimentos;
z. Separación convencional y divorcio ulterior;
3 . Interdicción;
4. Desalojo;
5. Interdictos;
6 . Los que no tienen una vía procedimental propia, son inapreciables en dinero o hay duda
sobre su monto o, porque debido a la urgencia de tutela jurisdiccional, el Juez considere
atendible su empleo;
7. Aquellos cuya estimación patrimonial no sea mayor de cien Unidades de Referencia Pro
cesal; y,
8 . Los demás que la ley señale.
El saneamiento procesal como la fijación de puntos controvertidos y pruebas se realizan en
audiencia única.
En este tipo de procesos, tienen competencia: los Jueces de Familia (interdicción y separación
convencional y divorcio ulterior), los Jueces Civiles (interdictos y los que no tengan una vía pro
cedimental propia, desalojo cuando la renta mensual es mayor a 50 URP o no exista cuantía),
los Jueces de Paz Letrados (alimentos, desalojo cuando la cuantía sea hasta 50 URP), Juez de
Paz (en aquellas pretensiones cuya estimación patrimonial no sea mayor a 100 URR cuando la
pretensión sea hastaio URP hasta 50 URP para resolver mediante conciliación, cuando supere
esos montos, es competente el Juez de Paz Letrado).
No procede la reconvención; los informes sobre los hechos; el ofrecimiento de medios proba
torios en segunda instancia,y en ningún otro caso; la modificación y ampliación de la deman
d a ^ los medios probatorios extemporáneos.
4. Proceso único de ejecución
El proceso de ejecución es la contraparte de los procesos declarativos ya que en ellos se parte
de una situación cierta que ha quedado insatisfecha, en ese sentido, el objetivo de este proce
so es obtener la satisfacción para el ejecutante respecto de aquello que se pretende ejecutar.
El proceso único de ejecución no persigue la constitución declaración de una relación jurídica
sino que se cumpla con un derecho que ya ha sido reconocido. Liebman “califica al proceso de
ejecución como “aquella actividad con la cual los órganos jurisdiccionales tratan de poner en
existencia coactivamente un resultado práctico, equivalente a aquel que habría debido produ
cir otro sujeto en cumplimiento de una obligación jurídica”.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 537 of 1506 --

Tema 2: Temas de derecho civil
El proceso de ejecución tiene por finalidad obtener el cumplimiento de una obligación que
consta en los títulos ejecutivos siguientes (Art. 688 C.PC.):
1. Las resoluciones judiciales firmes;
2. Los laudos arbítrales firmes;
3. Las Actas de Conciliación de acuerdo a ley;
4 . Los Títulos Valores que confieran la acción cambiaría, debidamente protestados o con la
constancia de la formalidad sustitutoria del protesto respectiva; o, en su caso, con presan-
dencia de dicho protesto o constancia, conforme a lo previsto en la ley de la materia;
5 . La constancia de inscripción y titularidad expedida por la Institución de Compensación y
Liquidación de Valores, en el caso de valores representados por anotación en cuenta, por
los derechos que den lugar al ejercicio de la acción cambiaría, conforme a lo previsto en la
ley de la materia;
6 . La prueba anticipada que contiene un documento privado reconocido;
7 . La copia certificada de la Prueba anticipada que contiene una absolución de posiciones,
expresa o ficta;
8 . El documento privado que contenga transacción extrajudicial;
9 . El documento impago de renta por arrendamiento, siempre que se acredite instrumen
talmente la relación contractual;
10. El testimonio de escritura pública;
11. Otros títulos a los que la ley les da mérito ejecutivo.
En este caso señala la jurisprudencia:
"16.- Estando a lo señalado en el Fundamento 14 de la presente resolución, este extremo de la re
solución administrativa N° 170-2015-INDECOPI-PIU de fecha 13 de marzo de 2015 constituye título
ejecutivo, razón por el cual, el órgano jurisdiccional debe emitir un pronunciamiento de fondo" Exp:
00658-2017-0-2001 -JR-CI-02. Segunda Safe Civil de Piura.
Es decir, en documentos de origen judicial o extrajudicial (puede ser convencional y adm i
nistrativo) en los que existe un mandato de cumplimiento inmediato (títulos ejecutivos), en
relación al cual se encuentra notablemente reducida la actividad probatoria.
El proceso de ejecución se caracteriza por la reducción de las etapas procesales y por los plazos
de las actuaciones, así como por la imposibilidad de cuestionar los títulos en que sustenta la
ejecución, salvo por razones formales.
¿Qué es un título ejecutivo?
Título ejecutivo es aquel documento que prueba la existencia de una relación jurídica, al cual
la ley le confiere una calidad especial, por lo que el proceso se inicia con un mandato de pago
o de ejecución. En consecuencia, el título ejecutivo es aquel documento que la ley establece.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 538 of 1506 --

(£) Definición
Título ejecutivo es el documento en el que consta un derecho reconocido y cuya cualidad
(ejecutiva) la declara la ley; y proceso ejecutivo es aquel destinado a hacer efectivo ese derecho,
de tal manera que s¡ en el proceso de conocimiento, se parte de una situación de incertidumbre
a fin de obtener una declaración jurisdiccional de certeza o la solución a un conflicto intersub
jetivo de intereses, en el proceso ejecutivo se parte de un derecho cierto pero insatisfecho
Sala Civil de la Corte Suprema áe Justicia. Cas. N° 1695-97- Lima.
(Z) Diferencia entre eí título ejecutivo y el título de ejecución
"En efecto debe tenerse presente que el artículo seiscientos ochentiocho de la Ley procesal acotada distingue
el título ejecutivo del título de ejecución, además el mismo Código ha establecido las diferencias en cuanto
a la regulación del proceso ejecutivo con relación al proceso de ejecución de garantías, lo cual se refleja en
que las normas específicas del proceso ejecutivo están contenidas en los artículos seiscientos noventítrés aí
seis- cientos noventiséis. del Código Adjetivo;mientras que las normas relativas al proceso de ejecución dega--:
randas están previstas en los artículos setecientos veinte al setecientos veinticuatro del mencionado Cuerpo
Legal; que, además, cuando se trata de un proceso de ejecución de garantías el título que apareja ejecución no
es la liquidación de saldo deudor como tampoco lo es cualquier otro documento que acredite la existencia de
la obligación; sino la será el documento donde conste eíotorgamiento de la garantía real, com o puede ser-una
garantía hipotecaria tal como ocurre en el presen te caso, entonces, este documento es el considerado como el
título de e je c u c ió n Safa QW Transitoria áe la Corte Suprema de Justicia, Cas. N° 2166-2001-Arequipa.
Tipos de procesos de eje cu ció n :
La norma adjetiva regula las siguientes modalidades de proceso de ejecución:
- Ejecución de obligación de darsuma de dinero.
- Ejecución de obligación de dar bien mueble determinado.
- Ejecución de obligación de hacer.
- Ejecución de obligaciones de no hacer.
- Ejecución de resoluciones judiciales.
- Ejecución de garantías.
Requisitos para accionar en el proceso de ejecución: La demanda es el acto procesal en
virtud del cual se ejerce el derecho de acción, poniendo en marcha la actuación del órgano
jurisdiccional a fin de que éste solucione un conflicto de intereses. La demanda, como acto
inicial del proceso, constituye el pedido que se efectúa ante el Estado para que éste, a través
de la administración de justicia, brinde tutela jurídica, exigiendo al demandado cum plir con
la obligación correspondiente.
Toda demanda debe reunir los requisitos previstos por el artículo 4 2 4 del Código Procesal Ci
vil y además debe estar acompañada de los anexos que establece el artículo 425 del referido
Código. Sólo cumpliendo con todos los requisitos mencionados, podrá ser adm itida a trámite
inmediatamente.
En cuanto al proceso ejecutivo, éste se inicia con la demanda ejecutiva, a la cual, además de
los requisitos generales señalados líneas arriba, se debe acompañar como requisito especial
para su adm isibilidad el título ejecutivo. Con el cumplim iento efectivo tanto de los requisitos
generales como de los requisitos especiales, quedará expedita la ejecución de la obligación.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 539 of 1506 --

Tema 2: Temas de derecho civil
En el proceso único de ejecución, es necesario que la obligación contenida en el título ejecutivo, sea
cierta, expresay exigióle; si es una obligación de dar suma de dinero debe ser además liquida o liquidable.
En relación al primer requisito, implica que el título ejecutivo, debe constar en instrumento, afín
de que se conozca la certeza y la obligación resulte expresaren cuento a la exigibil idad implica
que la obligación contenida en el instrumento al momento de iniciarse el proceso de ejecución
es exigióle, es decir, que el acreedor puede demandar su cumplimiento por qué así resulta del
títu lo yd e las obligaciones legales materialesy sustantivas que regulan la relación jurídica.
Reglas especiales en el Proceso de E jecu ció n
Competencia jurisdiccional del proceso de ejecución: Son competentes para conocer los
procesos con título ejecutivo de naturaleza extrajudicial los jueces civiles y los jueces de paz
letrado, el Juez de Paz Letrado es competente cuando la cuantía de la pretensión no sea mayor
de 100 URR superado este monto son de competencia del Juez Civil. Para conocer los procesos
con título ejecutivo de naturaleza judicial son competentes los jueces de la demanda y para
conocer los procesos de ejecución con garantía constituida los jueces civiles.
1. El mandato ejecutivo: Una vez que se ha presentado la demanda ejecutiva ante el órga
no jurisdiccional pertinente, el juez verificará la concurrencia de los requisitos formales
para su admisión, esto es, deberá constatar el cumplim iento de los requisitos de proce-
denciay admisibilidad de la demanda. En primer lugar, el cumplim iento de las condicio
nes de la acción y de los presupuestos procesales. Luego observará el cumplim iento de los
requisitos generales de admisibilidad de la demanday el acompañamiento de los anexos
respectivos, para luego analizar el título ejecutivo mismo. Este últim o deberá de contener
de modo imprescindible los requisitos formales que la ley señale para cada caso.
Conforme se desprende del art. 690-C del CPC, el mandato ejecutivo (que se expedirá
siemprey cuando se cumplan los requisitos comunes indicados en el artículo 689 del CPC,
vale decir, que la obligación contenida en el título ejecutivo sea cierta, expresa y exigióle,
y, además líquida o liquidable mediante operación aritmética, si se trata de una obliga
ción de darsum a de dinero) ordenará que se cumpla la obligación contenida en el título
ejecutivo (de naturaleza judicial o extrajudicial).
El mandato ejecutivo, dispondrá el cumplimiento de la obligación contenida en el título;
bajo apercibimiento de iniciarse la ejecución forzada, con las particularidades señaladas
en las disposiciones especiales. En caso de exigencias no patrimoniales el juez debe ade
cuar el apercibimiento.
Una vez que el órgano j urisdiccional expide el mandato ejecutivo, el ejecutado podrá con
tradecir la ejecución y proponer excepciones procesales y defensas previas; en ese mismo
escrito deberá de: Presentar los medios probatorios pertinentes, de lo contrario el pedido
será declarado inadmisible. Sólo son admisibles la declaración de parte, los documentos,
y la pericia.
2. La contradicción: El CPC, en su artículo 690-D, regula lo concerniente a la contradicción
en el proceso único de ejecución. Del citado precepto legal (concretamente de su primer
párrafo) se puede apreciar, en principio, que la oportunidad para form ular contradicción
en el referido proceso y proponer excepciones procesales y defensas previas, es de cinco
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 540 of 1506 --

UBILEX
días de notificado el ejecutado con el mandato ejecutivo. Tal plazo es aplicable al pro
ceso único de ejecución, cuya demanda se sustenta en un título ejecutivo de naturaleza
extrajudicial (el art. 6 8 8 ° del CPC contempla los títulos ejecutivos de naturaleza judicial y
extrajudicial en virtud de los cuales se puede promover ejecución).
En el proceso único de ejecución cuya demanda se basa en un título ejecutivo de natu
raleza extrajudicial, el ejecutado puede plantear (en su escrito de contradicción a la eje
cución y según el primer párrafo del artículo 690°-D del CPC) las excepciones procesales
previstas en el artículo 4 4 6 ° del CPC, las cuales son las siguientes:
1. Incompetencia;
2. Falta de capacidad de ejercicio del demandante o de su representante;
3. Representación defectuosa o insuficiente del demandante o del demandado;
4. Oscuridad o ambigüedad en el modo de proponer la demanda;
5. Falta de agotamiento de la vía administrativa;
6 . Falta de legitimidad para obrar del demandante o del demandado;
7 . Litispendencia;
8 . Cosa juzgada;
9. Desistimiento de la pretensión;
10. Conclusión del proceso por conciliación o transacción;
11. Caducidad;
12. Prescripción extintiva;y,
13. Convenio arbitral; Falta de representación legal o de apoyo por capacidad de ejerci
cio restringida del demandante o de su representante.
También puede proponer el ejecutado (en su escrito de contradicción a la ejecución y se
gún el primer párrafo del art. 690-D del CPC) defensas previas como el beneficio de inven
tario, el beneficio de excusión, entre otras.
En el proceso único de ejecución cuya demanda se sustenta en un título ejecutivo de na
turaleza extrajudicial, el ejecutado debe presentar, en el mismo escrito que contiene la
contradicción a la ejecución, los medios probatorios correspondientes que acrediten lo
expuesto en tal contradicción. Si no lo hiciere el órgano jurisdiccional declarará inadm i
sible la contradicción (art. 690-Dsegundo párrafo del CPC). En el proceso único de ejecu
ción cuya demanda se basa en un título ejecutivo de naturaleza extrajudicial, existe una
limitación de medios probatorios (justificada por la naturaleza extrajudicial, existe una
limitación de medios probatorios (justificada por la naturaleza sumaria de tales procesos),
pues en dicha clase de proceso únicamente podrá ofrecerse y admitirse los siguientes me
dios de prueba (indicados en el segundo párrafo del artículo 690-D del CPC):
La declaración de parte
Los documentos
La pericia
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 541 of 1506 --

Tema 2: Temas de derecho civil
Por otro lado, en el proceso único de ejecución cuya demanda se basa en un título eje
cutivo de naturaleza extrajudicial la contradicción que form ula el ejecutado solo puede
fundarse en las hipótesis previstas en los incisos i), 2), y 3) del artículo 690-D del CPC, de
biendo el juez rechazar lim inarm ente— esto es, de plano— la contradicción cuyo susten
to sea ajeno a tales hipótesis, siendo tal decisión judicial apelable sin efecto suspensivo.
La contradicción sólo podrá fundarse según la naturaleza del título en: inexigibilidad o ¡liquidez
de la obligación contenida en el título; nulidad formal o falsedad del título; o, cuando siendo éste un título
valor emitido en forma incompleta, hubiere sido completado en forma contraria a los acuerdos adopta
dos, debiendo en este caso observarse la ley de la materia ¡y la extinción de la obligación exigida.
Cuando el mandato se sustente en título ejecutivo de naturaleza judicial, sólo podrá for
mularse contradicción, dentro del tercer día, si se alega el cumplim iento de lo ordenado
o la extinción de la obligación, que se acredite con prueba instrumental.
Si el ejecutado no form ula contradicción a la ejecución dentro del plazo de ley, el juez del
proceso procederá a em itir un auto sin más trámite (por lo que en este caso no cabe citar
a audiencia ni realizar ningún otro acto procesal), ordenando llevar adelante la ejecución.
Esto últim o se explica un mandato ejecutivo en el que el juez ordena el cumplim iento de
la obligación contenida en el título ejecutivo (de naturaleza judicial o extrajudicial), bajo
apercibimiento de iniciarse la ejecución forzada es por ello, que a falta de contradicción
del interesado, debe hacerse efectivo dicho apercibimiento.
Al respecto, en el VI PLENO CASATORIO CIVIL CAS. N° 2402-2012 Lambayeque (FJ. 39),
se detallan las causales de contradicción, en base a lo regulado en el CPC:
Dicha causal se invoca para cuestionar el fondo del título. Aquí no hay cues-
tionamiento al documento en sí, sino al acto que recoge dicho documento. Se
cuestiona la ejecutabilidad del título por carecer de una prestación cierta, expre
sa y exigióle; condiciones básicas para que un título revista ejecución, tal como
lo describe el artículo 689° del CPC.
La contradicción puede invocar la "¡liquidez de la obligación contenida en ei tí
tulo". Esto implica que no tiene inmediata ejecución una prestación ilíquida se
puede demandar la primera. Las prestaciones liquidables se liquidan mediante
operación aritmética. Cuando el título es ilíquido, no puede procederse a la eje
cución con una simple operación aritmética porque ella responde a razones muy
distintas. En estos casos, estamos ante las llamadas sentencias de condena
genérica o de condena de reserva.
El documento se cuestiona de nulo cuando no acoge la forma señalada por ley.
Se debe probar que se completó en el título valor contrariamente a los acuerdos
adoptados por las partes intervinientes en el título; siendo que la actividad pro
batoria se reduce a la prueba documental.
Cuando se invoca la falsedad del "título ejecutivo" es necesario tener en cuenta :
que el título valor es un documento constitutivo, en cuanto el derecho contenido :
en el título se constituye en el mismo título; con él nace y se transmite el derecho
incorporado. Un documento redactado con caracteres indelebles sobre soporte ;
adecuado, puede ser falso en el acto que le da vida o ser falsificado en su con- :
tenido en cualquier momento posterior a la creación; tanto la alteración como la ;
falsificación de la firma del emitente constituyen diversos aspectos de la falsedad. ;
La inexigibilidad de la obligación
contenida en el título
La liquidez de la obligación conteni
da en el título:
La nulidad formal del título
El título valor completado en forma
contraria a los acuerdos adoptados
Extinción de la obligación
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 542 of 1506 --

UBILEX
DE CONTRADICCIÓN PROCESO ÚNICO DE EJECUCIÓN
Extinción de ia obligación La "extinción de la obligación" constituye otra causal para sustentar la contra
dicción contenida en el artículo 690-D inciso 3) del CPC, Los hechos extintivos
para invocarla no se diferencias de aquellos previstos para aquellas obligacio
nes del derecho común, como el pago, la novación, la compensación, la conso
lidación, etc. -
Excepciones y defensas previas Bajo el proceso único de ejecución se permite recurrir a las excepciones y de
fensas previas. Tradicionalmente se definía a las excepciones como medios de;
defensa del demandado que atacan aspectos formales o procesales de la de
manda interpuesta o el derecho material en que se funda la pretensión. Si se
declara fundada una excepción procesal, su consecuencia será la nulidad de
todo lo actuado, no existiendo pronunciamiento sobre el fondo; mientras que
de ampararse una excepción sustantiva, va a existir un pronunciamiento sobre
el fondo de la litis y se declarará fundada la oposición e infundada o fundada.
La defensa previa viene a ser una modalidad de ejercer el derecho de contradic
ción y busca la suspensión del trámite del proceso hasta que se cumpla con el
requisito de procedibilidad que la ley dispone se debe satisfacer previamente sin
los cuales no es posible iniciar el proceso civil.
Cuando el mandato se sustente en título ejecutivo de naturaleza judicial, solo podrá formularse contradicción si se
alega el cumplimiento de lo ordenado o la extinción de la obligación.
3. Denegación de ejecución: Si el título ejecutivo no reúne los requisitos formales, el juez
de plano denegará la ejecución. El auto denegatorio sólo se notificará al ejecutado si que
da consentido o ejecutoriado.
4. Auto y apelación: El plazo para interponer apelación contra el auto, que resuelve la con
tradicción es de tres días contados, desde el día siguiente a su notificación. El auto que
resuelve la contradicción, poniendo fin al proceso único de ejecución es apelable con
efecto suspensivo. En todos los casos del proceso único de ejecución donde se conceda
apelación con efecto suspensivo, es de aplicación el trám ite previsto en el art. 376 CPC. SI
la apelación es concedida sin efecto suspensivo, tendrá la calidad de diferida, siendo de
aplicación el art. 369 CPC en lo referente a su trámite
5. Medidas cautelares en la ejecución: El artículo 692 del CPC contempla una limitación
cautelar tratándose de los procesos únicos de ejecución, en los casos que se haya consti
tuido prenda (entiéndase garantía mobiliaria en la actualidad), hipoteca o antlcresis para
garantizar las acreencias del sujeto activo de la relación jurídico procesal. Así tenemos
que en tales supuestos resulta inviable sol ¡citar y trabar alguna medida precautoria sobre
otros bienes del ejecutado (no afectados con los derechos reales de garantía mencionado
precedentemente), pues el legislador ha considerado que ellos resulten innecesarios. Di
cha limitación cautelar admite, sin embargo, dos excepciones, cuáles son las siguientes:
1. Que el valor de los bienes gravados con prenda (entiéndase garantía mobiliaria en la
actualidad), antlcresis por hipoteca resulte insuficiente para cubrir la cantidad ade
cuada por concepto de capital, intereses, costas y costos procesales;
2. Que existan otros motivos debidamente acreditados por el ejecutante y adm itido
por el juzgador en decisión que no puede ser recurrida por la contraparte (tales mo
tivos justificantes de la viabilidad de ejecutar una medida cautelar sobre bienes no
gravados, pese a existir otros que si lo están, quedan sometidos al criterio jurisdiccio
nal.
2 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 543 of 1506 --

Tema 2: Temas de derecho civil
I
PROCESO DE EJECUCION DE GARANTIA:
La ejecución de garantías conocido en la doctrina como "ejecuciones comerciales”, “ejecucio
nes aceleradas” y “procesos de ejecución calificada” es una acción real que corresponde al titu
lar del derecho real de garantía para hacer efectiva la venta del bien por incumplimiento de la
obligación garantizada, lo que se despacha en virtud de un título de ejecución constituido por
el documento que contiene la garantía y el estado de cuenta del saldo deudor.
Se trata de otra modalidad del proceso de ejecución en el cual se ejecutan toda clase de ga
rantías reales, prescindiendo de variaciones en razón de la persona a favor de quien se ha otor
gado la garantía. En este proceso el ejecutante acude a los órganos jurisdiccionales exigiendo
tutela jurídica efectiva a fin de que el ejecutado cumpla con las obligaciones contenidas en el
título de ejecución que contiene la garantía real o, en caso contrario, se proceda a rematar los
bienes dados en garantía mobiliaria, anticrética o hipotecaria.
Procedencia: De conformidad con el artículo 720 inciso 1) del Código Procesal Civil, modifica
do por el Decreto Legislativo N °io 6 9 , procede la ejecución de garantías reales, siempre que su
constitución cumpla con las formalidades que la ley prescribe y la obligación garantizada se
encuentre contenida en el mismo documento o en cualquier otro título ejecutivo.
El VI PLENO CASATORIO CIVIL estableció los requisitos de procedencia, ya sea el supuesto de
personas ajenas al sistema financiero o a favor de empresas que lo integran, y se estableció,
entre otros, lo siguiente:
¡ ^ PRECEDENTE PRIMERO: Para la procedencia de una ejecución de: garantías reales, en e¡ caso
J t * | •••;> de personas ajenas al Sistema Financiero, a la demanda de ejecución deberá-acompañarse;;-^:.
jJ S B L r i) Documento constitutivo de la garantía real, que cumpla con las formalidades yrequisitos de?
H H B H j validez:establecidos en los artículos 1098 y 1099 del Código Civil o, en su caso, por ley especial,
con las siguientes particularidades:
a. Tratándose de una garantía real constituida expresamente para asegurar una obligación
determinada, siempre que aquella esté contenida en el propio documento constitutivo de la garantía, a
los efectos de la procedencia de la ejecución, no será exigióle ningún otro documento.
b. Tratándose de una garantía real constituida para asegurar una obligación determinable, existente o
futura, documento reconocido por ley como título ejecutivo u otro documento idóneo que acredíte la
