BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 544 of 1506 --

UBILEX
en el acto de su emisión o aceptación, siempre que cumpla con los demás requisitos establecidos en la ley de
la materia según el tipo de título valor.
b.3 . Tratándose de operaciones distintas de las indicadas en los dos acápites anteriores, documento que con
tenga la liquidación de saldo deudor conforme a lo establecido en el artículo 132 inciso 7 de la Ley N° 2 6 7 0 2 ,
Ley General del Sistema Financiero y del Sistema de Seguros y Orgánica de la Superintendencia de Banca y
Seguros, suscrito por apoderado de la entidad del sistema financiero con facultades para liquidación de opera
ciones, detallando cronológicamente los cargos y abonos desde el nacimiento de la relación obligatoria hasta
la fecha de la liquidación del saldo deudor, con expresa indicación del tipo de operación así como la tasa y tipos
de intereses aplicados para obtener el saldo deudor; asimismo, la parte ejecutante puede presentar prueba
idónea y especialmente documental, para acreditar la obligación objeto de la demanda, teniéndose en cuenta
para ello los fines de los medios probatorios previstos en el artículo 1 8 8 del Código Procesal Civil.
Demanda: El ejecutante anexará a su demanda el documento que contiene la garantía y el
estado de cuenta del saldo deudor. El primero, o sea, el documento que contiene la garantía,
es el título de ejecución en el que figura expresamente la garantía de mobiliaria, la anticresis
y la hipoteca que debe ejecutarse en caso de incumplimiento.
En cambio, el estado de cuenta del saldo deudor, es otro documento que contiene una ope
ración en el que se establece la situación en la que se encuentra el deudor respecto de las
obligaciones que ha contraído, en el que se especifique, el monto de intereses, los gastos que
hubiera ocasionado, el monto que ha devengado la liquidación por cláusula penal, etc. Enton
ces, el objeto del saldo deudor está referido a la cantidad que el ejecutado debe pagar, en caso
de prosperar la acción, para evitar el remate del bien dado en garantía.
Si el bien fuere inmueble, debe presentarse documento que contenga tasación comercial ac
tualizada realizada por dos ingenieros y/o arquitectos colegiados, según corresponda, con sus
firmas legalizadas. Si el bien fuere mueble, debe presentarse similares documentos de tasa
ción, la que, atendiendo a la naturaleza del bien, debe ser efectuada por dos peritos especia
lizados, con sus firmas legalizadas.
Se refiere a la tasación comercial actualizada del bien como exigencia para la admisión de la
demanda de ejecución de garantías.
No será necesaria la presentación de nueva tasación si las partes han convenido el valor actua
lizado de la misma.
Tratándose de bien registrado se anexará el respectivo certificado de gravamen, se entiende
que debe ser expedido por los Registros Públicos correspondientes.
La resolución que declara inadmisible o improcedente la demanda es apelable con efecto sus
pensivo y sólo se notificará al ejecutado cuando quede consentida o ejecutoriada.
Según el VI Pleno Casatorio Civil:
IV) PRECEDENTE CUARTO: El juez de considerar que el estado de cuenta de saldo deudor presenta
evidentes omisiones de los requisitos y formalidades ya precisadas o tiene notorias inconsistencias
contables, debe declarar inadmisible la demanda a los efectos de que el ejecutante presente nuevo
estado de cuenta de saldo deudor conforme a sus observaciones.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 545 of 1506 --

Tema 2: Temas de derecho civil
Mandato de ejecución: Adm itida la demanda, se notificará el mandato de ejecución al ejecu
tado, ordenando que pague la deuda dentro de tres días, bajo apercibimiento de procederse
al remate del bien dado en garantía.
Por consiguiente, el ejecutado en esta modalidad de proceso de ejecución puede asumir las
alternativas siguientes:
a) Cumplir el mandato de ejecución dentro del término previsto, se trata de una aceptación
incondicional, lo que se expresa en el cumplim iento de la obligación derivada del título
de ejecución.
b) Proponer contradicción al mandato de ejecución, en el plazo de tres días desde su n o tifi
cación.
Una innovación importante es lo dispuesto en el numeral 720 m fine, según el cual, en el
mandato ejecutivo debe notificarse al deudor, al garante y al poseedor del bien en caso de
ser personas distintas al deudor. Todo ello a fin de garantizar el debido proceso. Empero si el
ejecutante omite demandarlo o mencionarlos en la demanda, el Juez debe integrar la relación
procesal tanto al garante como al poseedordel bien para que puedan hacervalersus derechos
conforme a los artículos 95 0101 del Código adjetivo vigente.
Según el VI Pleno Casatorio Civil:
■ VI) PRECED EN TE SEXTO: Eí pago dispuesto en el mandato ejecutivo debe serporsuma líquida,mo
pudiendo emitirse mandato ejecutivo disponiendo el pago de suma dinerada en parte liquida y:en
parte ¡líquida, a liquidarse tras el remate judicial o el pedido de adjudicación en pago del ejecutante;
conforma al artículo 746 del Código Procesal Civil, salvo en lo atinente a jos intereses; costas y
costos que se generen después de la emisión del mandato de ejecución hasta la fecha de pago.
Contradicción: El ejecutado, en el mismo plazo que tiene para pagar, puede contradecir con
arreglo a las disposiciones generales.
Las causales para el contradictorio se describen en los tres supuestos que recoge el artícu
lo 690-D del Código Procesal Civil. Son causales cerradas, no cabe interpretación extensiva
a otros supuestos que no sean los expresamente regulados en dicho artículo; de ahí que el
texto de la norma señale; «(...) la contradicción solo podrá fundarse según la Naturaleza del
título en (...)», de tal manera que el juez debe declarar liminarmente la improcedencia de la
contradicción si esta se funda en supuestos distintos a los que describe la norma. VI Pleno
Casatorio Civil (FJ.38),
Orden de remate y saldo deudor: De la contradicción formulada por el ejecutado se correrá
traslado al ejecutante portres días y, con su contestación o sin ella, se resolverá: (i) ordenando
el remate o, (ii) declarando infundada la contradicción. Luego se establecerá el saldo deudor
conforme a lo establecido para las obligaciones de dar sumas de dinero,
a) Orden de Remate.- La ley establece que transcurrido el plazo sin haberse pagado la o bli
gación o declarada infundada la contradicción, el Juez, sin trámite previo, ordenará el
remate de los bienes dados en garantía. En este tipo de procesos sólo cabe expedir un
auto, en la medida en que pone fin al proceso de ejecución resolviendo la contradicción
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 546 of 1506 --

UBILEX
propuesta por el ejecutado. En tal sentido se expide el auto para resolver la contradicción
ordenando el remate en caso de que ésta no se hubiera formulado, por lo tanto, no proce
de em itir decisión final como se hacía antes.
b) Saldo deudor.- Si después del remate del bien dado en garantía, hubiera saldo deudor,
se proseguirá la ejecución dentro del mismo proceso, conforme a lo establecido para las
obligaciones de dar suma de dinero. En este tipo de procesos no proceden medidas cau
telares.
Para finalizar, ofrecemos un esquema sobre la secuencia del proceso único de ejecución, con
forme al C.PC., elaborado por el profesor Alexander Rioja Bermúdez29:
29 Guía rápida del trámite en el proceso único de ejecución.
