27. Procesos no contenciosos
Generalmente se recurre al poder judicial para despejar una incertidumbre. La principal misión
de los jueces es resolver los casos litigiosos, pero también los jueces ejecutan actos que no supo
nen una controversia, sino por el contrario se fundan en el acuerdo de las partes o en la inexisten
cia de contradicción. En este último caso hablamos de jurisdicción voluntaria o no contenciosa,
es decir que la función del juez en estos casos es la de dar autenticidad al acto o verificar el cum
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 548 of 1506 --

UBILEX
plimiento de una formalidad. Propiamente aquí no se habla de función jurisdiccional, sino que
se trata de uno de los casos en que los jueces ejercen funciones administrativas.
En la jurisdicción contenciosa la sentencia tiene la autoridad de cosa juzgada. En la jurisdic
ción voluntaria no hay cosa juzgada ni sentencia. En la primera hay conflicto, en la segunda
hay ausencia de conflicto.
Se tram itan como procesos no contenciosos los siguientes asuntos (7 4 9 ° CPC):
1. Inventario.
2. Administración judicial de bienes.
3. Adopción.
4 . Autorización para disponer derechos de incapaces.
5. Declaración de desaparición, ausencia o muerte presunta.
6 . Patrimonio familiar.
7. Ofrecimiento de pagoy consignación.
8 . Comprobación de testamento.
9 . Inscripción y rectificación de partida.
10. Sucesión intestada.
11. Reconocimiento de resoluciones judiciales y laudos expedidos en el extranjero.
12. Las solicitudes que, a pedido del interesado y por decisión del Juez, carezcan de conten
ción.
13. La designación de apoyos para personas con discapacidad.
14. Las que la ley señale.
El inventario (763oa 768oCPC): El i nventario consiste en un acta descri ptiva de la existencia
de los bienes, documentos, etc. que se encuentran en un determinado mom ento en pose
sión, detentación de determinadas personas, o que formen parte de un determ inado acervo
patrimonial o estén custodiados o aun sólo materialmente colocados en un determinado
lugar, se sepa o no quién es en aquel momento el que tiene jurídicam ente su posesión o su
detención.
Cuando lo prescriba la ley o se sustente su necesidad, cualquier interesado puede solicitar
facción de inventario con el fin de individualizar y establecer la existencia de los bienes que
pretende asegurar (763o CPC).
Puede ordenarse que los bienes inventariados sean valorizados por peritos, siempre que se so
licite antes de concluida la audiencia. Pedida la valorización, el Juez nombrará peritos y fijará
fecha para la audiencia respectiva (767o CPC).
La adopción (781oa 785o CPC): Por la adopción el adoptado adquiere la calidad de hijo del
adoptante y deja de pertenecer a su familia consanguínea.
En este proceso no contencioso se tram ita la adopción de personas mayores de edad. Si el
presunto adoptado es contemplada en el artículo 4 4 del Código Civil, se requiere la interven
ción de su representante o su apoyo. Si es este el adoptante, la solicitud se entenderá con el
Ministerio Público (781oCPC).
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 549 of 1506 --

ietna 2: Temas de derecho civil
Consentida o ejecutoriada la resolución que declara la adopción, el Juez oficiará al Registro del
Estado Civil respectivo para que extienda nueva partida de nacimiento del adoptado y anote
la adopción al margen de la partida original (784o CPC).
El patrimonio familiar (795° a 801oCPC): El patrimonio fam iliar consiste en la afectación de
un inmueble urbano o rural a la satisfacción de las necesidades de sustento y de la vivienda
del titu lar y su fam ilia y, en consecuencia, se lo sustrae a las contingencias económicas que
pudieran provocar, en lo sucesivo, su embargo o enajenación.
Pueden solicitar la constitución de patrimonio familiar:
a) Cualquiera de los cónyuges sobre bienes de su propiedad.
b) Los cónyuges de común acuerdo sobre bienes de la sociedad conyugal.
c) El padre o la madre que haya enviudado o se haya divorciado, sobre sus bienes propios.
d) El padre o la madre solteros sobre bienes de su propiedad.
e) Cualquier persona dentro de los límites en que pueda donar o disponer libremente en
testamento.
Pueden ser beneficiarios del patrimonio fam iliar las siguientes personas en relación con el
constituyente:
a) Los cónyuges.
b) Los hijos y otros descendientes menores o incapaces.
c) Los padres y otros ascendientes que se encuentren en estado de necesidad.
d) Los hermanos menores o incapaces.
A la solicitud de constitución de patrimoniofamiliarsedebeacompañareindicarenella(796°CPC):
1. Certificado de gravamen del predio afectado.
2. M inuta de constitución del patrimonio familiar.
3. Documentos públicos que acrediten la relación fam iliar invocada.
4. Los datos que permitan individualizare! predio.
5. Los nombres de los beneficiarios y el vínculo que los une con el solicitante.
Comprobación de testamento (817oa 825oCPC): En este proceso no contencioso se tram ita
la comprobación de autenticidad y cumplimiento de formalidades del testamento cerrado,
ológrafo, militar, m arítimo o aéreo, para su posterior protocolización notarial (817oCPC).
Está legitimado para solicitar la comprobación (Art. 817oCPC):
1. Quien tenga en su poder el testamento.
2. Quien por su vínculo fam iliar con el causante se considere heredero forzoso o legal.
3. Quien se considere instituido heredero voluntario o legatario,y
4. Quien sea acreedor del testador o del presunto sucesor.
Tratándose de testamento cerrado, sólo se admite como medio probatorio el acta notarial de
otorgamiento extendida en el sobre o cubierta.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 54

-- 550 of 1506 --

Tratándose de testamento ológrafo sólo son admisibles el cotejo de letra y firm a o, si esto no
fuera posible, la pericia (Art. 821oCPC).
Si la solicitud de comprobación de testamento fuera rechazada en forma definitiva, puede ser
nuevamente intentada en un proceso de conocimiento dentro de un plazo no mayor de un
año desde que quedó ejecutoriada la resolución final (Art. 824o CPC).
Inscripción y rectificación de partida (826oa 829oCPC): La solicitud de inscripción o de recti
ficación de una partida de matrimonio o de defunción, y la de rectificación de una partida de
nacimiento, procede sólo cuando no se practicó dentro del plazo que señala la ley o cuando el
Juez considere atendible el motivo (Art. 826oCPC).
La solicitud será formulada por (Art. 827 CPC):
1. El representante legal o el apoyo de una persona contemplada en el artículo 43 o 44 del
Código Civil y, a falta de aquél, por cualquiera de sus parientes hasta el cuarto grado de
consanguinidad o segundo de afinidad, para la rectificación de la partida de nacimiento.
2. La persona cuya partida de nacimiento se trata de rectificar, si es mayor de edad, y, si ha
fallecido, por sus parientes hasta el cuarto grado de consanguinidad o segundo de afinidad.
3. Cualquiera de los cónyuges o, por fallecimiento de éstos, por cualquiera de sus parientes
hasta el cuarto grado de consanguinidad o segundo de afinidad, para la inscripción o rec
tificación de la partida de matrimonio.
4. Cualquiera de los parientes hasta cuarto grado de consanguinidad o segundo de afinidad
del fallecido, para la inscripción o rectificación de la partida de defunción.
5. Por el Ministerio Público cuando el fallecido no tiene parientes. En este caso no se requie
re de publicación, salvo que la actuación del Ministerio Público se origine a pedido de
interesado.
Se requiere la publicación del extracto de la solicitud que se practicará por una sola vez (Art.
828oCPC).
Las personas en cuyas partidas figure por error entre sus nombres y apellidos la palabra “de”
o las letras "y”, “i”, “e” o “a”, u otro error manifiesto de ortografía, de sexo o similar que fluya del
propio documento, podrán pedir su rectificación. El Juez dispondrá de plano, sin observar el
trám ite regular, la rectificación correspondiente (Art. 829oCPC).
Sucesión intestada (Arts. 830 a 836 CPC).- La sucesión intestada, tiene por objeto designar a
los herederos legales de aquellas personas que han fallecido sin otorgar testamento, o si éste
ha sido declarado nulo, invalidado o caducado.
La sucesión intestada se tram ita ante el Notario o Juez de Paz Letrado del lugar del últim o
domicilio del causante, a elección de los interesados.
Pueden tram itarlo el presunto heredero o herederos.
Requisitos del trámite: Copia del DNI del solicitante, nombre del causante, copia certifica
da de la partida de defunción del causante, copia certificada de la partida de nacimiento del
presunto heredero o herederos, partida de matrimonio si fuera el caso, relación de los bienes
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 551 of 1506 --

Tema 2: Temas de derecho civil
conocidos, certificado negativo de testamento expedido por la Oficina Registra!, certificado
negativo de declaratoria de herederos expedido por la Oficina Registral.
Trámite:
1. Deberá presentar por escrito ante el Notario Público o juez de Paz Letrado, con firm a de
abogado.
2. El Notario o Juez de Paz Letrado ordenará se extienda anotación preventiva de la solicitud
en Registros Públicos.
3. El Notario o]uez de Paz Letrado mandará a publicar un aviso conteniendo un extracto de
la solicitud, en el diario de los anuncios judiciales como en otro de amplia circulación.
4. Pueden incluirse otros herederos dentro del proceso, durante el plazo de quince (15) días
de iniciado el trámite, debiendo acreditar su condición o cal idad de heredero. El notario o
Juez de Paz Letrado pondrá en conocimiento de los solicitantes la inclusión de un nuevo
presunto heredero. Si transcurridos los diez (10) días útiles no mediara oposición al trám i
te de parte de los presuntos herederos, el notario lo incluirá en su declaración y en el tenor
del acta correspondiente.
5. Acta o sentencia declarando herederos: Transcurridos quince días útiles desde la publica
ción del últim o aviso, el notario extenderá un acta declarando herederos del causante a
quienes hubiesen acreditado su derecho. El Juez de Paz Letrado en sentencia declarará a
los herederos.
6. Inscripción de la Sucesión Intestada: Cumplido con expedir acta de declaratoria de he
rederos, el notario remitirá partes a Registro Públicos, a fin que se inscriba la sucesión
intestada. El Juez de Paz en su caso mediante oficio ordenará la inscripción del mismo en
Registros Públicos.
Reconocimiento de resoluciones judiciales y laudos expedidos en el extranjero (Arts. 837
a 840 CPQ.- Es el proceso tendiente a obtener el reconocimiento por tribunales peruanos de
una Resolución Judicial o laudo arbitral expedido en el extranjero.
Procedimiento:
1. Demanda firm ada por abogado.
2. En divorcio, acreditar que el domicilio conyugal se constituye en el lugar donde se em itió
la sentencia extranjera.
3. Acreditar que se haya citado al demandado conforme a ley; el lugar del proceso; que se
le haya concedido el plazo para comparecer y que se le hayan otorgado las garantías del
debido proceso.
4. Acreditar, mediante Resolución o certificación expendida por el Tribunal Extranjero, que
la sentencia tiene la calidad o autoridad de Cosa Juzgada.
5. Acreditar que no existe en el país juicio pendiente entre las mismas partes y sobre el
mismo objeto iniciado con anterioridad a la Interposición de la demanda que originó la
sentencia, mediante Certificación o Declaración Jurada de su inexistencia debidamente
legalizada o certificada ante la Secretaria de la Sala.
6 . Acreditar que la sentencia, materia de Reconocimiento, no es incompatible con otra.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 552 of 1506 --

UBILEX
7. Copia simple del documento de identidad del solicitantey el apoderado.
8. Precisar la dirección del demandado, anexando certificación domiciliaria o, si se descono
ce, declarar bajo juramento o promesa de haber agotado las gestiones.
9. Partida de matrimonio celebrado en el Perú o inscrito ante el Consulado Peruano.
10. Sentencia extranjera previamente legalizada por el Cónsul peruanoy por el Ministerio de
Relaciones Exteriores.
11. T r a d u c c ió n o f ic ia l d e la s e n t e n c ia e x t r a n je r a (A rt. 2 1 0 7 C .C .).
12. Poder, por Escritura Pública o por acta suscrita ante la Secretaría de la Sala.
13. Que la sentencia no resuelva sobre asuntos de competencia exclusiva peruana.
14. Que el Tribunal Extranjero haya sido competente para conocer el asunto, de acuerdo a las
normas de Derecho Internacional.
D e s ig n a c ió n d e ap o yo s p a ra p e rs o n a s con d is c a p a c id a d (Arts. 841 a 8 4 7 C P C ).- Los apoyos
son formas de asistencia libremente elegidos por una persona mayor de edad para facilitar el
ejercicio de sus derechos, incluyendo el apoyo en la comunicación, en la comprensión de los
actos jurídicos y de las consecuencias de estos, y la manifestación e interpretación de la volun
tad de quien requiere el apoyo.
Requisitos de la solicitud: Las solicitudes de apoyos y salvaguardias se tramitarán ante el juez
competente o notario, y deberán iniciarse por petición de la propia persona mayor de edad, de
forma librey voluntaria, para coadyuvar a su capacidad de ejercicio.
No obstante, se dispone que en los casos de las personas que se encuentren en estado de coma
que no hubieran designado un apoyo con anterioridad (Art. 44 numeral 9 del C.C.) y aquellas
personas con discapacidad que no pueden manifestar su voluntad (Art. 45-B numeral 2 del
C.C.), la solicitud puede ser realizada por cualquier persona en los términos previsto en el artí
culo 659-E del Código Civil, esto es, tomando en cuenta la relación de convivencia, confianza,
amistad, cuidado o parentesco que exista entre ella o el las y la persona que requiere apoyo.
La solicitud contiene indicaciones con respecto a quiénes serán las personas o instituciones
que fungirían de apoyo, a qué actos jurídicos se restringen y por cuánto tiempo rigen.
En el c a s o d e q u e la s p e r s o n a s s o lic it a n t e s s e a u n a p e r s o n a c o n d is c a p a c id a d , a d e m á s d e los
r e q u is it o s p r e v is to s en lo s A rts. 4 2 4 y 4 2 5 d e l C P C , a la s o lic it u d se a c o m p a ñ a :
a) Las razones que motivan la solicitud.
b) El certificado de discapacidad que acredite la condición de discapacidad de la persona
que solicita el apoyo o salvaguardia.
Contenido de la resolución final:
La resolución final debe indicar quién o quiénes serían las personas o instituciones de apoyo,
a qué actos jurídicos se restringen, por cuánto tiempo van a regiry cuáles son las medidas de
salvaguardia, de ser necesarias. Tal resolución se inscribe en el Registro Personal conforme al
artículo 2030 del Código Civil.
Adicionalmente, la resolución final es redactada en formato de lectura fácil donde sus conte
nidos son resumidos y transcritos con lenguaje sencillo y claro, de acuerdo a las necesidades
de la persona con discapacidad.
