Tema 2: Temas de derecho civil
28. Medidas cautelares
Naturaleza.- La medida cautelar, denominada también preventiva o precautoria, es aquella
institución procesal mediante la cual el órgano jurisdiccional, a instancia de parte, asegura la
eficacia o cumplim iento de la sentencia a dictarse en el proceso que dirige, anticipando todos
los determinados efectos del fallo, en razón de existir verosim ilitud en el derecho invocado y
peligro en que la demora en la sustanciación de la litis u otra razón justificable traiga como
consecuencia que la decisión judicial no pueda reintegrar a la parte vencedora en el juicio la
totalidad de su derecho.
"La medida cautelar no impone un estado jurídico inatacable; por el contrario, más allá de la
probabilidad de que a quien se le otorga pueda resultar vencedor del proceso, lo cierto es que
toda cautelar es provisoria y por ello mismo, las consecuencias que la medida genere no pueden
ser absolutas, porque de ser así lo provisorio se convertiría en definitivo y lo probable adquiriría la
calidad de certeza." Cas. N ° 2479-2014 C allao.
Requisitos: Se tiene que señalar en cuanto a los presupuestos, que los mismos son aquellos
elementos que son indispensables para obtener una medida cautelar válida y no pasible de
ser revocada. La doctrina tradicionalmente reconoce tres: la apariencia del derecho, el peligro
en la dem oray la contracautela o caución.
Sin embargo, en el Perú, con la dación de la Ley N° 29384, del 28.06.2009, se agrega como un
requisito para la concesión de una medida cautelar, la razonabilidadde la medida para garan
tizar la eficacia de la pretensión.
i. Verosimilitud del derecho, o también conocida como la apariencia de fundabilidad de
la pretensión principal o fumus boni ¡uris. Aquí debemos referir que cuando el magistrado
emite pronunciamiento respecto de la pretensión principal, se dice que se dio certeza al
derecho litigioso, que el juez ha de alcanzar en tales casos, la convicción. Sin embargo, cabe
precisar que la función jurisdiccional no solamente admite pronunciamiento de certeza,
sino también otro en los que no se logra la convicción del derecho pero sí un grado de certi
dumbre suficiente como para alcanzar los niveles exigidos por ley para determinados fines.
En estos casos, la decisión adoptada no es definitiva al no ser un juicio de certeza. Si el
juez considera que la pretensión demandada tiene algún sustento jurídico a considerar,
que la posición del demandante sea discutible o en todo caso, que exista la posibilidad
razonable de que la pretensión sea declarada fundada, es que se concede la medida por
contar con verosim ilitud el pedido cautelar efectuado.
ii. Peligro en la demora de la prestación jurisdiccional o p e ricu lu m in mora. Para Monroy
Palacios, constituye el presupuesto más importante del pedido cautelar, a tal punto que
se le puede considerar como el verdadero fundamento de la Teoría Cautelar. Este requisi
to está relacionado con la amenaza de que el proceso se torne ineficaz, por el transcurso
del tiempo, entre el inicio de la relación procesal hasta la expedición de la sentencia defi
nitiva, no sólo se sustenta en la posibilidad de que el demandado impida el cum plim ien
to de lo pretendido por el accionante sino también por el sólo transcurso del tiempo, éste
se convierte en una amenaza que merece una tutela especial.
