iv. Adecuación, ésta es la correlación que debe existir entre el pedido cautelar y la situa
ción jurídica de la que es objeto, también se le conoce como la relación de coherencia
y adecuación entre lo que se intenta garantizar y la medida solicitada como garantía o
como dice Monroy Palacios, que deba ser congruente y proporcional con el objeto de su
aseguramiento.
v. Razonabilidad de la medida, debe precisarse en principio que lo razonable es aquello
que está ajustado a la razón, lo justo, equitativo, lo aceptable, debiendo entenderse a la
razón como la facultad por medio de la cual puede el hombre discurrir o juzgar. En aten
ción a ello, podemos decirque la razonabilidad de la medida, implica que con ella se pue
da asegurar de mejor manera la pretensión principal del proceso, con lo cual podemos
decirque la razonabilidady la adecuación están relacionadas; y ello es así puesto que en
la exposición de motivos de la modificatoria instaurada (Proyecto de Ley 3079/2008-CR)
se establece que laexigenciade la razonabilidad de la medida, determinará que sea nece
saria la adecuación real entre el pedido cautelary la pretensión procesal garantizada con
dicho pedido: teniendo como sustento la instrum entalidady el principio de proporciona
lidad; siendo que el principio de proporcionalidad persigue que la medida deba tener un
fin determinado y que la misma sea adecuada para el logro del fin; por ello se dice tam
bién que por el principio de proporcionalidad, la medida que se adopte debe ser aquella
que afecte en menor medida la esfera jurídica ajena.
Clases: Según nuestro ordenamiento procesal civil pueden clasificarse las medidas cautelares:
A) De acuerdo a la oportunidad en que han sido peticionadas.
1. - Medidas cautelares anticipadas o fuera del proceso (artículos 608y 636 del C P C ) .
2 . - M e d id a s c a u t e la r e s d e n t r o d e l p r o c e s o ( a r t íc u lo 6 2 9 d e l C P C ) .
B) Según su previsión o no en el ordenamiento legal.
1.- Medidas cautelares genéricas o atípicas (artículo 629 del CPC). Es la que dicta el
juez atendiendo a las necesidades del caso, si no existiese un modo específico que
satisfaga la necesidad de aseguramiento. Es aquella que no se encasilla o se ubica en
los tipos de medidas ya existentes.
La medida genérica no debe ser utilizada en reemplazo de las específicamente regula
das, cuando esas no son suficientes para asegurar el derecho de quien la refiere. Si las ti
