en recurrirá las genéricas con la misma amplitud con laque deben usarse aquellas.
"La medida cautelar genérica es aquella diferente a las tipificadas en el ordenamiento procesal, per
mitiendo al juzgador ser flexible en cuanto a los modelos existentes, introduciéndoles variantes o
modificaciones, que asegure de la forma más adecuada el cumplimiento de la decisión definitiva''1.
Exp. N° 2555-2009-Uma.
2.- Medidas cautelares específicas o típicas (Capítulondel Título IV de la Sección Quin
ta del CPC). Estas medidas se subdividen a su vez en:
a) Medidas para futura ejecución forzada (artículos 624 al 673 del CPC).-
La a fe c t a c ió n d e lo s b ie n e s d e l o b lig a d o b a jo c u a lq u ie r a d e la s m e d id a s p a r a e je c u c ió n
f o r z a d a c o n s t it u y e un a c to p re v io p a ra la e je c u c ió n f o r z a d a d e u n a s e n t e n c ia d e c o n d e n a .
P u e d e n s e r la s s ig u ie n t e s :
a.i) Embargo: El embargo es una medida cautelar que garantiza la ejecución de la sen
tencia que se dicte en un proceso, cuando este persigue una pretensión apreciable
en dinero. Este consiste en la afectación jurídica de un bien o derecho del presunto
obligado, aunque se encuentre en posesión de tercero, con las reservas que para este
supuesto señala la ley (Art. 642 CPC).
El embargo recae sobre el bien afectado y puede alcanzar a sus accesorios, frutos y
productos. Pueden ser:
En forma de depósito.- S e a fe c ta n b ie n e s m u e b le s s e ñ a la n d o a u n d e p o s it a r io
q u e se h a c e r e s p o n s a b le p o r lo s b ie n e s . C u a n d o el e m b a r g o re c a e en b ie n e s
m u e b le s d e l o b lig a d o , é ste s e rá c o n s t it u id o en d e p o s it a r io , s a lv o q u e se n e g a re
a a c e p t a r la d e s ig n a c ió n ,
En forma de inscripción.- La medida consiste en una inscripción en el asiento re-
gistral, lo que importa un conocimiento de todos. Tratándose de bienes registra
dos, la medida puede ejecutarse inscribiéndose el monto de la afectación, siempre
que ésta resulte compatible con el título de propiedadya inscrito. Este embargo no
impide la enajenación del bien, pero el sucesor asume la carga hasta por el monto
inscrito. La certificación registral de la inscripción se agrega al expediente.
En forma de retención.- Cuando la medida recae sobre derechos de crédito u
otros bienes en posesión de terceros, cuyo titu lar es el afectado con ella, puede
ordenarse al poseedor retener el pago a la orden del Juzgado, depositando el
dinero en el Banco de la Nación. Tratándose de otros bienes, el retenedor asume
las obligaciones y responsabilidades del depositario, salvo que los ponga a dis
posición del Juez.
En forma de intervención.-Se c o n f ig u r a c o n la a d m in is t r a c ió n d e b ie n e s y d ir i
g id o c o n t r a a q u e llo s q u e r e a liz a n a c t iv id a d e s p r o d u c t iv a s . P u e d e n se r:
• Intervención en recaudación.- Se a fe c ta n lo s in g r e s o s d e la p e r s o n a n a t u r a l
o ju r íd ic a s o b r e la q u e se d ic t a n .
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
