UBILEX
• In te rv e n c ió n en in fo rm a c ió n .- La intervención en información se lim ita a
fiscalizar o controlar el movimiento económico de una empresa.
Mediante esta medida cautelar, el designado por el juez llamado interven
tor, actúa juntamente con el administrador o administradores de una empre
sa, en lo estrictamente comisionado, sin desplazarlo. El interventor informan
te se designa para que dé noticia acerca del estado de los bienes objeto del
proceso o de las operaciones o actividades con la periodicidad que se esta
blezca en la providencia que lo designe. En ese sentido, el artículo 665 del CPC
dice: “el juez nombrará uno o más interventores informadores, señalándose el
lapso durante el cual deben verificar directamente la situación económica del
negocio afectado y las fechas en que informarán al juez”.
En forma de administración.- Es aquel que recae sobre bienes fructíferos que se
afectan en administración con la finalidad de recaudar los frutos que produzcan.
Tal es la definición legal de este instituto que hace el CPC en su art. 669.
a.2) Secuestro:
Judicial.- Es una medida cautelar de conservación de un bien específico. Como tal ga
rantiza el mantenimiento de la integridad del bien de Litis hasta el final del proceso,
para hacer posible la ejecución específica de la sentencia. Cuando el proceso princi
pal tiene por finalidad concreta la dilucidación del derecho de propiedad o posesión
sobre determinado bien, la medida puede afectar a éste, con el carácter de secuestro
judicial, con desposesión de su tenedory entrega a un custodio designado porel juez.
Conservativo.- El secuestro conservativo no recae necesariamente sobre el bien
que se discute en el proceso principal como en el judicial, sino en cualquier bien
del deudor. Cuando la medida tiende a asegurar la obligación de pago conteni
da en un título ejecutivo de naturaleza judicial o extrajudicial, puede recaer en
cualquier bien del deudor, con el carácter de secuestro conservativo, también
con desposesión y entrega al custodio.
En caso de que se dicte secuestro conservativo sobre soportes magnéticos, ópticos o similares,
el afectado con la medida tendrá derecho a retirar la información contenida en ellos.
Secuestro de vehículo.- El vehículo sometido a secuestro, será internado en almacén
de propiedad o conducido por el propio custodio, accesible al afectado o veedor, si lo
hay. El vehículo no podrá ser retirado sin orden escrita del juez de la medida. Mientras
esté vigente el secuestro, no se levantará la orden de captura o de inmovilización.
a.3) Anotación de demanda en los Registros Públicos:
Ésta se da a efectos de que, en virtud del principio de publicidad registra!, personas
ajenas al proceso puedan i nformarse de la existencia de dicho proceso. Cuando la pre
tensión discutida en el proceso principal está referida a derechos inscritos, la medida
cautelar puede consistir en la anotación de la demanda en el registro respectivo. Para
su ejecución, el juez remitirá partes al registrador, los que incluirán copia íntegra de
la demanda, de la resolución que la admite y de la cautelar. El registrador cumplirá la
orden por su propio texto, siempre que la medida resulte compatible con el derechoya
inscrito. La certificación registral de la inscripción se agrega al expediente.
