Tema 2: Temas de derecho civil
La anotación de la demanda no impide la transferencia del bien ni las afectaciones
posteriores, pero otorga prevalencia a quien ha obtenido esta medida.
b) Medidas temporales sobre el fondo (Arts. 674 al 681 del CPC).
La medida temporal sobre el fondo consiste en la ejecución anticipada de loque el juzgador
va a decidiren la sentencia en su integridad o sólo en aspectos sustanciales, por la necesidad
impostergable del que la pide o por la firmeza del fundamento de su acción y prueba que
aporta, siempre que los efectos de la decisión puedan ser de posible reversión y, no afecten
el interés público. El CPC establece que proceden: la asignación anticipada de alimentos; la
ejecución anticipada cuanto la pretensión principal versa sobre separación, divorcio, patria
potestad, régimen de visitas, entrega de menor, tutela y cúratela; ejecución anticipada en
los procesos sobre nombramiento y remoción de administradores de bienes; ejecución an
ticipada en los procesos de desalojo por vencimiento del plazo de contrato o por otro título
que obligue la entrega; ejecución anticipada en el interdicto de recobrar.
c) Medidas innovativas (Arts. 682 al 6 8 6 del CPC).
Cuando el Juez restituye al estado de hecho o de derecho que se tenía cuando se interpu
so la demanda; esto siempre y cuando resulte necesario para asegurar la efectividad de
la sentencia. El CPC establece que se pueden dar en: procesos de interdicción, demandas
sobre demolición de una obra en ejecución que daña la propiedad o la posesión, deman
das de ejercicio abusivo del derecho, demandas de reconocimiento o restablecimiento
del derecho a la intim idad, a la imagen y a la voz.
d) Medidas de no innovar (Arts. 687 del CPC).
Esta medida se encuentra regulada en el artículo 687 del C.PC., siendo una medida cau
telar específica, pero no para futura ejecución forzaday que se distingue de la medida de
innovar. Es una medida esencialmente conservativa porque lo que busca es que se pueda
hacer efectivo eí fallo emitido por el órgano jurisdiccional, situación que no podría ha
cerse posible de modificarse o alterarse la situación anterior al auto admisorio de la de
manda. Esta medida tiene un carácter excepcional, es decir no será concedida si pueden
aplicarse otras medidas cautelares que aseguren el normal cumplim iento de la decisión
final; sin embargo, cabe precisar que la misma no puede tener por finalidad la de suspen
der el trám ite de otro proceso o el de impedir el cumplim iento de una resolución dictada
en éste, ni mucho menos impedirse inicie un proceso.
"La medida cautelar de no innovar o también conocida como prohibición de innovar, es aquella
en la que con mayor claridad se evidencia el efecto cristalizador de las medidas cautefaresylassi
consecuencias inhibitorias de las actividades de las partes sobre los bienes en juego en un
litigio. Esta medida tiene por finalidad impedir que mientras dure el pleito, aiguna de las partes
realice movimientos o actos jurídicos o de hecho que alteren la situación existenteypporendes
afecten o frustren los derechos de la contraparte. Se encuentra dirigida a mantener el estado
de hecho o de derecho existente al tiempo de ser admitida la demanda, para poder garantizar la
eficacia de la sentencia a dictarse posteriormente Cas. N° 2479-2014-Cailao. Fj. 9.
Éfc
Trámite de las medidas cautelares (Art. 637 C.P.C): El procedimiento cautelar tiene como
principal característica el ser sumario. Su tramitación es expeditivay casi inmediata; y solo res
