UBILEX
ponde a dos situaciones: concede o rechaza la pretensión cautelar, sin embargo, esta últim a
alternativa puede alterarse, si luego de apelado el rechazo, se revoca la decisión.
Cuando el juez aprecia de manera sumaria la veroslmllldad del derecho lo hace a través de la
prueba anexa a la pretensión cautelar, pero puede darse el caso que los medios de pruebas
aportados requieran ser mejorados o complementados por los otros, para una mejor aprecia
ción del derecho que se invoca. En estas circunstancias, de manera excepcional, el juez puede
conceder un plazo adicional a fin de que el peticionante presente otros medios de prueba, que
m uestren-en m ejorform a- la verosimilitud del derecho que sustenta su pretensión principal.
El procedimiento cautelar es reservado. La reserva opera en todo momento sea que se ampare
o rechace la pretensión. En este últim o supuesto, procede la apelación, pero la característica
de la reserva del procedimiento se mantendrá porque el demandado no será notificado y el
superior absolverá el grado, sin adm itirle intervención alguna.
La reserva en el procedimiento va a producir que el principio de contradicción se suspenda. En
esta etapa, podemos ubicar el procedimiento cautelar porque solo interviene el peticionante
ante el juez. Esta reserva cesa luego de que se dicta la medida. Recién ahí se deja sin efecto
la suspensión del contradictorio, para dar paso a que la parte afectada con la medida cautelar
pueda ejercer su derecho de defensa a través de la oposición lo cual podrá hacerlo dentro de
un plazo de 05 días hábiles, contados desde que toma conocimiento de la resolución cautelar.
Esto se debe a que el procedimiento que se regula en el Código Procesal Civil se basa en reglas
de carácter imperativo. Cuando se resuelve la oposición, ya sea estimándola o desestimándo
la, en ambos casos la apelación se concede, de ser el caso, sin efecto suspensivo.
29. Ejecución forzada: remate y adjudicación
La ejecución forzada, forzosa o procesal (denominada también vía de apremio), procede
cuando los bienes materia del proceso ejecutivo o de ejecución han sido afectados con la fina
lidad de asegurar dicho cumplimiento.
De conformidad con lo dispuesto en el artículo 725 del Código Procesal Civil, la ejecución for
zada de los bienes afectados se realiza en las siguientes formas:
a. Remate.- El r e m a te d e n o m in a d o t a m b ié n en l a d o c t r in a y le g is la c ió n c o m p a r a d a s u b a s t a
o v e n t a f o r z a d a o j u d ic ia l, se c o n s t it u y e en la v e n t a ju d ic ia l d e lo s b ie n e s e m b a r g a d o s y
p r o c e d e u n a v e z q u e h a y a q u e d a d o f ir m e la r e s o lu c ió n ju d ic ia l q u e o r d e n a lle v a r a c a b o
la e je c u c ió n , d e b ie n d o t a s a r s e lo s b ie n e s p a r a s e r r e m a ta d o s .
El r e m a te es d e f in id o p o r A z u la C a m a c h o c o m o “La v e n t a f o r z a d a q u e el f u n c io n a r io j u d i
c ia l o a d m in is t r a t iv o , s u s t it u y e n d o la v o lu n t a d d e l p r o p ie t a r io , h a c e d e u n b ie n m u e b le o
in m u e b le a q u ie n f o r m u la la m e jo r o fe rta o p o s t u r a ”.
Se e n c u e n t r a r e g u la d o en el s u b c a p ít u lo 2 ° (“R e m a te ”) d e l c a p ít u lo 3i ( “E je c u c ió n f o r z a d a ”)
d e l t ít u lo V (“P ro c e so ú n ic o d e e je c u c ió n ”) d e la s e c c ió n q u in t a (“P ro c e so s c o n t e n c io s o s ”)
d e l C ó d ig o P ro c e sa l C iv il, en lo s a rts. 728 a! 7 4 3 .
Reglas comunes al remate:
El artículo 736° del CPC establece una serie de reglas que deben ser seguidas en el acto de
remate, desprendiéndose de dicho precepto legal lo siguiente.-
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

