Tema 2: Temas de derecho civil
La base de la postura (o precio base) consistirá en una suma equivalente a las dos
terceras partes del valor de tasación del bien o bienes a ser rematados y de ninguna
manera se adm itirá oferta inferior.
Si el remate comprende varios bienes,sedebe preferiral postorque proponga adqui
rir el conjunto de los bienes afectados, siempre y cuando el precio que ofrezca para
tal efecto no resulte inferior a la suma de las posturas hechas individualmente; es
decir, con relación a un determinado bien, caso contrario, los bienes en cuestión irán
siendo rematados por separado.
Si son varios los bienes a ser rematados, el acto de remate finalizará, bajo respon
sabilidad del m artiliero público o del juez (a falta de m artiliero público hábil en el
lugar donde se convoque el remate: art. 731 del CPC) que conduce el remate, en caso
que el producto de lo ya rematado resulte suficiente para cubrir lo adeudado por el
ejecutado, lo que comprenderá, obviamente, el capital, los intereses devengados, y
las costas y costos procesales.
b. Adjudicación.- Se constituye en un acto judicial que consiste en la atribución de un bien
como propio a determinadas personas como consecuencia de una subasta con la consi
guiente entrega del mismo.
Se e n c u e n t r a r e g u la d o en el s u b c a p ít u lo 30 (“a d ju d ic a c ió n ”) d e l c a p í t u l o s (“E je c u c ió n f o r z a d a ”)
d e l t ít u lo V (“P ro c e so ú n ic o d e e je c u c ió n ”) d e la S e c c ió n Q u in t a (“P ro c e so s C o n t e n c io s o s ”) d e l
C ó d ig o P ro c e sa l C iv il, en lo s a r t íc u lo s 7 4 4 y 7 4 5 .
De acuerdo a nuestro ordenamiento jurídico, la adjudicación procede en el caso de frustrarse
el remate (convocado por tercera vez) por falta de postores. En tal hipótesis, el ejecutante se
encuentra facultado para solicitar la adjudicación directa del bien materia de ejecución for
zosa, por el precio base de la postura que sirvió para la últim a convocatoria (esto es, la tercera
convocatoria), pagando el exceso sobre el valor de su crédito, si lo hubiere (art. 742-tercer pá-
rrafo-del CPC) quedando sin efecto la adjudicación (conforme al art. 744-primer párrafo del
CPC) si el adjudicatario no deposita el exceso dentro del tercer día de notificado con la liqui
dación prevista por el artículo 746 del Código Procesal Civil (liquidación de intereses, costas y
costos del proceso).
