1. Familia: clases. Parentesco
Los Principios Constitucionales de protección a la fam iliay de promoción del m atrim onio que
el legislador ha considerado en la Constitución Peruana dei979 en el artículos0 prescribía que
“El Estado protege el matrimonio y la familia como sociedad natural e institución fundamen
tal de la Nación”. En la Constitución de 1993 en el artículo 4o se considera que "La com unidady
el Estado protegen especialmente al niño, al adolescente, a la madrey al anciano en situación
de abandono. También protegen a la fa m iliay promueven el m atrim onio”. Reconocen a estos
últimos como institutos naturalesy fundamentales de la sociedad.
En el Código Civil, en el Libro III El Derecho de Familia, en las disposiciones generales de la
sección primera, en el artículo 233o, el legislador ha señalado que "La regulación jurídica de la
familia tiene por finalidad contribuir a la consolidación y fortalecimiento, en armonía con los
principiosy normas proclamados en la Constitución Política del Perú.
El Art. 234o del Código Civil ha definido al matrimonio como la “Unión voluntariamente con
certada por un varón y una mujer legalmente aptos para ellay formalizada con sujeción a las
disposiciones del C.C. a fin de hacer vida en común”. En el mismo artículo 234osegundo párrafo
del Código Civil se establece la igualdad del marido y la mujer, los mismos que tienen en el ho
gar autoridad, consideraciones, deberes, derechos y responsabilidades iguales; concordando
con lo prescrito en el Art. 20 de la Constitución Política del Perú que considera que nadie debe
ser discriminado por motivo de origen, raza, sexo, idioma, religión, opinión, condición econó
mica o de cualquier otra índole. Esta igualdad, podemos encontrarla también en los artículos
24o, 36°, 234o, 287o, 290o, 292o, 293o, 300o, 313o, 315°, 317°, 419° del Código Civil.
Tanto el marido como la mujer participan en el gobierno del hogar, administran el patrimonio
de familia, ejercen la representación de la sociedad conyugal, disponen los bienes comunesy
están facultados para decidir en cuestiones referidas a la Patria Potestad de los hijos.
El Principio de Amparo a las uniones de hecho, se regulaba en el artículo 9 de la Constitución de
1979 "La unión estable de un varón y una mujer, libres de impedimento matrimonial, que forman
un hogar de hecho por el tiempo y en las condiciones que señala la ley, da lugar a una sociedad
de bienes que se sujeta al régimen de la sociedad de gananciales, en cuanto es aplicable”.
Por otro lado, en la Constitución de 1993 en el artículo 50 “La unión estable de un varón y una
mujer libres de impedimento matrimonial que forman un hogar de hecho, da lugar a una co
munidad de bienes sujeta al régimen de la sociedad de gananciales en cuanto sea aplicable”.
