tes; en donde se establece que todos los hijos tienen iguales Derechos sucesorios respecto
de sus padres; comprendiendo a los hijos matrimoniales reconocidos voluntariamente o de
clarados por sentencia judicial, respecto a la herencia del padre o la madre y los parientes de
