En la Constitución Política de 1979, en el artículo 6 o se señala que “El Estado ampara la pater
nidad responsable. Es debery derecho de los padres alimentar, educary dar seguridad a sus
hijos, así como los hijos tienen el deber de respetary asistir a sus padres. Todos los hijos tienen
iguales derechos. Está prohibida toda mención sobre el estado civil de los padres y la natura
leza de la filiación de los hijos en los registros civiles y en cualquier documento de identidad”.
En el artículo 6 o de la Constitución Política de 1993 se prescribe que: “La política nacional de
población tiene como objetivo d ifu n d iry promover la paternidady maternidad responsables.
Reconoce el Derecho de las familias y de las personas a decidir. En Tal sentido, el Estado ase
gura los programas de educación y la información adecuadosy el acceso a los medios, que no
afecten la vida o la salud. Es debery derecho de los padres alimentar, educary dar seguridad
a sus hijos. Los hijos tienen el deber de respetary asistir a sus padres. Todos los hijos tienen
iguales derechos y deberes. Está prohibida toda mención sobre el estado Civil de los padres y
sobre la Filiación en los Registros Civilesy en cualquier otro documento de identidad".
En el Tercer Pleno Casatorio Civil (Pub. El Remano 13.05.2011) se establece que en los procesos
de familia, como en los de alimentos, divorcio, filiación, violencia familiar, entre otros, el Juez
tiene facultades tuitivas y, en consecuencia, se debe flexibiIizar algunos principios y normas
procesales como los de iniciativa de parte, congruencia, formalidad, eventualidad, preclusión,
acumulación de pretensiones, en atención a la naturaleza de los conflictos que debe solu
ciones, derivados de las relaciones familiares y personales, ofreciendo protección a la parte
perjudicada, ello de conformidad con lo dispuesto en los artículo 4 y 43 de la Constitución
Política del Estado que reconoce, respectivamente, la protección especial a: el niño, la madre,
el anciano, la familia y el matrimonio, así como la fórm ula política del Estado democrático y
social de Derecho.
Clases de familia: Cambios sociales y jurídicos tales como la inclusión social y laboral de la
mujer, la regulación del divorcio y su alto grado de incidencia, las grandes migraciones hacia
las ciudades, entre otros aspectos, han significado un cambio en la estructura de la familia
tradicional nuclear, conformada al rededor de la figura del pater familias. Consecuencia de ello
es que se hayan generado familias con estructuras distintas a la tradicional, como son las sur
gidas de las uniones de hecho, las monopaternales o las que en doctrina se han denominado
familias reconstituidas.
Familias Reconstituidas.- En realidad no existe un acuerdo en doctrina sobre el nomen iuris de
esta organización familiar, utilizándose diversas denominaciones tales como familias ensam
bladas, reconstruidas, reconstituidas, recompuestas, familias de segundas nupcias o familias-
tras. Son familias que se conforman a partir de la viudez o el divorcio. Esta nueva estructura fa-
miliarsurge a consecuencia de un nuevo matrimonio o compromiso. Así, la fam ilia ensamblada
puede definirse como “la estructura fam ilia r originada en el m atrim onio o la unión concubinaria de
