Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 563 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
una pareja en la cual uno o ambos de sus integrantes tienen hijos provenientes de una relación previa".
(STC Exp. N.° 09332-2006-PA /TC- Lima).
Parentesco: Es la relación o conexión fam iliar existente sobre dos o más personas, vinculación
que pueden derivarse de la propia naturaleza, de la Ley, o de la religión. Hay tres clases de
parentesco:
a) Parentesco N a tu ra l o consanguíneo. Cuando se deriva de la naturaleza, o se funda en la con
sanguinidad, como es del caso de las personas que descienden de otras, tales como los
hijos respecto a los padres, en la línea recta: o cuando descienden de un tronco común,
como los hermanos, tíosy sobrinos, parientes en la línea colateral. (Art. 236 del C.C.)
b) Parentesco Legal. Cuando se establece por ministerio de la ley que crea relaciones de pa
rentesco entre varias personas, como aquéllas que se derivan de la adopción, que vinculan a
los adoptantes con los adoptados; o por afinidad resultante del matrimonio, que vincula
a cada uno de los cónyuges con los parientes consanguíneos del otro. (Arts. 237 al 238 del
C.C.)
c) Parentesco Espiritual. Que se deriva de la administración de los sacramentos del bautismo
y de la confirmación, que vincula a los padrinos con los padres de losahijadosy con éstos.
Desde el punto de vista jurídico los efectos del parentesco son limitados. Así en el caso de la
Ley peruana, se aplican las reglas siguientes:
1. - En el parentesco por consanguinidad: es reconocido indefinidamente en el caso de los que
descienden unos de otros, es decir en la línea recta; en tanto que entre parientes de la
línea colateral los efectos legales se extienden hasta el cuarto grado, o sea hasta primos
hermanos.
2. - En el parentesco legal: el que se deriva de la adopción, ha sido equiparado por el Código
Civil de 1984 al consanguíneo. No habiendo variación en el parentesco por afinidad, que
se circunscribe a la línea recta ilim itadam entey a la línea colateral sólo hasta el segundo
grado, y de aplicación únicamente a los impedimentos matrimoniales.
3. - En el parentesco espiritual: las limitaciones son mayores, y su aplicación, o utilidad se
restringe al ámbito del Derecho Procesal, como causales de recusación y excusa de los
jueces, árbitros, peritos, relatores, secretarios de Corte, excusa de los fiscales y para impe
dimentos y tachas de los testigos.
En cuanto a la relación conyugal no genera parentesco alguno, porque para nuestro sistema
jurídico, los cónyuges no son parientes, ni afines, como los consideraba el Derecho Romano.
Definimos tam bién:
TRO NCO , a la persona que viene a ser ascendente común de las personas cuyo parentesco co
lateral se trata de establecer, o la persona a quienes estas reconocen como ascendiente común.
De modo que los hermanos tienen como tronco al padre y la madre: los primos-hermanos al
abuelo, lo mismo que tíos,y sobrinos, los primos segundos tienen como tronco al bisabuelo, etc.
De ahí que entre más alejado sea el parentesco que vincula a dos personas, más remoto será
su tronco.
LÍNEA, es la sucesión ordenada de personas que se derivan o proceden del mismo tronco.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 564 of 1506 --

UBILEX
I ■ Se denomina línea recta cuando se forma con personas que descienden unas de otras; línea
TT colateral, cuando está constituida por personas que sin descender unas de otras unen sus
respectivas líneas rectas en un ascendiente común, o sea que provienen de un ascendiente
común, que viene a ser el tronco, pero sin descender unas de otras.
En el caso de la línea recta se distinguen dos ramas, una que asciende y otra que desciende
la primera está formada por los ascendientes de la persona que se ha tomado como punto de
referencia, que vienen a ser sus padres, abuelos, bisabuelos, etc.; y la segunda por sus descen
dientes, como hijos, nietos, bisnietos, etc.
GRADO es la distancia existente entre dos parientes, o también al tránsito o intermedio que
hay entre los mismos. En el supuesto de computación de grados en la línea recta, el punto de
partida o peldaño de partida, lo da una de las personas cuyo parentesco se desea averiguar, y
el punto de llegada, o peldaño de llegada, lo da la otra persona, de modo que el número de
peldaños o de generaciones que hay entre ambas proporciona el grado de parentesco entre
los dos así, del hijo al padre, o viceversa, hay un grado en la línea recta; desde el abuelo al nieto
dos grados; del bisabuelo al bisnieto hay tres grados.
En la línea colateral, utilizando la escalera de dos tramos, en tijera, para la computación, el
punto de partida lo da uno de los parientes, desde cuyo peldaño se asciende hasta el vértice o
tronco común, del que se desciende, por el segundo tramo de la escala, hasta, el otro pariente,
quedando determinado el grado de parentesco según el número de peldaños o personas que
medien entre los dos referidos extremos. En ambas líneas, rectay colateral, el grado de paren
tesco está determinado por el número de personas comprendidas entre el punto de partida
y el punto de llegada menos una, aunque resulta más sencilla la computación considerando
únicamente el número de enlaces que median entre los dos extremos.
