Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 565 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
2 . M a t r im o n io c i v i l
Según el artículo 234 del Código Civil “el matrimonio se entiende como la unión voluntaria y
concertada por un varón y una mujer legalmente aptos para e llay formalizada con sujeción a
las disposiciones del C.C., a fin de hacer vida en común".
Se trata de un acto jurídico complejo en cuya estructura se advierte por un lado el consenti
miento de los interesados y concurrentemente la intervención administrativa del funcionario
público (alcalde o notario) 2 encargado de controlar la legalidad del acto. Los contrayentes son
pues enteramente libres para decidirsi persisten en su propósito de contraer m atrim onio pero
una vez prestado este consentimientoy la intervención del funcionario público declarándolos
unidos en matrimonio, los cónyuges ya no pueden sustraerse a los efectos de dicha institución
que se gobierna por un conjunto de normas que fijan sus deberes y derechos con prescinden-
cia de su voluntad, de modo que el matrimonio es la institución social y jurídica que se carac
teriza por la subordinación de la voluntad individual de los cónyuges a intereses superiores de
orden fam iliary social recogidas en un estatuto familiar de carácter obligatorio.
Naturaleza jurídica: Este concepto ha tratado de ser explicado desde las siguientes perspectivas:
a) Tesis Contractualista: Esta posición puede ser enfocada, desde tres perspectivas: lacanóni-
ca, la civil tradicional y la del derecho de familia.
El enfoque canónico considera al matrimonio como un sacramento que se forma a través
de un contrato m atrimonial válido. La perspectiva Civil tradicional postula que el m atri
monio participa de todos los elementos esenciales de los contratos, lo que determina que
resulta aplicable la teoría de la nulidad de los contratosy de los vicios del consentimiento.
Finalmente, se postula que el matrimonio es un contrato, pero no un simple contrato, sino
un acto de poder estatal o un acto jurídico complejo.
b) Tesis Institucionalista: Desde esta perspectiva, el m atrim onio es entendido como el con
junto de normas, formalidades, deberes, obligaciones, derechosy relaciones a que deben
someterse, sin posibilidad de negociar, quienes deseen casarse, vale decir que se trata de
una institución.
c) D octrina M ix ta : De acuerdo con esta teoría, el matrim onio es a la vez un contrato y una
institución. “Mientras que el matrimonio como acto es un contrato, como estado es una
institución”.
Efectos jurídicos: A partí r de la celebración del matrimonióse derivan un conjunto de deberes y
derechos, una serie de efectos o relaciones entre los padres e hijos de los cónyuges entre sí, que
el Código Civil contempla bajo el título de deberes y derechos que nacen del matrimonio en el
Título II correspondiente a las relaciones entre los cónyuges (Art. 287 a 294 C.C.); y además otras
relaciones de carácter patrimonial o económico (Art. 295 a 300); y lo relativo a la sociedad de
gananciales (Art. 301 a 326) o al régimen de separación de patrimonios (Art. 327 a 331).
Según nuestro C.C., en su artículo 269o, para reclamar efectos civiles del matrimonio la prueba es
la partida de matrimonio del Registro de Estado Civil, la copia certificada del acta de su celebra
ción, el que al ser un instrumento público crea presunción legal de veracidad de su contenido.
Esta prueba es exigible para los matrimonios celebrados después del 4 de octubre dei930; los
2 Ley N °3i 643 (Pub. 15/12/2023): Ley que faculta a los notarlos a celebrar matrimonios civiles en sus respectivas
notariasy excepcionalmente fuera de estas conforme al procedimiento del C.C.
