partida de los Registros Parroquiales.
El C.C. en su artículo 269oen su segundo párrafo, señala que la posesión constante del estado de
matrimonio subsana cualquier defecto puramente formal de la partida.
En el artículo 271 del C.C. se contempla respecto de la prueba de m atrim onio resultante de
proceso penal, en la hipótesis de que si resultara inutilizada el acta de m atrim onio civil por
acto delictivo de empleados del Municipio, encargados de su custodia o por terceros, porcau-
sa de adulteración o destrucción o supresión o alteración del estado civil; razón por la cual
se haya abierto el proceso penal por delito contra la fe pública. La sentencia que determina
la preexistencia del m atrim onio posee mérito suficiente para ordenar la reinscripción de la
partida de matrimonio.
3. La teoría de los impedimentos matrimoniales
El matrimonio es un acto jurídico por el que se establece el vínculo jurídico m atrimonial en
cuya estructura encontramos los siguientes requisitos: el consentimiento matrimonial, la di
versidad del sexo de los contrayentes, la aptitud nupcial, la observancia de la forma prescrita,
con intervención de la autoridad competente para su celebración. La teoría de la invalidez se
presenta cuando no concurre alguno de estos requisitos. La aptitud nupcial está determina
da por la ausencia de impedimentos señalados por ley en los artículos 241 al 243 de nuestro
Código Civil. En donde se puede encontrar impedimentos generales; impedimentos de orden
moral o social; impedimentos establecidos en protección de las personas con capacidad de
ejercicio restringida. Plazo de viudedad.
En la Doctrina, según su extensión los impedimentos se clasifican en absolutos y relativos-,
son absolutos cuando la persona está inhabilitada para contraer m atrim onio con ninguna
otra persona, por ejemplo, porque ya está casada, o porque padece de SIDA. Son relativos
cuando no se pueden casar con determinadas personas por ejemplo si fuera su pariente en
línea recta.
Según su duración los impedimentos se clasifican en permanentes y temporales-, permanentes
son los impedimentos que no desaparecen como por ejemplo el parentesco; los temporales
son los que tienden a desaparecer como el impedimento por impubertad o falta de edad mí
nima.
Según sus efectos los -impedimentos pueden ser dirimentes o impedientes. Son dirimentes
aquellos cuya inobservancia provoca la invalidez del matrimonio, regulados en los Arts. 241 y
242 del C.C. por ejemplo el casado que se vuelve a casar. Son impedientes aquellos cuya inob
servancia no provoca la invalidez del matrimonio, sino la aplicación de sanciones civiles a los
infractores, que por lo general son de carácter económico, como la pérdida de la retribución
del tutor que ha infringido la prohibición de contraer matrimonio con el menor o con la per
sona con capacidad de ejercicio restringida a su cargo; y que están regulados en el Art. 243 y
244 del C.C.
Los impedimentos generales o absolutos que señalan quienes no pueden contraer m atrim o-
nio y que están enumerados en el artículo 241 del Código Civil son los siguientes:
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 567 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
IMPEDIMENTOS GENERALES
Artículo 241.- No pueden contraer matrimonio:
1. Las personas menores de dieciocho años de edad.
2. Las personas que se encuentren en estado de coma, en tanto no exista manifestación de
la voluntad expresa o tácita sobre esta materia.
3. Los casados.
IMPEDIMENTOS DE ORDEN MORAL 0 SOCIAL
Artículo 242.- No pueden contraer matrimonio entre sí:
1. Los consanguíneos en línea recta. El fallo que condena al pago de alimentos en favor del
hijo extramatrimonlal no reconocido ni declarado judicialmente produce también el impe
dimento a que se refiere este inciso.
2. Los consanguíneos en línea colateral dentro del segundo y el tercer grado. Tratándose del
tercer grado el juez puede dispensar este impedimento cuando existan motivos graves.
3. Los afines en línea recta.
4. Los afines en el segundo grado de la línea colateral cuando el matrimonio que produjo la
afinidad se disolvió por divorcio y el excónyuge vive.
5. El adoptante, el adoptado y sus familiares en las líneas y dentro de los grados señalados en
los incisos 1 a 4 para la consanguinidad y la afinidad.
6. El condenado como partícipe en el homicidio doloso de uno de los cónyuges, ni el procesa
do por esta causa con el sobreviviente.
7. El raptor con la raptada o a la Inversa, mientras subsista el rapto o haya retención violenta.
© IMPEDIMENTOS ESTABLECIDOS EN PROTECCIÓN DE PERSONAS CON CAPACIDAD DE EJERCICIO
RESTRINGIDA. PLAZO DE VIUDEDAD
Artículo 243.- No se permite el matrimonio:
1. Del tutor o del curador con el menor de dieciocho años de edad o con la persona con capa
cidad de ejercicio restringida del artículo 44, numerales 4 al 7, durante el ejercicio del cargo,
ni antes de que estén judicialmente aprobadas las cuentas de la administración.
2. Del viudo o de la viuda que no acredite haber hecho inventario judicial, con Intervención del
Ministerio Público, de los bienes que esté administrando pertenecientes a sus hijos o sin
que preceda declaración jurada de que no tiene hijos bajo su patria potestad o de que éstos
no tienen bienes.
La infracción de esta norma acarrea la pérdida del usufructo legal sobre los bienes de
dichos hijos. Esta disposición es aplicable al cónyuge cuyo matrimonio hubiese sido inva
lidado o disuelto por divorcio, así como al padre o la madre que tenga hijos extramatrimo
niales bajo su patria potestad.
3. De la viuda en tanto no transcurran por lo menos 300 días de la muerte de su marido, salvo
que diere a luz. Esta disposición es aplicable a la mujer divorciada o cuyo matrimonio hu
biera sido invalidado.
Se dispensa el plazo si la mujer acredita no hallarse embarazada, mediante certificado
médico expedido por autoridad competente.
La viuda que contravenga la prohibición contenida en este inciso pierde los bienes que
hubiese recibido de su marido a título gratuito.
Matrimonio entre menores de edad
La prohibición del m atrimonio entre menores de 18 años se establece a través de la modifica
ción del artículo 46 del Código Civil, a través de la Ley N°31945 (Pub. 25.11.2023), la misma que
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 568 of 1506 --

UBILEX
I I modifica los artículos 42, 241, 243 y 248 e incorpora el artículo 46-Ay el inciso 10 del artículo
’T 274 del Código Civil, respondiendo así a una regulación conforme a los tratados internaciona
les sobre los derechos de los menores de edad.
De este modo, establece que los menores de 18 años no pueden contraer matrimonio, declara
nulo el matrimonio de menores de 18 años y faculta a los menores de edad, en forma directa
y sin intermediarios, a solicitar la anulabilidad del m atrim onio que hubieran contraído con
anterioridad a la vigencia de esta ley. Además, prohíbe el m atrim onio del tutor o curador con
el menor de 18 años de edad o con la persona con capacidad de ejercicio restringida.
Hasta antes de la Ley N° 31945, el Código Civil exigía para contraer m atrim onio que los pre
tendientes tengan capacidad plena, que se adquiere a partir de los 18 años. De manera ex
cepcional contemplaba la posibilidad de que los padres soliciten al juez autorización para el
matrimonio desús hijos mayores de 16 años.
A partir de la modificación del régimen de capacidad jurídica en el Código Civil, que introdujo
el D. Leg. N° 1384, los mayores de 14 años y menores de 18 años adquirían la capacidad de
jurídica al contraer matrimonio, según el segundo párrafo del artículo 42o del Código Civil, en
consecuencia, la edad para contraer m atrimonio se redujo a los catorce años.
Esta nueva regulación, confirma que a los 18 años de edad se adquiere capacidad de ejercicio
plenay deroga la disposición que señalaba que-excepcionalmente- adquieren plena capaci
dad de ejercicio, los mayores de 14 años y menores de 18 años que contraigan matrimonio, o
quienes ejerciten la paternidad.
Por ello, esta ley marca un cambio sustancial en la legislación peruana con el objetivo de pro
teger a los menores en situaciones de vulnerabilidad. La capacidad legal de los menores se
condiciona ahora al nacimiento de un hijo, según los nuevos criterios establecidos en el Códi
go Civil.
4. La teoría de la invalidez matrimonial
La infracción a cualquiera de los impedimentos que aparecen en los artículos 241, 242 y 243
del C.C., se convierte automáticamente en una causal de invalidación del matrimonio. De ha
berse celebrado el matrimonio a pesarde la existencia de algún impedimento para contraerlo
traerá como consecuencia la insubsistencia del vínculo m atrimonial; lo que se traduce en lo
siguiente: falta de aptitud nupcial, defectos en el consentimiento m atrimonial, inobservancia
de la forma prescrita,y la impotencia absoluta.
La pretensión de invalidez del matrimonio como puede verse en el artículo 281 del C.C., se
tram ita como proceso de conocimiento,y le son aplicables en cuanto sean pertinentes las dis
posiciones establecidas para los procesos de separación de cuerpos o divorcio por causal.
Porello en salvaguarda de los derechosy principios tutelados porel ordenamiento jurídico en
los artículos 274 a 277 del Código Civil, se regula dos modalidades puede declararse la invali
dez del matrimonio a través de la nulidady la anulabilidad.
Nulidad del matrimonio: La nulidad se deriva de la existencia de un vicio con carácter de
esencial. El impedimento para su celebración está determinado porel Derecho Positivo, pero,
si a pesar de éste se lleva a cabo el matrimonio, se lesiona además del interés de los contrayen-
