tes, el interés de la colectividad, el interés general. La consecuencia de celebrar un m atrimonio
pasando por alto normas de orden público es la invalidez del matrimonio.
Las causales por las que un matrimonio es nulo se encuentran indicadas expresamente en el
Art. 274° del C.C.:
jl 1. Del casado. No obstante, si el primer cónyuge del bigamo ha muerto o si el primer matrimonio ha
