matrimonio contraído por el cónyuge de un desaparecido sin que se hubiera declarado la muerte presunta
de este, solo puede ser impugnado, mientras dure el estado de ausencia, por el nuevo cónyuge y siempre
que hubiera procedido de buena fe.
2. De los consanguíneos o afines en línea recta.
3. De los consanguíneos en segundo y tercer grado de línea colateral. Sm embargo, tratándose del tercer
grado, el matrimonio se convalida si se obtiene ia dispensa judicial del parentesco.
4. De los afines en segundo grado de la línea colateral cuando el matrimonio anterior se disolvió por divorcio
y el excónyuge vive.
5. Del condenado por homicidio doloso de uno de los cónyuges con el sobreviviente a que se refiere el Art.
242, inc. 6.
6. De quienes lo celebren con prescindencia de los trámites establecidos en los artículos 248 a 268. No
obstante queda convalidado si los contrayentes han actuado de buena fe y se subsana la omisión.
7 De los contrayentes que, actuando ambos de mala fe, lo celebren ante funcionario incompetente, sin per
juicio de la responsabilidad administrativa, civil o penal de éste. La acción no puede ser planteada por los
cónyuges.
8. De los contrayentes menores de dieciocho años.
En el artículo 275 del C.C. respecto de los Titulares de la Acción de Nulidad, se prescribe que
debe ser interpuesta por el Ministerio Público y puede ser intentada por cuantos tengan en
ella un interés legítim oy actual. Si la nulidad es manifiesta, el juez la declara de oficio. Sin em
bargo, disuelto el matrimonio, el Ministerio Público no puede intentar ni proseguir la nulidad
ni el juez declararla de oficio.
Por otro lado, respecto a lo inextinguible de la acción de nulidad el artículo 276 del C.C. consi
dera que la acción de nulidad no caduca.
Anulabilidad del matrimonio: Se considera que un matrim onio es anulable cuando le falta
un elemento al que la legislación civil no considera esencial razón por la cual es susceptible de
convalidación. En el artículo 277 del C.C. Es anulable el matrimonio:
y 2. De quien está impedido conforme el artículo 241, inciso 2. La acción sólo puede ser intentada por el:
n cónyuge del enfermo y caduca sí no se interpone dentro del plazo de un año desde el día en que tuvo;
J conocimiento de la dolencia o del vicio.
3. Del raptor con la raptada o a la inversa o el matrimonio realizado con retención violenta. La acción
corresponde exclusivamente a la parte agraviada y sólo será admisible si se plantea dentro del plazo dé;
un año de cesado el rapto o la retención violenta.
De quien no se halla en pleno ejercicio de sus facultades mentales por una causa pasajera, La acción sólo;
puede ser interpuesta por él, dentro de los dos años de la celebración del casamiento y siempre que no
haya hecho vida común durante seis meses después de desaparecida la causa.
