UBILEX
5. De quien lo contrae por error sobre la identidad física del otro contrayente o por ignorar algún defecto
sustancial del mismo que haga insoportable la vida común. Se reputan, defectos sustanciales: la vida
deshonrosa, la homosexualidad, la toxicomanía, la enfermedad grave de carácter crónico, la condena por
delito doloso a más de dos años de pena privativa de libertad o el oculíamiento de la esterilización o del
divorcio. La acción puede ser ejercitada sólo por el cónyuge perjudicado, dentro del plazo de dos años de
celebrado.
6. De quien lo contrae bajo amenaza de un mal grave e inminente, capaz de producir en el amenazado un
estado de temor, sin el cual no lo hubiera contraído. El juez apreciará las circunstancias, sobre todo si la
amenaza hubiera sido dirigida contra terceras personas. La acción corresponde al cónyuge perjudicado y
sólo puede ser interpuesta dentro del plazo de dos años de celebrado. El simple temor reverencial no anula
el matrimonio.
7. De quien adolece de impotencia absoluta al tiempo de celebrarlo.
La acción corresponde a ambos cónyuges y está expedita en tanto subsista la impotencia. No procede la
anulación si ninguno de los dos cónyuges puede realizar la cópula sexual.
8. De quien, de buena fe, lo celebra ante funcionario incompetente, sin perjuicio de la responsabilidad admi
nistrativa, civil o penal de dicho funcionario. La acción corresponde únicamente al cónyuge o cónyuges de
buena fe y debe interponerse dentro de los seis meses siguientes a la celebración del matrimonio.
Efectos del matrimonio invalidado frente a terceros: El m atrim onio invalidado produce los
efectos de un m atrimonio válido disuelto por divorcio, frente a los terceros que hubieran ac
tuado de buena fe.
Validez de matrimonio ilícito: Según el artículo 286 dei C.C., se configura el matrimonio ilíci
to cuando se ha celebrado contrariamente al artículo 243 del mismo cuerpo de leyes, en el que
no se permite el m atrimonio del tutor o curador con el menor o con la persona con capacidad
de ejercicio restringida (los pródigos los que incurren en mala gestión, ebrios habituales, los
toxicómanos), del viudo o viuda que no acredite haber hecho inventario judicial, de la viuda
en tanto no transcurran por lo menos 300 días de la muerte de su marido, salvo que diere a luz.
No obstante, lo indicado, el matrimonio es válido.
5. El concubinato
El artículo 50 de la Constitución Política del Perú, de 1993 reconoce el concubinato como la
unión estable entre un varón y una mujer, libres de impedimento m atrimonial, que forman
un hogar de hecho, dando lugar a una comunidad de bienes sujeta al régimen de la sociedad
de gananciales en cuanto sea aplicable. Merece recalcar que un rasgo distintivo de la unión
concubinaria es la vida en común notoria y a la vista de la sociedad, en el mismo domicilio,
mas no cuando ésta es clandestina o a través de encuentros furtivos.
En la doctrina se ha distinguido dos tipos de uniones de hecho o concubinatos: la propiay la
impropia, así tenemos.-
Concubinato propio: Unión voluntaria entre un hombre y una mujer, libres de im pedi
mento m atrim onial, para alcanzar los fines y cum plir los deberes semejantes a los del
m atrim onio, de conform idad con lo establecido en el prim er párrafo del artículo 326 del
Código Civil.
Concubinato impropio: Aquellas uniones de hecho que se dan sin cumplir con lo señalado
anteriormente, es decir, que uno de los concubinos o ambos estén casados, que los concubinos
sean del mismo sexo, o que ambos o uno de ellos tenga algún impedimento matrimonial.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 571 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
En ambos casos, la legislación peruana ha regulado un tratam iento distinto. Así, en el caso del
concubinato propio, cuando dicha unión haya durado un periodo de 2 años continuos, se ori
ginará una sociedad de bienes sujeta al Régimen de Sociedad de Gananciales; situación que
no ocurre con el concubinato impropio.
Lo concerniente a la unión de hecho o concubinato se halla previsto en el artículo 326 del Có
digo Civil, según el cual:
La unión de hecho, voluntariamente realizada y mantenida por un varón y una mujer, li
bres de impedimento matrimonial, para alcanzar finalidades y cumplir deberes seme
jantes a los del matrimonio, origina una sociedad de bienes que se sujeta al régimen de
sociedad de gananciales, en cuanto le fuere aplicable, siempre que dicha unión haya du
rado por lo menos dos años continuos.
La posesión constante de estado a partir de fecha aproximada puede probarse con cual
quiera de los medios admitidos por la ley procesal, siempre que exista un principio de
prueba escrita.
Según lo dispuesto por el segundo párrafo del artículo 326 del C.C, la unión de hecho
se considera como fehacientemente constituida sólo a través de un proceso judicial en
el que se declare como tal, previa constatación del cumplim iento de requisitos legales
(unión de varón y mujer libres de impedimento matrimonial por los menos dos años con
tinuos). La declaración judicial de convivencia o unión de hecho tiene como propósito el
cautelar los derechos de cada concubino sobre los bienes adquiridos durante la unión,
entendiéndose que por la unión de hecho se ha originado una sociedad de bienes sujeta
al régimen de la sociedad de gananciales, en cuanto le fuere aplicable.
Asimismo, en cuanto a su reconocimiento se refiere tenemos a la Ley N° 29560 (El Peruano
16.07.2010), la misma que amplía la Ley N° 26662, Ley de Competencia Notarial en asun
tos no Contenciosos, estableciendo un procedimiento alternativo al proceso judicial, más
ágil, a través del procedimiento no contencioso a cargo de los Notarios Públicos (Ley N°
26662), al cual pueden acudir para su reconocimiento las parejas que reúnan los requisi
tos establecidos en el art. 326 del C.C. y que básicamente exige que la relación sea entre
varón y mujer (no es posible en nuestro ordenamiento jurídico las uniones de personas
del mismo sexo) libres de impedimento matrimonial (establecidos en los arts. 241, 242y
243 del Código Civil) y que la unión tenga por objeto alcanzar finalidades y cum plir debe
res semejantes al m atrimonio con una duración no menor de dos años.
El procedimiento ante notario público se inicia a solicitud de los convivientes, que debe
ser acompañada por la declaración de los solicitantes (en caso se brinde información fal
sa, serán pasibles de sanción penal conforme a la ley de la materia) y de testigos que reú
nen los requisitos antes señalados, así como el certificado dom iciliario de los solicitantes
y el certificado negativo de la unión de hecho expedido porel registro personal. El notario
manda a publicar un extracto de la solicitud por una vez en el diario oficial y otro de am
plia circulación del lugar donde se realiza el trámite y, a falta de diario en dicho lugar, en
el de la localidad más próxima. La norma también señala que los convivientes pueden
