UBILEX
dejar constancia en la escritura pública de haber puesto fin a su estado de convivencia
y liquidar el patrimonio social, y que en este caso no se necesita hacer publicaciones. El
reconocimiento del cese se inscribe en el Registro Personal.
La unión de hecho termina por muerte, ausencia, mutuo acuerdo o decisión unilateral.
En este últim o caso, el juez puede conceder, a elección del abandonado, una cantidad de
dinero por concepto de indemnización o una pensión de alimentos, además de los dere
chos que le correspondan de conformidad con el régimen de sociedad de gananciales.
Tratándose de la unión de hecho que no reúna las condiciones señaladas en este artículo
(art. 326 del C.C.), el interesado tiene expedita, en su caso, la acción de enriquecimiento
indebido. Al respecto, el Código Civil establece: A. que aquel que se enriquece indebida
mente a expensas de otro está obligado a indemnizarlo (art. 1954 del C.C.); y B. que la ac
ción a que se refiere el a rtícu lo i954 del Código Civil (acción de enriquecimiento sin causa
o de enriquecimiento indebido) no es procedente cuando la persona que ha sufrido el
perjuicio puede ejercitar otra acción para obtener la respectiva indemnización (art. 1955
del C.C.).
Las uniones de hecho que reúnan las condiciones señaladas en el artículo 326 del C.C.
producen, respecto de sus miembros, derechos y deberes sucesorios, similares a los del
matrimonio, por lo que las disposiciones contenidas en los artículos 725,727,730,731,732,
822, 823, 824y 825 del Código Civil se aplican al integrante sobreviviente de la unión de
hecho en los términos en que se aplicarían al cónyuge.
La Ley N° 30007, pub. el 17.04.2013, que modificó los artículos 326,724,816, y 2030 del Código
Civil; además del inciso 4 del artículo 425 y el artículo 831 del Código Procesal Civil; adicio
nalmente los artículos 35 y 38 y el inciso 4 del artículo 39 de la Ley N° 26662, ha reconocido la
vocación hereditaria del integrante sobreviviente de unión de hecho. Según el art. 2 de esta Ley
debe tratarse de la unión de hecho acorde con los requisitos establecidos en el artículo 326 del
Código Civil, pues voluntariamente deben haber unido sus vidas un varón y una mujer, que
deben encontrarse libres de impedimento m atrimonial (por ejemplo, no tener estado civil de
casado), para alcanzar finalidades y cum plir deberes semejantes a los del matrimonio, unión
que debe haber durado cuando menos dos años continuos.
La Ley N° 30007 establece en el primer párrafo del artículo 3 que se reconocen los derechos
sucesorios a favor de los miembros de uniones de hecho inscritas en el Registro Personal, con
forme con lo dispuesto en el artículo 49 de la Ley N° 26662. En buena cuenta, el artículo bajo
comentario establece hasta tres formas para el reconocimiento de los derechos sucesorios,
que no son otra cosa que las formas de reconocimiento de la propia unión de hecho. Es así,
que en función del artículo 49 de la Ley N° 26662, puede reconocerse e inscribirse en el Regis
tro Personal, por mutua decisión de los convivientes, uniones de hecho de personas vivas; lo
cual también puede ocurrirsi dichos convivientes no eligen la vía notarial sino recurren a la vía
judicial para el mismo efecto. Subrayamos que tanto en la vía notarial como la judicial se parte
de la idea que los concubinos se encuentran vivos cuando realizan dicha gestión, vale decir
que el trám ite no puede ser iniciado por los herederos pero sí concluidos por ellos.
En el supuesto contenido en el segundo párrafo de la Ley N° 30007, en caso se dé la situación
en la cual al momento de muerte de uno de los integrantes de la unión de hecho, ésta no
m
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
