Tema 3: Temas de la especialidad de fam ilia
se encontrará inscrita en el Registro Personal, corresponde el trámite de reconocimiento de
unión de hecho al conviviente supérstite, con vocación hereditaria.
A partir del artículo 4 la Ley N° 30007 introduce modificaciones significativas en los siguientes
artículos del Código Civil:
i) Art. 32.6 del C.C. precepto al que se le ha incorporado un últim o párrafo, de texto siguien
te: "Las uniones de hecho que reúnan las condiciones señaladas en el presente artículo
producen, respecto de sus miembros, derechos y deberes sucesorios, similares a los del
m atrimonio
Con la Ley N° 30007, el conviviente sobreviviente de una unión de hecho, denominado in
tegrante sobreviviente de unión de hecho, tendrá tal calidad siempre y cuando reúna las
condiciones previstas en el artículo 326 del Código Civil, así tendrá derechos sucesorios
sobre el patrimonio de su fallecido conviviente, no solo tendrá el derecho a recibir bienes
y derechos patrimoniales, sino también deberá asumir las obligaciones transmisibles por
herencia que hubiera dejado el fallecido conviviente.
ii) Art. 724 del C.C. disposición cuyo texto es: "Son herederos forzosos los hijos y los demás
descendientes, los padresy los demás ascendientes, el cónyuge o, en su caso, el integran
te sobreviviente de la unión de hecho.”
Este artículo le ha dado a los miembros de las uniones de hecho, el carácter de herederos
forzosos y ha dispuesto que ellos se verán beneficiados con lo establecido porel art. 725, que
dispone el tercio de libre disposición para el causante que tenga hijos u otros ascendien
tes, o cónyuge o sea miembro de una unión de hecho. La institución de heredero forzoso
está directamente relacionada con el derecho a la legítima, que es la parte intangible que el
Código Civil establece a favor de aquellos. Con la inclusión del integrante sobreviviente de
unión de hecho como heredero forzoso, se le otorga el derecho a la legítima.
Estas normas tienen un valioso contenido, en la medida que amplían su manto de protec
ción de la calidad sucesoria al miembro de una unión de hecho, aparte de la protección
que ya brindaba al cónyuge.
iii) Art. 816 del C.C. cuyo es el siguiente: “Son herederos del primer orden, los hijos y demás
descendientes; del segundo orden, los padres y demás ascendientes; del tercer orden, el
cónyuge o, en su caso, el integrante sobreviviente de la unión de hecho; del cuarto, quinto
y sexto órdenes, respectivamente, los parientes colaterales del segundo, tercer y cuarto
grado de consanguinidad. El cónyuge o, en su caso, el integrante sobreviviente de la unión
de hecho también es heredero en concurrencia con los herederos de los dos primeros
órdenes indicados en este artículo”.
Cuando no hay testamento vigente a la muerte del causante, los herederos deberán ser
declarados judicialmente o notarialmente, en cuyo caso el orden legal del derecho a he
redar de los parientes lo establece el artículo 816 del C.C.
Los órdenes sucesorios determinan quién o quiénes son los parientes con derecho a here
dar al causante; en ese sentido, la Ley N° 30007 incorpora al integrante sobreviviente de la
unión de hecho en el tercer orden sucesorio, y con derecho concurrente a heredar con los
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 574 of 1506 --

UBILEX
parientes de los dos primeros órdenes sucesorios, esto es, los hijos y demás descendien
tes, y los padres y demás ascendientes.
Debe considerarse que el conviviente tendrá derecho a heredar de modo preferente,
siendo posible que herede únicamente o en concurrencia con alguno de los parientes del
primer o segundo orden sucesorio. De existir parientes de dichos dos órdenes, la apli
cación de la regla de exclusión sucesoria del artículo 817 del Código Civil permitirá de
term inar cuál o cuáles de los parientes tienen derecho a heredar, en concurrencia con el
conviviente, en función a que los parientes de línea recta descendente excluyen a los de la
ascendente, y los parientes más próximos en grado excluyen a los más remotos, salvo el
derecho de representación sucesoria.
iv) Art. 2030 del C.C. el artículo 7 de la Ley N° 30007 dispone que serán inscribibles en el
Registro Personal “las uniones de hecho inscritas en vía notarial o reconocidas por vía ju
dicial”. Esto, al haber agregado el inciso 10 al referido artículo 2030.
Así, el derecho sucesorio del conviviente se encontrará mejor cautelado si a la fecha del fa
llecimiento del conviviente estaba inscrita la unión de hecho en Registros Públicos, pues
podrá pedir que se ejecute la voluntad testamentaria, si hubo testamento, sino tendrá el
derecho de iniciar el proceso de sucesión intestada para obtener el título de heredero, ya
sea en vía notarial o judicial. Incluso, si hubo testamento pero no se le comprendió en su
calidad de heredero forzoso, podrá impugnar el testamento.
Respecto del Código Procesal Civil la Ley N° 30007 a través del artículo 8 modificó el inciso
4 del artículo 425, el cual se refiere a los anexos de la demanda, para establecerse que a
la demanda deberá acompañarse la prueba de la calidad de sobreviviente de la unión de
hecho, salvo que tal calidad sea materia del conflicto de intereses. Sin embargo, el art. 425
CPC volvió a ser modificado con fecha 28.12.2014 regresando el inc. 4) a su texto original.
Igualmente con el artículo 9 de la mencionada Ley se incorpora un párrafo final al artículo
831 del Código Procesal Civil, para establecer que a la solicitud de sucesión intestada se
deberá acompañar la constancia de inscripción de la unión de hecho en el Registro Perso
nal.
Finalmente, la Ley N° 30007 (Art. 10) ha modificado el artículo 35 de la Ley N° 26662- Ley
de Competencia Notarial en Asuntos No Contenciosos, para incluir al integrante sobrevi
viente de la unión de hecho reconocida conforme a ley como uno de los sujetos que pue
de suscribir la petición escrita para la comprobación de testamentos cerrados. También
se modifica el artículo 38, para adicionar al sobreviviente de la unión de hecho reconocido
conforme a ley como uno de los sujetos que puede presentar la solicitud de sucesión in
testada. Y, por último, se modifica el inciso 4 del artículo 39 de la misma ley, indicando no
solo a la partida de matrimonio como requisito que debe incluir la solicitud de sucesión
intestada sino también la inscripción en el Registro Personal de la declaración de la unión
de hecho, adjuntándose, según sea el caso, el testimonio de la escritura pública o la copia
certificada de la sentencia judicial firme.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 575 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
6. Deberes y derechos personales que nacen del m atrim onio civil
En el Código Civil en el Título II respecto de las relaciones personales entre los cónyuges y de
los Deberesy derechos que nacen del matrimonio encontramos en los artículos 287 al 294. Los
padres por el m atrim onio se obligan a:
1. Proveerá la alimentación y educación desús hijos.
2. El deber de fidelidad, se sustenta en la aceptación exclusiva y reciproca de un esposo res
pecto del otro. El deber de asistencia, entendiéndose como la mutua ayuda, el respeto
recíproco, los cuidados materiales y espirituales que ambos cónyuges deben dispensarse.
3. Es deber de ambos cónyuges el hacer vida en común en el dom icilio conyugal. Pueden
ocurrir casos en los que se deba suspender la cohabitación por importar al interés fam i
liar. El Art. 289 del Código Civil contempla que el juez está facultado para suspender este
deber cuando su cumplimiento ponga en peligro la salud o el honor de uno de los cónyu
ges o la actividad económica de la que depende el sostenimiento de la familia.
4. La participación en la conducción y el gobierno del hogar y cooperar al mejor desenvol
vimiento del mismo. A ambos compete, fijar y mudar el domicilio conyugal y decidir las
cuestiones referentes a la economía del hogar.
5. Si uno de los cónyuges se dedica exclusivamente al trabajo del hogary al cuidado de los
hijos, la obligación de sostener a la familia recae sobre el otro, sin perjuicio de la ayuda y
colaboración que ambos cónyuges se deben en uno y otro campo.
Cesa la obligación de uno de los cónyuges de alimentar al otro cuando éste abandona la
casa conyugal sin justa causa y rehúsa volver a ella. En este caso el juez puede, según las
circunstancias, ordenar el embargo parcial de las rentas del abandonante en beneficio
del cónyuge inocentey de los hijos. El mandamiento del embargo queda sin efecto cuan
do lo soliciten ambos cónyuges.
6 . La representación de la sociedad conyugal es ejercida conjuntamente por los cónyuges,
sin perjuicio de lo dispuesto por el Código Procesal Civil. Cualquiera de ellos, sin embar
go, puede otorgar poder al otro para que ejerza dicha representación de manera total o
parcial.
Para las necesidades ordinarias del hogary actos de administración y conservación, la
sociedad es representada indistintamente por cualquiera de los cónyuges. Si cualquiera
de los cónyuges abusa de los derechos a que se refiere este artículo, el juez de Paz Letrado
puede limitárselos en todo o parte. La pretensión se tram ita como proceso abreviado.
7. Cada cónyuge puede ejercer cualquier profesión o industria permitidos por la ley, así
como efectuar cualquier trabajo fuera del hogar, con el asentimiento expreso o tácito del
otro. Si éste lo negare, el juez puede autorizarlo, si lo ju s tific a d interés de la familia.
8 . Uno de los cónyuges asume la dirección y la representación de la sociedad:
1. Si el otro está impedido por interdicción u otra causa.
2. Si se ignora el paradero del otro o éste se encuentra en lugar remoto.
3. Si el otro ha abandonado el hogar.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 576 of 1506 --

UBILEX
7. Régimen patrimonial
Se llama régimen patrimonial o régimen de bienes en el m atrim onio al conjunto de normas
jurídicas que regulan las relaciones patrimoniales de los cónyuges entre sí y la de estos con
terceros. En este régimen se señala como deben contribuir los cónyuges a las necesidades de
su hogary cómo deben administrar los bienes que han aportado al m atrimonio incluyendo su
mutua responsabilidad por las obligaciones frente a terceros.
En el Código Civil se produce una innovación, la figura de la separación de patrimonios por
la que pueden optar los cónyuges antes o durante el matrimonio, es decir, los contrayentes
pueden adoptar la decisión de ceñirse al régimen de sociedad de gananciales o al régimen de
separación de patrimonios pueden además cambiarse de uno a otro régimen repetidas veces.
La sociedad de gananciales se presumey no requiere de formalidad alguna para su constitución,
en cambio, la separación de patrimonios necesita para su configuración de ciertas formalidades.
7.1. Separación de patrimonios
Como lo encontramos en el artículo 295o del C.C. antes de la celebración del m atrim onio los
futuros cónyuges pueden optar libremente por el régimen de sociedad de gananciales o por
el de separación de patrimonios, Si optan por el de separación de patrimonios, deben otorgar
escritura pública bajo sanción de nulidad; pudiendo cambiar de un régimen a otro. En este
régimen existen bienes propios del marido y bienes propios de la mujer, que les pertenecen
a cada uno y que desean conservar independientemente a plenitud la propiedad, adminis
tración y disposición de sus bienes presentes y futuros incluyendo los frutos y productos; tal
como aparece en el artículo 327o del C.C. Pero también responde de sus deudas con sus res
pectivos bienes. En este régimen que se exige por ley la declaración de la voluntad expresada
en escritura pública e inscripción en el registro personal. Puede presentarse el caso en que se
solicita la sustitución judicial de la sociedad de gananciales por la de separación de patrimo
nios que queda establecido por el juez a pedido del cónyuge agraviado, cuando el otro abusa
de las facultades que le corresponden o actúa con dolo o culpa. Cuando uno de los cónyuges
quiebra la declaración de insolvencia de uno de los cónyuges determina de pleno derecho la
sustitución del régimen de sociedad de gananciales por el de separación de patrimonios, para
lo que se inscribirá de oficio, a solicitud del insolvente, de su cónyuge o del administrador Es
pecial en los Registros Públicos, a fin deque produzca efectos frente a terceros.
7.2. Sociedad de gananciales
Una característica esencial de este régimen de bienes, es que admite la coexistencia de bie
nes propios como bienes sociales o comunes de la sociedad, la denominación de la sociedad
como de gananciales proviene de la idea que el esfuerzo común que deben realizar los cónyu
ges es la fuente de las ganancias, utilidades o rendimientos, por lo que cada uno de ellos debe
ser partícipe de la propiedad de los bienes adquiridos por el otro.
Tratándose de dos clases de bienes, interesa obviamente determinar cuales tienen la condi
ción de bienes propios y cuales la de sociales, lo que en el primer caso se determina por una
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 577 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
relación o enumeración contenida en el artículo 3023 del Código Civil, mientras que los so
ciales a los que se contrae el artículo 310° del Código Civil se les determina por exclusión, al
señalarse que tiene ese carácter todos los bienes no comprendidos en el artículo 302o antes
mencionado.
Al margen de dicha enumeración, hay ciertos criterios básicos para distinguir ambas clases de
bienes, ellos son la época de la adquisición, el título de la adquisición, y el criterio de subro
gación. Es decir, fueron adquiridos antes de la vigencia de la sociedad de gananciales serán
bienes propios de su titular, si lo fueron a título oneroso después de la vigencia de la sociedad
serán bienes sociales; si los bienes fueron adquiridos por donación, herencia o legado, es de
cir a título gratuito dichos bienes tendrán la calidad de propios, si lo fueron a título onerosos
durante la vigencia de la sociedad, los mismos tendrán en carácter de sociales; y finalmente
el criterio de subrogación, es decir la naturaleza de los bienes empleados en una posterior
adquisición, que seguirán la misma naturaleza de los que fueron subrogados o sustituidos.
8. Decaimiento y disolución del vínculo matrimonial
8.1. Separación de cuerpos:
Según Peralta Anoía "La separación de cuerpos es una institución del Derecho de Familia que
consiste en la interrupción de la vida conyugal por decisión judicial que suspende los deberes
relativos al lechoy habitación,y pone fin al régimen patrimonial de la sociedad de gananciales”.
Se debe diferenciar la separación de cuerpos declarada judicialmente de la simple separación
de hecho, que se da cuando los cónyuges dejan de hacer vida en común pero no cuentan para
ello con ninguna decisión judicial que declare dicha situación. Para que se declare judicial
mente la separación de cuerpos es necesario que quien inicie el proceso acredite cualquiera
de las causales previstas en el artículo 333° del Código Civil o que ambos cónyuges soliciten la
separación convencional.
Causales:
Puede obedecer a las siguientes causales, establecidas en el artículo 333° del Código Civil.
3 Art. 302 C.C.: Son bienes propios de cada cónyuge:
1. - Los que aporte al iniciarse el régimen de sociedad de gananciales.
2. - Los que adquiera durante la vigencia de dicho régimen a título oneroso, cuando la causa de adquisición
ha precedido a aquélla.
3. - Los que adquiera durante la vigencia del régimen a título gratuito.
4. - La indemnización por accidentes o por seguros de vida, de daños personales o de enfermedades, deduci
das las primas pagadas con bienes de la sociedad.
5. - Los derechos de autor e inventor.
6. - Los libros, instrumentos y útiles para el ejercicio de la profesión o trabajo, salvo que sean accesorios de
una empresa que no tenga la calidad de bien propio.
7. - Las acciones y las participaciones de sociedades que se distribuyan gratuitamente entre los socios por
revaluación del patrimonio social, cuando esas acciones o participaciones sean bien propio.
8. - La renta vitalicia a título gratuito y la convenida a título oneroso cuando la contraprestación constituye
bien propio.
9. - Los vestidos y objetos de uso personal, así como los diplomas, condecoraciones, correspondencia y re
cuerdos de familia.
