1. ti adulterio, constituye la violación dei deber de fidelidad en su forma más grave. Consiste en ia
relación sexual que practica uno de los cónyuges con tareera persona.
2. La violencia física o psicológica, consiste en los maltratos físicos o ataques psicológicos que sufre
uno de los cónyuges por parte del otro.
3. Atentado contra ia vida del cónyuge.
A. Injuria grave, que haga insoportable la vida en común.
5. Abandono Injustificado de la casa familiar por más de dos años continuos o cuando la duración sumada
de los períodos de abandono exceda a este plazo.
6. Conducta deshonrosa que hace insoportable la vida en común.
7. Uso habitual e injustificado de drogas alucinógenas o sustancias que pueden generar toxicomanía
8. Enfermedad venérea grave contraída luego de la celebración del matrimonio,
9. Homosexualidad sobreviviente al matrimonio
10. La condena por delito doloso a pena privativa de la libertad mayor de dos años, impuesta después de la
celebración del matrimonio.
11. La imposibilidad de hacer vida en común, debidamente probada en proceso Judicial
12. La separación de hecho de los cónyuges durante un periodo ininterrumpido de dos años, o de cuatro
años si los cónyuges tuviesen hijos menores de edad.
13. La separación convencional, después de transcurridos dos años de la celebración del matrimonio.
