BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 579 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
Si bien ia norma no señala expresamente que la separación de cuerpos conlleve otros
efectos, además de los explicados precedentemente, existen consecuencias que se des
prenden de la separación de cuerpos tales como:
La obligación de pagar una pensión alimenticia, cuyo monto será fijado porel juez aten
diendo a las circunstancias de ambos cónyuges o acogiendo lo propuesto poraquellos en
caso de que la separación de cuerpos sea convencional. En efecto, por disposición expresa
del artículo 483 del Código Procesal Civil, a la pretensión de separación de cuerpos deben
acumularse, entre otros, las pretensiones relativas a derechos u obligaciones de los cón
yuges, tales como la de alimentos; en tal virtud, el juez para fijar la cuantía de la pensión
alimenticia deberá analizar las posibilidadesy necesidades de las partes.
Caducidad de la acción: La acción basada en el artículo 333, inciso 1,3,9 y 10, caduca a los seis
meses de conocida la causa por el ofendido y, en todo caso, a los cinco años de producida. La
que se funda en los incisos 2 y 4 caduca a los seis meses de producida la causa. En los demás
casos, la acción esta expedita mientras subsistan los hechos que la motivan. (Art. 339 del CC).
8 .2 . El divorcio
Concepto: Es la voz latina D ivortium la que nos revela el origen etimológico de la expresión Di
vorcio; ella describe plásticamente la actitud de los cónyuges que, después de haber recorrido
unidos un trecho de existencia, se alejan por distintos caminos Divertere. Su significado es se
paración, por lo que no es de extrañar que dicho término haya sido empleado en el pasado por
la legislación nacional tanto para referirse al divorcio vincular (divorcio propiamente dicho),
como también al denominado relativo o separación de cuerpos.
El divorcio al igual que la separación de cuerpos en el Perú debe ser declarado judicialmente;
precisión que se acota, porque si bien son reiterados los esfuerzos por intentar desplazar la
competencia de los divorcios consensuados a los Municipios o a la función notarial, acogién
dose a tendencias legislativas innovadoras que vienen admitiendo divorcios contractuales-
porsim pley mutuo consentimiento de las partes, los divorcios adm inistrativosy los divorcios
religiosos, éstas aún no han prosperado en nuestro medio.
Teorías:
Divorcio sanción: se exige la prueba de la culpa de uno o de ambos cónyuges, y, por ello,
el divorcio implica una sanción contra el culpable que se proyecta en los efectos: pérdida
o restricción del derecho alimentario, pérdida de la vocación hereditaria, etc.
Divorcio remedio: no se alegan hechos imputables a uno de los cónyuges, o a los dos. Se
exige que el vínculo matrimonial esté resquebrajado y, por tanto, la vida en común resul
ta imposible o intolerable.
La diferencia sustancial entre la concepción del divorcio sanción y del divorcio remedio,
reside en que la primera considera que la causa del conflicto conyugal es la causa del di
vorcio; mientras que la segunda entiende que el conflicto es, él mismo, la causa del divor
cio, sin que interesen las causas de ese conflicto. Caben así dos sistemas: subjetivo, o de la
culpa de un cónyuge,y objetivo, basado en la ruptura de la vida matrimonial, constatada
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 579

-- 580 of 1506 --

UBILEX
a través del mutuo acuerdo de los propios cónyuges o del cese efectivo de la convivencia
durante cierto tiempo.
Sistema mixto o complejo: Resultado de una combinación de los 2 sistemas anteriores.
Nuestro Código Civil sigue un sistema mixto, en el que hay diversas vías para obtener la
separación personal y el divorcio vincular. Reconoce el “divorcio remedio" a la disolución
por mutuo disensoy el “divorcio sanción” al que se produce por causal.
Admite el mutuo consentimiento (separación convencional) únicamente para invocar la sepa
ración personal o de cuerpos, la que puede convertirse después en divorcio vincular.
Contempla causas de inculpación (incumplimiento graves o reiterados de los deberes conyu
gales) de un cónyuge frente al otro, que pueden ser alegadas sólo por el consorte inocente,
tanto para demandar la separación personal o de cuerpos, como el divorcio vincular, conjun
tamente con causas no ¡nculpatorias (separación de hecho y separación convencional), que
pueden ser alegadas por cualquiera de ellos.
Permite el divorcio ulterior cuando se declara la separación de cuerpos por causas i nculpato
rias.
Es además complejo, evidenciándose en los efectos personalesy patrimoniales, cuando se ex
tienden los del divorcio-sanción a quienes acuden a las causales no ¡nculpatorias, atenuando
el rigor objetivo del sistema de divorcio-remedio.
Causales: El Código Civil vigente establece en el art. 333o, incisos del 1 al 12, las causales por las
que se puede obtener el divorcio y son las siguientes:
® 1. El adulterio.
2. La violencia física o psicológica, que el juez apreciará según las circunstancias.
3. El atentado contra la vida del cónyuge.
4. La injuria grave, que haga insoportable la vida en común.
5. El abandono injustificado de la casa conyugal por más de dos años continuos o cuando la duración
sumada de los períodos de abandono exceda a este plazo.
6. La conducta deshonrosa que haga insoportable la vida en común.
7. El uso habitual e injustificado de drogas alucinógenas o de sustancias que puedan generar toxicomanía,
salvo lo dispuesto en el Artículo 347.
8. La enfermedad grave de transmisión sexual contraída después de la celebración del matrimonio.
9. La homosexualidad sobreviniere al matrimonio.
10. La condena por delito doloso a pena privativa de la libertad mayor de dos años, impuesta después de la
celebración del matrimonio.
11. La imposibilidad de hacer vida en común, debidamente probada en proceso judicial.
12. La separación de hecho de los cónyuges durante un período ininterrumpido de dos años. Dicho plazo
será de cuatro años si los cónyuges tuviesen hijos menores de edad. En estos casos no será de aplica
ción lo dispuesto en el Artículo 335.
— El adulterio: El adulterio se presenta cuando uno de los cónyuges mantiene relaciones
sexuales heterosexuales con una tercera persona (ajena a la relación matrimonial), por tanto
implica, entre otras, el incumplimiento del deber de fidelidad que puede ser permanente o
temporal, así como, un actuar doloso por parte del adúltero.
