sociedad por estratos de mayor o menor cultura, costumbres o educación, pues en un mismo
estrato económico, social y cultural es posible encontrar parejas y dentro de éstas, personas,
con distinta apreciación y sentimiento de lo que constituye una injuria grave: la indagación
del juez debe referirse al honor interno de la víctima y a la relación con su pareja, sin que sea
gravitante el estrato social o cultural al que pertenezca. STC Exp. N° 0 1 8 - 9 6 - l/ T C , Lima.
— E l a b a n d o n o in ju s t if ic a d o : Para que el abandono sufrido por uno de los cónyuges sea cau
sa de divorcio deben concurrir tres elementos: i) Objetivo (Separación material del hogar con
yugal. ii) Subjetivo (Intención deliberada de poner fin a la comunidad de vida matrimonial),
iii) Temporal (Plazo legal mínimo de abandono, 2 años). Así también lo señala la Corte Supre
ma en la Cas. N° 4 2 4 - 2 0 0 2 - H u a u r a «[PJara la configuración de la causal de abandono injustificado
del hogar conyugal se requiere la conjunción de los siguientes elementos-, a) el alejamiento físico del ho
gar conyugal; b) el elemento temporal, constituido por el tiempo establecido por la ley; c) la voluntad
de sustraerse de sus obligaciones conyugales, el cual constituye un factor de atribución subjetivo». Por
tanto, la causal de abandono injustificado del hogar conyugal «no puede considerarse acredi
tada con el solo mérito de la copia certificada de la denuncia policial obrante a fojas cuatro,
pues constituye una manifestación unilateral que no forma convicción en el juzgador respecto
a la configuración de los tres requisitos establecidos en el inciso 5 del artículo 333° del Código
Civil, no existiendo otros elementos de prueba que los acrediten, esto es, que el demandado
se haya retirado del hogar conyugal por el lapso predeterminado en la norma referida y sin
justificación alguna4.
Respecto a la carga probatoria, quien invoca el abandono injustificado, debe acreditar tanto la mate
rialización del retiro como que éste es injustificado. Tema I. Pleno Jurisdiccional Distrital de Fami
lia 2018.
— La conducta deshonrosa que haga insoportable la vida en común: La Corte Suprema ha
definido esta causal de la siguiente manera”(...) proceder incorrecto de una persona, que se
encuentra en oposición al orden público, la moral y las buenas costumbres, que afectan la
imagen, el honory el respeto de lafam ilia, condiciones en las cuales hace insoportable lavida
en común; pudiendo, manifestarse en una gama de hechosy situaciones, como pueden serla
vagancia y ociosidad, la ebriedad habitual, la reiterada intim idad amorosa con persona dis
tinta del cónyuge, salidas injustificada, entre otras, ya que la ley no establece un numerus
clausus al respecto sino un numerus apertus.” Cas. N° 2090-01, Huánuco.
Para que se configure el divorcio por causal de conducta deshonrosa que haga insoportable
la vida en común se requiere la presencia de dos elementos: i) La existencia de una conducta
deshonrosa por parte de uno de los cónyuges; ii) Que, dicha conducta sea de tal magnitud que
haga insoportable lavida en común. Exp. N° 00435- 2015-0-0901-JR-FC-06.
— La imposibilidad de hacer vida en común: La imposibilidad de hacer vida en común, sig
nifica que el m atrimonióse ha quebrado, que existe un fracaso irreparable, que el m atrimonio
no cumple con su función, que la relación solo resulta perjudicial, que, por lo tanto, no existe
