a la imposibilidad de continuar con lavida matrimonial.
La causal de imposibilidad de hacervidaen común, debidamente probadaen proceso judicial
(inciso 11 del artículo 333 del Código Civil) da lugar a un divorcio sanción, resultando aplicable
la restricción del artículo 335 del Código Civil, que prescribe que ninguno de los cónyuges pue
de fundar su demanda en hecho propio5.
— La separación de hecho de los cónyuges: Es la interrupción de la vida en común de los
cónyuges, que se produce por voluntad unilateral de uno de ellos o de ambos, quienes sin
previa decisión jurisdiccional definitiva, quiebran el deber de cohabitación en forma temporal
o permanente. En segundo lugar, a diferencia de otras causales el accionante puede fundar su
demanda en hecho propio6.
Por su parte, la Corte Suprema, en reiterada jurisprudencia, ha definido esta causal como “la
interrupción de la vida en común de los cónyuges, que se produce por voluntad unilateral de
uno de ellos o de ambos; en segundo término, que se haya producido la desunión por deci
sión unilateral o conjunta, la naturaleza de esta causal no se sustenta en la exigencia de un
cónyuge culpable y de un cónyuge perjudicado y, en tercer lugar, que a través de esta causal es
posible que el accionante funde su pretensión en hechos propios’’7.
El profesor Alex Placido ha señalado que para que se configure la separación de hecho debe
cumplirse con dos elementos. Un primer elemento objetivo o material, consistente en la evidencia
del quebrantamiento definitivoy permanente, sin solución de continuidad en la convivencia. Asimismo,
un segundo elemento subjetivo o psíquico, determinado por la falta de voluntad de unirse, esto es,
la intención cierta de los cónyuges de no continuar viviendo juntos.
Indemnización por daños, conforme a lo señalado en el III Pleno Casatorio Civil (CAS. N°
4664-2010, Puno)
Regla 2. En los procesos sobre divorcio -y de separación de cuerpos- por la causa! de sepa-
ración de hecho, el Juez tiene el deber de velar por la estabilidad económica del cónyuge que
resulte más perjudicado por la separación de hecho así como la de sus hijos, de conformidad
■ H H H con lo dispuesto por el artículo 345-A del Código Civil. En consecuencia, a pedido de parte o de
oficio señalará una indemnización por daños, el que incluye el daño a la persona, u ordenará la
adjudicación preferente de bienes de la sociedad conyugal, independientemente de la pensión
de alimentos que pudiera corresponderle. El daño moral es índemnizable y se halla compren
dido en el daño a la persona.
Regla 3. Respecto a la indemnización por daños o la adjudicación preferente de bienes la sociedad con-
3.1. A pedido de parte, podrá formularse tal pretensión en los actos postúlatenos, ya sea en la demanda como
pretensión accesoria o en la reconvención, según sea el caso, salvo renuncia expresa del interesado. El pedido
también es procedente después de los actos postulatorios.
3.2. De oficio, el Juez de primera instancia se pronunciará sobre estes puntos, siempre que la parte interesada
haya alegado o expresado de alguna forma hechos concretos referidos a los perjuicios resultantes de la se
paración de hecho o del divorcio en si. Aquellos hechos pueden ser alegados o expresados incluso después
