3.4. En todo caso ei Juez se pronunciará sobre la existencia de la condición de cónyuge más perjudicado de
una de las partes según se haya formulado - y probado- la pretensión o la alegación respectiva, o sobre la
inexistencia de aquella condición, si no existiera elementos de convicción necesarios para ello,
3.5. En el trámite señalado, se garantizará el derecho a la tutela jurisdiccional efectiva y el debido proceso, par
ticularmente el derecho de defensa de las partes, ei principio de contradicción y el derecho a la instancia plural.
Efectos del Divorcio:
Los efectos de la separación personal respecto de los cónyuges
Suspensión de los deberes de cohabitación y de débito conyugal.
Fenecimiento y la liquidación de la sociedad de gananciales y la entrada en vigencia ipso
iure del régimen de separación de patrimonios.
Fijación de una pensión de alimentos recíproca, si fuere el caso.
Pérdida de la vocación hereditaria del cónyuge culpable de la separación respecto del
cónyuge inocente, quien la conserva.
Los efectos de ¡a separación personal por voluntad unilateral respecto de los hijos
La tenencia de los hijos se otorga al cónyuge inocente, aunque se puede disponer lo con
trario o entregárselo a un tercero. Si ambos cónyuges son culpables, los varones mayores
de siete años quedan a cargo del padre y todos los demás al cuidado de la madre, pudién
dose disponer otra solución.
El régimen alimentario es de cargo de los cónyuges, de acuerdo a sus posibilidades y ren
tas.
El juez fija el régimen de la patria potestady los alimentos de acuerdo al convenio regula
dor propuesto por los cónyuges, siempre que convenga al interés de los hijos.
Los efectos del divorcio vincular respecto de los cónyuges
Determina la disolución del vínculo matrimonial; cesa la obligación alimentaria entre
ellos, aunque puede subsistir por acreditarse la Imposibilidad para subvenir a sus nece
sidades; determina la pérdida por el cónyuge culpable de los gananciales que proceden
de los bienes del inocente; provoca la extinción de la vocación hereditaria entre ellos; y,
posibilita que el cónyuge ¡nocente exija una indemnización por el daño moral.
9 . Separación convencional
La separación convencional denominado también divorcio por m utuo acuerdo, es un proceso
contencioso si se solicita la disolución por la vía judicial ante los juzgados de familia, con la
dación de la Ley N° 29227 se contempla la posibilidad de realizarla la disolución del vínculo
matrimonial como proceso no contencioso a través de las Municipalidades Provinciales o Dis-
