En relación con el régimen legal de divorcio en el país, siguiendo el proceso flexibilizador, estas
últimas disposiciones, amplían y facilitan las posibilidades de divorciarse en el Perú. Como se
mencionó esta normatividad no ha derogado la legislación sustantiva y procesal relativa a la
separación convencional y divorcio ulterior judicial, el que se encuentra vigente, en todo caso
los usuarios encuentran en el divorcio notarial o municipal una alternativa más a la que pue
den acceder, si reúnen las condiciones requeridas para tal efecto.
El procedimiento sea en sede judicial, municipal o notarial tiene dos etapas: La Separación
Convencional, que es el paso previo para obtener el Divorcio Ulterior.
El d iv o r c io n o t a r ia l o m u n ic ip a l e x ig e , al ig u a l q u e el ju d ic ia l, q u e lo s c ó n y u g e s te n g a n p o r
lo m e n o s d o s a ñ o s d e h a b e r c o n t r a íd o m a t r im o n io . D if ie r e c o n e ste ú lt im o en lo s s ig u ie n t e s
a sp e c to s :
A) P ro c e d e c u a n d o lo s c ó n y u g e s n o t ie n e n h ijo s m e n o r e s d e e d a d o m a y o r e s in c a p a c e s , a s í
c o m o c u a n d o lo s c ó n y u g e s q u e se e n c u e n t r e n b a jo el r é g im e n d e s o c ie d a d d e g a n a n c ia
les c a r e z c a n d e b ie n e s , o s u s r e la c io n e s p a t r im o n ia le s se s u je t e n a l r é g im e n d e s e p a r a
c ió n d e p a t r im o n io s .
B) En caso de que los cónyuges tengan hijos menores de edad o mayores incapaces es po
sible acceder por estas vías, siempre que exista pronunciamiento judicial firm e respecto
de la patria potestad, régimen de visitas, alimentos, interdicción, o en su defecto estas
materias hayan sido objeto de conciliación de acuerdo a la Ley de la materia, N° 26872y
su Reglamento, la que exige autorización gubernamental del centro de conciliación para
estos fines específicos, así como la intervención de un conciliador especializado en fam i
lia.
C) En materia patrimonial, a diferencia del requerimiento judicial de inventario de bienes
con firm a legalizada de los cónyuges, a la vía notarial o municipal se le condiciona, de
existir bienes, que el régimen de sociedad de gananciales haya fenecido, sea por una va
riación convencional, la que se perfecciona mediante escritura públicay su inscripción en
los Registros Públicos, o el fallo judicial que de manera inculpatoria amparando la causal
de abuso de facultades, dolo o culpa de uno de los cónyuges, permite al órgano jurisdic
cional decretar la separación de patrimonios.
D) En cuanto al procedimiento, en las tres modalidades convencionales los cónyuges acce
den en primer térm ino a la declaración de separación de cuerpos, para posteriormente,
luego de dos meses, solicitar la disolución del vínculo. Divorcio que es declarado a pedido
de parte, no pudiendo ser de oficio de acuerdo con lo dispuesto por el artículo 354 del Có
digo Civil y artículo 7 de la Ley N° 29227. En consecuencia, aún no podemos sostener que
haya un acceso directo al divorcio convencional en nuestro régimen legal.
E) La d if e r e n c ia m á s re le v a n t e q u e a d v e r t im o s en la s t r a m it a c io n e s es q u e e n el p r o c e s o j u
