el consenso hasta la audiencia que se contempla, en la que los cónyuges o sus represen
tantes ratifican su solicitud de separación convencional.
F) Las tres vías contemplan aún la defensa cautiva, debiendo los cónyuges contar con la ase
soría de un (a) abogado(a). Sólo en el caso municipal será la asesoría legal del órgano de
gobierno local, quien cumplirá tal función.
C) En cuanto a la competencia, tanto los notarios como las municipalidades conocerán los
divorcios de aquellos cónyuges cuyo últim o dom icilio conyugal se encuentra bajo su ju
risdicción, para lo cual se requerirá de la declaración jurada respectiva. De tal disposición
se desprende que en el caso de los cónyuges cuyo últim o dom icilio conyugal fuese en el
extranjero, corresponde a los jueces tram itar y disponer el divorcio, observando dado el
carácter internacional de la relación, las normas de Derecho Internacional privado esta
blecidas en el Código Civil.
Como se observa en materia litigiosa no se ha alterado los caracteres mixtos de divorcio san-
cionadory remedio, habilitándose en materia convencional las otras dos posibilidades tanto
notarial como municipal, además del vigente camino judicial. Creemos que al fin y al cabo las
innovaciones acotadas no van a conducir a una deserción de los procesos judiciales en mate
ria convencional, por los requerimientos específicos anotados precedentemente, quedando
a voluntad de los cónyuges la elección de la vía que consideren no sólo más expeditiva, sino
también más al alcance de sus economías, aspecto en el cual aún el proceso judicial tiene
alguna ventaja.
10. La sociedad paterno - filia l
Puede definirse la filiación como aquella relación jurídica reconocida por la ley que se esta
blece entre una persona y otra derivada del hecho biológico de la procreación. El Derecho no
regula propiamente ese hecho natural, lo que regula son los efectos o consecuencias que pro
duce, pero no necesariamente el vínculo jurídico de la filiación va a coincidir con la realidad
biológica, pues el vínculo biológico responde a la verdad de una relación natural, en cambio
el vínculo jurídico puede negar reconocimiento a esa verdad natural por entrar en juego otras
consideraciones de orden moral, religioso o de conveniencia social.
Entre parentescoy filiación existe una relación de género a especie; el parentesco vincula a las
personas por consanguinidad, por afinidad o civilmente por la adopción, ese parentesco pue
de ser en línea recta o colateral, en grado más próximo o más remoto, relaciones que genera
según los casos deberes y derechos entre los parientes o prohibiciones como ocurre en el caso
de los impedimentos matrimoniales, es decir el parentesco hace surgir diferentes efectos y
relaciones jurídicas; una de esas relaciones, indudablemente la más importante es la que se
denomina filiación; es decir el vínculo de parentesco que une a las personas con sus padres o
con sus hijos.
Clases de filiación: Se distingue la filiación fundamentalmente en base a la existencia o
inexistencia del vínculo matrimonial entre los padres, en dos clases o variedades de filiación,
¡afiliación m atrimonial y la extramatrimonial.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 587 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
Se admiten esas dos clases de filiación, no porque subsista el trato discriminatorio por la na
turaleza de las cosas, pues son diferentes los criterios que pueden tomarse en cuenta para
establecer una u otra filiación; así, en la filiación matrimonial existe un punto de referencia
que es el de la celebración del matrimonio respecto del cual existe una evidencia pública y
preconstituida cual es la partida de un matrimonio, a partir del cual se toman en cuenta un
conjunto de presunciones jurídicas en cuanto al deber de fidelidad, al débito conyugal y a
los periodos probables de concepción y de embarazo, referencia que no existe en la filiación
extramatrimonial de la que tampoco pueden derivarse presunciones por la inexistencia de
deberes jurídicos.
A. La filiación matrimonial
Los presupuestos sobre los que reposa la afirmación de una filiación m atrimonial son por la
razón de lógica los siguientes: a) que el hijo ha sido alumbrado por una mujer casada generan
do entre ambos una relación materno filial; b) que la concepción o el nacimiento han ocurrido
dentro del m atrimonio; c) que el hijo fue engendrado por el marido de su mujer; establecién
dose así una relación paterno filial.
La concepción y subsiguiente parto deben haberse efectuado por mujer casada; la causa efi
ciente del nuevo ser es la unión sexual entre los cónyuges, relación m atrimonial que permite
suponerel débito sexual y el cumplimiento del deber de fidelidad entre los esposos, de modo
que salvo prueba en contrario puede afirmarse con fundamento que el embarazo de mujer
casada es obra del marido.
La concepción y el nacimiento deben darse dentro del matrim onio para que le corresponda al
hijo la filiación matrimonial.
La concepción en cuanto al momento en que este tiene lugar escapa sin embargo a una com
probación cronológica directa, es posible únicamente deducirla de un hecho posterior que es
consecuencia de ese fenómeno biológico, que es el nacimiento. Como el cálculo no se hace
en cada caso particular, la ley fija periodos promedios de tiempo para atender así a la infinita
diversidad de los casos más variados de modo que queden cubiertas las hipótesis más extre
mas de partos prematuros y partos retrasados, y fija los plazos m ínim oy máximo de gestación
de 180 y 300 días respectivamente, así que el que nace después de los 180 días siguientes al
matrimonio se le considera concebido dentro de él y tiene por padre al marido e igualmente
el nacido dentro de los 300 días posteriores a su disolución.
De la fecha de nacimiento se colige el período probable de concepción, no la fecha sino el
período, la presunción al respecto, es jure et de jure, no admite prueba en contrario, pues ellas
reposan en periodos que cubren, los extremos posibles de casos particulares.
El últim o presupuesto de que el hijo ha sido procreado por el cónyuge de la madre no requiere
probanza especial, la ley presume, es una presunción conocida como “paterisestquem nuptiae
demostremt”, que se funda en la realidad evidente de las relaciones sexuales entre los cónyuges
y la fidelidad que deben guardarse, quien intente destruir tales supuestos deberá probar lo
contrario.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 588 of 1506 --

UBILEX
Contestación de la paternidad matrimonial: Se le denomina también acción de negación,
desconocimiento o impugnación de la paternidad, en rigor procesal es la pretensión en virtud
del cual se trata de negara una persona la calidad de hijo m atrim onial del accionante.
En la filiación m atrimonial la ley presume que el marido es el padre del hijo concebido por
su mujer, presunción que tiene el carácter de ju ris tantum , adm itiendo prueba en contrario si
se ejercita la acción dentro de cierto lapso, pues en determinados casos no podría obligárse
le al esposo a reconocer o aceptar como hijo a quien fue engendrado por otro, a quien se le
franquea por consiguiente el ejercicio de la acción negatoria o contestatoria de la paternidad,
pero como el ejercicio de esta acción no puede ser abierto para que sin mayor fundamento se
provoquen estos cuestionamientos que afectan el honor de la madrey la identidad del hijo, se
señala taxativamente los únicos casos en los que procede el ejercicio de dicha acción que son
los enumerados por el artículo 3 6 3 °del Código Civil que son los siguientes:
a) Cuando el hijo nace antes de cumplidos los ciento ochenta días siguientes a la celebra
ción del matrimonio, la concepción se habrá producido con anterioridad, posibilitando
la acción negatoria por el marido que se sustentará con la partida de m atrim onio y de
nacimiento que demuestre el nacimiento prematuro, pretensión que podría quedar des
virtuada si la demandada opone la existencia de cualquiera de las excepciones capaces
de privar al marido de negar o impugnar su paternidad previstas en el artículo 366°del
Código Civil, es decir si antes del matrimonio o el marido tuvo conocimiento del embara
zo, si ha adm itido expresa o tácitamente que el hijo es suyo, o si el hijo ha muerto.
b) Cuanto sea manifiestamente imposible, dadas las circunstancias, que haya cohabitado
con su mujer en los primeros ciento veintiún días de los trescientos anteriores al naci
miento del hijo. En la fórmula genérica de “dadas las circunstancias” se incluye la posibili
dad de amplia probanza en diversidad de hechos que entrañen la imposibilidad de coha
bitación, que podrían referirse a casos de ausencia, privación de la libertad, enfermedad,
accidente, etc. Los que de ser reales excluirían la posible paternidad del marido.
c) Cuando está judicialmente separado durante el mismo periodo indicado en el inciso 2),
salvo que hubiera cohabitado con su mujer en ese periodo. La ley ha incluido este caso de
contestación de la paternidad ya que durante el período de separación de cuerpos auto
rizada judicialmente se supone que no ha habido relaciones sexuales pues la separación
de cuerpos suspende los deberes de lecho y habitación, salvo que se pruebe alguna de
las excepciones previstas en el artículo 366odel Código Civil. Para acreditar esta causal
deberá presentarse copia certificada de la resolución judicial de separación de cuerpos y
copia certificada de la partida de nacimiento.
d) Cuando adolezca de impotencia absoluta. Esta causal de contestación tiene un funda
mento obvio, pues si por razón de esa afección el marido no ha podido tener relaciones
sexuales con su mujer mal podría ser el autor del embarazo de ésta.
e) Cuando se demuestre a través de la prueba del ADN u otras pruebas de validez científica
que no existe vínculo parental. Se discute el tratam iento de ésta como una nueva causal,
pues mas bien se trata de un medio probatorio, pero cuyo efecto es el de descartar la po
sible relación biológica entre el esposo y el hijo alumbrado por su mujer.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 589 of 1506 --

Tema 3: l emas de la especialidad de fam ilia
impugnación de la maternidad matrimonial: Aunque poco menos frecuente que la contesta
ción o la impugnación de la paternidad, la negación de la maternidad está prevista en el artículo
371 del Código Civil, la que es posible ejercitar en los casos de parto supuesto llamado también
falso parto o parto fingido, que es cuando no ha existido realmente el alumbramiento de que se
le atribuye a una mujer casada, asimismo es posible ejercitar esta acción en los casos de suplan
tación de hijo, que es cuando se sustituye o se reemplaza al hijo verdaderamente alumbrado,
cuando falta identidad entre el verdadero hijo y el que indebidamente goza de ese estado. Esta
acción impugnatoria de la maternidad debe ejercitarse dentro del plazo de noventa días de des
cubierto el fraude y corresponde plantearla únicamente a la presunta madre, la acción se dirige
contra el hijo y en todo caso contra quien aparezca como presunto padre.
B. La filia ció n extramatrimonial
Esta filiación en oposición a la filiación matrimonial, es la que se genera fuera del matrimonio,
señalando al respecto el artículo 386o del Código Civil que son “hijos extramatrimoniales, los
concebidos y nacidos fuera del m atrimonio”, es decir tanto la concepción como el nacimiento
deben haberse dado fuera del matrimonio.
Como se ha señalado, la filiación matrimonial es relativamente fácil de ser constatada, pues
tiene como referencia un hecho objetivo y verifjcable como es el matrimonio de los padres y
del juego de presunciones bastante consistentes sobre deberes jurídicos y los plazos mínimo
y máximo de gestación, factores que no se dan en el caso de la filiación extramatrimonial, de
modo que no hay sino dos maneras de determinar o lograr ese emplazamiento, cuales son: a)
el reconocimiento voluntario; y b) la declaración judicial de la paternidad extramatrimonial.
El instrumento en que conste aquel reconocimiento voluntario o la sentencia favorable que
ponga fin al proceso judicial sobre declaración de paternidad constituyen así los únicos me
dios de prueba de esta filiación.
Declaración judicial de filiación extramatrimonial (Ley N° 28457).- Esta Ley regula el proce
dimiento para obtener una declaración judicial de filiación extramatrimonial. De acuerdo a la
ley el proceso se inicia con la petición de quien tenga interés en obtener una declaración de pa
ternidad, esta pretensión se interpone ante un juez de Paz Letrado quien expedirá resolución
declarando la filiación demandada. En este mismo proceso podrá acumularse como preten
sión accesoria, la fijación de una pensión alimentaria, de conformidad con lo establecido en el
últim o párrafo del artículo 85 del Código Procesal Civil. En este caso, el juez correrá traslado al
emplazado de la pretensión de filiación extramatrimonial y la pretensión de alimentos.
El emplazado puede form ular oposición a la declaratoria de paternidad extramatrimonial y
absolver el traslado de la pretensión de alimentos en el térm ino de diez días sujetándose a lo
dispuesto en el art. 565 del CPC. Si el emplazado no formula oposición dentro del plazo de diez
días, el juzgado declara la paternidad extramatrimonial y dictará sentencia pronunciándose
además sobre la pretensión de alimentos.
El demandado podrá allanarse a la demanda, desde que fue notificado hasta antes de la rea
lización de la prueba biológica de ADN.
En caso se dé la oposición, ésta no genera declaración judicial de paternidad siemprey cuando
el emplazado se obligue a realizarse la prueba biológica del ADN. El juzgado fijará fecha para
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 5

-- 590 of 1506 --

UBILEX
la audiencia única dentro de los i o días siguientes, en esta audiencia se llevará acabo la toma
de muestras para la prueba biológica del ADN, la cual es realizada con muestras del padre,
la madre y el hijo; en caso el padre no tenga domicilio conocido, sea inubicable o este haya
muerto, podrá realizarse la prueba al padre, madre u otros hijos del demandado de ser el caso.
El costo de la prueba es abonado por la parte demandada en la audiencia al laboratorio pri
vado al que se encargue la realización de la prueba. Este deberá estar acreditado conforme a
la regulación sanitaria correspondiente para brindar las garantías necesarias. Si la parte de
mandante asume el costo de la prueba en un laboratorio privado, la parte demandada debe
reintegrarle lo asumido en caso de que el resultado sea positivo a la paternidad.
El juzgado resuelve la causa por el solo mérito del resultado de la prueba biológica del ADN,
no resulta necesaria la realización de la audiencia especial de ratificación pericial.
Si la prueba produjera un resultado negativo, el juez declarará fundada la oposición y dictará
sentencia declarando también infundada la pretensión de alimentos, condenando a la parte
demandante al pago de las costas y costos del proceso. Si la prueba produjera un resultado
positivo, la oposición será declarada infundada, declarándose la paternidad. En la misma re
solución, se dictará sentencia respecto a la pretensión de alimentos condenando al demanda
do al pago de costas y costos del proceso. La declaración judicial de paternidad, la resolución
que ampara la oposición y/o el fallo relativo a la prestación de alimentos podrán ser apelados
dentro del plazo de tres días de notificado. Ingresada la causa al superior jerárquico, el juez
señalará fecha para la vista de la causa dentro del plazo de diez días y se emitirá la sentencia
en un plazo que no excederá de diez días.
El reconocimiento voluntario:
El reconocimiento es esencialmente un acto voluntario, una manifestación o declaración for
mal por el cual una persona expresa su paternidad o maternidad respecto de otra; este acto
jurídico tiene ciertos caracteres peculiares; como el de ser una declaración con efectos retroac
tivos al día de la concepción, el ser unilateral, en tanto se perfecciona con una sola declaración
de voluntad del padreo la madre que la hace sin requerirse la aceptación del hijo reconocido;
individual, por cuanto vincula al hijo sólo con quien la efectúa sin involucrar al otro padre,
teniendo en todo caso por no puesta toda mención al respecto; puroy simple, pues no admite
modalidades o elementos accidentales que podrían alterar o lim itar sus consecuencias lega
les; e irrevocable, pues no se admite retractación, la que se funda en una razón de seguridad
jurídica que hace preciso que el estado de las personas no quede expuesto a la volubilidad o a
una conducta ambivalente.
El reconocimiento puede ser efectuado por el padre o la madre, conjunta o separadamente,
excepcionalmente lo pueden hacer los abuelos o las abuelas de la respectiva línea en caso de
desaparición o muerte de los padres. Cuando el padre o la madre estén en estado de coma,
el hijo extramatrimonial puede ser reconocido a través de apoyos designados judicialmente.
Las formas de reconocimiento, que están sujetas a una cierta solemnidad son las siguientes:
a) A través del Registro de Nacimientos, puede hacerse en el momento de inscribirel nacimien
to o en declaración posterior mediante acta firmada por quien lo practicay autorizada por
el funcionario correspondiente.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 591 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
b) Por escritura pública, otorgada ante notario, que para estos efectos no requiere incluso de
minuta, explícitamente destinado a otorgar ese reconocimiento o que se haga alusión a
ella de manera indirecta.
c) Por testamento, en laque puede incluirse una cláusula sobre reconocimiento de la filiación,
referirse a ella nombrando al hijo con la calidad de tal o instituyéndolo como heredero.
La eventual revocación de ese testamento no afectará a la cláusula de reconocimiento por
tratarse de una declaración que no admite retractación.
El reconocimiento puede ser impugnado o negado por el padre o la madre que no intervino en
él, porel propio hijo o porsus descendientes si hubiera muerto, e incluso porquienes pueden
invocar un interés legítimo; el plazo para impugnar el reconocimiento o negarlo será de 90
días a partir del día en que se tuvo conocimiento del acto, o del año siguiente a la mayoría o
cese de la incapacidad del menor o incapaz en caso deque la ejercite el hijo.
Reconocimiento del h ijo extramatrimonial de mujer casada, el hijo o hija de mujer casada
puede ser reconocido por su progenitor cuando la madre haya declarado expresamente que
no es de su marido. Este reconocimiento se puede realizar durante la inscripción del nacimien
to cuando la madrey el progenitor acuden al registro civil, o con posterioridad a la inscripción
realizada solo por la madre, cuando esta haya declarado quién es el progenitor.
Procede también cuando el marido lo hubiese negado y obtenido sentencia favorable.
Reconocimiento de hijo mayor de edad, en este reconocimiento no se confiere derechos su
cesorios al que lo hace ni derecho a alimentos, sino en caso que el hijo tenga respecto de él la
posesión constante de estado o consienta en el reconocimiento.
Declaración judicial del vínculo paterno filial:
La determinación de la filiación no podría estar librada al arbitrio o a la buena voluntad de los
padres, por lo que cuando no hay ese reconocimiento espontáneo los hijos pueden suplir la
falta de disposición a través de una acción judicial de declaración de la paternidad o acción in-
vestigatoria de la paternidad extramatrimonial, para que luego de la investigación dentro de
un proceso contradictorio se declara por sentencia, aún contra la voluntad del presunto padre
la relación de filiación que le corresponde al hijo.
Conforme al artículo 402° del Código Civil, los casos en los que procede la acción investí gato ri a
de la paternidad extramatrimonial son los siguientes:
1. Cuando exista escrito indubitado del padre que la admita.
Es todo aquel documento que sin constituir un reconocimiento voluntario, constituye si
una constancia indubitable de paternidad, tales como las cartas o postales intercambia
das, actuados judiciales sobre alimentos, etc. En los que el padre señale inequívocamente
a su hijo no reconocido.
2. Cuando el hijo se halle, o se hubiera hallado hasta un año antes de la demanda, en la
posesión constante de estado de hijo extramatrimonial comprobado por actos directos
del padre o de su familia. La posesión de estado es un reconocimiento im plícitoy perma
nente que se configura cuando una persona ha criado a un hijo como suyo, ha provisto a
su educación, es conocido como tal en el ámbito de sus relaciones familiares y vecinales,
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 592 of 1506 --

UBILEX
es decir detenta el nombre, el trato y la fama, de los cuáles más importante es el trato
paterno filial que se han dispensado.
3. Cuando el presunto padre hubiera vivido en concubinato con la madre en la época de la
concepción.
Para estos efectos se toma en cuenta el concubinato en sentido amplio ¡atusensu, es decir
cuando falta uno o algunos de los caracteres que se exigen para considerar que existe un
concubinato propio o en sentido estricto, que son la singularidad, permanencia, notorie-
dady que los concubinos estén libres de impedimento matrimonial.
4. En los casos de violación, rapto o retención violenta de la mujer, cuando la época del deli
to coincide con la de la concepción.
Para que pueda fundarse en esta causal, la acción deberá estar sustentada en una sen
tencia penal condenatoria pues sólo con ella queda acreditada la existencia del d elitoy la
responsabilidad del procesado, pero si el ilícito ha sido perpetrado por varios sujetos en
banda en agravio de la misma víctima a cuya consecuencia ésta resulta embarazada re
sulta un problema de difícil solución que eventualmente puede ser resuelta con la prueba
de los grupos sanguíneos o la reciente del ADN.
5. En caso de seducción cumplida con promesa de matrimonio en época contemporánea
con la concepción.
Para que proceda la demanda por esta causal será necesario previamente que se haya
dictado sentencia condenatoria contra el presunto padre por el delito de seducción y que
se acredite la existencia de la promesa de matrimonio de manera indubitable.
6 . Cuando se acredite el vínculo parenteral entre el presunto padrey el hijo o hija a través de la
prueba del ADN u otras pruebas genéticas o científicas con igual o mayor grado de certeza.
Con la incorporación de esta nueva causal se flexibiliza el sistema de determinación de la
paternidad extramatrimonial que resultaba extremadamente rígido cuando se circuns
cribía a las cinco causales anteriores creando un estado de violencia en tanto no permita
este tipo de acción fuera de los casos mencionados.
El juez desestimará las presunciones de los incisos precedentes cuando se hubiera reali
zado una prueba genética u otra de validez científica con igual o mayor grado de certeza.
11. Aspectos procesales
El artículo 233A incorporado al Código Civil a través de la Ley N° 32228 (Pub. 08.01.2025),
detalla los principios generales aplicables en los procesos judiciales relacionados con los pro
cesos en materia de familia. Así tenemos:
Principio de oralidad: Prioriza el uso de audiencias verbales, reduciendo la dependencia
de trámites escritos para agilizar los procesos. A diferencia del proceso escrito, el principio
de concentración cobra especial vigencia en el sistema oral. En las audiencias se realizan
los mayores actos procesales posibles, concentrándolos en un sólo acto, evitando la dis
persión. Los medios probatorios se actúan en un solo acto, con la dirección obligatoria del
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

