Tema 3: Temas de la especialidad de fam ilia
juez, bajo sanción de nulidad, con lo que el Juez toma conciencia cabal y convicción de lo
que se discute en el proceso8.
Para hacer viable el sistema oral es necesario la aplicación de los principios procesales de in
mediación, concentración y publicidad, sin cuya concurrencia, perdería toda su eficacia.
Principio de tutela judicial efectiva: Con la tutela judicial efectiva no solo se persigue ase
gurar la participación o acceso del justiciable a los diversos mecanismos (procesos) que ha
bilita el ordenamiento dentro de los supuestos establecidos para cada tipo de pretensión,
sino que se busca garantizar que, tras el resultado obtenido, pueda verse este últim o mate
rializado con una mínimaysentada dosis de eficacia. STC N °0763-2005-PA/TC (Fj. 6).
Principio de inmediación: Implica la relación directa del Juez con las partes. El Juzgador
al dirigir las audiencias apreciará la conducta procesal de las partes, apreciará sus reaccio-
nesy se formará un concepto respecto de ellas, hecho que constituye un elemento impor
tante cuando realice la valoración de los medios probatorios. Pero, no sólo es el contacto
directo con las partes y los abogados, sino además, con todo el material del proceso. La
inmediación implica oralidad.
Principio de buena fe y lealtad procesal: Establece un marco ético para las partes invo
lucradas, promoviendo un comportamiento honesto y transparente durante el proceso.
Supone "un conjunto de reglas de conducta, presidido por el imperativo ético a las cuales
deben ajustar la suya todos los sujetos del proceso (partes, apoderados, jueces, testigos,
peritos, personas que auxilian al juez o que suministran la prueba)9”.
Principio de oficiosidad: Permite a los jueces actuar de manera proactiva para recolectar
pruebas y garantizar el cumplimiento de los derechos, incluso sin solicitud explícita de
las partes. El principio de oficiosidad que se manifiesta a través del impulso de oficio a
cargo del juez y puede cubrir las deficiencias en la defensa de las partes, ejemplo de la
aplicación de este principio tenemos a lo dispuesto en el art. 675 del CPC que establece
la responsabilidad del Juez de ordenar una pensión anticipada en tanto dura el proceso
judicial de alimentos aun cuando no haya sido solicitada por la parte demandante.
Protección prioritaria a niños y adolescentes
El segundo párrafo del artículo 233-A, incorporado a través de la Ley N° 32228 señala que en
los procesos que involucren derechos de niños y adolescentes, los jueces están obligados a
evaluar los hechos y circunstancias desde un punto de vista que priorice la vulnerabilidad de
la persona en las etapas de la infanciay la adolescencia garantizando el interés superiory su
derecho de participación en todo momento.
Este enfoque busca proteger su desarrollo integral y brindarles un entorno judicial que consi
dere sus necesidades y perspectivas.
11.1. Los hijos alimentistas
Se denomina así a los hijos extramatrimoniales que no pueden obtener la declaración ju d i
