y no tienen derecho sucesorio respecto de éste.
Se trata de grados de certeza en el conocimiento si se presentan los casos previstos en el artí
culo 402o del Código Civil se puede afirmar con cierta certidumbre que el emplazado es efecti
vamente padre de quien reclama ese estado, pero si no se dan esos presupuestos y sólo puede
