11.2. La adopción
La adopción puede definirse, así como el acto jurídico por el cual se toma como hijo a quien
no lo es por naturaleza estableciéndose entre adoptante y adoptado un parentesco civil que
produce los efectos jurídicos similares a los de la filiación biológica. Los antecedentes de esta
figura jurídica se remontan a los pueblos de la antigüedad, eminentemente religiosos, en los
que se cuidaba de modo especial el culto a los antepasados, las personas necesitaban dejar
descendencia para asegurar el cumplimiento de dichos cultos, ese fue el germen de la adop
ción, las personas que no tenían descendencia podían procurarse a través de ella un heredero
que al mantener la estirpe fam iliar aseguraba la continuidad del culto doméstico.
La adopción fue asimismo ampliamente difundida en Roma, se la utilizaba para diversos efec
tos, para hacer que algunas personas adquirieran el derecho de ciudadanía, para que algunos
plebeyos pudieran convertirse en patricios o que, viceversa, estos pudieran adquirir la condi
ción de plebeyos con fines políticos, el de desempeñar el cargo de Tribuno de la Plebe y tam
bién como medio empleado por ciertos Emperadores para asegurarse sucesores de su afectoy
confianza como Claudio que adoptó a Nerón.
Clases de adopción: La adopción en el Perú se tramita con arreglo a lo dispuesto en el Código
Procesal Civil, el Código de los Niños y Adolescentes, en la Ley para la protección de niñas, ni
ños y adolescentes sin cuidados parentales o en riesgo de perderlos y su reglamento y en Ley de
Competencia Notarial, según corresponda (Art. 379 C.C.). Así tenemos tres formas de adopción:
la adopción convencional o notarial que es exclusivamente para personas mayores de edad y ca
paces de ejercicio, el que se realiza a través de una minuta que se eleva a escritura pública dentro
de los procesos no contenciosos de competencia notarial según la Ley N° 26662, luego tenemos
la adopción administrativa que es para aquellos niñas, niños o adolescentes con declaración
judicial de desprotección familiar y adoptabilidad que según el Decreto Legislativo N° 1297 el
vínculo adoptivo se establece por resolución administrativa a cargo de la Unidades de Adopción10
del Ministerio de la M ujery Poblaciones Vulnerables-MIMP-; y final mente la adopción judicial
para casos de personas mayores de edad y por excepción según el artículo 128° del Código de los
Niños y Adolescentes la adopción en caso de quien posea vínculo matrimonial con el padre o
madre del niño o adolescente por adoptary cuando exista vínculo de parentesco hasta el cuarto
grado de consanguinidad o segundo de afinidad entre el posible adoptante y adoptado.
• Adopción administrativa:
La adopción administrativa se regulaen nuestro país conformeal Decreto Legislativoi297y su
reglamento D.S. N° 001-2018-MIMR es la medida de protección definitiva que tiene por objeto
garantizar el derecho de la niña, niño y adolescente declarada/o judicialmente en desprotec
ción fam iliary adoptabilidad, a vivir en una familia idónea para desarrollarse integralmente.
Personas que pueden solicitar la adopción: Pueden solicitar la adopción de una niña, niño o
adolescente:
