a) Cónyuges.
b) Integrantes de una unión de hecho con declaración notarial vigente.
c) Personas que deseen conformar una familia monoparental.
d) Las familias acogedoras tienen derecho preferente a adquirir la adopción.
Requisitos para la adopción: Las familias o personas interesadas en adoptar deben:
a) Contar entre veinticinco y sesenta y dos años de edad. La edad máxima puede ampliarse
excepcionalmente por razones debidamente justificadas en función del interés superior
del niño.
b) Acceder voluntariamente a la adopción, en forma escrita. Los cónyuges o integrantes de
unión de hecho, deben presentar la solicitud de adopción en forma conjunta.
c) Contar con declaración de idoneidad, a través de la declaración de idoneidad se comprue
ba que las/los solicitantes de adopción cumplen con el perfil del adoptante y tienen la
capacidad, aptitud y motivación adecuadas para ejercer la maternidad y/o paternidad y
asumir todas las responsabilidades que conlleva una adopción.
Las personas solicitantes de adopción nacional o internacional que obtienen resultado favo
rable en las evaluaciones, legal, psicológica y social son declaradas idóneas, mediante resolu
ción administrativa emitida por la Dirección General de Adopciones o las Unidades de Adop
ción, disponiendo su ingreso al Registro de Adoptantes
La idoneidad declarada en las adopciones nacionales tiene una vigencia de 03 años renovable
y en caso de las adopciones internacionales es la que determina el Decreto de Idoneidad o
documento análogo emitido en el país de residencia de las personas solicitantes.
Tipos de Adopción: La adopción puede ser:
Adopción Nacional: Se considera adopción nacional cuando:
a) El o la adoptante es peruano con residencia habitual en el país y solicita la adopción
de un niño, niñay adolescentes con residencia habitual en el Perú.
b) La o el adoptante extranjero con residencia habitual en el Perú por más de 2 años
continuos solicita la adopción de una niña, niño o adolescente con residencia habi
tual en el Perú.
Adopción Internacional: Se considera adopción internacional cuando:
a) La o el adoptante peruano o extranjero que reside habitualmente fuera del país so
licita la adopción de una niña, niño o adolescente con residencia en el Perú que va a
ser trasladada/o al país de residencia del o la adoptante.
b) La o el adoptante con residencia habitual en el Perú, solicita la adopción de algún
niño, niña o adolescente que reside habitualmente en el extranjero.
Las adopciones internacionales requieren de la existencia de convenios internacio
nales en materia de adopción, de los cuales el estado peruano sea parte.
Adopción Especial. Las Unidades de Adopción del MIMR realizan un trám ite especial para
casos de adopción de niños mayores de seis años, adolescentes, grupos de hermanos, niñas,
