Tema 3: Temas de la especialidad de fam ilia
níñosy adolescentes con díscapacidad, con problemas de saludy aquellos casos debidamente
fundamentados en el interés superiordel niño.
Etapas del procedimiento de adopción: El procedimiento administrativo de adopción de ni
ñas, niñosy adolescentes que cuentan con declaración del estado de desprotección fam iliary
situación de adoptabilidad, comprende cuatro etapas:
a) Evaluación.
b) Designación.
c) Integración familiar.
d) Post adopción.
Efectos de la adopción
A través de la adopción la niña, niño o adolescente declarado en estado de desprotección
fam iliary adoptabilidad, conforma una familia con el/la/los adoptantes, constituyéndose
en parte de ésta, con todos sus derechos y obligaciones, en calidad de hija o hijo, extin
guiéndose a la vez cualquier efecto legal por razón de parentesco con sus ascendientes o
colaterales consanguíneos.
La adopción es de carácter pleno, indivisibley establece de manera irrevocable la relación
paterno-ñlial entre el o la adoptante y la o el adoptado.
• Adopción judicial
1. La adopción de personas mayores de edad: El Código Procesal Civil (Art. 781) regula el pro
ceso de adopción de personas mayores de edad. La adopción mediante proceso judicial de
naturaleza no contencioso consiste en adoptar a una persona mayor de edad soltera o casada.
Por este proceso el adoptado adquiere la calidad de hijo del adoptante y deja de pertenecerá
su familia consanguínea, este trám ite también se puede llevar a cabo en sede notarial.
2. La adopción de menores de edad en vía de excepción: En vía de excepción, podrán iniciar
acción judicial de adopción ante el juzgado especializado, los peticionarios siguientes:
a) El que posea vínculo matrimonial con el padre o madre del niño o el adolescente por
adoptar. En este caso el niño o adolescente mantienen los vínculos de filiación con el pa
dre o madre biológicos; y,
b) El que posea vínculo de parentesco hasta el cuarto grado de consanguinidad o segundo
de afinidad con el niño o adolescente pasible de adopción.
Requisitos para la adopción: Según el art. 378 del C.C. para la adopción se requiere:
Que el adoptante goce de solvencia moral. Requisito que anteriormente se exigía bajo
la denominación de buena reputación la que tiene su justificación en la responsabilidad
formadora que se asigna al adoptante que para orientar, dirigir y educar al adoptado,
debe gozar de solvencia moral, de un clima fam iliar favorable a la formación de su perso
nalidad.
Diferencia mínima de edad. En el Código Civil de 1936 se exigía al adoptante una edad
mínima de 50 años en el entendido que a partir de esa edad la posibilidad de tener hijos
