Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 598 of 1506 --

biológicos era ya remota, requisito que se ha flexibi¡izado sustituyéndose por la diferen
cia mínima de edades, que está dada por la suma de la mayoridad con la del hijo por
adoptar para impedir que bajo la apariencia de la adopción se puedan desarrollar rela
ciones distintas a las que se deriva de la inflación.
Consentimiento del cónyuge adoptante. La forma condicional como esta expresado
este requisito cuando el adoptante sea casado permite inferir que pueden adoptar tan
to hombres como mujeres, sea cual fuere su estado civil de casados, viudos, divorciados
o solteros, aunque como es obvio tendrán preferencia los casados que tienen un hogar
sólidamente constituido; se exige este requisito pues por la adopción se crea automática
mente vocación sucesoria a favor del adoptado lo que a su vez menoscaba la expectativa
hereditaria del o la cónyuge del adoptante que por ende debe consentir en dicho trámite.
En caso de ser los adoptantes convivientes la Ley prevé, en reciente modificatoria del Art.
378 del C.C. (Ley N° Ley N°30311, publicada e h 8 marzo 2015) que “cuando el adoptante sea
conviviente conforme a lo señalado en el artículo 326, concurra el asentimiento del otro
conviviente”.
Asentimientos concurrentes. Según los casos, será necesario contar con la concurrencia
de otros asentimientos, entre ellos, el del propio adoptado si es mayorde diez años, pues
repugnaría que se le imponga un padre o una madre sin contar con su avenimiento; los
padres del adoptado igualmente deben prestarsu asentimiento pues la patria potestad a
su cargo quedará sustituida por la adopción; y finalmente, deberá escucharse la opinión
del tutor o curador o del consejo de familia si el adoptado fuere incapaz.
Que sea aprobada por el Juez, con excepción de los dispuesto en las leyes especiales.
Que si el adoptante es extranjero y el adoptado menor de edad, aquél ratifique perso
nalmente ante el juez su voluntad de adoptar. Se exceptúa de este requisito, si el menor se
encuentra en el extranjero por motivo de salud.
Procedimiento:
1. Presentación de la demanda.
2. Contestación de la demanda (padre o madre biológico)
3. Audiencia Única.
4. Informe social y evaluación psicológica a cargo del Equipo Técnico.
5. Dictamen del Fiscal de Familia.
6 . Sentencia.
Efectos de la adopción judicial: La adopción produce los siguientes efectos:
Crea un parentesco civil entre adoptante y adoptado en cuya virtud aquel adquiere la ca
lidad de hijo de éste, dejando de pertenecer a su familia consanguínea.
Por la adopción el adoptado quierey lleva los apellidos del adoptante pues deja de perte
necer a su familia consanguínea, extinguiéndose todo vínculo con ella con excepción a lo
relativo a los impedimentos matrimoniales.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 599 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
La patria potestad pasa a ser ejercida por el adoptante si es que el adoptado es menor de
edad, ya que por este vínculo se produce una transferencia de la patria potestad de los
padres consanguíneos a los adoptantes.
Derecho alim entarioy sucesorio afavordel adoptado, lo que teniendo el carácterde rela
ciones recíprocas genera igual derecho a favor del adoptante.
La adopción es irrevocable para el adoptante, para hacer más plena y completa la asimi
lación de la adopción a la filiación de la sangre. Si el adoptado fue incapaz es el único que
puede pedir que se deje sin efecto dentro del año siguiente de adquirida la mayoría de
edad.
• Adopción notarial
De conformidad con la Ley 26662, Ley de Competencia Notarial en Asuntos no Contenciosos,
sólo se tram ita ante notario la adopción de personas mayores de edad con capacidad de goce
y de ejercicio. Por ello tanto el adoptante como el adoptado tendrán que ser mayores de 18
años; y además deberá existir entre ellos una diferencia de 18 años de edad (art. 378o inc. 2do
del Código Civil).
Presentación de minuta y requisitos: La solicitud constará en una minuta presentada por el
adoptante y el adoptado acompañada de:
a. Copia Certificada de la partida de nacimiento del adoptante y de matrimonio, si es casa
do.
b. Copia Certificada de la partida de nacimiento del adoptadoyde matrimonio, si es casado.
c. Documento que acredite que las cuentas de su administración han sido aprobadas, si el
solicitante ha sido representante legal del adoptado;
d. Testimonio del inventario de los bienes que tuviera el adoptado.
La solicitud además de las firmas del adoptante y del adoptado, deberá de acompañar firm a
del abogado. Si el adoptante es casado, deberá acompañar cláusula adicional con firm a del
cónyuge.
Elevación a escritura pública e inscripción: La m inuta de adopción deberá de elevarse a es
critura pública, insertando en la misma los documentos anexados y posteriormente deberá
oficiarse a la Oficina del Registro Nacional de Identificación y Estado Civil de la Municipalidad
donde se haya asentado, para su inscripción y extensión de nueva partida de nacimiento del
adoptado.
12. Instituciones de protección familiar
12.1. Patria potestad
Concepto. El Derecho Romano en sus primeras épocas consideraba a la patria potestad como
un derecho casi absoluto de los padres sobre sus hijos, el hijo se encontraba sometido en todo
y por todo a su padre, de tal modo que el primitivo pater familias era propietario de sus hijos
como de sus esclavos, pues podía venderlos en casos de extrema necesidad, entregarlos para
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 600 of 1506 --

UBiLEX
que reparen el daño que hubiesen causado, incluso podían en casos extremos condenarlos a
muerte.
Posteriormente se ha opuesto una tendencia opuesta de considerar a la patria potestad como
un derecho del hijo frente al padre, o como la sumisión de los pares a las necesidades de los
hijos, es decir que no consideran ala patria potestad como una facultad de los padres sobre los
hijos sino como una obligación establecida en beneficio de los hijos. Entre las dos tendencias
ha surgido como es natural, la patria potestad como un derecho de los padres sobre sus hijos
ni solo como un derecho de los hijos frente a los padres sino como un complejo de derechosy
obligaciones recíprocas, que de una parte impone a los padres la responsabilidad de velar por
la personay los bienes desús hijos menoresy les permite por otra aprovechar de los servicios
de estos, usufructuar de sus bienes e im prim ir orientación a su personalidad.
Por ello el artículo 418o del Código Civil recoge como concepto de la patria potestad “el de
ber y derecho” que tienen los padres de cuidar de la persona y bienes de sus hijos menores.
Cabe anotar que si bien el ejercicio de la patria potestad puede atribuirse a uno u otro de los
padres en los casos de disenso, la titularidad la mantienen ambos; es decir son conceptos no
coincidentes que se pueden diferenciar; la titularidad está referida al complejo de deberes y
derechos especialmente en cuanto a los deberes como el alimentarlo, mientras que el ejerci
cio está referido al aspecto dinámico de la institución, al actuar concreto y actual que se da con
mayor énfasis en cuanto a las facultades que se concentra en uno de los padres quedando el
otro en suspenso.
Ejercicio de la patria potestad: Tratándose del hijo matrimonial, cuyos padres se hallan en
convivencia normal, estos ejercen conjuntamente y simultáneamente la patria potestad con
forme al principio de igualdad jurídica entre el varón y la mujer, en caso de disentimiento
resuelve el Juez de Familia en vía incidental, si el matrimonio se ha disuelto por muerte de
uno de los cónyuges, el ejercicio de la patria potestad corresponde exclusivamente al cónyuge
sobreviviente; si la disolución se hubiera producido por divorcio, la potestad la ejerce aquel de
los padres a quien el juez haya confiado los hijos, por lo general a favor de aquel a cuyo favor
se haya declarado el divorcio, quedando el otro en suspenso.
Si ambos cónyuges estuvieran en condiciones equivalentes, es decirsi ambos son culpables o
procedieron de mala fe se sigue el criterio de laedady el sexo de los hijos; los hijos menores de
siete años se confiarán de preferencia a la madre por considerarse que hasta en esa edad sus
cuidados serían insustituibles por estar especialmente dotada para la crianza y la educación
de los niños, pero cuando estos adquieren mayor uso de razón y capacidad reflexiva necesitan
una dirección y vigilancia más vigorosos, por lo que se encomienda al padre la responsabili
dad por los hijos varones mayores de siete años, conservando la madre la opción por las hijas
mayores de siete años por la afinidady posibilidades de identificación sexual.
Estas reglas no son de obligatoria observancia, por lo que se da al Juez un amplio margen para
aplicar sus criterios discrecionales, pudiendo apartarse de las reglas enunciadas como lo au
toriza la propia norma al hacer la salvedad en “a no ser que el Juez determine otra cosa por el
bienestar de ellos” además cabe señalar que el criterio de edad para establecer la preferencia
a favor de uno de los padres ha evolucionado, es así que el Código de los Ni ños y Adolescentes
establece la preferencia a favor de la madre sólo hasta la edad de los dos años.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 601 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
En la filiación extramatrimonial, el artículo 421° del Código Civil fija como primer criterio el del
reconocimiento voluntario, la patria potestad corresponde a que de los progenitores que hu-
biese efectuado el reconocimiento voluntario: Si ambos han efectuado dicho reconocimiento
aunque en diferente tiempo, la ley no establece preferencia en cuanto al orden de los reco
nocimientos a favor de aquel que primero lo practicó, sin embargo por un elemental sentido
lógico, menos opción tendrá aquel que ha efectuado un reconocimiento tardío, que es aquel
practicado varios años después del nacimiento de hijo lo que denotaría un cierto descuido o
desinterés por la suerte del hijo.
Si ambos padres han practicado el reconocimiento simultáneo o sucesivo el Juez toma en
cuenta la edad y el sexo del hijo, la circunstancia de vivir juntos o separados los padres, y, en
todo caso a los intereses del menor como se precisa en el artículo 421° del Código Civil a los que
ya se ha hecho referencia. El Código de los Niños y Adolescentes ha incorporado un criterio
importante, estableciendo una preferencia a favor del padre o la madre con quien haya con
vivido un tiempo mayor, periodo de convivencia que tiene sentido si se refiere al de la época
más reciente pues el simple aspecto cuantitativo referido a periodos primigenios ya pasados
podría resultar arbitrario frente a la situación actual o más reciente del niño o adolescente del
que se trate.
D erech o s y d e b e re s d e los p adres:
Los deberes y derechos que dan contenido a la patria potestad están enumerados en el artícu
lo 423o del Código Civil que considera a los siguientes:
1. Proveer el sostenimientoy educación de los hijos.
2. Dirigir el proceso educativo de los hijos y su capacitación para el trabajo conforme a su
vocación y aptitudes.
3. Aprovechar de los servicios de sus hijos atendiendo a su edady condición y sin perjudicar
su educación.
4. Teñera los hijos en su compañía y recogerlos del lugar donde estuviesen sin su permiso.
5. Representara los hijos en los actos de su vida civil.
6 . Administrar los bienes de sus hijos.
7. Usufructuar los bienes de sus hijos. Tratándose de productos, se está a lo dispuesto en el
artículo 1004.
Suspensión de la Patria Potestad (Art. 75oCNA): La característica de los casos de suspensión
es que no se trata de una pérdida definitiva de la patria potestad, pues los padres que han
quedado suspendidos en ella pueden pedir su restitución conforme al artículo 78o del Código
de los Niños y Adolescentes, cuando haya cesado la causal que las motiva. Las causales de
suspensión de la patria potestad son-,
a) Por la interdicción del padre o de la madre originada en causas de naturaleza civil;
b) Por ausencia judicialmente declarada del padre o de la madre;
c) Por darles órdenes, consejos o ejemplos que los corrompan;
d) Por permitirles la vagancia o dedicarlos a la mendicidad;
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 601

