UBILEX
e) Por maltratarlos física o mentalmente;
f) Por negarse a prestarles alimentos;
g) Por separación o divorcio de los padres, o por invalidez del matrimonio.
h) Por haberse abierto proceso penal al padre o a la madre por delito en agravio de sus hijos,
o en perjuicio de los mismos o por cualquiera de los delitos previstos en los artículos 107,
108-B, 110, 121-B, 122, 122-B, 125, 148''A, 153,153''A, 153-B, 153-D, 153-E, 153-F, 153-G, 153-H,
153- 1, 153-]. 170,171,172,173, 174, 175,176,176-A, 177, 179, 179-A, 180,181,181-A, 182-A, 183,
183-Ay 183-B del Código Penal, o por cualquiera de los delitos establecidos en el Decreto
Ley 25475, que establece la penalidad para los delitos de terrorismo y los procedimientos
para la investigación, la instrucción y el juicio.”
i) Por declaración de desprotección fam iliar provisional de un niño o adolescente.
Extinción o pérdida de la Patria Potestad (Art. 77 CNA).- Implica la pérdida definitiva de la
patria potestad, se pierde la patria potestad:
a) Por muerte de los padres o del hijo;
b) Porque el adolescente adquiere la mayoría de edad;
c) Por declaración judicial desprotección familiar;
d) Por haber sido condenado por delito doloso cometido en agravio desús hijos o en perjui
cio de los mismos o por la comisión de cualquiera de los delitos previstos en los artículos
107,108-B, 110,121-B, 122,122-B, 125,148-A, 153,153-A, 153-B, 153-D, 153-E, 153-F, 153-C, 153-H,
153- 1, 153-], 17 0,171,172, 173, 174, 175, 176, 176-A, 177,179,179-A, 180,181,181-A, 182-A, 183,
183-Ay 183-B del Código Penal, o por cualquiera de los delitos establecidos en el Decreto
Ley 25475, que establece la penalidad para los delitos de terrorismo y los procedimientos
para la investigación, la instrucción y el juicio.
e) Por reincidir en las causales señaladas en los incisos c), d), e) y f) del Artículo 75; y,
f) Por cesar la incapacidad de hijo, conforme al Artículo 46 del Código Civil.
Restitución de la Patria Potestad (Art. 78 CNA).- Los padres a quienes se ha suspendido el
ejercicio de la Patria Potestad podrán pedirsu restitución cuando cesa la causal que la motiva.
El Juez especializado debe evaluar la conveniencia de la restitución de la Patria Potestad en
razón del Principio del Interés Superior del Niño y del Adolescente.
12.2.La Tutela
Del latín “tuere” que significa proteger, es la institución supletoria o subsidiaria a la patria po
testad por la cual se provee al cuidado de la persona y de los bienes de los menores de edad
cuando estos no se encuentran sujetos a la patria potestad, sea porque ambos padres han
fallecido, son incapaces de ejercicio, no tienen filiación conocida o han sido privados de la
patria potestad, situaciones en las que es preciso designarles un tutor para que se ocupe de
los asuntos concernientes a la personay los bienes del menor que carece de padres expeditos.
Entre la patria potestad y la tutela que son instituciones afines existen sin embargo diferencias,
entre ellas, que la patria potestad se ejerce por mandato de la naturaleza más que por crea
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 603 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
ción de la ley, mientras que la tutela es ejercida más que por un deber natural por un impera
tivo de solidaridad recogido por la ley; la patria potestad se deriva de la procreación mientras
que existe tutela porque así lo exige la convivencia social. El fundamento de la tutela es el
deberde solidaridad fam iliary social que obliga a dar protección a quien no puede valerse por
sí mismo en razón de su minoría de edady hallarse privado al amparo de sus padres naturales.
Clases de tutela: Atendiendo a su fuente de designación pueden distinguirse hasta cuatro
clases de tutela, que son las siguientes:
a) La tutela testamentaria o escrituraria, es la tutela preferencial cuya designación proviene de
una declaración de voluntad de parientes muy próximos como son los padres, los abuelos
o de cualquier testador que instituya al menor como heredero o legatario dejándole bie
nes en cuantía suficiente para atender a su subsistencia.
b) La tutela legítima, a falta de tutor testamentario desempeñarán el cargo los abuelos y de
más ascendientes, prefiriéndose al más próximo en lugar del más rem otoy al más idóneo
en igualdad de grado, lo que es explicable, pues a falta de padres no hay parientes más
interesados en la suerte y bienestar de los huérfanos que los abuelos.
c) La tutela dativa, supletoria de las dos anteriores, es aquella cuyo nombramiento es efec
tuado por el Consejo de Familia, que es convocado y presidido por el Juez de fam ilia a
pedido de los parientes, del Ministerio Público o de cualquier persona, designación que
pueda recaer en cualquier persona residente en el dom icilio del menor.
d) La tutela estatal; cuando no es posible las otras clases de tutela, funciona esta tutela que
la ejerce figuradamente el Estado o a través de establecimientos ajenos a la fam ilia del
menor o de instituciones particulares dedicadas a la guarda de menores, se ejerce a través
del director del establecimiento o responsable de la institución, clase de tutela que se da
principalmente respecto de los menores expósitos o en situación irregular.
e) La tutela oficiosa irregular, llamada también tutela estatal, una vez emitida la resolución
que declara la desprotección fam iliar provisional de una niña, niño o adolescente se pro
duce la asunción automática de la tutela estatal por parte de la autoridad competente.
Asimismo, produce de forma automática, la suspensión de la patria potestad o de la tute
la. (Arts. 51,53 del Decreto Legislativo N°i297)-
Requisitos previos al ejercicio de la tutela (Art. 520o C.C.): En resguardo de los derechos e
intereses del menor se exige una serie de requisitos que deben cumplirse en forma previa al
ejercicio de la tutela con el objeto de verificar la idoneidad de la persona que se hará cargo del
m enory asegurar un eficientey responsable ejercicio.
Ellos son los siguientes:
a) Facción de inventarios, de los bienes del menor, con intervención de este si tuviera dieciséis
años cumplidos. Si bien la norma exige que el inventario sea “judicial” al haberse dado
competencia alternativa para este tipo de trámites no contenciosos a los Notarios, en
tendemos que este requisito que permitirá pedir luego rendición de cuentas, conocer los
frutos producidos por los bienes del tutelado, podría hacerse también en la vía notarial
que es mucho más expeditiva. Sólo después de efectuado el inventario el tutor podrá to
mar la administración de los bienes del pupilo.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 6

-- 604 of 1506 --

UBILEX
b) La constitución de garantía- el tutor antes de discernir el cargo ante el Juez debe constituir
garantía hipotecaria o prendaria para asegurar las resultas de su gestión y la eventual res
ponsabilidad que le podría corresponder; y si no tuviera bienes sobre los cuales constituir
esas garantías reales podrá constituir una garantía personal como es una fianza. El tutor
legítimo, que puede serlo uno de los abuelos u otros ascendientes no está obligado a
constituir esa garantía real o personal dado que por acto natural se presume que desem
peñará el cargo de manera responsable. Del mismo modo no sería exigible esta garantía
en el caso de la tutela estatal y en el caso de la tutela oficiosa.
c) El discernimiento del cargo-, es un trám ite obligatorio que debe realizarse ante un Juez, ante
quien el tutor nombrado debe prometer que guardará fielmente de la persona y de los
bienes del menor, declarar si es acreedory el importe de sus créditos bajo sanción de per
derlo, o si es su deudor o fiador del deudor, este requisito es exigible al tutor testamen
tario o escriturario, lo mismo que al legítimo y al dativo en esta diligencia, el tu to r debe
asumir ante el Juez competente que es el de familia, el buen desempeño de su función.
La inscripción del discernimiento del cargo de tu to r en el Registro Personal de los Regis
tros Públicos, con fines de publicidad para conocimiento de terceros. Debe precisarse que
conforme al Art. 2030o inc. 4) del Código Civil se inscribe en el Registro Personal no el
nombramiento de tutores sino el discernimiento del cargo con mención de los inmuebles
inventariados y de las garantías prestadas.
Impedimentos para ejercer tutoría: No pueden ser tutores (Art. 515 CPC):
1. - Los menores de edad. Si fueran nombrados en testamento o por escritura pública, ejerce
rán el cargo cuando lleguen a la mayoría.
2. - Los sujetos a cúratela.
3. - Los deudores o acreedores del menor, por cantidades de consideración, ni los fiadores de
los primeros, a no serque los padres los hubiesen nombrado sabiendo esta circunstancia.
4. - Los que tengan en un pleito propio, o de sus ascendientes, descendientes o cónyuge, inte
rés contrario al del menor, a menos que con conocimiento de ello hubiesen sido nombra
dos por los padres.
5. - Los enemigos del menor o de sus ascendientes o hermanos.
6 . - Los excluidos expresamente de la tutela por el padre o por la madre.
7. - Los quebrados y quienes están sujetos a un procedimiento de quiebra.
8 . - Los condenados por homicidio, lesiones dolosas, riña, aborto, exposición o abandono de
personas en peligro, supresión o alteración del estado civil, o por delitos contra el patri
monio o contra las buenas costumbres.
9. - Las personas de mala conducta notoria o que no tuvieren manera de vivir conocida.
10. - Los que fueron destituidos de la patria potestad.
11- Los que fueron removidos de otra tutela.
Derechos del pupilo
- Pueden adquirir bienes a título gratuito, sin la participación del tutor. Nada les impide
aceptar legados, donacionesy herencias voluntarias que sean purasy simples.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 605 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
- Pueden ejercitar derechos estrictamente personales y celebrar contratos relacionados
con las necesidades ordinarias de la vida diaria.
- Pueden dedicarse a un trabajo, ocupación, industria u oficio con la debida autorización.
- El menorque ha cumplido catorce años puede impugnar los actos del tutor o puede soli
citar su renovación.
- Puede pedir la remoción del tutor el m enorque te n g a n años.
- El menor de 18 y mayor de 16 puede prestar su consentí miento y tendrá derecho a ser oído
por el juez, antes de que se autorice al tu to r a disponer de los bienes.
- Puede presenciar la rendición de cuentas del tutor, siempre que cuente con más de 14
años.
Derechos del tutor
- El tutor tiene derecho a una retribución que fijará el juez teniendo en cuenta la impor
tancia de los bienes del m enory el trabajo que ha demandado su administración en cada
período. Nunca excederá dicha retribución del ocho por ciento de las rentas o productos
líquidos consumidos ni del diez por ciento de los capitalizados.
- Al respeto y obediencia del menor.
Deberes y atribuciones del tutor.
- A lim entary educar al menor de acuerdo a la condición de éste y proteger y defender su
persona.
- Corregir moderadamente al menor.
- Cuando el menor carezca de bienes o éstos no sean suficientes, el tutor demandará el
pago de una pensión alimenticia.
- Representar al menor en todos los actos civiles, excepto en aquellos que, por disposición
de la ley, éste puede ejecutar por sí solo.
- Adm inistrarlos bienes del menorcon la diligencia ordinaria.
- Solicitar autorización judicial para enajenar o gravar los bienes del menor en caso de ne
cesidad o utilid ad y para realizar otros actos expresamente señalados.
- A dar cuenta de su administración: anualmentey al acabarse la tutela o cesaren el cargo.
- Continuar ejerciendo el cargo hasta su relevo, en los casos en que el tutor renuncie a la
tutela o su nombramiento sea impugnado.
Fin de la tutela:
La tutela se acaba:
1. - Por la muerte del menor.
2. - Por llegar el menora los 18 años.
3. - Por cesar la incapacidad del menor conforme al artículo 46o.
4. - Por cesar la incapacidad del padre o de la madre en el caso del artículo 580o.
5. - Por ingresar el menor bajo la patria potestad.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 606 of 1506 --

12.3. La Cúratela
La cúratela es una institución tutelar de familia destinado a la protección y representación de
personas con capacidad de ejercicio restringida en mayores de edad, a quienes se provee de
un curador que lo asiste en el manejo de sus bienes, lo representa y procura en lo posible su
restablecimiento. Según el Art. 564 del C.C. modificado por el Decreto Legislativo N °ib 8 4 , es-
tán sujetas a cúratela los pródigos, los que incurren en mala gestión, los ebrios habituales, los
toxicómanosy los que sufren pena que lleva anexa la interdicción civil. Conforme este nuevo
texto, las personas con discapacidad ya no se encuentran inmersas o sujetas al régimen de la
cúratela. Ahora la cúratela solo es aplicable a las personas con capacidad de ejercicio restringi
da, cabe señalar que para esta figura, en virtud del nuevo art. 566o, se necesita necesariamente
declaración judicial de interdicción para los casos de los pródigos, los que incurren en mala
gestión, los ebrios habitualesy los toxicómanos.
Nuestra legislación regula separadamente la tutela de la cúratela, aunque atendiendo a sus simi
litudes extiende a la cúratela las reglas previstas para la tutela con las modificaciones establecidas
en el capítulo que le es propio, aplicación supletoria que establece el artículo 568°de| Código Civil.
Se mantiene el tratamiento separado en razón de que existen diferencias entre el tipo de in
capacidades que se trata de suplir; así, la tutela tiende a prestar amparo a quienes atravie
san por una etapa de incapacidad natural por la que todas las personas atraviesan de modo
inexorable, en cambio la cúratela tiende a proteger a quienes adolecen de una incapacidad
accidental, que no llegan a padecertodas las personas sino algunas de ellas pues no todas por
ejemplo llegarán a estar afectados por ebriedad habitual o ser toxicómanos.
Clases de cúratela:
Nuestra legislación contempla en principio diferentes tipos de cúratela:
a) Cúratela de bienes o administración de bienes. Según Aguilar Llanos, esta cúratela no
tiene mayor incidencia en el orden personal, pues como su nombre lo refiere solo com
prende el cuidado, custodia y manejo de un patrimonio, bien o conjunto de bienes que
por circunstancias particulares carecen de titu lar expedito, tal es el caso por ejemplo, del
desaparecido que por obvias razones no puede estar al frente de su patrimonio, en tal si
tuación se ha visto por conveniente que alguien cuide ese patrimonio, y ese alguien viene
a ser el curador de bienes, limitándose sus funciones solo al gobierno de esos intereses
económicos, mas no tiene ninguna función que cumplir con respecto a la persona del
titu lar de ese patrimonio, de allí la denominación de cúratela atípica. (Art. 565o inc. 2) C.C.)
b) Cúratela para asuntos determinados (Art. 565o inc. 3 del C.C.). Llamada cúratela especial,
se instituyen para asuntos concretosy determinados, son cúratelas atípicas restringidasy
para casos específicos en los que existe conflicto o incompatibilidad. Ejemplo: Cuando los
intereses de los hijos están en oposición al de los padres que ejerzan la patria potestad, se
nombrará curador especial para que se encargue del interés del menor que está en franca
oposición con el de los padres, una vez superada la diferencia u oposición de intereses
habrá terminado la cúratela especial (Art. 460 C.C.).
El curador sustituye a la persona que es declarada interdicta judicialmente en lo que respecta a su
capacidad de ejercicio, en cambio el apoyo asiste a la persona con discapacidad, no la reemplaza.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 607 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
12.4. La Autotuteia (Art. 568-A C.C)
Llamada también penúltim a voluntad, figura incorporada a nuestro ordenamiento jurídico a
través de la Ley N° 29633, se complementa la Institución de la cúratela modificándose, vía am
pliación, el artículo 568 Código Civil al incorporar la estipulación de autotuteia para la propia
incapacidad. A través de esta institución una persona capaz de ejercicio puede anticipada
mente establecer la protección de su persona y bienes ante su propia incapacidad futura, fa
cultándosele a que (i) nombre su propio curador; (ii) indicar sus facultades; o, (iii) disponer
quiénes no pueden ser designados como tal.
Tiene como sustento el legítimo ejercicio de derecho a la autodeterminación del sujeto de for
ma tal que, en previsión que en un futuro sea declarado judicialmente incapaz en un proceso
de interdicción, se le reconoce la libertad para elegir quien será el responsable del cuidado de
su vida y patrimonio. Así, por la autotuteia se reconoce el derecho para que una persona escoja
y designe a su curador concediéndole las atribuciones que tenga a bien.
Este acto se formaliza mediante Escritura Pública con la presencia de 02 testigos y se inscri
be en el Registro Personal de la SUNARR Al tratarse de un acto jurídico unilateral puede ser
modificado, revocado, ampliado o limitado, lo que permite una amplia autonomía; lo único,
es que cualquiera de estos actos debe cumplirse con las mismas formalidades que para su
otorgamiento.
Iniciado un proceso de interdicción, el Juez recabará la certificación del Registro a efectos de
verificar la existencia del nombramiento de curador, sus facultades o, en su caso, el impedi
mento impuesto a que cierta persona sea designada. La voluntad debe ser respetada por el
juez. En efecto, estas disposiciones son tomadas en cuenta por el juez en el curso del proceso
y regirán desde la sentencia que declara la interdicción.
Impedimentos: Le son aplicables los mismos impedimentos y excusas para ejercer la tutela
establecidos en el Código Civil.
12.5. El Consejo de Familia
El Consejo de Familia es así un órgano colegiado, deliberantey en ocasiones ejecutivo, presidi
do por un Juez, que tiene por función controlar la labor que cumplen los tutores y curadores,
velando de esta manera por la persona e intereses de los menores e incapaces mayores de
edad que no tenga padre ni madre.
Clases de Consejo de Familia y su composición: En nuestra legislación civil se distingue hasta tres
clases de Consejo de Familia, de acuerdo a la fuente de designación de sus miembros, ellos son:
a) El Consejo de Familia testamentario o escriturario; el que según el artículo 623o del C.C.
está conformado por las personas que hayan sido designadas por los padres que hayan
ejercido la patria potestad o la cúratela o por los abuelos que hayan tenido al menor o
incapaz bajo su tutela.
b) El Consejo de Familia legítimo; el que conforme al artículo 623o del C.C. se constituye a
falta del Consejo de Familia testamentario o escriturario, formando parte de el los abue-
losy las abuelas, hermanosy hermanas, tíosy tías del incapaz, siendo también miembros
natos de este órgano los hijos capaces del mayor incapaz.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 608 of 1506 --

UBILEX
c) El Consejo de Familia dativo: es para los casos que no pudiendo conformarse el Consejo
de Familia con cuatro miembros natos antes señalados es integrado por el juez de Familia
o el juez de Paz Letrado llamando a parientes colaterales por consanguinidad tales como
sobrinos, primos hermanos hasta completar el número mínimo de cuatro.
Con respecto a la composición, los integrantes son individualizados en el testamento o escritura
pública tratándose del Consejo escriturario o testamentario y en los otros Consejos de Familia la
persona que solicita la información de Consejo debe indicar los nombres que deben integrarlo.
Excusase impedimentos: Por regla general el desempeño del cargo de miembro del Consejo
de Familia es obligatorio, señalando el artículo 633o del Código Civil que es gratuito e inexcu
sable, pues se trata de un deber derivado de un imperativo de solidaridad social, de modo que
ni el rico dedicado a sus negocios o el pobre preocupado de sus problemas puedan desenten
derse fácilmente de esta responsabilidad: la única excepción en la que se permite excusa es
cuando hay impedimento legal o cuando el pariente llamado reside fuera de los cincuenta
kilómetros del lugar donde funciona el Consejo.
Si bien el cargo de miembro del Consejo de Familia es obligatorio, si existe un impedimento
legal el llamado no sólo no se encuentra obligado a aceptar el cargo sino que no debe aceptar
ni ejercer el cargo, entre ellos tenemos a quienes precisamente van a ser supervisados tales
como los tutores, curadores o padres, los parientes menores de edad, cuando exista oposición
de intereses con los del menor o incapazy aquellos que carecen de idoneidad moral.
Funcionamiento y fin del Consejo de Familia: Instalado el Consejo de Familia, por el juez de
Familia o el juez de Paz Letrado según los casos, se extiende el acta respectiva en los Libros
previstos para tal efecto, quedando expedito el Consejo, previa convocatoria del juez que la
preside, para reunirse cada vez que lo exija el interés del incapaz o cuando deba cumplirse con
alguna de las atribuciones que compete ejercer al Consejo. El quorum para la validez de sus
sesiones es cuando menos tres de sus miembros además del juez.
Entre las múltiples funciones que corresponden al Consejo de Familia enumeradas por el ar
tículo 647o del Código Civil pueden señalarse lo relativo al nombramiento de tutores y cura
dores; adm itir o su renuncia o excusa; remover o provocar la remoción de tutores o curadores;
fijar la parte de las rentas destinadas a los alimentos del incapaz; aceptar la donación, heren
cia o el legado; autorizar al tutor o curador a contratar administradores especiales; indicar los
bienes que deben ser vendidos por causa de necesidad y utilidad; etc.
Tratándose de un órgano encargado de supervisar las labores que cumplen tutores o curado
res, el Consejo de Familia cesa en los mismos casos en loque acaba la tutela o la cúratela, pues
en esos casos ya no tendría objeto del funcionamiento de ese órgano deliberativo.
12.6. Apoyos y salvaguardias (Arts. 659-A a 659-H del C.C.)
El artículo 45 del C.C (Modificado por el D. Leg. 1384) establece: “Toda persona con discapaci
dad que requiera ajustes razonables o apoyo para el ejercicio de su capacidad jurídica puede
solicitarlos o designarlos de acuerdo a su libre elección.”
En esa línea, el artículo 45-B del C.C. (Incorporado por el D. Leg. 1384) regula la designación de
apoyos y salvaguardias: “Artículo 45-B.- Designación de apoyos y salvaguardias.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 609 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
Pueden designar apoyosy salvaguardias:
1. Las personas con discapacidad que manifiestan su voluntad pueden contar con apoyosy
salvaguardias designados judicial o notarialmente.
2. Las personas con discapacidad que no pueden manifestar su voluntad podrán contar con
apoyos y salvaguardias designados judicial mente.
3. Las personas que se encuentren en estado de coma que hubieran designado un apoyo
con anterioridad mantendrán el apoyo designado.
4 . Las personas con capacidad de ejercicio restringida contempladas en el numeral 9 del
artículo 4 4 contarán con los apoyos y salvaguardias establecidos judicialmente, de con
form idad con las disposiciones del artículo 659-E del presente Código.”
Por su parte en el art. 659-B del C.C. se define la figura del apoyo (incorporado por el Decreto
Legislativo 1384), estableciendo lo siguiente.- Tos apoyos son formas de asistencia libremente
elegidos poruña persona mayor de edad para facilitar el ejercicio desús derechos, incluyendo
el apoyo en la comunicación, en la comprensión de los actos jurídicos y de las consecuencias
de estos, y la manifestación e interpretación de la voluntad de quien requiere el apoyo”.
En el Perú, los “apoyos” son figuras jurídicas incorporadas a nuestra legislación, mediante el
Decreto Legislativo N°i384, con la finalidad que las personas con discapacidad puedan ejercer
plenamente sus derechos de manera autónoma y en igualdad de condiciones. Son así una
forma de asistencia para facilitar el ejercicio de los derechos de una persona y garantizar el
ejercicio de su capacidad jurídica, que se caracterizan porque no sustituyen o reemplazan a la
persona con discapacidad sino que lo ayudan a tomar sus decisiones, esto es, a formar y dar
a conocer la voluntad, para lo cual tendrán en cuenta aspectos de la vida de la persona a la
que asisten, como son educación, intereses, círculo social y en general cualquier situación que
permita determinar la real voluntad del asistido. Resolución N° 953 -2021-SUNARP-TR. Fj. 5.
El apoyo no tiene facultades de representación salvo en los casos en que ello se establezca
expresamente por decisión de la persona con necesidad de apoyo o el juez.
La persona o personas que realicen el apoyo están exentas de la obligación de garantizar su
gestión, salvo lo dispuesto en el artículo 42.6 C.C. (Garantía para la administración legal).
Cuando el apoyo requiera interpretar la voluntad de la persona a quien asiste aplica el criterio
de la mejor interpretación de la voluntad, considerando la trayectoria de vida de la persona,
las previas manifestaciones de voluntad en similares contextos, la información con la que
cuenten las personas de confianza de la persona asistida, la consideración de sus preferencias
y cualquier otra consideración pertinente para el caso concreto.
La persona mayor de edad que requiera de apoyo para el ejercicio de su capacidad jurídica
puede designarlo ante un notario o un juez competente, es decir, “la designación de apoyos no es
facultad exclusiva de las personas con discapacidad, sino que también cualquier persona mayor de edad
que requiera-o pueda requerirla en el fu tu r o - asistencia para el ejercicio de su capacidad jurídica podrá
designar apoyo, para lo cual deberá concurrir al juez o al n otarioy manifestarsu voluntad.” Resolución
N °953- 2021-SUNARP-TR. Fj. 6.
Excepción a la designación de los apoyos por juez: El juez puede determinar, de modo excep
cional, los apoyos necesarios para las personas con discapacidad que no puedan manifestarsu
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DESELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 610 of 1506 --

UBILEX
i voluntad y para aquellas con capacidad de ejercicio restringida (personas que se encuentren
en estado de coma).
El juez determina la persona o personas de apoyo tomando en cuenta la relación de convi-
vencía, confianza, amistad, cuidado o parentesco que exista entre ella o el las y la persona que
requiere apoyo. Cas. N° 2958-2018-Lambayeque. Asimismo, fija el plazo, alcances y responsa
bilidades del apoyo. En todos los casos, el juez debe realizar las diligencias pertinentes para
obtener la mejor interpretación posible de la voluntady las preferencias de la persona, y aten
der a su trayectoria de vida. No pueden ser designados como apoyos las personas condenadas
por violencia fam iliar o personas condenadas por violencia sexual.
El proceso judicial de determinación de apoyos excepcionalmente se inicia por cualquier per
sona con capacidad jurídica.
"4.2. En ese orden de ideas, el artículo 45-B del Código Civil, incorporado por el artículo 2 del
Decreto Legislativo 1384, establece que pueden designar apoyos y salvaguardias las personas
con discapacidad que m pueden manifestar su voluntad podrán contar con apoyos y salvaguardias
designados judicialmente.
Asimismo, el artículo 659-E del Código Civil establece que el juez puede determinar, de modo
excepcional, los apoyos necesarios para las personas con discapacidad que no puedan m ani
festar su voluntad. Esta medida ss justifica, cuando la designación da apoyos sea necesaria para si ejercicio y protección
de sus derechos." Cas. N° 2558-2018 Lambayeque.
Designación de apoyos a futuro: Los apoyos pueden serelegidos también por personas mayo
res de edad a futuro, según lo señalado en el art. 659-FC.C., en caso consideren que a posteriori
puedan tener una discapacidad o en caso de que ya tengan discapacidad, pero consideran
que en cierto momento será adecuado tener un apoyo en la toma de decisiones. Es menester
mencionar que los derechos de la persona con discapacidad mental e intelectual que cuente
con apoyos serán protegidos y garantizados por medio de las salvaguardias establecidas en el
art. 659''G del C.C., como bien se detalla: "Las salvaguardias son medidas para g arantizare! respeto
de los derechos, la voluntady las preferencias de la persona que recibe apoyo, prevenir el abuso y la in
fluencia indebida por parte de quien brinda tales apoyos; así como evitar la afectación o poner en riesgo
los derechos de las personas asistidas.
La persona que solicita el apoyo o el juez interviniente en el caso del artículo 65 9-E establecen las sal
vaguardias que estimen convenientes para el caso concreto, indicando como mínimo los plazos para la
revisión de los apoyos.
El juez realiza todas las audiencias y diligencias necesarias para determ inar si la persona de apoyo está
actuando de conformidad con su mandato y la voluntady preferencias de la persona”.
Las salvaguardias fueron reconocidas en el art. 12, numeral 4,40 de la Convención sobre los
derechos de las personas con discapacidad, este obliga a los Estados Partes a adoptar las sal
vaguardias afín de evitar abusos en el ejercicio de las facultades otorgadas a los apoyos.
