Tema 3: Temas de la especialidad de fam ilia
12.7. Interdicción
La interdicción civil es la acción judicial por la cual se declara incapaz a una persona de ejercer
sus derechos civiles por sí misma, en los casos en que esta no puede expresar su voluntad de
forma librey cabal.
Con anterioridad al D. Leg. 1384, en el Perú, a la persona que tenía alguna discapacidad (aque
llas personas con deficiencias físicas, mentales, intelectuales o sensoriales, ya sea de natu
raleza temporal o permanente) se le tenía que iniciar un proceso legal de interdicción en el
que se le asignaba un curador. Actualmente, se reconoce y regula la capacidad jurídica de las
personas con discapacidad en igualdad de condiciones. Es decir, ha surgido un cambio en el
tratamiento de la capacidad en el Perú. En este sentido las personas con discapacidad ya no
serán interdictadas y podrán tomar decisiones con la ayuda de la figura legal de los apoyos y
salvaguardias si así lo requieren, a excepción por ejemplo del caso de los ebrios habituales y
toxicómanos para los que se aplica la interdicción.
Al respecto, señala el profesor Reynaldo Mario Tantaleán Odar11 que "el modelo de interdic
ción, es decir, aquel en virtud del cual se entiende que un sujeto con incapacidad absoluta o
relativa, requiere ser declarado interdicto y designarle un curador para que supla su voluntad,
está vigente aún en el Perú. Ciertamente, luego del exabrupto “ingreso” del Decreto Legislativo
1384, en el Perú se incorporó el esquema de los apoyos y salvaguardias para quienes adole
cieran de cualquier discapacidad, sea esta física, mental, intelectual o sensorial, sin importar
el nivel o gravedad de estas, desterrando el esquema de interdicción y cúratela porque era
necesario apoyar la voluntad del sujeto con discapacidad y no suplirla. Pero el legislador se
olvidó que los supuestos de interdicción no solamente se conectaban con temas relacionados
con discapacidades, sino que también había casos de otra índole, como, por ejemplo, aso
ciados a temas económicos o de dependencia a sustancias. Efectivamente, entre los casos de
interdicción se contemplaba también a los incapaces relativos, resultado de la prodigalidady
la mala gestión, como asuntos económicos; así como al toxicóm anoy al ebrio habitual, como
supuestos de dependencia a sustancias; todo ello dejando de lado el supuesto del penado
con interdicción civil anexa, caso en el cual al estarya declarado como interdicto, solamente le
corresponde la designación de un curador. Con todo lo dicho, a la razón le cuesta creer que un
pródigo o dilapidador sufra de una “discapacidad” tal que requiera ser declarado interdicto y
designársele un curador, pero a un sujeto con esquizofrenia paranoide grave e irreversible se
le considere con plena capacidad y, a lo sumo, necesite solo de apoyos.”
