13. El patrimonio familiar
El patrimonio familiar, antes denominado hogar de familia o bien de familia, es la afectación
de un bien inmueble destinado a satisfacer las necesidades de vivienda de una fam ilia o de
cualquiera de los miembros de ella o la afectación de un predio dedicado a la agricultura, la
artesanía, la industria o el comercio para que el rendimiento de ese predio o lo que produzca
ese predio sirva de sustento a esa familia.
El fundamento del patrimonio fam iliar es el de servir como un mecanismo de protección de
la familia afectando al uso de ella o a su sostenimiento un inmueble o un predio que tendrá
los caracteres de ser inembargable e inalienable, se trata de poner a la fam ilia a cubierto de
las vicisitudes económicas que podrían afectarla por malos negocios y aún por la muerte de
alguno o no de ambos padres.
El bien o bienes afectados no integran, como podrían desprenderse de su denominación, que
sea un patrimonio de la familia o de los beneficiarios, pues la propiedad no se transmite, el
bien sigue siendo de propiedad individual de quien o quienes lo han adquirido que son los
constituyentes; quienes seguirán detentando la nuda propiedad, que no es otra que la propie
dad despojada de los atributos que le son propios.
Caracteres del patrimonio familiar:
Se puede enumerar como caracteres del patrimonio fam iliar a los siguientes:
a) Sólo se puede constituir patrimonio fam iliar sobre inmuebles,ya sea inmuebles, urbanos
para fines de vivienda o predios rústicos destinados al sustento de la familia, mas no se
puede afectar a estos fines a bienes muebles, equipos o enseres, por ende, a ese tipo de
bienes no se le podría conferir el carácter de inembargables o inalienables.
b) La constitución del patrimonio fam iliar sólo puede recaer sobre el dom inio pleno de un
inmueble, no puede recaersobre derechos o acciones sobre un inmueble, tampoco cuan
do la adquisición se ha efectuado bajo condición resolutoria, o cuando el inmueble se
encuentra gravado con otros derechos reales tales como hipoteca, anticresis, usufructo,
etc. es por ello que uno de los requisitos para constituirlo es que se aporte la prueba ins
trumental como lo es el certificado de gravámenes que acredite que el predio se encuen
tra realengo, libre de gravámenes.
c) Los beneficiarios del patrimonio fam iliar pueden ser los cónyuges, los hijos y otros des
cendientes menores o incapaces, los pares y otros ascendientes que se encuentran en
2 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 613 of 1506 --

Tema 3: Tem as de la especialidad de fam ilia
estado de necesidad y los hermanos menores o incapaces del constituyente; mas no la
familia en sentido abstracto, pues carece de personalidad jurídica o carácter orgánico.
Formas de constitución: En nuestro país existe un sistema dual y alternativo para la consti
tución de patrimonio familiar, pues conforme a los artículos i° y 2o de la Ley 26662, los inte
resados pueden recurrir indistintamente ante el juez de Paz Letrado o ante Notario, siendo
esencial en ambos casos la publicidad del acto como garantía de terceros.
Para la constitución del patrimonio fam iliar se requiere en uno u otro caso, según el artículo
4 9 6 ° del Código Civil lo siguiente:
1. Que el constituyente formalice su solicitud, si es ante el juez con los requisitos que una
demanda debe contener y si es ante Notario presentando una minuta; en ambos casos
el constituyente indicará sus nombresy apellidos, su edad, estado civil y domicilio, indi
vidualizará el predio que se propone afectar, aportar la prueba instrumental de no hallar
el predio sujeto a hipoteca, anticresis o embargo registrado y señalar a los beneficiarios
con precisión del vínculo que los une a ellos. En la minuta que se presente ante Notario
deberá incluirse una cláusula con la declaración expresa del o los constituyentes de no
tener deudas pendientesy adjuntará además las partidas que acrediten el vínculo con los
benefician os y certificado de gravámenes del predio según lo dispuesto por el artículo 25o
de la Ley 26662.
2. A la solicitud o demanda que se presente ante el juzgado de Paz Letrado se adjuntará la
minuta respectiva de constitución de patrimonio fam iliar a efecto de que de ser aprobada
la solicitud sea elevada a escritura pública, aspecto que nos lleva a señalar que quedará
en desuso el trám ite judicial, devendrá en trámite insulso si existe la posibilidad de acudir
directamente al Notario, con ahorro de gastos y de tiempo.
3. Para evitar que se utilice esta figura de protección para que un deudor de mala fe se libere
de eventuales obligaciones vgr. El propietario de un vehículo que causa un accidente de
tránsito y que para evadir su responsabilidad extracontractual quiera constituir patrim o
nio fam iliar sobre su vivienda, se establece como una formalidad esencial el de su publi
cidad; en la vía judicial debe publicarse extractos de la solicitud por dos días interdiarios,
mientras que en la vía notarial se publican esos avisos por una sola vez en el diario oficial
y en otro de amplia circulación del lugar donde se realiza el trámite, publicación de los
edictos que se hace para que los posibles acreedores del constituyente que pudieran ser
afectados con la inafectabilidad de dicho bien puedan oponerse a su declaración.
En el trám ite judicial la aprobación o no de la solicitud se efectuará en la audiencia respectiva,
exista o no contradicción; en la vía notarial se procederá a extender la escritura pública si es
que no media oposición alguna dentro del plazo de diez días útiles desde el día siguiente de
la publicación del últim o aviso. La escritura pública de constitución del patrimonio fam iliar
deberá ser inscrita en el Registro de la Propiedad Inmueble para conocimiento de terceros.
14. Los alimentos
Concepto: Los juicios sobre alimentos, en sus diversas modalidades de fijación, aumento, re
ducción, exoneración, extinción, prorrateo, etc. son de los procesos más comunes y numero-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 61

-- 614 of 1506 --

UBILEX
sos en los distritos judiciales de la República, siendo entre ellos los más frecuentes los casos
en los cuales quien reclama alimentos es el hijo extramatrimonial. Las causas del masivo in
cumplim iento de la obligación alimentaria son de diversa índole, tales como el deterioro de
la relación paterno filial cuando no hay convivencia entre los progenitores, la falta de entereza
y sentido de la responsabilidad de los padres, la estrechez económica del obligado, la insufi
ciencia de la madre para hacerse cargo por sí sola de la alimentación del hijo, etc. que hacen
que el incumplimiento de la obligación alimentaria sea más que un problema jurídico unos
problemas de carácter socioeconómico.
Por regla general se entiende por alimentos, lo que es indispensable para el sustento, ha
bitación, vestido, educación, instrucción y capacitación para el trabajo, asistencia médica y
psicológica y recreación, según la situación y posibilidades de la familia a favor del niño o
del adolescente. También los gastos del embarazo de la madre desde la concepción hasta
la etapa de postparto. En este sentido pueden distinguirse los alimentos naturales que son
aquellos indispensables para la subsistencia de la persona, de los alimentos civiles que son los
necesarios para que el ser humano se desenvuelva en sociedad o tenga una vida de relación.
Caracteres del derecho alimentario: El Derecho alimentario tiene caracteres especiales; en
tre ellos tenemos los siguientes:
Es intransmisible, que a su vez se deriva de su carácter personalísimo tanto desde el punto
de vista del obligado como del titu la r del derecho alimentario, pues siendo personalí
simo, destinado a garantizar la vida del titu la r de este derecho no puede ser objeto de
cesión o transferencia ni por acto inter vivos ni por causa de muerte, la prestación alimen
taria termina con la muerte del titu lar o del obligado.
Esirrenunciable, pues la renuncia de este derecho equivaldría a renunciar a la vida que este
derecho tutela, aunque cabe mencionar que la jurisprudencia ha adm itido y admite la
renuncia a la prestación alimentaria especialmente en los casos de separación convencio
nal y divorcio ulterior, en los que propiamente no se configura el estado de necesidad que
es uno de los presupuestos de hecho necesarios para que pueda hablarse de la existencia
de este derecho.
Es intransigible, no cabe transacción en materia de alimentos, pues la transacción implica
renuncia de derechos, que no es posible efectuar dado que se trata de un derecho irre-
nunciable, más procesalmente se admite la conciliación en la cual hay una fijación cuan
titativa, una aproximación de las partes en cuanto al monto de la obligación de acuerdo
al estado de necesidady las reales posibilidades económicas del obligado.
Es incompensable, es decir no se puede extinguir esta obligación por la existencia de otras
recíprocas a cargo del alimentista, pero sí está permitida la variación de la forma de pago
dado que se admite en casos especiales que dicha obligación pueda ser cumplida en es
pecie.
Es revisable, no hay sentencia definitiva ni autoridad de cosa juzgada, pues el monto de
la pensión aumenta o reduce según el aumento o la disminución que experimenten las
necesidades del alimentista y las posibilidades del que debe prestar los alimentos, para
evitar sucesivas reclamaciones, tratándose de obligados que perciben sus ingresos por
trabajo dependiente se ha establecido la posibilidad que la pensión se fije en un porcen-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

