Tema 3: Temas de la especialidad de fam ilia
taje del monto de la remuneración de modo que el aumento de la pensión sea autom áti
co con el aumento que experimenten las remuneraciones del obligado.
Es imprescriptible, ya que en tanto subsista el estado de necesidad estará expedita la po
sibilidad de que pueda ejercitarse la acción respectiva, devengando la obligación a partir
de la notificación con la demanda al obligado, no así porel periodo de tiempo precedente
porconsiderarsequesi no reclamó es porque constituye un reconocimiento implícito que
no existió estado de necesidad.
Sujetos obligados y beneficiarios del derecho alimentario: Las relaciones alimentarias que
nacen del parentesco vinculan en forma más amplia que las relaciones conyugalesy las paterno
filíales, pues no sólo corresponde a maridoy mujer o a padres e hijos, sino también a los demás
ascendientes, descendientes y hermanos. No existe obligación alimentaria entre parientes por
afinidad ni a favor de los concubinos, salvo el caso de la ruptura unilateral e injustificada. El ma
yor d e i8 años sólo tiene derecho a alimentos cuando no se encuentre en aptitud de atender a su
subsistencia por causas de incapacidad física o mental debidamente comprobadas.
Según el artículo 4 7 4 ° del Código Civil, se deben alimentos recíprocamente los cónyuges, los
ascendientes y descendientes y los hermanos. En cuanto a los obligados a prestarlos es dis
tinto el orden según el beneficiario sea mayor o menor de edad, si es mayor de edad según el
artículo 475° están obligados los cónyuges, los descendientes, los ascendientes y los herma
nos. En cambio, el artículo 93° del Código de los Niños y Adolescentes determina que deben
ser llamados en primer lugar los padres, y a falta de éstos los hermanos mayores de edad, los
abuelos, los parientes colaterales hasta el tercer grado e incluso otros responsables del niño o
del adolescente.
Cuando el matrimonio funciona normalmente, el deber de asistenciay su obligación alimenta
ria consiguiente se cumplen habitual mente en especie o en dinero sin que medie intervención
extraña, pero cuando se produce el incumplimiento de uno de los cónyuges, la ruptura de
la comunidad de vida, la separación de cuerpos o el divorcio, debe procederse a su fijación
judicial, casos en los cuales deberá tenerse en cuenta que el cónyuge que abandona la casa
conyugal sin motivo justificado y rehúsa volverá ella queda privado de este derecho.
Los hijos y demás descendientes tienen frente a sus padres y ascendientes derecho alim en
tario que siendo de carácter recíproco lo tendrán a su vez los ascendientes respecto de sus
descendientes cuando varíen las circunstancias respecto al estado de necesidad y posibilidad
económica, es decir cuando el ascendiente ha devenido en un estado de incapacidad que no
le permite subvenir a sus necesidades por sus propios medios y por el contrario los descen
dientes han llegado a adquirir capacidad económica u obtener ingresos que les permite aten
der las necesidades de sus allegados.
El derecho alimentario de los hermanos tiene su origen en el parentesco consanguíneo que los
vincula, siempre que el que pida se encuentre en estado de necesidad, en este caso al igual que en
el de los padres y descendientes, el estado de necesidad no se presume, tiene que ser acreditado.
Criterios para fija r alimentos: Los alimentos se regulan porel juez en proporción a las necesida
des de quien los pidey a las posibilidades del que debe darlos, atendiendo además a las circuns
tancias personales de ambos, especialmente a las obligaciones que se halle sujeto el deudor.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 616 of 1506 --

UBILEX
El juez considera como un aporte económico el trabajo doméstico no remunerado realizado
por alguno de los obligados para el cuidadoy desarrollo del alimentista, de acuerdo a lo seña
lado en el párrafo precedente.
Nuevas reglas de tramitación de los procesos de alimentos (Ley N° 31464)
El Código de Niños y Adolescentes (CNA) es aplicable a la pensión de alimentos de menores
de edad, a través del proceso único y el Código Procesal Civil es aplicable para pensión de
alimentos para mayores de edad, a través del proceso sumarísimo. Ambos códigos han sido
modificados por la Ley N° 31464 (Pub. 04.05.2022) con el objetivo de proteger al alimentista
de manera más célere.
1. Modificaciones en el Código de Niños y Adolescentes
Virtualidad en el proceso de alimentos.- La demanda de alimentos se presenta por escrito
a través de la Mesa de Partes física o de manera virtual empleando la Mesa de Partes Electró
nica. Alternativamente, la demanda puede ser presentada por medio de formularios físicos o
electrónicos (Art. 164-A CNA).
En este sentido, el especialista legal notifica el auto admisorio a las partes en el domicilio real
y a través de la casilla electrónica y, de ser el caso, por correo electrónico o aplicaciones de ser
vicios de mensajería instantánea para dispositivos móviles. (Art. i 67-A, últim o párrafo, CNA).
Celeridad en el proceso.- Esta ley busca que el alimentista obtenga una pensión a través de
una sentencia firme en el menor tiempo posible. Por consiguiente, algunos cambios impor
tantes encaminados a este fin son los siguientes:
Ante una omisión o un defecto subsanable al momento de presentar la demanda, la mis
ma se admite a trám ite y la parte demandante tienen plazo para subsanarla hasta la fe
cha de la realización de la audiencia única. (Art. 164-A CNA)
En el mismo acto de la audiencia se emite sentencia, así ambas partes no hayan asistido
y existan medios probatorios suficientes para resolver. Antes, se suspendía y se reprogra
maba en una nueva fecha. Solo si no se cuentan con los medios probatorios, el juez puede
reprogramar la audiencia por única vez. (Art. 170-A CNA)
Tanto en primera como en segunda instancia se expide sentencia, de manera oral, ya sea
durante la audiencia única o la vista de la causa. En primera instancia, las partes dan su
conformidad o interponen su recurso de apelación de forma oral dentro de la misma au
diencia. (Arts.i73-Ay 178-ACNA)
Rol activo del Juez.- En el auto admisorio el juez establecerá una medida cautelar de asig
nación anticipada de alimentos a favor del niño, niña o adolescente alimentista. Si bien el
artículo 675 del Código Procesal Civil ya establecía que, en casos de hijos menores de edad con
indubitable relación familiar, el juez deberá otorgar esta medida, muchas veces los jueces no
la hacían de oficio, sino solo a instancia de parte.
Así en el artículo 167-A del CNA se dispone que el auto admisorio para la demanda de alimen
tos debe contener:
