"Artículo 556.- Apelación
La resolución citada en el último párrafo del artículo 551, la que declara fundada una excepción o defensa
previa y la sentencia son apelables con efecto suspensivo, dentro del tercer día de notificadas. Se exceptúa de
esta regla a la sentencia en el proceso de alimentos, la cual es apelable sin efecto suspensivo.
Las demás resoluciones son solo apelables durante la audiencia, sin efecto suspensivo y con la calidad de
diferidas, siendo de aplicación ei artículo 359 en lo que respecta a su trámite."
Rol activo del Juez.- Con la aplicación de la Ley N° 31464, el juez asumió un rol más activo en
los procesos de alimentos ya que no solo podía solicitar de oficio informes al centro de labo
res del obligado sobre su remuneración, gratificaciones, vacaciones y cualquier suma de libre
disponibilidad que provenga de la relación laboral de este, sino también podía requerir docu
mentación de la parte demandada a entidades públicas para conocer mejor las posibilidades
económicas del deudor alimentario.
A través del artículo 564 del C.PC. se incorporó la facultad al juez de poder solicitar las declara
ciones juradas de renta anual de la parte demandada a la SUNAT, copia literal de las partidas
regístrales de los bienes muebles e inmuebles activos e inactivos del demandado a la SUNARP
y verificar la existencia de otros hijos menores de edad del demandado en RENIEC.
El artículo 564 del C.RC nuevamente a sido objeto de modificación a través de la Ley N° 32006
(Pub. 24.04.2024), esta vez se otorga al juez la facultad, de oficio, de acceder en línea a los siste
mas de información automatizados (planilla electrónica) del MINTRA o a los sistemas de infor
mación automatizados de la SUNAT y extraer en tiempo real la información sobre el centro de
trabajo del demandado, su remuneración y demás beneficios laborales proveniente de la rela
ción laboral de éste y, de ser el caso, obtener información sobre la actividad comercial o profesio
nal independiente y sobre la renta mensual que perciba por estas actividades, así como las de
claraciones juradas de renta anual que hubiera realizado. Asimismo, accede en línea al sistema
automatizado de la Superintendencia de Banca, Seguros y Administradoras Privadas de Fondos
de Pensiones y extrae en tiempo real la información bancada y financiera del demandado. La
resolución que ordena el acceso, de oficio, a la información sobre la situación laboral y capacidad
económica del demandado debe estar debidamente motivaday es inimpugnable.
El juez procede de la misma forma que ingreso a las instituciones públicas mencionadas con
anterioridad para obtener información de la SUNARP sobre los bienes muebles e inmuebles
activos e inactivos del demandado y del RENIEC sobre el número total de hijos menores de
edad que tuviera del obligado al pago de los alimentos.
