15. Ley para prevenir, sancionar y erradicar la violencia contra las mujeres y los inte
grantes del grupo fam iliar. Alcances. Tipos de violencia, medidas de protección
Alcances: La violencia de género representa una de las brechas sociales con mayor data en la
historia de la humanidad. Debemos reconocer que el discurso patriarcal dominante naturali
zó a la mujer para que se subordine al yugo del varón. Solo basta con remitirnos a la filosofía
griega para comprender que dentro de los planteamientos de Aristóteles la mujer debe estar
sujeta a la voluntad del varón, ya que tal hecho encuentra su contrapartida en el orden impe
rante de la naturaleza. En la actualidad, tal planteamiento ha quedado relegado, sin embargo,
aún subsiste un saldo cultural que se resiste al cambio. Así, la ONU Mujeres indica que el 35%
de mujeres en el mundo han sufrido violencia física y/o sexual por parte de su pareja senti
mental. En nuestro país, el Observatorio nacional de violencia contra la m ujery los integrantes
del grupo fam iliar indica que el 70,08% de mujeres entre los 15/49 años, ha sufrido violencia
por parte de su pareja y no buscaron ayuda. Esto revela que los índices de violencia en contra
de la mujersiguen en aumento, duplicando las cifras registradas oficialmente por laONU Mu
jeres, es decir, el Perú es un país con varones violentosy mujeres naturalizadas con la violencia.
Sobre la base de lo anteriormente indicado, se ha dedicado denodados esfuerzos por redu
cir los índices de violencia en contra de la mujer, así tenemos la Convención Interamericana
para prevenir, sancionar y erradicar la violencia contra la mujer del 09 de junio de 1994, más
conocida como la Convención Belém do Pará, que eventualmente trajo repercusiones en ám
bito de la política-criminal de cada país. En el caso peruano el Estado dictó e implemento una
serie de medidas destinadas a prevenir, sancionar y erradicar la violencia contra las mujeres
y el grupo familiar, una de las más relevantes es la Ley N° 30364, Ley para prevenir, sancionar
y erradicar la violencia contra las mujeres y los integrantes del grupo familiar, publicada en
el Diario Oficial El Peruano el 23 de noviembre de 2015;, posteriormente, se aprueba el Texto
Único Ordenado de la Ley N° 30364- D.S. N° 004-2020-MIMP con fecha de publicación en el
Diario Oficial El Peruano 06 de setiembre de 2020. En el plano jurisprudencial, se emitieron
el Acuerdo Plenario número ooi-20i6/CJ-n6, referido sobre los alcances típicos del delito de
feminicidio; el Acuerdo Plenario número 005-2016/CJ-116 , respecto de los delitos de violencia
contra las mujeresy los integrantes del grupo familiar,y el Acuerdo Plenario número 09-2019/
CIJ-116, que trata sobre la violencia contra las mujeres e integrantes del grupo, principio de
oportunidad, acuerdo reparatorio y problemática de su punición.
Así las cosas, surge la pregunta ¿s/ la Ley N° 30364 fue promulgada en noviembre de 2015, porque
motivo se publica un texto único ordenado de la misma con fecha setiembre de 2020 (casi 5 años des
pués)? Al respecto debe precisarse que la norma en comento -T.U.0 de la Ley 30364, - en reali
dad no representa novedad, sino que busca compendiar en un solo apartado legal las m ú lti
ples modificaciones efectuadas a la Ley N° 30364 desde su publicación.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 620 of 1506 --

UBILEX
Solo a manera de comentario es posible mencionar las siguientes normas: i) Ley N° 308621, ii)
Decreto Legislativo N° 13232, iii) Decreto Legislativo N° 13863, iv) Ley 31439, v) Ley N° 31715 y vi)
Decreto Legislativo N ° i55i, dictadas para modificaren fechas distintas y apartados diferentes
la Ley N° 30364.
Entonces, lo que hace este D.S. N° 004--2020--MIMP es agrupar, compendiar o unificar la Ley
N° 30364 con todas sus modificaciones, teniendo como resultado un texto único ordenado
al que puede recurrirse sin temor a invocar artículos modificados y/o derogados. Allí radica
la importancia de esta norma como fuente confiable, útil y practica para su análisis y sobre
todo correcta aplicación por parte de los operadores de justicia. Dicho Texto único Ordenado
publicado el 06 de septiembre de 2020 consta de cuatro (4) títulos, siete (7) capítulos, sesen
ta y dos (62) artículos, seis (6) Disposiciones Complementarias Finales, seis (6) Disposiciones
Complementarias Transitorias, cuatro (4) Disposiciones Complementarias Modificatorias; y,
dos (2) Disposiciones Complementarias Derogatorias.
Finalmente, una de las modificaciones de la Ley 30364, es la mencionada 30862, que estable
ció como única disposición complementaria final referida a la adecuación del reglamento de
la Ley 30364. Por lo que es necesario interpretary aplicar el T.U.O. de la Ley 30364 de acuerdo a
su reglamento, cuya últim a modificación (a la fecha) es realizada por el Decreto supremo N°
009-2023-MIMP, de fecha 07 de setiembre de 2023.
Definición de violencia contra las mujeres: La violencia contra las mujeres es cualquier ac
ción o conducta que les causa muerte, daño o sufrim iento físico, sexual o psicológico por su
condición de tales, tanto en el ámbito público como en el privado.
Se entiende por violencia contra las mujeres: a. La que tenga lugar dentro de la fam ilia o uni
dad doméstica o en cualquier otra relación interpersonal, ya sea que el agresor comparta o
haya compartido el mismo domicilio que la mujer. Comprende, entre otros, violación, maltra
to físico o psicológico y abuso sexual, b. La que tenga lugar en la comunidad, sea perpetrada
por cualquier personay comprende, entre otros, violación, abuso sexual, tortura, trata de per
sonas, prostitución forzada, secuestro y acoso sexual en el lugar de trabajo, así como en insti
tuciones educativas, establecimientos de salud o cualquier otro lugar, c. La que sea perpetrada
o tolerada por los agentes del Estado, donde quiera que ocurra.
Definición de violencia contra los integrantes del grupo familiar: La violencia contra cual
quier integrante del grupo familiares cualquier acción o conducta que le causa muerte, daño
o sufrimiento físico, sexual o psicológico y que se produce en el contexto de una relación de
responsabilidad, confianza o poder, de parte de un integrante a otro del grupo familiar.
Se tiene especial consideración con las niñas, niños, adolescentes, adultos mayores y personas
con discapacidad.
Sujetos de protección de la Ley:
a. Las mujeres durante todo su ciclo de vida: niña, adolescente, joven, adultay adulta mayor.
b. Los miembros del grupo familiar. Entiéndase como tales, a los cónyuges, excónyuges,
convivientes, exconvivientes; padrastros, madrastras; o quienes tengan hijas o hijos en
común; lasy los ascendientes o descendientes por consanguinidad, adopción o por afini
dad; parientes colaterales hasta el cuarto grado de consanguinidad o adopcióny segundo
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 621 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
grado de afinidad; y quienes habiten en el mismo hogar siempre que no medien relacio
nes contractuales o laborales, al momento de producirse la violencia.
Contexto de Violencia Familiar: Para delimitar el “contexto de violencia” como bien lo estable
ce el Acuerdo Plenario N °i-20i6/CJ-ii6 se debe recurrir a la definición legal. El contexto en la
“violencia contra la mujer o de género” debe ser entendido como una manifestación de discri
minación que inhibe gravemente la capacidad de las mujeres de gozar de derechos y libertadas
en pie de igualdad, a través de relaciones de dominio, de control, de ejercicio de poder, de sometimiento
y subordinación hacia las mujeres. En tanto, en la “violencia doméstica” o hacia un o una integrante
del grupo familiar se entiende a cualquier acción o conducta que le causa muerte, daño o sufri
miento físico, sexual o psicológicoy que se produce en el contexto de una relación de responsabi
lidad, confianza o poder, de parte de un integrante a otro del grupo familiar.1213
¿Qué es el enfoque de género?
La Primera Sala Civil de la Corte Superior de la Libertad señala al respecto:
"4.3. Es en esa lógica de defensa y protección de los derechos de la mujer, que se exige al siste-
: 1f ma de administración de justicia garantizar el derecho fundamental a una vida libre de violencia
. . í U j i y a la igualdad, en tanto deben actuar con la debida diligencia y de manera inmediata, a efectos
de prevenir, sancionar y erradicar y sancionar la violencia contra la mujer. Es por dicha exigencia
constitucional y convencional, que toda decisión judicial que asuma el/ la juez/a en un caso
m il i u iH concreto - y en su condición de "garante de derechos"- debe tener en cuenta, el contexto de :
desigualdad y desventaja táctica existente entre hombres y mujeres (ya sea social o personal),
así como el grado de vulnerabilidad en la que se encuentra la mujer, así como el contexto donde se desarrolla
la violencia en sí, en tanto ello dificulta el ejercicio pleno de su derecho de acceso a la justicia; y es a partir de
dicho análisis que el órgano jurisdiccional está obligado a romper dichas barreras de género para brindarle una
tutela judicial real. Surge así, el enfoque de género como una técnica convencional y constitucional de carácter obliga
torio que debe tenerse en cuenta al momento de abordar un caso que involucre a la mujer y el ejercicio de sus derechos
fundamentales [sea en el ámbito civil, familiar, laboral, comercial, penal, etcj, ya sea al momento de interpretar o aplicar
las normasjurídicas como al resolver el caso mismo, en la medida que a través de su aplicación se resguarde su
derecho a la igualdad, 4.4. Este colegiado ha tenido la oportunidad de definir en un anterior pronunciamiento
(resolución número tres de fecha 23 de marzo del 2021, en el Exp. 07839- 2020- 35-1601 -J R -F T -09) el con
cepto de enfoque de género en el ámbito jurisdiccional, indicando lo siguiente: "El enfoque de género es una
herramienta metodológica que deben tener los/las jueces/juezas al momento de abordar un caso concreto, y
exige qué todo análisis de los hechos, debe partir de la existencia de la desigualdad material y debilidad en la :
que se encuentra la m ujer en el escenario personal y social (asimetría), en relación a los hombres e incluso de :
la propia sociedad y el Estado m ism o (discriminación estructural), situación que limita ejercer plenamente sus
derechos fundamentales, incluso el de acceso a la justicia"A
Tipos de violencia.- Siguiendo a lo establecido en el artículo 8 o del Decreto Supremo N° 004-
2020-MIMP-TUO de Ley 30364, los tipos de violencia contra las mujeres y los integrantes del
grupo familiarson:
a) Violencia física. Es la acción o conducta, que causa daño a la integridad corporal o a la
salud. Se incluye el maltrato por negligencia, descuido o por privación de las necesidades
básicas, que hayan ocasionado daño físico o que puedan llegar a ocasionarlo, sin importar
el tiempo que se requiera para su recuperación.
