13 Exp. N° 09623-2019-60-1601-1R-FC-01. Primera Sala C iv il-L a libertad.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 622 of 1506 --

UBILEX
■ ■'' 1 ''
*
"Tratándose de un caso de violencia fam iliar en la modalidad de maltrato físico, el certificado
médico legal emitido por el Instituto Médico Legal, por s í solo, resulta insuficiente para demos
trar que efectivamente se ha incurrido en dicha modalidad de violencia. En efecto, un certificado
médico legal puede corroborar la existencia, por ejemplo, de una lesión física, pero además de
acreditarse dicha lesión, es necesario determinar quién la ocasionó; de ahí la relevancia de esta- .
blecersi las lesiones que presenta la presunta agraviada, fueron resultado délas patadas que le
habría propinado su hermano, el demandado". Cas. W° 3145-2017-Lima Norte,
b) Violencia psicológica. Es la acción u omisión, tendiente a controlar o aislar a la persona
contra su voluntad, a humillarla, avergonzarla, Insultarla, estigmatizarla o estereotiparla,
sin importar el tiempo que se requiera para su recuperación.
"La violencia familiar en la modalidad de maltrato psicológico debe ser acreditado con el dicho de la
presunta víctima y el informe psicológico practicado." Cas. N° 2215-2017-Del Santa.
c) Violencia sexual. Son acciones de naturaleza sexual que se cometen contra una persona
sin su consentimiento o bajo coacción. Incluyen actos que no involucran penetración o
contacto físico alguno. Asimismo, se consideran tales la exposición a material pornográfi
co y que vulneran el derecho de las personas a decidir voluntariamente acerca de su vida
sexual o reproductiva, a través de amenazas, coerción, uso de la fuerza o Intimidación.
d) Violencia económica o patrimonial. Es la acción u omisión que ocasiona un menoscabo
en los recursos económicos o patrimoniales de las mujeres por su condición de tales o
contra cualquier integrante del grupo familiar, en el marco de relaciones de poder, res
ponsabilidad o confianza, por ejemplo, a través de (Art. 8 del TUO la Ley):
1. La perturbación de la posesión, tenencia o propiedad de sus bienes.
2 . La pérdida, sustracción, destrucción, retención o apropiación indebida de objetos,
instrumentos de trabajo, documentos personales, bienes, valores y derechos patri
moniales.
3. La limitación de los recursos económicos destinados a satisfacer sus necesidades o
privación de los medios indispensables para vivir una vida digna; así como la evasión
del cumplimiento de sus obligaciones alimentarias.
4 . La limitación o control de sus ingresos, así como la percepción de un salario menor
por igual tarea, dentro de un mismo lugar de trabajo.
En los casos en que las mujeres víctimas de violencia tengan hijos/asy estos/as vivan con ellas,
la limitación de los recursos destinados a satisfacer sus necesidades o privación de los medios
indispensables para vivir una vida digna, así como la evasión de sus obligaciones alimentarias
por parte de la pareja, se considerará como una forma de violencia económica o patrimonial
contra la m ujery los/las hijos/as.
Resumiendo todo lo avanzado es que definimos a la violencia económicay patrimonial como
toda conducta activa u omisiva realizada por el presunto agresor, el cual se encuentra orien
tada a afectar derechos patrimoniales y económicos de la m ujery que a su vez repercuten de
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 623 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
manera negativa en su plan de vida, e impidiéndole el pleno goce y ejercicio de los derechos
reconocidosen la Constitución y tratados internacionales. La violencia patrimonial escomo lo
afirma Cintia Gramari y Norberto Codoy, el uso del poder económico del agresor para provo
car un daño a la mujer14.
Del propio artículo 8o del TUO de la Ley 30364 y de la definición de este tipo de violencia, se
advierte la existencia de dos elementos que convergen indeseablem ente y que le dotan de
contenido a la violencia económicay patrimonial, pero deben darse ambas en forma conjunta
y al mismo tiempo. Estos elementos son dos:
Elemento objetivo: es la conducta objetiva (acción u omisión) ejercida por el presunto agre
sor que ocasiona el menoscabo de los recursos económicos o patrimoniales de las mujeres
(transformación, sustracción, destrucción, pérdida, limitación, retención de objetos, docu
mentos personales, bienes, valoresy derechos patrimoniales) y/o afectación de la superviven
cia misma de la m ujery sus hijos.
Elemento s u b je tiv o .- Es la intencionalidad que tiene el agresor de pretender menoscabar,
coaccionar, manipular o hacer daño a la mujer, por su condición de tal. Este constituye un ele
mento importante tal como lo describe Diego Valdir Roca Saucedo, al señalar que el “El hecho
en sí [violencia patrimonial], se presenta cuando, sin razón y con toda la intención de afectar
o mantener el control sobre la víctima, afectando su equilibrio económico” y emocional (el
énfasis es nuestro)15.
Entre las diversas expresiones de la violencia patrimonial contra la mujer, tenemos el supues
to de evasión dolosa por parte del agresor del cumplimiento de las obligaciones alimentarias
que tiene para con la mujer y/o sus hijos. Este supuesto se da cuando el obligado (esposo o
conviviente o cualquier otro) le niega intencionalmente a la mujer (esposa, conviviente, hija,
hermana, etc.) el dinero suficiente para que satisfaga ellay/o hijos sus necesidades elementa
les, como son la alimentación, vivienda, vestimenta, acceso a la salud, entre otros, dándose en
una relación de desigualdad de podery de detrimento de la dignidad de la mujer16.
A continuación, diagramaremos un esquemaque recoja totalmente lodesarrolladoyque pro
yecte los elementos que deben darse para que se configure la violencia patrimonial contra la
mujer en la modalidad de evasión de obligación alimentaria17-.
