Medidas de protección: En el artículo 32 del TUO de la Ley N° 30364 se consigna que.- “El objeto
de las medidas de protección es neutralizar 0 minimizar los efectos nocivos de la violencia
ejercida por la persona denunciada, y perm itir a la víctima el normal desarrollo de sus activi
dades cotidianas, con la finalidad de asegurar su Integridad física, psicológica y sexual, o la de
su fam ilia,y resguardar sus bienes patrimoniales”.
Su dictado en las formas establecidas en el citado artículo o en otras que resulten necesarias
para la protección de la vida e integridad de la víctima 0 de sus familiares, está condicionado
a aspectos tales como el riesgo de la víctima, la urgencia y necesidad de la protección y el
peligro en la demora.
Entre sus efectos de garantía se tienen las siguientes: a) su duración se mantiene mientras per
sistan las condiciones de riesgo de la víctima, con presdndencia de la resolución que pone fin
a la investigación y al proceso penal 0 de faltas,y b) la posibilidad de ser sustituidas, ampliadas
y cesadas por el Juzgado de Familia, cuando se advierta variación de la situación de riesgo de la
víctima, a solicitud de esta, cuando toma conocimiento de la sentencia firm e o disposición de
archivo de la investigación, proceso penal o de faltas que originaron las medidas de protección
(conforme al artículo 30 del T. U. O. de la Ley N° 30364).
Existen pronunciamientos del órgano jurisdiccional que señalan que las medidas de protec
ción no solo buscan el cese de la violencia, sino también deben velar por una recomposición
del conflicto entre los miembros del grupo familiar, cuando este sea posible; es decir, se reco
noce que estas medidas de alejamiento y retiro del agresor deben estar acorde a las circuns
tancias, cuando no existe posibilidad de remedio alguno, además que el riesgo para la victima
