Tema 3: Temas de la especialidad de fam ilia
debe ser severo o elevado. Así tenemos: En el marco de la Ley 3 0 3 6 4 , Ley para prevenir, sancio
nar y erradicar la violencia contra las mujeres y los integrantes del grupo familiar, el Juez de
Familia o el que haga sus veces, “debe” dictar medidas de protección y/o medidas cautelares
que aborden de manera integral el problema de violencia fam iliary/o contra la mujer expues
to en el caso concreto, el cual debe buscar no sólo el cese de la violenciay preservar así la vida,
la integridad psicofísica, la dignidad, la libertad de las personas, víctimas de violencia, sino
también debe buscar la recomposición del grupo fam iliar de acuerdo con la características de
cada familia. En este últim o caso, el Juez de Familia, ante la presencia de circunstancias que
imposibiliten la búsqueda de la recomposición del vínculo familiar, podría disponer, de ma
nera excepcional, el alejamiento entre el agresory víctima y, porende, no dictar medidas que
conlleven a la recomposición de las relaciones afectivas entre ambos, para ello está obligado a
motivar la aplicación de dicha excepción”. Exp. N °09448-2017-70-1601 -JR-FC-02. Tercera Sala
Civil. La Libertad.
Entre las medidas de protección que pueden dictarse en los procesos por actos de violencia
contra las mujeres y los integrantes del grupo fam iliar se encuentran las siguientes (Art. 33
TUO Ley 30364):
4 .
f f
7 .
1i
II
1 . Retiro del agresor del domicilio en el que se encuentre la víctima, así como la prohibición del regresar
I al mismo en caso de riesgo severo acreditado, reincidencia, violencia física, independientemente de en
quien recaiga la titularidad del inmueble donde se ejecuta las medidas de protección. La Policía Nacio
nal del Perú puede ingresar a dicho domicilio para su ejecución.
En el supuesto de riesgo moderado acreditado, si el bien inmueble pertenece a la sociedad conyugal, el
agresor será conminado a abandonar el bien inmueble, caso contrario, será retirado por la Policía Nacio
nal del Perú.
En los casos leves se evalúa la propiedad del bien inmueble.
Impedimento de acercamiento o proximidad a la víctima en cualquier forma, a su domicilio, centro de
trabajo, centro de estudios, lugar de esparcimiento, u otros donde aquella realíce sus actividades co
tidianas de habitual concurrencia, a una distancia idónea, determinada por la autoridad judicial, para
garantizar su seguridad e integridad. ’ ''
Prohibición de comunicación con la víctima vía epistolar, telefónica, electrónica; asimismo, vía chat, re
des sociales, red institucional, intranet u otras redes o formas de comunicación.
Prohibición del derecho de tenencia y porte de armas para el agresor, debiéndose notificar a la Superin
tendencia Nacional de Control de Servicios de Seguridad, Armas, Municiones y Explosivos de Uso Civil.
para que proceda a dejar sin efecto la licencia de posesión y uso, y para que se incauten las armas que;
están en posesión de personas respecto de las cuales se haya dictado la medida de protección. En el
caso de integrantes de las Fuerzas Armadas y Policía Nacional del Perú en situación de actividad que
emplean armas de propiedad del Estado en el ejercicio de sus funciones, el juzgado oficia a la institución
armada o policial para los fines de este numeral.
Inventario de bienes.
Asignación económica de emergencia que comprende lo indispensable para atender las necesidades
básicas de la víctima y sus dependientes. La asignación debe ser suficiente e idónea para evitar que se :
mantenga o coloque a la víctima en una situación de riesgo frente a su agresor e ingrese nuevamente a
un ciclo de violencia. El pago de esta asignación se realiza a través de depósito judicial o agencia banca-,
ría para evitar la exposición de la víctima.
Prohibición al presunto agresor de disponer, enajenar, destruir, trasladar, ocultar u otorgar en prenda o!
hipoteca los bienes muebles o-inmuebles comunes de la sociedad conyugal o de la pareja conviviente. ''
Prohibición a la persona denunciada de retirar del cuidado del grupo familiar a los niños, niñas, adoles-:
ceníes u otras personas en situación de vulnerabilidad.
Tratamiento reeducativo o terapéutico para la persona agresora.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 626 of 1506 --

UBILEX
10.
S í:
Tratamiento psicológico para la recuperación emocional de la víctima.
Albergue de la víctima en un establecimiento en el que se garantice su seguridad, previa coordinación
con la institución a cargo de este.
Cualquier otra medida de protección requerida para la protección de la integridad y la vida de la víctima
o sus familiares.
-Diferencia con las medidas cautelares.- Nuestra legislación ha efectuado una diferenciación
entre las medidas de protección y cautelares; tanto es así, que se permite dictar en forma in
tegral a las medidas de protección otras de carácter cautelar. Así lo ha reconocido el Tribunal
Constitucional18 al señalar que “las medidas de protección presentan características o elemen
tos que también son propios de las medidas cautelares, como la temporalidad, variabiIidad y
la urgencia; sin embargo, ello no supone necesariamente que ambas tengan la misma natu
raleza” En este sentido, las medidas de protección, a diferencia de la medida cautelar, no busca
asegurar el cumplimiento efectivo de un fallo definitivo, sino “es detener la violencia ejercida
contra la víctima o prevenir que esta se vuelva a suscitar,”19 ello en razón de evitar que la violen
cia se perpetúe con mayor Intensidad y gravedad.
