Es así que el artículo 32 del TUO de la Ley N.° 30364 establece que el objeto de las medidas de
protección es “neutralizar o m inimizar los efectos nocivos de la violencia ejercida por la perso
na denunciada, y perm itirá la víctima el normal desarrollo de sus actividades cotidianas con la
finalidad de asegurar su integridad física, psicológica y sexual, o la de su familia, y resguardar
sus bienes patrimoniales.” Es decir, una medida de protección debe prevenlrel surgimiento del
ciclo de la violencia y frenar su escalamiento20.
Criterios para dictar medidas de protección: El juzgado de fam ilia dicta las medidas de pro
tección teniendo en cuenta lo siguiente:
a. Los resultados de la ficha de valoración de riesgo y los informes sociales emitidos por en
tidades públicas competentes.
