Mujery el Grupo Familiar. Ubi Lex Asesores SAC. pp. 313 y 314.
26 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 627 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
b. La existencia de antecedentes policiales o sentencias en contra de la persona denunciada
por actos de violencia contra la mujer e integrantes del grupo familiar, por delitos contra
la vida, el cuerpo y la salud; la libertad sexual, el patrimonio y otros que denoten su peli
grosidad.
c. La relación entre la víctima con la persona denunciada.
d. La diferencia de edades y la relación de dependencia entre la víctim ay la persona denun
ciada.
e. La condición de discapacidad de la vícti ma.
f. La situación económicay social de la víctima.
g. La gravedad del hechoy la posibilidad de una nueva agresión.
h. Otros aspectos que denoten el estado de vulnerabilidad de la víctima o peligrosidad de la
persona denunciada.
El juzgado de fam ilia puede hacer extensivas las medidas de protección a las personas depen
dientes o en situación de vulnerabilidad a cargo de la víctima. Asimismo, en casos de feminici-
dio o tentativa de feminicidio, toma en cuenta a las víctimas indirectas del delito.
Los criterios señalados en los párrafos anteriores también son aplicables para la emisión de las
medidas cautelares.
-Presupuestos materiales de las medidas de protección y cautelares21.- El segundo párrafo
del artículo 32 del TUO de la Ley N.° 30364 establece cuáles son los recaudos que deben satis
facer para ordenar una medida de protección, por lo que considera que para dictar una medi
da de protección se debe tener en cuenta el riesgo de la víctima, la urgenciay necesidad de la
protección y el peligro en la demora. De igual forma, el Tribunal Constitucional reafirma que
para el dictado de las medidas de protección, el Juzgado de Fami lia tomará en cuenta el riesgo
al cual se encuentra sometida la vida de la víctima de violencia, la necesidad de protección, así
como la urgenciay el peligro en la demora22; por lo que resulta importante desarrollar estos
cuatro presupuestos materiales para dictar una medida de protección:
