BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 628 of 1506 --

UBILEX
a) El riesgo de la víctima: Es la identificación de factores de riesgo y de protección en la perso-
na evaluada que generan una probabilidad de la comisión de un hecho violento que permita
dictar una medida de protección idónea.
Nuestra legislación ha considerado tres niveles de riesgo que deben ser identificados por la
ficha de valoración de riesgo, pero sobre todo por la judicatura en la valoración en conjunta de
todos los elementos para la identificación del riesgo. A modo de referencia, podemos conside
rarlo de la siguiente manera23:
Riesgo severo: cuando se determina que existe una alta probabilidad de recurrencia del
hecho, el impacto podría ser alto, existen escasos factores protectores y el tiempo de ocu
rrencia del hecho es corto.
Riesgo moderado: cuando se determina que existe una baja probabilidad de recurrencia
del hecho, el impacto podría ser alto, se identifican algunos factores protectores y el tiem
po de ocurrencia del hecho es de mediano a largo plazo.
Riesgo leve: cuando se determina que existe una baja probabilidad de recurrencia del
hecho, bajo impacto del hecho, existen factores protectores y el tiempo de ocurrencia del
hecho es largo. En este nivel la persona afectada puede anticipar la reacción violenta, tie
ne un alto nivel de conciencia de la situación y cuenta con fuertes redes de apoyo fam iliar
y/o social.
b) La urgencia de la protección: Para determinar que un caso requiere una tutela urgente, es
crucial considerar que los factores de riesgo identificados hacen imposible esperar para tomar
una decisión judicial. De no adoptarse medidas de protección de manera inmediata, existe el
riesgo de que la conducta violenta persista o incluso se intensifique.
c) La necesidad de la protección: Este presupuesto se sustenta en el derecho fundamental de
toda persona a vivir libre de violencia, consagrado en diversos instrumentos legales y tratados
internacionales de derechos humanos. Es un elemento fundamental que refleja el compro
miso de la sociedady del Estado de salvaguardar la integridad física, emocional y psicológica
23 Adaptado del Protocolo de Atención del Centro de Emergencia Mujer, aprobado por Resolución Ministerial
N.° 100- 2021-MIMR
8 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 629 of 1506 --

Tema 3: Temas de la especialidad de fam ilia
de cada individuo, sin importar su género, edad, orientación sexual, origen étnico o cualquier
otra característica.
En el contexto específico de la violencia de género o familiar, esta necesidad de protección
adquiere una urgencia aún mayor. Las víctimas de este tipo de violencia se encuentran en una
situación de extrema vulnerabilidad y peligro.
d) El peligro en la demora: El peligro que conlleva la demora constituye una alerta funda
mental acerca de los riesgos adicionales que pueden surgir si no se actúa de manera rápida y
efectiva ante situaciones de violencia. La falta de prontitud en la implementación de medidas
de protección puede acarrear consecuencias devastadoras, ya que prolonga la exposición de
la víctima a niveles cada vez más elevados de peligro y vulnerabilidad. En esta situación, cada
momento de inactividad incrementa la posibilidad de que la violencia se agrave, poniendo en
riesgo la integridad física, emocional y psicológica de la víctima.
Ejecución de las Medidas de Protección.- La entidad que se encarga de la ejecución de las
medidas de protección es la Policía Nacional del Perú, siempre que la medida de protec
ción éste dentro del ámbito de sus competencias, pero si la resolución final ha ordenado
que otras entidades públicas ejecuten algunas medidas de protección porque están den
tro de sus competencias, estas también serán consideradas como órgano ejecutor de la
resolución judicial.
La Policía Nacional del Perú u otras entidades encargadas de ejecutar la medida de pro
tección remiten al juzgado de familia un informe sobre la ejecución de la medida, que
debe contener información si la persona denunciada está cumpliendo con la medida de
protección y cautelares; así como de la situación de riesgo de la víctima, con las recomen
daciones que consideren pertinentes. En caso de incumplimiento, la judicatura comunica
al titu lar de la entidad respectiva, a fin de que inicie una investigación disciplinaria y se
determinen las responsabilidades que correspondan24.
16. Convención sobre los derechos del niño
La doctrina de la protección integral, sirve de sustento al instrumento internacional más im
portante en materia de derechos humanos relativos a la niñez: La Convención Internacional de
los Derechos del Niño, adoptada en el seno de la Organización de las Naciones Unidas (ONU),
el 20 de noviembre de 1989, diez años después que se conformó el Grupo de Trabajo Abierto
que redactó el proyecto.
En atención a la protección primordial y superior de la infancia, los consagrados por la con
vención son "derechos específicos” con el fin de reforzar los derechos otorgados a los seres hu
manos en general, cuando se trata de aplicarlos a niños y adolescentes, adecuándolos a su
proceso de desarrollo. En otras palabras, se reconoce no menos derechos de los establecidos
para los seres humanos en general, pero reforzados, dada la especial protección de sus desti
natarios.
