afectará a las disposiciones que sean más conducentes a la realización de los derechos del niño y que
puedan estar recogidas en el derecho interno de un Estado parte, o el derecho internacional vigente en
dicho Estado.
Destacan entre sus normas, la consagración de derechos que anteriormente lo estuvieron ex
clusivamente para los mayores de edad: como la libertad de opinión, el derecho a trabajar,
la libertad de religión, libertad de asociación, derecho a vivir en un ambiente sano y en un
ambiente ecológicamente equilibrado, entre otros. Asimismo, el cambio de paradigma en el
tratamiento del adolescente infractor de la ley penal, de uno eminentemente protector a otro
básicamente sancionador.
A la fecha, existen tres sentencias y una opinión consultiva de la Corte Interamericana de De
rechos Humanos relativas explícitamente a derechos de los niños. Las sentencias abordan
importantes aspectos de la relación entre Convención sobre Derechos del Niño y el Sistema
Interamericano, a propósito de prácticas lamentablemente sistemáticas de vulneración del
derecho a la vida. La Opinión Consultiva 17, de zooz, emana de una petición hecha a la Corte
por la Comisión Interamericana de Derechos Humanos, y se titu la precisamente “Condición
jurídicay derechos humanos de los niños”. Explicaremos brevemente estos cuatro pronuncia
mientos del sistema interamericano en relación a la infancia, siguiendo un orden cronológico:
1 6.1 .El caso Villagrán Morales, también conocido como caso “niños de la calle".
Sentencia de 19 de noviembre de 1999, contra el Estado de Guatemala
Los hechos que dieron origen a esta sentencia acontecieron en 1990, cuando 4 personas
(entre ellos dos menores de 18 años de edad) fueron secuestradas y asesinadas, y otra per
sona (m e no rd e i8 ) fue asesinadaen la cal le, en circunstancias similares que apuntaban a la
actuación de escuadrones de la muerte en contra de “niños de la calle”. Tras lo que se estimó
como denegación de justicia por el Estado de Guatemala, se interpuso por parte de Casa
Alianza y el Centro por la Justicia y el Derecho Internacional (CEJIL) una denuncia formal
ante la Comisión Interamericana, e h 5 de septiembre de 1 9 9 4 - Tras el procedimiento ante la
Comisión, esta estimó mediante el informe N° 33/96, de 16 de octubre de 1996, que "el Esta
do de Guatemala violó los derechos humanos del niño y los derechos a la vida, la integridad
personal, la libertad personal y a un proceso justo y a la protección judicial consagrados en
los artículos 4, 5 , 7 , 1 9 , 8 y Z5 de la Convención Americana e incumplió con sus obligacio
nes prescritas en el artículo 1”. Además, se estableció que el Estado de Guatemala “violó los
artículos 1, z y 6 de la Convención Interamericana para Prevenir y Sancionar la Tortura”. El
Informe fue trasm itido al Estado de Guatemala, al que se le dieron dos meses para aplicar
las recomendaciones de la Comisión.
