Tema 3: Temas de la especialidad de fam ilia
El 30 de enero de 1997 la Comisión presentó una demanda ante la Corte Interamericana de
Derechos Humanos. La sentencia fue dictada con fecha 19 de noviembre de 1999 y la senten
cia de reparaciones el día 26 de mayo del 2001.
16.2. Opinión Consultiva N° 17/2002, de la Corte Interamericana de Derechos Humanos,
Condición Jurídica y Derechos Humanos del Niño.
La cuestión del alcance de las medidas de protección a que alude la Convención Americana
en su artículo 19 y las alusiones de la Corte en el fallo Villagrán que ligan esta disposición con
otros instrumentos llevó a que poco tiempo después de dicho fallo la Comisión Interamerica-
na planteara a la Corte Interamericana una serie de preguntas relativas al tema, que fueron
respondidas en la Opinión Consultiva N ° i7 , del año 2002.
La facultad de form ular estas consultas se encuentra regulada en el artículo 64 de la Conven
ción Americana, que la entrega a los Estados miembros de la Organización de los Estados
Americanos, y a los órganos enumerados en el capítuloxde la Carta de laOEA. Las consultas a
que alude el artículo 64 versan acerca de la interpretación de la propia Convención Americana
o de otros tratados concernientes a la protección de derechos humanos (64.1). Además, los
Estados miembros pueden hacer solicitudes a la Corte acerca de la compatibilidad entre sus
leyes internas y esos instrumentos (64.2).
16.3. El caso Walter Bulado. Sentencia de 18 de septiembre de 2003, contra el Estado de
Argentina
Estos hechos ocurrieron en el año 1991, cuando el 19 de abril la policía detuvo a alrededor de
ochenta personas en las inmediaciones de un Estadio, entre ellas algunas personas menores
de edad. Walter Bulacio tenía 17 años, cursaba educación secundaria y trabajaba, y producto
de lesiones infringidas por agentes policiales presentó vóm itosy tuvo que ser conducido a un
hospital. Finalmente, tras algunos días interno, murió el 26 de abril.
La detención de personas, sin orden judicial y sin estar en situación de comisión flagrante de un
delito, era habitual en la época, y respecto de menores de edad regía el Memorando 40 que facul
taba a la policía a decidir si notificaba o no estas detenciones a la justicia correccional de menores.
En el caso de Walter, ni el juez pertinente ni su familia fueron puestos en conocimiento del he
cho de la detención. La familia se enteró al día siguiente de esta circunstancia, cuando Walter
ya había sido trasladado inconsciente a un establecimiento de salud, para luego ser traslada
do a otro, en el cual, sin recuperar jamás la conciencia, murió.
El fallo de la Corte en este caso presenta importantes áreas de análisis relativo a este tipo de
violencia estatal y su relación con los derechos fundamentales de las personas, y de los niños
en particular, fijando la Corte una serie de límites y resguardos a ser adoptados en lo sucesivo
por los Estados. Lamentablemente, pese a la aparente falta de discordia entre los peticionarios
y el Estado argentino, la ¡mplementación de esta sentencia ha resultado muy lenta y proble
mática.
El 13 de mayo de 1997 la Comisión Interamericana de Derechos Humanos recibió una denun
cia contra la República Argentina, tras cuya tramitación se elaboró el informe N° 72/00 (3 de
