artículo 1 de dicha Convención). El informe disponía algunas recomendaciones al Estado ar
gentino, en orden a impedir la impunidad de estos hechosy reparara los familiares. Se otorgó
un plazo de dos meses para implementar las recomendaciones, tras el cual no hubo respuesta.
La Comisión presentó la demanda ante la Corte el 24 de enero de 2001. El 19 de junio de 2002
la Comisión informó a la Corte que se estaba trabajando en una solución amistosa, a la que se
llegó finalmente el 26 de febrero del 2003 siendo comunicada a la Comisión al día siguiente. El
Estado argentino reconoció su responsabilidad, pero se estimó necesario realizar las audien
cias públicas previstas ante la Corte: de hecho, los términos del acuerdo al que se llegó entre
los familiares de Walter (representados en todo este procedimiento por el Centro de Estudios
Legales y Sociales -CELS-y la Coordinadora contra la Represión Policial e Institucional -CO-
RREPI-) y los representantes del Estado argentino incluían la solicitud del pronunciamiento
de la Corte en varios puntos relevantes.
16.4. Caso Instituto de Reeducación del Menor "Panchito López", sentencia contra el
Estado de Paraguay, 2 de Septiembre de 2004.
Este es el tercer fallo en que la Corte Interamericana se pronuncia sobre violaciones por los
Estados del Continente de derechos consagrados en la Convención Americana de Derechos
Humanos donde las víctimas de las violaciones son -m ayoritariam ente- niños. Da lugar al
procedimiento la violencia institucional sistemática contra los niños de sectores pobres de la
población. En este caso, lo que inicialmente se plantea al sistema interamericano son las pési
mas condiciones de reclusión de niños en un recinto en particular: El Instituto de Rehabilita
ción del Menor"Panchlto López”.
Tales condiciones de reclusión (infernales) motivaron que el 14 de agosto de 1996 se presen
tara por el Instituto Tekojojáy CEJIL una denuncia ante la Comisión Interamericana. A ésta le
siguió un proceso de solución amistosa iniciado en mayo de 1997,y que perduró hasta el 25 de
junio de 2001, momento en que los peticionarlos se retiraron del proceso. Durante este tiem
po se produjeron 3 incendios en el recinto, con varios muertos y lesionados graves, dándose
por terminado el proceso de solución amistosa con fecha 26 de julio de 2001.
La Comisión aprobó su Informe de fondo N° 126/01, de 3 de noviembre de 2001. En este infor
me la Comisión sostuvo que el Estado de Paraguay había violado el derecho a la vida (artícu
lo 4 de la Convención Americana), a la integridad física (artículo 5), a la integridad personal
(artículo 5), a la libertad personal (artículo 7), a los derechos del niño (artículo 19), derecho
a garantías procesales (artículo 8) y a protección judicial (artículo 25). En base a lo anterior,
la Comisión sostuvo que "el Estado paraguayo ha incumplido además, con su obligación de
respetar y garantizar el goce de esos derechos conforme al artículo 1.1 de la Convención” (pá
rrafo 24). Además, se formularon recomendaciones al Estado,y se le otorgaron dos meses para
implementarlas. Estas recomendaciones incluían el traslado inmediato de niños a estableci
mientos distintos de las penitenciarías de adultos, la adopción de medidas para que el Códi
