17. Principios generales del derecho de niños y adolescentes
Principio de protección especial: El derecho que protege a los niñosy adolescentes en el Perú,
es eminentemente tuitivo, en tanto se reconoce que el niño(a) se encuentra en constante for
mación de su personalidad, y tiene como finalidad la protección integral del mismo.
Principio de reconocimiento como sujeto de derechos: Por este principio se la reconoce autono
mía al niño(a) desde su fecundación,y se le otorga su condición de persona. Como consecuencia
de ello al niño se le protege desde la unión del óvulo con el es pe rm atozo ide y el Derecho peruano
sanciona el aborto. El principio de reconocimiento del niño, como sujeto de derechos tiene im
plicancias en la legislación del niño, en tanto puede decir su opinión, tiene derecho a formular
denuncias en las Fiscalías, a interponer el recurso de hábeas corpus, a asociarse.
Principio del interés superior del niño: Este principio como los anteriores han sido recogidos
en nuestra legislación especial, Código de los Niñosy Adolescentes, del texto de la Convención
de las Naciones Unidas sobre los derechos del niño.
Por este principio, en todas las medidas concernientes a los niños, que tomen las instituciones
públicas o privadas de bienestar social, los tribunales, las autoridades administrativas o los
órganos legislativos una consideración primordial a que se atenderá, será el interés superior
del niño. Este principio tiene una notable aplicación en materia alimenticia, tenencia, régi
men de visita. Sin embargo, su existencia no excluye la necesaria probanza de los hechos o los
términos de la pretensión. En el título prelim inardel C. del Niño del Perú se ha plasmado este
principio (Art. IX). Consideramos que si bien se ha precisado en mayor detalle a las institucio
nes a quienes corresponde aplicar tal principio, es de señalar que la Convención indica que se
priorizaráy no que se considerará, el texto del Código restringe el mandato de la Convención,
en caso de conflicto al tratarse de un tratado de derechos humanosy por aplicación de la dis
posición transitoria 4o debe interpretarse que debe priorizarse el Interés Superior del niño(a).
18. Doctrina de la protección integral
