UBILEX
la comunidad internacional de la doctrina de la protección integral, a través de la Convención
Internacional porlos Derechos del Niño ha significado el pleno reconocimiento del niño como
sujeto de derecho. A partir del salto cualitativo en la percepción de los ni ños y adolescentes, la
intervención penal en sus vidas, debe limitarse a casos graves y excepcionales que no admitan
solución por vías alternativas no judiciales. Las circunstancias económicas, sociales o fam ilia
res de los niños y jóvenes, ya no pueden legitimar su injustay arbitraria criminalización e ins-
titucionalización. El Estado se halla en la obligación de adoptar políticas sociales que tiendan
a dism inuir las desigualdades entre los individuos y que permitan acceder a todos por igual, a
condiciones de existencia dignas.”25
19. Interés superior del niño
La Convención Internacional de los Derechos del Niño consagra como principio fundamental:
el interés superiordel niño; es asíqueen su artículo 3o se dispone que: “En todas las medidas con
cernientes a los niños que tomen las instituciones públicas, privadas de bienestar social, los tribunales, las
autoridades adm inistrativas o los órganos legislativos, una consideración prim ordial a que se atenderá
será el interés superior del niño"
El interés superior del niño se consagra como un principio inspirador, que tiene su origen en
el Derecho Común, donde sirve para la solución de conflictos de interés entre un niño y otra
persona, donde priman los intereses del niño; lo que implica que, este principio favorece la
protección de los derechos del niño y, el lugar central que ocupa en la Convención constitu
ye un valioso aporte a la ideología de los derechos del niño. La Convención, además permite
imponera los derechos del niño, límites destinados a asegurar la “protección especial” que ne
cesitan las personas menores de edad, debido a su mayor vulnerabilidad y limitada madurez,
esa posibilidad no se deriva del principio de los intereses superiores del niño exclusivamente,
sino que está reconocida en varias disposiciones de la Convención.
20. Derechos de los niños, niñas y adolescentes
Entre los derechos que la Legislación reconoce al niño y adolescente tenemos-.
Derecho a la vida (Art. i° CNA), precisándose que la protección es desde el momento de la
concepción del ser humano, debiendo entenderse que la concepción es entendida como
la unión del óvulo con el espermatozoide. El derecho a la vida está protegido tanto por la
Constitución de 1993 como por el Pacto Internacional de Derechos Civiles y Políticos, la
Convención Americana, y se encuentra establecido en la Declaración Universal de Dere
chos Humanos.
Derecho a la integridad (Art. i° CNA), Por este derecho se prohíben los atentados contra
la integridad del niño, desarrollo físicoy mental así como las manipulaciones antes de su
nacimiento.
